INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c5c3f5b2-2c4b-4aa8-bd76-cdcb594e0dda', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "concept-reveal", "title": "Custo e lucro", "locale": "pt-BR", "subject": "mixed", "objectives": ["Entender que o dinheiro é ganho oferecendo algo que outros querem, e que uma meta clara (o violão de 80 reais) ajuda a começar."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-concept-reveal", "xp": 0, "type": "concept_reveal", "hints": ["O custo é o que você gasta para fazer a limonada.", "O lucro é o que sobra depois de vender."], "title": "Custo e lucro", "payload": {"cards": [{"icon": "payments", "back_md": "O que você gasta em limões e açúcar para fazer a limonada.", "front_md": "**Custo**", "image_url": "http://localhost:4006/files/lesson-images/b59b4b80cf426d8dccfd5542cf296fb94400c09b3489e5b0b8e9c829fc7e1706.png"}, {"icon": "monetization_on", "back_md": "O que sobra depois de pagar o custo dos ingredientes.", "front_md": "**Lucro**", "image_url": "http://localhost:4006/files/lesson-images/8fcaaa242c454f1e3bede325277f90246a0041b4f6d51a21ebb4bf963191e730.png"}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Toque em cada cartão para descobrir o que é custo e o que é lucro.", "difficulty": 1, "explanation_md": "Custo é o que você gasta em limões e açúcar. Lucro é o que sobra depois de pagar o custo. Assim Liruf sabe quanto economizar para o violão!", "audio_segment_id": "s1-concept-reveal.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-concept-reveal.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b58aa61f15fe6cd10e2b49c0c8ff6551f653d906b7b5265ebdd3f65f807cb304.mp3", "hash": "d26c05786b1e1cdb6f2729bf99b37ce86f604162089c93127de6ec6435484c31", "bytes": 21024, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/b58aa61f15fe6cd10e2b49c0c8ff6551f653d906b7b5265ebdd3f65f807cb304.mp3", "duration_ms": 3440}, "s1-concept-reveal.hint.1": {"url": "http://localhost:4006/files/lesson-audio/4a7ad17daab0849b21ddc04f09704c317cea42e823109c9be7df91a137794edd.mp3", "hash": "f009c1fa88af65abdee8cea0833bee5e3547161d95dfc87225ada1bf5fcfd8c0", "bytes": 16704, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/4a7ad17daab0849b21ddc04f09704c317cea42e823109c9be7df91a137794edd.mp3", "duration_ms": 2720}, "s1-concept-reveal.prompt": {"url": "http://localhost:4006/files/lesson-audio/a4e1ad2015ab99a0c24e6c45b815f7a0d1d27431221e76b13ba87969c9ca2142.mp3", "hash": "7c89f3aa6ab156c62f3fe16f99b37b3012a52477df5ce7fa974b9528cccc0ff8", "bytes": 23904, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/a4e1ad2015ab99a0c24e6c45b815f7a0d1d27431221e76b13ba87969c9ca2142.mp3", "duration_ms": 3920}, "s1-concept-reveal.card.0.back": {"url": "http://localhost:4006/files/lesson-audio/8c884425575bb441ee47164a072a888d19da69c2493c21261ba293e4974ede30.mp3", "hash": "04d8f2a213c6f38de6dba1625d84a12843e5e921098e1f1ac411d957d6a61e4f", "bytes": 23904, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/8c884425575bb441ee47164a072a888d19da69c2493c21261ba293e4974ede30.mp3", "duration_ms": 3920}, "s1-concept-reveal.card.1.back": {"url": "http://localhost:4006/files/lesson-audio/34fa3e682f809b02ce5ebe68e2f9d3fac7dc60e1bcf4ce140aa138f79a7c9154.mp3", "hash": "6884c7920edba83cc80dd925d38e6f921fbb18e1ca37dbfb188c0f8afdb0e6de", "bytes": 21024, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/34fa3e682f809b02ce5ebe68e2f9d3fac7dc60e1bcf4ce140aa138f79a7c9154.mp3", "duration_ms": 3440}, "s1-concept-reveal.explanation": {"url": "http://localhost:4006/files/lesson-audio/bbf1cc1ac06ea2536634424566a24042a5146b7cd58f39c8cc724556e093f74d.mp3", "hash": "36c4a5b898482c53a3efcd431be8865bc268fdcf80205f507072f893dd4ed27e", "bytes": 63216, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/bbf1cc1ac06ea2536634424566a24042a5146b7cd58f39c8cc724556e093f74d.mp3", "duration_ms": 10480}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('881ae1da-74af-4378-a3cd-da8a9bc0e6b2', 'es-MX', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "key-ideas", "title": "Las tres reglas de oro del pequeño vendedor", "locale": "es-MX", "subject": "money", "objectives": ["Fijar las 3 ideas clave del plan: tener una meta (80 pesos), ofrecer algo que la gente quiera (limonada fría), y guardar lo ganado."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-key-ideas", "xp": 0, "type": "key_ideas", "hints": [], "title": "Las tres reglas de oro del pequeño vendedor", "payload": {"ideas": [{"icon": "flag", "title": "Meta: 80 pesos", "body_md": "Liruf quiere una guitarra que cuesta **80 pesos**. Tener una meta clara ayuda a saber cuánto hay que ganar.", "image_url": "http://localhost:4006/files/lesson-images/da9703b2d2f9389eb7fbb521f2ce7f36b488017005921419f3a8c0511fb24d7b.png"}, {"icon": "local_cafe", "title": "Ofrecer limonada fría", "body_md": "La gente del vecindario quiere algo rico y fresco. Liruf venderá **vasos de limonada a 5 pesos**.", "image_url": "http://localhost:4006/files/lesson-images/f5c4930000b26c112f7a72fd80a02d4bb98edb0d793dbcde51797db54ec4fecf.png"}, {"icon": "savings", "title": "Guardar lo ganado", "body_md": "Cada vez que vendas un vaso, guarda el dinero. Poco a poco llegarás a los **80 pesos** de la guitarra.", "image_url": "http://localhost:4006/files/lesson-images/99c05b3eb63d7ad321e1a01d5a26f3d9124624de2fc0a5abb071b59b87d3d711.png"}]}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho escribió en su pizarra las tres reglas de oro para vender limonada. Toca cada una para leerla.", "difficulty": 1, "explanation_md": "Rho anotó las tres ideas clave: una meta clara (80 pesos), un producto que la gente quiera (limonada fría), y guardar lo que se gana.", "audio_segment_id": "s1-key-ideas.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-key-ideas.idea.0": {"url": "http://localhost:4006/files/lesson-audio/e1e82b95b3e6a2b50d5273441cd03104c878163739a031f7c8deffae7315af78.mp3", "hash": "e85dcf615503d73e5b14ee146803ea25948262ff5e789da4447cfe587c7cfc41", "bytes": 44496, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/e1e82b95b3e6a2b50d5273441cd03104c878163739a031f7c8deffae7315af78.mp3", "duration_ms": 7360}, "s1-key-ideas.idea.1": {"url": "http://localhost:4006/files/lesson-audio/6523494ee2fb5f8424753e1858271ab1466b55aac293610a324639fc25cb8cb3.mp3", "hash": "2012664dc4830f9c60634c1c019e16947ffdb3d15f84b35082bbe60d480adf8f", "bytes": 41616, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/6523494ee2fb5f8424753e1858271ab1466b55aac293610a324639fc25cb8cb3.mp3", "duration_ms": 6880}, "s1-key-ideas.idea.2": {"url": "http://localhost:4006/files/lesson-audio/a0b2e902d1c1e198a7ed6b10faefec8bba1db6d01b9cc7c065748ddf1e0b31c7.mp3", "hash": "7c8342a1368e1a7f1f3791aa972b567ddb031600030a22e46b4c1354f80e4f0b", "bytes": 44928, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/a0b2e902d1c1e198a7ed6b10faefec8bba1db6d01b9cc7c065748ddf1e0b31c7.mp3", "duration_ms": 7440}, "s1-key-ideas.prompt": {"url": "http://localhost:4006/files/lesson-audio/15ba8f6cf8b553a545fc949d04aa65bab8efac95c72bc0043ab5321f1bbfa8ba.mp3", "hash": "8bc90da237043e2626abfea9e1cf8ee862765c36dca83fa15606da025b9245f1", "bytes": 44928, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/15ba8f6cf8b553a545fc949d04aa65bab8efac95c72bc0043ab5321f1bbfa8ba.mp3", "duration_ms": 7440}, "s1-key-ideas.explanation": {"url": "http://localhost:4006/files/lesson-audio/3f0b12c5b68cdfa0ac080ecb3cba3544f31609d6978d9ddb2ab010819ec44bfa.mp3", "hash": "b5ca25bc696472b36237f6ae3edfe37836da2452cd21d0074e78518b8611544d", "bytes": 58896, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/3f0b12c5b68cdfa0ac080ecb3cba3544f31609d6978d9ddb2ab010819ec44bfa.mp3", "duration_ms": 9760}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('36624bae-eea6-49e3-8767-c43ffbdf09e7', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "compare-table", "title": "Compara proveedores de limones", "locale": "es-MX", "subject": "mixed", "objectives": ["Leer una tabla de dos proveedores de limones (precio y cantidad) y elegir el que da más por menos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-compare-table", "xp": 15, "type": "compare_table", "hints": ["Mira cuántos limones da cada uno por 5 pesos."], "title": "Elige el mejor proveedor", "payload": {"cols": [{"id": "precio", "label": "Precio"}, {"id": "cantidad", "label": "Cantidad de limones"}], "rows": [{"id": "proveedor-a", "label": "Proveedor A"}, {"id": "proveedor-b", "label": "Proveedor B"}], "tokens": [{"id": "t1", "text_md": "5 pesos"}, {"id": "t2", "text_md": "10 limones"}, {"id": "t3", "text_md": "5 pesos"}, {"id": "t4", "text_md": "8 limones"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/43f4d3c904139fa8cd5ccb8232aa6642d969030d26ada5949c65d79fda568269.png", "prompt_md": "Dina tiene 5 pesos. ¿Con cuál proveedor consigue más limones?", "difficulty": 1, "explanation_md": "Con el proveedor A, Dina obtiene 10 limones por sus 5 pesos. Con el B, solo 8. ¡El A le da más limones por el mismo dinero!", "audio_segment_id": "s1-compare-table.prompt"}], "schema_version": 1}', '{"s1-compare-table": {"cells": {"proveedor-a:precio": "t1", "proveedor-b:precio": "t3", "proveedor-a:cantidad": "t2", "proveedor-b:cantidad": "t4"}}}', '{"units": {"s1-compare-table.hint.0": {"url": "http://localhost:4006/files/lesson-audio/aa004ff56dea1d46d1f6b476ddfe1b5ff68da8ac19b8098457bdc3883b58f501.mp3", "hash": "6ed11f2dc67db0620cbf7de1653c539767e85961a9c554a94675525fd6ef4a4a", "bytes": 22464, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/aa004ff56dea1d46d1f6b476ddfe1b5ff68da8ac19b8098457bdc3883b58f501.mp3", "duration_ms": 3680}, "s1-compare-table.prompt": {"url": "http://localhost:4006/files/lesson-audio/1936ee2b93935cd7d1f978aef72239365a157830fcb9b1f24ce11e258a893249.mp3", "hash": "43daeb7f8a2657984d93e0cba5de026969030f2733108d6bd1ee358b3c14570a", "bytes": 31968, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1936ee2b93935cd7d1f978aef72239365a157830fcb9b1f24ce11e258a893249.mp3", "duration_ms": 5280}, "s1-compare-table.explanation": {"url": "http://localhost:4006/files/lesson-audio/2e47f6cb078ae0d6ef50a890a396a71465a0e79f15d6be248b0b8565e4632474.mp3", "hash": "460be4f137f24cd4e3b23a124a4fb8c846db90f7604e3978cf8f1802cf5cd17d", "bytes": 57888, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/2e47f6cb078ae0d6ef50a890a396a71465a0e79f15d6be248b0b8565e4632474.mp3", "duration_ms": 9600}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08604886-c155-4f4b-85dd-0b5b853997e1', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "quiz-mcq", "title": "Precio justo para la limonada", "locale": "es-MX", "subject": "money", "objectives": ["Elegir el precio justo para un vaso de limonada comparando opciones."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-justo", "xp": 10, "type": "quiz_mcq", "hints": ["Piensa: si cuesta mucho, nadie compra; si cuesta poco, Liruf pierde dinero.", "Un vaso cuesta 5 pesos hacerlo. ¿Qué precio deja ganancia sin espantar clientes?"], "title": "¿A cuánto el vaso?", "payload": {"options": [{"id": "op1", "text_md": "50 pesos", "rationale_md": "50 pesos es muy caro para un vaso de limonada. Los clientes se irían a otro puesto."}, {"id": "op2", "text_md": "5 pesos"}, {"id": "op3", "text_md": "1 peso", "rationale_md": "1 peso no alcanza ni para comprar los limones. Liruf perdería dinero con cada vaso."}], "shuffle": true}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf pone el precio al vaso de limonada. ¿Cuál es justo?", "difficulty": 1, "explanation_md": "5 pesos es justo: cubre el costo de 5 pesos y la gente compra. 50 pesos es demasiado caro; 1 peso no cubre ni los limones.", "audio_segment_id": "s1-precio-justo.prompt"}], "schema_version": 1}', '{"s1-precio-justo": {"correct_option_id": "op2"}}', '{"units": {"s1-precio-justo.hint.0": {"url": "http://localhost:4006/files/lesson-audio/1592884454a4e3465353f66319211bb2cd8a210498e458d26ccec6646edd1bd8.mp3", "hash": "dda3b6e2fa93d874bf036d76133e8022a2f5db32f88857df562a60950b8aca87", "bytes": 35424, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1592884454a4e3465353f66319211bb2cd8a210498e458d26ccec6646edd1bd8.mp3", "duration_ms": 5840}, "s1-precio-justo.hint.1": {"url": "http://localhost:4006/files/lesson-audio/9a270ec6eec6c0220a92b3541e729f1dfadf23d87a715f48344726b55eb186cf.mp3", "hash": "f32e975886dfc47526d5d67593c65a89a3aa26684ab8633b349c048f2e501dc5", "bytes": 37296, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/9a270ec6eec6c0220a92b3541e729f1dfadf23d87a715f48344726b55eb186cf.mp3", "duration_ms": 6160}, "s1-precio-justo.prompt": {"url": "http://localhost:4006/files/lesson-audio/56affb6e5e70ec74351699202b23ff3293965ae62ba146681062ef4ea161c845.mp3", "hash": "bb0de783ebaa4271ac5d9552f073d084fa5eb2c7df750dc2386eff83a14db523", "bytes": 25776, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/56affb6e5e70ec74351699202b23ff3293965ae62ba146681062ef4ea161c845.mp3", "duration_ms": 4240}, "s1-precio-justo.choices": {"url": "http://localhost:4006/files/lesson-audio/be539c7bd53591d610c2b22b009a1f70b07173ae43ab490c82fbfccea583d0b1.mp3", "hash": "1616836e93b85ff90c52f290a25871cf56e408a4b27da367f8014804d26af8ff", "bytes": 23328, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/be539c7bd53591d610c2b22b009a1f70b07173ae43ab490c82fbfccea583d0b1.mp3", "duration_ms": 3840}, "s1-precio-justo.explanation": {"url": "http://localhost:4006/files/lesson-audio/214053bbc141b4de3b47c2f7b36ec69b291bf47241eb62a14ec2bffb3215eb68.mp3", "hash": "3f9f6cb82a3804dc237302ffe98b7e2e366e1ac2bf646f5fed0378091e288bf4", "bytes": 57456, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/214053bbc141b4de3b47c2f7b36ec69b291bf47241eb62a14ec2bffb3215eb68.mp3", "duration_ms": 9520}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('21c29ede-4ec5-4118-8e88-04f1068e985b', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "count-objects", "title": "Contar moedas do pote derrubado", "locale": "pt-BR", "subject": "mixed", "objectives": ["Contar moedas de relance (até 12) e associar cada moeda a um copo de limonada vendido."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-count-coins", "xp": 10, "type": "count_objects", "hints": ["Olhe apenas para as moedas, não para os biscoitos nem para o copo.", "Você pode tocá-las uma por uma para contá-las."], "title": "Moedas no pote", "payload": {"scene": [{"icon": "monetization_on", "tint": "primary", "count": 8}, {"icon": "cookie", "tint": "accent", "count": 3}, {"icon": "local_drink", "tint": "accent", "count": 1}], "ask_icon": "monetization_on"}, "narrator": {"emotion": "surprised", "character": "liruf"}, "prompt_md": "Conte as moedas que caíram do pote. Quantas são?", "difficulty": 1, "explanation_md": "Há 8 moedas. Cada moeda é um copo de 5 reais que Liruf vendeu hoje. Esse número é o que soma para o violão de 80 reais.", "audio_segment_id": "s1-count-coins.prompt"}], "schema_version": 1}', '{"s1-count-coins": {"value": 8}}', '{"units": {"s1-count-coins.hint.0": {"url": "http://localhost:4006/files/lesson-audio/5b62703d273ce5deec2416149a2dd6e9754c22ae9cd34a59ae47cc5000a3a285.mp3", "hash": "ba211cad3b22f4013320d095e991a3296f6237decc62ed8d2eac7e371837fd1d", "bytes": 27216, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/5b62703d273ce5deec2416149a2dd6e9754c22ae9cd34a59ae47cc5000a3a285.mp3", "duration_ms": 4480}, "s1-count-coins.hint.1": {"url": "http://localhost:4006/files/lesson-audio/cff8f38ba4afa8d51fbe2825049e3d14d7afab0eb82452b7d8b55ee0b0965399.mp3", "hash": "8fa5c9eaa6dda9b2babbc484d384c3d311ff056244513b4d7db9a9b47d7a5a1f", "bytes": 21024, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/cff8f38ba4afa8d51fbe2825049e3d14d7afab0eb82452b7d8b55ee0b0965399.mp3", "duration_ms": 3440}, "s1-count-coins.prompt": {"url": "http://localhost:4006/files/lesson-audio/f24fa48ca3e1d59666897c7177f718f99d14be5ebc34799563cf600af455effc.mp3", "hash": "7c36c7dac39f675e27ed69e9d0e13120c6bbd44b5b1bbf1365691dc94b13f4d6", "bytes": 21888, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/f24fa48ca3e1d59666897c7177f718f99d14be5ebc34799563cf600af455effc.mp3", "duration_ms": 3600}, "s1-count-coins.explanation": {"url": "http://localhost:4006/files/lesson-audio/4c3846a4dc8189fcacce3ac19cd49ebfaec7ac24c2b72f53625c034ecade77ba.mp3", "hash": "efe870885004955eca2f44a3e9f9d3d00f4002e77c9f6e435e8a11958d2e2d17", "bytes": 57456, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/4c3846a4dc8189fcacce3ac19cd49ebfaec7ac24c2b72f53625c034ecade77ba.mp3", "duration_ms": 9520}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('3c639b5e-01f3-469e-95e3-a52a215847f4', 'es-MX', '1', E'{"meta": {"cast": ["rho"], "slug": "fact-opinion", "title": "Hechos y opiniones en el puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Separar hechos de opiniones en frases del puesto de limonada"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fact-opinion", "xp": 10, "type": "fact_opinion", "hints": ["Un hecho se puede medir o contar. ¿Cuánto cuesta el vaso?", "Una opinión dice cómo se siente alguien. No se puede comprobar."], "title": "Hecho u opinión", "payload": {"statements": [{"id": "s1", "text_md": "El vaso de limonada cuesta 5 pesos."}, {"id": "s2", "text_md": "Mi limonada es la más rica del mundo."}, {"id": "s3", "text_md": "Hoy vendí 12 vasos de limonada."}, {"id": "s4", "text_md": "Esta limonada sabe mejor que la de Dina."}]}, "narrator": {"emotion": "neutral", "character": "rho"}, "image_url": "http://localhost:4006/files/lesson-images/984ed5f2b9d4054ce4dbef5a8c4be8b288bfe23a4564b3327a9c19b3244acdb9.png", "prompt_md": "Rho oyó a un cliente decir: \\"¡Tu limonada es la mejor!\\" ¿Es un hecho o una opinión? Toca las frases que son HECHOS.", "difficulty": 1, "explanation_md": "El precio del vaso (5 pesos) es un hecho porque se puede verificar. \\"La más rica\\" es una opinión, porque cada persona puede pensar distinto. Rho aprendió a no creer promesas sin pruebas.", "audio_segment_id": "s1-fact-opinion.prompt"}], "schema_version": 1}', '{"s1-fact-opinion": {"fact_ids": ["s1", "s3"]}}', '{"units": {"s1-fact-opinion.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4555f95bdd1a255ab6bda33be8251e1b67f59518d2a5221be3f372738682d0d5.mp3", "hash": "f07e254cbbd263b2a82c7b27fdcf2067e8f30440749930cf44a735f4a4b05fe1", "bytes": 28224, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/4555f95bdd1a255ab6bda33be8251e1b67f59518d2a5221be3f372738682d0d5.mp3", "duration_ms": 4640}, "s1-fact-opinion.hint.1": {"url": "http://localhost:4006/files/lesson-audio/166a2c9ea96d50761f8a0feab97e54cce86936046be57f08bc797753c48c5807.mp3", "hash": "9d362e513e765cf9f425d5e0bc46621566e326ca64c1205e6e17182d3c1cdc7c", "bytes": 28224, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/166a2c9ea96d50761f8a0feab97e54cce86936046be57f08bc797753c48c5807.mp3", "duration_ms": 4640}, "s1-fact-opinion.prompt": {"url": "http://localhost:4006/files/lesson-audio/6138e0e1cf4d304f83ed8dd0c274a8de1cfe7180961fb131ff583855cc5c41f4.mp3", "hash": "9661eddd1f4234a696e77dd21e0f5a586b767f7782375b9e4a6569ab0b16880e", "bytes": 59328, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/6138e0e1cf4d304f83ed8dd0c274a8de1cfe7180961fb131ff583855cc5c41f4.mp3", "duration_ms": 9840}, "s1-fact-opinion.explanation": {"url": "http://localhost:4006/files/lesson-audio/3657b7a04aaae87ba680830f34fe277d29f35ae4c4aacaafea3900e3abdb2e8c.mp3", "hash": "e58077aa1108e71fbaa859facf38b19777cbcedd343c629a3d21b55f1f2318b5", "bytes": 88128, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/3657b7a04aaae87ba680830f34fe277d29f35ae4c4aacaafea3900e3abdb2e8c.mp3", "duration_ms": 14640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('6e000ee0-e5b3-4521-b30f-cd54bbd72297', 'en-US', '1', '{"meta": {"cast": ["rho"], "slug": "type-answer", "title": "Write the word: savings", "locale": "en-US", "subject": "money", "objectives": ["Write the word ''savings'' to name the money you keep for later."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ahorro", "xp": 10, "type": "type_answer", "hints": ["Starts with the letter S. It''s what you do when you don''t spend all your money today.", "Hint: you keep money in your piggy bank to buy something later. That word is..."], "title": "Rho saves for his guitar", "payload": {"max_chars": 10, "placeholder": "Write here..."}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho saves 5 pesos each week. What is the money he keeps for later called?", "difficulty": 1, "explanation_md": "The money Rho saves for his guitar is called ''savings''. That way he can buy it!", "audio_segment_id": "s1-ahorro.prompt"}], "schema_version": 1}', '{"s1-ahorro": {"accept": ["ahorro", "Ahorro"], "keywords": ["ahorro"], "case_sensitive": false}}', '{"units": {"s1-ahorro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b1c999bdb8f0b1472d5c7bd0fd596e881100dc25e106bd41befe10dc873299a5.mp3", "hash": "7b4b028bcf81e01d685c273929086c7a851a98afd81c0700252357538c8f7dd7", "bytes": 35856, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/b1c999bdb8f0b1472d5c7bd0fd596e881100dc25e106bd41befe10dc873299a5.mp3", "duration_ms": 5920}, "s1-ahorro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/7560b3f66f5d7cf15f07bd2c793964fa80c69bb758ffa2330bb5e436c1817502.mp3", "hash": "1b637310410d3beb0b16762aa0bfe88ee5fb0288f67c95b50f4ac97537757391", "bytes": 33984, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/7560b3f66f5d7cf15f07bd2c793964fa80c69bb758ffa2330bb5e436c1817502.mp3", "duration_ms": 5600}, "s1-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/5af6f69efc868d32e83a1d25c57b0b1d3223f2e5a4b1882869611ba8b691d6c8.mp3", "hash": "6b2fdfd1e8c975785c1cef401a740ccbd2346029f5787e9068684c4f40b63aa9", "bytes": 35856, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/5af6f69efc868d32e83a1d25c57b0b1d3223f2e5a4b1882869611ba8b691d6c8.mp3", "duration_ms": 5920}, "s1-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/e10b91764958d9f41cf51b8cc8d1ab9ac4d69e458e934fa3274d17cda86bab14.mp3", "hash": "8a1553becb50593e161949d043718a4393644d1b2cda83470b24d2a0d1026bf8", "bytes": 37728, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/e10b91764958d9f41cf51b8cc8d1ab9ac4d69e458e934fa3274d17cda86bab14.mp3", "duration_ms": 6240}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('6e000ee0-e5b3-4521-b30f-cd54bbd72297', 'pt-BR', '1', '{"meta": {"cast": ["rho"], "slug": "type-answer", "title": "Escreva a palavra: poupança", "locale": "pt-BR", "subject": "money", "objectives": ["Escrever a palavra ''poupança'' para nomear o dinheiro que se guarda para depois."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ahorro", "xp": 10, "type": "type_answer", "hints": ["Começa com a letra P. É o que você faz quando não gasta todo o seu dinheiro hoje.", "Dica: você guarda dinheiro no seu cofrinho para comprar algo depois. Essa palavra é..."], "title": "Rho poupa para seu violão", "payload": {"max_chars": 10, "placeholder": "Escreva aqui..."}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho guarda 5 reais toda semana. Como se chama o dinheiro que ele guarda para depois?", "difficulty": 1, "explanation_md": "O dinheiro que Rho guarda para seu violão se chama ''poupança''. Assim ele pode comprá-lo!", "audio_segment_id": "s1-ahorro.prompt"}], "schema_version": 1}', '{"s1-ahorro": {"accept": ["ahorro", "Ahorro"], "keywords": ["ahorro"], "case_sensitive": false}}', '{"units": {"s1-ahorro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/582e357f88505d969f8c2ca354ac1a4800654a59fe7eec99311dcccabe829b76.mp3", "hash": "961dec159fd7e05ff6fe4393bdfae9b3f3a1d53774aef1e8e69b7444c9fd1a3d", "bytes": 35856, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/582e357f88505d969f8c2ca354ac1a4800654a59fe7eec99311dcccabe829b76.mp3", "duration_ms": 5920}, "s1-ahorro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/8669e0a9853ae78a6791f674525b70fe2da6566ec2ddb37e18568c47f6ea9f0f.mp3", "hash": "0265696f3d36ff644741447bc013c5303fe76d9fec1bd5edd71225fd0974c201", "bytes": 40608, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/8669e0a9853ae78a6791f674525b70fe2da6566ec2ddb37e18568c47f6ea9f0f.mp3", "duration_ms": 6720}, "s1-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/72a7a7d9b57c89fc100e321b60aafb3e7f403af6a7002291fd2298526895a195.mp3", "hash": "4347626483bee8220ffe9acda7f4fa2b20390e8fb80c7478b30600d791133eac", "bytes": 38304, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/72a7a7d9b57c89fc100e321b60aafb3e7f403af6a7002291fd2298526895a195.mp3", "duration_ms": 6320}, "s1-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/a0997df58587a4e79aaaa983cc18c408fa135f2a07a6937e40a2e01ff3b9e468.mp3", "hash": "16893d4443aec43933d39f9645594dea19b75332dbc759ba93b9a8df8592453c", "bytes": 42048, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/a0997df58587a4e79aaaa983cc18c408fa135f2a07a6937e40a2e01ff3b9e468.mp3", "duration_ms": 6960}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a6e01e69-b662-4c31-9021-3de01a60bbc7', 'en-US', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "odd-one-out", "title": "The ingredient that is not", "locale": "en-US", "subject": "mixed", "objectives": ["Identify which items are not lemonade ingredients to distinguish real expenses from distractions."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-odd-one-out", "xp": 10, "type": "odd_one_out", "hints": ["For lemonade you need things that mix in the glass.", "The ball does not mix or sell, it''s only for playing."], "title": "The ingredient that is not", "payload": {"items": [{"id": "item1", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/46abc1662f6c1232c9749f15929a9b9176457185ea0b75550d234ce9854a7d91.png"}, {"id": "item2", "text_md": "Sugar", "image_url": "http://localhost:4006/files/lesson-images/f32156f5bd4b4c233f6fd346edeb51e1834331935180e346174537f4e0fd53fb.png"}, {"id": "item3", "text_md": "Water", "image_url": "http://localhost:4006/files/lesson-images/b0f1b4a4bd81d90c3ff4cc28d46723fe168d2a3b24bba8a2a38a057f414f681d.png"}, {"id": "item4", "text_md": "Ball", "image_url": "http://localhost:4006/files/lesson-images/cb15e3734a936cbc5a1b34085e28d552ab1ba360e9d73e370474ab15e62ba987.png"}], "reasons": [{"id": "reason1", "text_md": "Not used to make lemonade"}, {"id": "reason2", "text_md": "Costs more than the others"}, {"id": "reason3", "text_md": "Not sold in the store"}]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Rho has $10 in her piggy bank with a lock. Which purchase is NOT for the lemonade?", "difficulty": 1, "explanation_md": "The ball is not a lemonade ingredient. If you spend $3 on the ball, you only have $7 left for ingredients. Better keep your piggy bank key and spend only on what you need!", "audio_segment_id": "s1-odd-one-out.prompt"}], "schema_version": 1}', '{"s1-odd-one-out": {"odd_item_id": "item4", "correct_reason_id": "reason1"}}', '{"units": {"s1-odd-one-out.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d67481983ff21f7988201f0d4dd4679f27c5f304be7c4fa3f0d64e9b978c29cf.mp3", "hash": "76d555ebbf0cbe7d0793d4926cb7b1dd354d98fb0acee869e1800053b2582907", "bytes": 18576, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/d67481983ff21f7988201f0d4dd4679f27c5f304be7c4fa3f0d64e9b978c29cf.mp3", "duration_ms": 3040}, "s1-odd-one-out.hint.1": {"url": "http://localhost:4006/files/lesson-audio/688ea556f5e89ac20498e35f24b2adcf94b310db07f53eaf6a1c02007ba97080.mp3", "hash": "72ce7d8cb5192a8e30877e4dff00719ac151f9fc9a9b0d5269cc474b288bc4ef", "bytes": 23904, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/688ea556f5e89ac20498e35f24b2adcf94b310db07f53eaf6a1c02007ba97080.mp3", "duration_ms": 3920}, "s1-odd-one-out.prompt": {"url": "http://localhost:4006/files/lesson-audio/3e8029c75bd9cfd828a46d2462f41d44f61fa21ad28ecdd7f2f08765f3286c89.mp3", "hash": "d8b106ed83277cdba52ba53bc42b1bf1c8177fcc8c600e99174fa412ccec8aa7", "bytes": 39168, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/3e8029c75bd9cfd828a46d2462f41d44f61fa21ad28ecdd7f2f08765f3286c89.mp3", "duration_ms": 6480}, "s1-odd-one-out.choices": {"url": "http://localhost:4006/files/lesson-audio/821f2ee20b3f16c4d46d5de65264c48e5c45f110db7b47c0708af74d20da777d.mp3", "hash": "3e8da1da7d919271b370b33b88cfc47018742bcaa3fbd0da086a2edd01cca212", "bytes": 18576, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/821f2ee20b3f16c4d46d5de65264c48e5c45f110db7b47c0708af74d20da777d.mp3", "duration_ms": 3040}, "s1-odd-one-out.explanation": {"url": "http://localhost:4006/files/lesson-audio/81066c9bf88a07704c9eed08c3aad77ce974dd9990afd12db1f9bdcdc5d75aa1.mp3", "hash": "2e04d61c81dc75c7b86c274ebfd409575de911ee797fe3eb39ec11ba18de66bd", "bytes": 73728, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/81066c9bf88a07704c9eed08c3aad77ce974dd9990afd12db1f9bdcdc5d75aa1.mp3", "duration_ms": 12240}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('43eb7cc6-46cc-44ee-9a87-14d05d8f357d', 'en-US', '1', '{"meta": {"cast": ["liruf", "zara"], "slug": "dialogue-choice", "title": "Can you give it to me for 3?", "locale": "en-US", "subject": "mixed", "objectives": ["Choosing a kind but firm response to a customer asking for a discount, without losing profit."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cliente-rebaja", "xp": 15, "type": "dialogue_choice", "hints": ["If you say yes, you earn less than what it costs to make the cup.", "You can be kind and explain why the price is fair."], "title": "The customer asks for a discount", "payload": {"turns": [{"id": "turn1", "npc_md": "Hello, young man. Your lemonade looks very tasty. Can you give it to me for 3 pesos? I only have that much.", "replies": [{"id": "r1a", "text_md": "I''m sorry, the price is 5 pesos. I can''t lower it."}, {"id": "r1b", "text_md": "Okay, I''ll give it to you for 3 pesos."}, {"id": "r1c", "text_md": "No, ma''am. If you don''t want to pay 5, I won''t sell to you."}]}, {"id": "turn2", "npc_md": "Oh, 5 pesos seems expensive for a cup.", "replies": [{"id": "r2a", "text_md": "I understand, but each cup has fresh lemons and sugar. 5 pesos is fair."}, {"id": "r2b", "text_md": "Okay, I''ll give it to you for 4, but that''s my final offer."}, {"id": "r2c", "text_md": "Then go to another stand."}]}], "persona": {"name": "Zara", "role_md": "Customer at the lemonade stand", "character": "zara"}, "opening_md": "Liruf is at his lemonade stand. A lady named Zara approaches and smiles."}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/8ff40b48dab19a1bfc74d077bef6df2ecda8531058f55d65ec93d5047798d8a5.png", "prompt_md": "A customer wants to pay 3 pesos for a cup that costs 5. What do you say?", "difficulty": 2, "explanation_md": "Each cup costs 5 pesos because that covers the lemons and sugar, and you also save for your goal. If you sell it for 3, you lose money.", "audio_segment_id": "s1-cliente-rebaja.prompt"}], "schema_version": 1}', '{"s1-cliente-rebaja": {"turns": [{"turn_id": "turn1", "qualities": {"r1a": 90, "r1b": 10, "r1c": 30}, "reactions": {"r1a": "Zara asiente, pensativa.", "r1b": "Zara sonríe y paga 3 pesos, pero Liruf pierde dinero.", "r1c": "Zara frunce el ceño y se va."}}, {"turn_id": "turn2", "qualities": {"r2a": 100, "r2b": 60, "r2c": 0}, "reactions": {"r2a": "Zara sonríe y dice: ''Tiene razón, deme un vaso.''", "r2b": "Zara duda, pero acepta. Ganas 4 pesos, pero podrías haber ganado 5.", "r2c": "Zara se va enojada y no compra nada."}}]}}', '{"units": {"s1-cliente-rebaja.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c8f7086085dc601b1b3711027352d33042b998e392d90a8021e56661f6c63bb2.mp3", "hash": "204a1bdef4661aba27b419d8af1773043ad97b5c91dbabfe396e2791cda217bd", "bytes": 28224, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/c8f7086085dc601b1b3711027352d33042b998e392d90a8021e56661f6c63bb2.mp3", "duration_ms": 4640}, "s1-cliente-rebaja.hint.1": {"url": "http://localhost:4006/files/lesson-audio/ae546643cf3733f0423c2afbc468521b3179aad3965e1ff718c59f8bb15beeac.mp3", "hash": "05dd5280460ff46007a38c468a42fca4e7fad47f15d256e99c42e3a24301d96f", "bytes": 20016, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/ae546643cf3733f0423c2afbc468521b3179aad3965e1ff718c59f8bb15beeac.mp3", "duration_ms": 3280}, "s1-cliente-rebaja.prompt": {"url": "http://localhost:4006/files/lesson-audio/1c0ddd0862e2ed29d8d6e2c0985fd885d4ce7d8ce9121026544c23b8b8d35556.mp3", "hash": "76522a851a49dff904a7f46175658764a60bed5a8eacbb74fac96c274b82e246", "bytes": 29664, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/1c0ddd0862e2ed29d8d6e2c0985fd885d4ce7d8ce9121026544c23b8b8d35556.mp3", "duration_ms": 4880}, "s1-cliente-rebaja.explanation": {"url": "http://localhost:4006/files/lesson-audio/dc194b511438cc0b2fb6dd2080e17f24aeebbd7d3d0e296940ebb0d9d6b4eeb2.mp3", "hash": "5df3323807b9258b1ee0fdf4b87dc1916a040ac71cc5743650bfdb65286ccc23", "bytes": 52704, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/dc194b511438cc0b2fb6dd2080e17f24aeebbd7d3d0e296940ebb0d9d6b4eeb2.mp3", "duration_ms": 8720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('43eb7cc6-46cc-44ee-9a87-14d05d8f357d', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "zara"], "slug": "dialogue-choice", "title": "Você me deixa por 3?", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher uma resposta gentil, mas firme, diante de um cliente que pede desconto, sem perder o lucro."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cliente-rebaja", "xp": 15, "type": "dialogue_choice", "hints": ["Se você disser sim, ganha menos do que custa fazer o copo.", "Você pode ser gentil e explicar por que o preço é justo."], "title": "A cliente pede desconto", "payload": {"turns": [{"id": "turn1", "npc_md": "Olá, jovem. Sua limonada parece muito gostosa. Você me deixa por 3 reais? É que estou com o troco certo.", "replies": [{"id": "r1a", "text_md": "Desculpe, o preço é 5 reais. Não posso baixar."}, {"id": "r1b", "text_md": "Tudo bem, deixo por 3 reais."}, {"id": "r1c", "text_md": "Não, senhora. Se não quer pagar 5, não vendo."}]}, {"id": "turn2", "npc_md": "Ah, é que 5 reais acho caro para um copo.", "replies": [{"id": "r2a", "text_md": "Entendo, mas cada copo leva limões frescos e açúcar. 5 reais é justo."}, {"id": "r2b", "text_md": "Bom, deixo por 4, mas é minha última oferta."}, {"id": "r2c", "text_md": "Então vá a outra barraca."}]}], "persona": {"name": "Zara", "role_md": "Cliente da barraca de limonada", "character": "zara"}, "opening_md": "Liruf está em sua barraca de limonada. Uma senhora chamada Zara se aproxima e sorri."}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/c40a186dfb8adee9cc07f7083ae6d3f294dd3e2e2641ac953ae77637c3d7d28b.png", "prompt_md": "Uma cliente quer pagar 3 reais por um copo que custa 5. O que você diz?", "difficulty": 2, "explanation_md": "Cada copo custa 5 reais porque com isso você cobre os limões e o açúcar, e ainda guarda para sua meta. Se vender por 3, perde dinheiro.", "audio_segment_id": "s1-cliente-rebaja.prompt"}], "schema_version": 1}', '{"s1-cliente-rebaja": {"turns": [{"turn_id": "turn1", "qualities": {"r1a": 90, "r1b": 10, "r1c": 30}, "reactions": {"r1a": "Zara asiente, pensativa.", "r1b": "Zara sonríe y paga 3 pesos, pero Liruf pierde dinero.", "r1c": "Zara frunce el ceño y se va."}}, {"turn_id": "turn2", "qualities": {"r2a": 100, "r2b": 60, "r2c": 0}, "reactions": {"r2a": "Zara sonríe y dice: ''Tiene razón, deme un vaso.''", "r2b": "Zara duda, pero acepta. Ganas 4 pesos, pero podrías haber ganado 5.", "r2c": "Zara se va enojada y no compra nada."}}]}}', '{"units": {"s1-cliente-rebaja.hint.0": {"url": "http://localhost:4006/files/lesson-audio/19fe2c1b62959a46065ea8e97eb8f3dc05c7f90368214bbac530e6d53c7fe1cb.mp3", "hash": "c2ab9c91960f92c03bbb44bb7436b29a8330779a14382e779bc19b1e2b2e6220", "bytes": 22896, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/19fe2c1b62959a46065ea8e97eb8f3dc05c7f90368214bbac530e6d53c7fe1cb.mp3", "duration_ms": 3760}, "s1-cliente-rebaja.hint.1": {"url": "http://localhost:4006/files/lesson-audio/65dad342e6b3a395149532e3636c3cb30e9ccb99f9c2f33502f2902d23644f07.mp3", "hash": "c5619b12742f0d30a8656c3e6849f258e8634c5e9d3cbbb9790b767a925c47fb", "bytes": 25344, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/65dad342e6b3a395149532e3636c3cb30e9ccb99f9c2f33502f2902d23644f07.mp3", "duration_ms": 4160}, "s1-cliente-rebaja.prompt": {"url": "http://localhost:4006/files/lesson-audio/fbd0cb4f7674f10d5e8171c08d680b8ef73c50a9682bd3ca3e6005d64d8a670c.mp3", "hash": "a362476f741861875b3d5d9c9d0f5430ef1773e1d04031fbeabee2ec434573a4", "bytes": 31104, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/fbd0cb4f7674f10d5e8171c08d680b8ef73c50a9682bd3ca3e6005d64d8a670c.mp3", "duration_ms": 5120}, "s1-cliente-rebaja.explanation": {"url": "http://localhost:4006/files/lesson-audio/c7a70304f8a0eca3e285a6074091d98564783d464e7b596a97a6c74a959fb5ce.mp3", "hash": "e8613ed9d7309975be568b4e0c33a7d82e2b5d2d9b91935166b8ef5e948f7a0b", "bytes": 61776, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/c7a70304f8a0eca3e285a6074091d98564783d464e7b596a97a6c74a959fb5ce.mp3", "duration_ms": 10240}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('574fb312-93f9-4f2f-adea-606bbb0ca99d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "best-decision", "title": "La mejor decisión de Liruf", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir la mejor decisión cuando un cliente paga con billete de 20 por un vaso de 5: contar el cambio con calma."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-best-decision", "xp": 15, "type": "best_decision", "hints": ["Piensa: si el vaso cuesta 5 y te pagan con 20, ¿cuánto debes regresar?", "Imagina que tú eres Liruf: ¿prefieres contar despacio o adivinar?"], "title": "El cambio de Liruf", "payload": {"options": [{"id": "contar", "text_md": "Contar el cambio con calma: 15 pesos", "rationale_md": "Contar con calma es la mejor decisión porque asegura que el cambio sea correcto."}, {"id": "adivinar", "text_md": "Adivinar el cambio rápido y darle 10 pesos", "rationale_md": "Adivinar puede hacer que des cambio incorrecto y la clienta pierda dinero."}, {"id": "quedarse", "text_md": "Quedarse con todo el billete y no dar cambio", "rationale_md": "Quedarse con el billete completo es incorrecto porque la clienta pagó de más y merece su cambio."}], "scenario_md": "Liruf ya aprendió que la limonada necesita limones y azúcar, y que esos cuestan dinero. Ahora atiende a su primera clienta. Ella le da un billete de 20 pesos por un vaso de limonada de 5 pesos. Liruf está nervioso y no sabe qué hacer."}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/91b83ee01f542bcf37efb97abca94abb41316f76d47953dd102a4ee35f043173.png", "prompt_md": "La clienta paga con 20 pesos. El vaso cuesta 5. ¿Qué haces?", "difficulty": 2, "explanation_md": "Contar el cambio con calma asegura que no te equivoques. 20 menos 5 son 15 pesos de cambio.", "audio_segment_id": "s1-best-decision.prompt"}], "schema_version": 1}', '{"s1-best-decision": {"qualities": {"contar": 100, "adivinar": 20, "quedarse": 0}}}', '{"units": {"s1-best-decision.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ce6955da804a66ac490e0f67ef9051dcba7c8cd73343bd16389881d191a420a6.mp3", "hash": "193cb4835da3b28fd49ab899de6f8007c5d0e084f1cb7eb26ac022803f39df4e", "bytes": 33408, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/ce6955da804a66ac490e0f67ef9051dcba7c8cd73343bd16389881d191a420a6.mp3", "duration_ms": 5520}, "s1-best-decision.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a27643bc6b5a222bd0c286460714b2f0d3aa187aaba35b3d66859814aad18f4b.mp3", "hash": "34c436ee501b3640117f5c7ef6614b4a2cde3f47a5309e2e4e9725fc22a1d6a4", "bytes": 29088, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a27643bc6b5a222bd0c286460714b2f0d3aa187aaba35b3d66859814aad18f4b.mp3", "duration_ms": 4800}, "s1-best-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/9472f73ad8f738e0675d31bda158e0f3aa1be15fd666eb54637bb9a94071173f.mp3", "hash": "8f46f26d051abbcdd7afc912230b6e0e258956b1bd1d96bfc4217ffeb5a61bb2", "bytes": 31968, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/9472f73ad8f738e0675d31bda158e0f3aa1be15fd666eb54637bb9a94071173f.mp3", "duration_ms": 5280}, "s1-best-decision.choices": {"url": "http://localhost:4006/files/lesson-audio/ba35bb903c573b00b125a0cc27bb3450cd416986a017d79376515d036e0d6e6d.mp3", "hash": "7549c8bdce5b899fd1c42e8b5ccbf08a83e39f5211b3b5bbec42cf8028f00d5d", "bytes": 56016, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/ba35bb903c573b00b125a0cc27bb3450cd416986a017d79376515d036e0d6e6d.mp3", "duration_ms": 9280}, "s1-best-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/7670f36bfa89501f3baf96f471940fd8e62c1b792de428528c2121761e0116c0.mp3", "hash": "11dbca7e40a87bf4b12f4e18e32f8ad343a0f6de4ebe5d95df897b85fef36beb", "bytes": 43488, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7670f36bfa89501f3baf96f471940fd8e62c1b792de428528c2121761e0116c0.mp3", "duration_ms": 7200}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a6e01e69-b662-4c31-9021-3de01a60bbc7', 'pt-BR', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "odd-one-out", "title": "O ingrediente que não é", "locale": "pt-BR", "subject": "mixed", "objectives": ["Identificar quais itens não são ingredientes da limonada para distinguir gastos reais de distrações."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-odd-one-out", "xp": 10, "type": "odd_one_out", "hints": ["Para a limonada você precisa de coisas que se misturam no copo.", "A bola não se mistura nem se vende, só se brinca."], "title": "O ingrediente que não é", "payload": {"items": [{"id": "item1", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/04c3e26ebe03ee63afe9bef6b7e69dac219c50310b90f4a40c77233f3a38bff5.png"}, {"id": "item2", "text_md": "Açúcar", "image_url": "http://localhost:4006/files/lesson-images/8db85f51276631a2319760c901a3c382fec60eda018c7581b5e73464bbf06b0f.png"}, {"id": "item3", "text_md": "Água", "image_url": "http://localhost:4006/files/lesson-images/5e97470c9a4a6a3a74abc701128a3f43ca77182e96987a678a5d963b2e16405a.png"}, {"id": "item4", "text_md": "Bola", "image_url": "http://localhost:4006/files/lesson-images/618936ab529e7f6cb674ec3ce53fcec9ab7aa3e8055699a51d9588222417c7a2.png"}], "reasons": [{"id": "reason1", "text_md": "Não é usado para fazer limonada"}, {"id": "reason2", "text_md": "Custa mais que os outros"}, {"id": "reason3", "text_md": "Não é vendido na loja"}]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Rho tem $10 em seu cofrinho com chave. Qual compra NÃO é para a limonada?", "difficulty": 1, "explanation_md": "A bola não é um ingrediente da limonada. Se você gastar $3 na bola, sobram apenas $7 para os ingredientes. Melhor guardar a chave do seu cofrinho e gastar só no que precisa!", "audio_segment_id": "s1-odd-one-out.prompt"}], "schema_version": 1}', '{"s1-odd-one-out": {"odd_item_id": "item4", "correct_reason_id": "reason1"}}', '{"units": {"s1-odd-one-out.hint.0": {"url": "http://localhost:4006/files/lesson-audio/70d81e107e07918c1530e567cc040bd7c610f9911b906ab6866f85ad5ab9e6dc.mp3", "hash": "4568f2c5283619ef99275811abd263ac45684b64f8b04dc030bdbe6dff9cf571", "bytes": 25344, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/70d81e107e07918c1530e567cc040bd7c610f9911b906ab6866f85ad5ab9e6dc.mp3", "duration_ms": 4160}, "s1-odd-one-out.hint.1": {"url": "http://localhost:4006/files/lesson-audio/b4858a32729b8f54a2e70c53bfae2d79a637083dffadf459059c129ecc282206.mp3", "hash": "6a1f483d6aaa59e6e88d745f156bc05b574e54631b1412a098c6562c4332a77b", "bytes": 23904, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/b4858a32729b8f54a2e70c53bfae2d79a637083dffadf459059c129ecc282206.mp3", "duration_ms": 3920}, "s1-odd-one-out.prompt": {"url": "http://localhost:4006/files/lesson-audio/a7ab639b71b95dda85d5164d80532730f02e6394d60e7ec841ebdb3d56ddca04.mp3", "hash": "b83743558c06c8ad838aa75943fbd940b843afba4411be389a4ac11a04680f69", "bytes": 37296, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/a7ab639b71b95dda85d5164d80532730f02e6394d60e7ec841ebdb3d56ddca04.mp3", "duration_ms": 6160}, "s1-odd-one-out.choices": {"url": "http://localhost:4006/files/lesson-audio/6140ba2b8961c20d452e4a7c5e3c6f22303c09098e8580ec4f15c0b75f781448.mp3", "hash": "b5ba5173a71400fbd7c728712c602b49ab782785d5cb1615058e22dfb4e79ae3", "bytes": 25344, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/6140ba2b8961c20d452e4a7c5e3c6f22303c09098e8580ec4f15c0b75f781448.mp3", "duration_ms": 4160}, "s1-odd-one-out.explanation": {"url": "http://localhost:4006/files/lesson-audio/7b3497e4d1b0b9c576bea568758bccd205d4dbb379b7fea9077398216c90fe39.mp3", "hash": "4d2714a2b1fff1746e6e720dc1b769d0cb6793a656318d342e933cbc713d0af7", "bytes": 87696, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/7b3497e4d1b0b9c576bea568758bccd205d4dbb379b7fea9077398216c90fe39.mp3", "duration_ms": 14560}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('29159ba6-6f90-42be-9578-fda50515f345', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "budget-fit", "title": "Surte el mercado con $20", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular cuánto dinero queda después de comprar necesidades", "Decidir qué extras caben en un presupuesto limitado"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-surte", "xp": 15, "type": "budget_fit", "hints": ["Primero suma el precio de los limones y el azúcar.", "Resta esa suma de $20 para saber cuánto te queda."], "title": "Surte el mercado con $20", "payload": {"items": [{"id": "limones", "icon": "eco", "need": true, "label": "Limones", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/7c6e58628aa1152864fdb88cafe9311482650bd5e34e8d4717737f320c0d0bf3.png"}, {"id": "azucar", "icon": "bakery_dining", "need": true, "label": "Azúcar", "price": 6, "image_url": "http://localhost:4006/files/lesson-images/a3ac990bcb4030502bff340e9c6d760bff595bdff905be5da36927d07473e828.png"}, {"id": "hielo", "icon": "ac_unit", "need": false, "label": "Hielo", "price": 5, "image_url": "http://localhost:4006/files/lesson-images/cb156c37bc42c60d9c968b1728e2fe1ad55891405453730e14f0370f43fcb477.png"}, {"id": "popotes", "icon": "local_drink", "need": false, "label": "Popotes", "price": 3, "image_url": "http://localhost:4006/files/lesson-images/7b6ab89a7f1b2bbf2ea6c54ae236b8ff6ffcd7d506da06a973c16738fdce4706.png"}, {"id": "jarra", "icon": "local_cafe", "need": false, "label": "Jarra bonita", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/47dda1ca474c191e8a19787232f7886e7c46e3ddde2f7768581b7dfe708a1201.png"}], "budget": 20, "currency": "MXN", "must_buy_needs": true}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf tiene $20. Debe comprar limones ($8) y azúcar ($6). ¿Qué extra cabe en lo que sobra?", "difficulty": 2, "explanation_md": "Limones ($8) + azúcar ($6) = $14. Te sobran $6. El hielo cuesta $5, los popotes $3, la jarra $8. Con $6 puedes comprar hielo ($5) o popotes ($3), pero no la jarra ($8). Si compras la jarra, no alcanza para el azúcar y la limonada sale amarga.", "audio_segment_id": "s1-surte.prompt"}], "schema_version": 1}', '{"s1-surte": {}}', '{"units": {"s1-surte.hint.0": {"url": "http://localhost:4006/files/lesson-audio/3c10e794b0586ede95a039d96896e090dad651f613da3837f0353082d0aca084.mp3", "hash": "d94a0c0fea15add4ee45660b441ac80ac6b7ac459a13003652ff2138ddf96d72", "bytes": 20016, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3c10e794b0586ede95a039d96896e090dad651f613da3837f0353082d0aca084.mp3", "duration_ms": 3280}, "s1-surte.hint.1": {"url": "http://localhost:4006/files/lesson-audio/b4a1ebceec35df8d7f1adb71ca275802202805fa8ecd6244b0f334f7e017c3a4.mp3", "hash": "eac1ed5e35e0e6afc1e3c3839738e93efa4f16a49edbc483fbe1836103d3101a", "bytes": 25344, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b4a1ebceec35df8d7f1adb71ca275802202805fa8ecd6244b0f334f7e017c3a4.mp3", "duration_ms": 4160}, "s1-surte.prompt": {"url": "http://localhost:4006/files/lesson-audio/5ad44b33c99a5373fcf44a9da9b40d8b55ff03299507d3bdad58509317b692e5.mp3", "hash": "d6f6e68af15e832103fe7912871609ee9bc02d1be07c9ab03cf679c44f131090", "bytes": 50688, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5ad44b33c99a5373fcf44a9da9b40d8b55ff03299507d3bdad58509317b692e5.mp3", "duration_ms": 8400}, "s1-surte.explanation": {"url": "http://localhost:4006/files/lesson-audio/5ee41a9aa2ca62f60999d24ef3de43ddeb8b3ad0552f14729d2df182167b28f4.mp3", "hash": "15ffa6444c37b5164b024fe8153a20d8a62010bb8ef8e33b6fe98af21829a52e", "bytes": 154944, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5ee41a9aa2ca62f60999d24ef3de43ddeb8b3ad0552f14729d2df182167b28f4.mp3", "duration_ms": 25760}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58172086-898d-4095-acf1-3502b8607e76', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "story-branch", "title": "O preço do dia", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher o preço da limonada considerando o custo de produção e o lucro por copo.", "Observar como o preço afeta as vendas e o progresso em direção a uma meta de economia."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio", "xp": 20, "type": "story_branch", "hints": ["Se cobrar muito caro, talvez ninguém compre. Se cobrar muito barato, ganhará pouco por copo."], "title": "Escolha o preço", "payload": {"nodes": [{"id": "inicio", "choices": [{"id": "precio5", "next": "final5", "text_md": "5 pesos (o de sempre)"}, {"id": "precio3", "next": "final3", "text_md": "3 pesos (mais barato)"}, {"id": "precio10", "next": "final10", "text_md": "10 pesos (o dobro)"}], "emotion": "thinking", "text_md": "Está muito quente e seis vizinhos fazem fila na barraca de Liruf. Cada copo de limonada custa 2 pesos para fazer. Qual preço Liruf coloca hoje?", "character": "liruf"}, {"id": "final5", "choices": [{"id": "fin5", "next": null, "text_md": "Fim"}], "emotion": "happy", "text_md": "Os 6 vizinhos compram! Cada copo dá 3 pesos de lucro (5 - 2 = 3). Liruf ganha 18 pesos hoje. Bom progresso em direção ao violão de 80!", "character": "liruf"}, {"id": "final3", "choices": [{"id": "fin3", "next": null, "text_md": "Fim"}], "emotion": "surprised", "text_md": "Os 6 compram, mas você ganha só 1 peso por copo (3 - 2 = 1). Liruf ganha apenas 6 pesos. Quase não avança em direção ao violão.", "character": "liruf"}, {"id": "final10", "choices": [{"id": "fin10", "next": null, "text_md": "Fim"}], "emotion": "surprised", "text_md": "Os vizinhos fazem careta e vão para a sorveteria. Liruf fica com a jarra cheia. Não vende nada e não ganha nada para o violão.", "character": "liruf"}], "start_node": "inicio"}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/8046a459b1d4c767bfe147be95d945265f75936115afb13d308e7b5574137977.png", "prompt_md": "Liruf precisa definir o preço de hoje. Cada copo custa 2 pesos para fazer. Quanto ele vai cobrar?", "difficulty": 2, "explanation_md": "Liruf escolheu um preço e viu o quanto avançou em direção ao violão de 80 pesos.", "audio_segment_id": "s1-precio.prompt"}], "schema_version": 1}', '{"s1-precio": {"qualities": [{"score": 100, "node_id": "inicio", "choice_id": "precio5"}, {"score": 30, "node_id": "inicio", "choice_id": "precio3"}, {"score": 0, "node_id": "inicio", "choice_id": "precio10"}]}}', '{"units": {"s1-precio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/10d796b8f6b7b54c230670c94d223690f3fbb5643f4394ff516391e236145011.mp3", "hash": "13f92cecbba99fb2f89caf91078304e1e0a6b73241a5e1275bf7cc349a569629", "bytes": 43056, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/10d796b8f6b7b54c230670c94d223690f3fbb5643f4394ff516391e236145011.mp3", "duration_ms": 7120}, "s1-precio.prompt": {"url": "http://localhost:4006/files/lesson-audio/e69507deec6685cf7ac10120da80bef533f3fd4587cc5e318715dd9fff815e56.mp3", "hash": "d9ea4d0df8cd0afffe52f7577e3ca3c7c1f08959781e6e92ff0baaa3a5794cbe", "bytes": 44928, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/e69507deec6685cf7ac10120da80bef533f3fd4587cc5e318715dd9fff815e56.mp3", "duration_ms": 7440}, "s1-precio.explanation": {"url": "http://localhost:4006/files/lesson-audio/25a648203117235199338f683fec491ee50adbe822c3948945acf3aaddd3c5cd.mp3", "hash": "78c35adeef68f2e93cf4c4a46424b4ecd3d848c0ec7e961d406aa06a958898db", "bytes": 40176, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/25a648203117235199338f683fec491ee50adbe822c3948945acf3aaddd3c5cd.mp3", "duration_ms": 6640}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f75b3e23-fb31-40cf-9b58-e918769e51b9', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "yes-no-cases", "title": "Sim ou não: ajuda a barraca?", "locale": "pt-BR", "subject": "money", "objectives": ["Decidir se um gasto ajuda a barraca de limonada (sim) ou é uma tentação (não)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-yes-no-cases", "xp": 10, "type": "yes_no_cases", "hints": ["Pense: isso ajuda a vender mais limonada ou a guardar o dinheiro?", "Se é só para brincar hoje, melhor esperar."], "title": "Sim ou não: ajuda a barraca?", "payload": {"cases": [{"id": "c1", "text_md": "Comprar 10 limões para fazer mais limonada.", "image_url": "http://localhost:4006/files/lesson-images/a2ad28cda3cb666be83ea55dc40801357e05c3b027bf79237cf6c703d2d508b3.png"}, {"id": "c2", "text_md": "Comprar um brinquedo de $5 para brincar hoje.", "image_url": "http://localhost:4006/files/lesson-images/cf5dfec25d52573b2c0f51f4adc60354bdd90837f2213bd44184c51df612649c.png"}, {"id": "c3", "text_md": "Comprar 20 copos descartáveis para servir a limonada.", "image_url": "http://localhost:4006/files/lesson-images/bbb098aafaa1cdf20d567879c5678883a0387f3f2036b0b0e332721619faf92a.png"}, {"id": "c4", "text_md": "Comprar um saco de doces de $3 para você.", "image_url": "http://localhost:4006/files/lesson-images/c0aff6c9ba78bb398e248c5757354c9b9f32619cb07069334c0a3b18a18e822e.png"}], "rule_md": "Pergunte-se: **isso ajuda a barraca a funcionar melhor ou a ganhar mais dinheiro?** Se sim, é um gasto que vale a pena. Se não, é uma tentação que pode esperar."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Aperte SIM se ajuda a barraca, NÃO se é tentação.", "difficulty": 1, "explanation_md": "Comprar mais limões ajuda a fazer mais limonada e vender mais. Um brinquedo novo não ajuda a barraca hoje.", "audio_segment_id": "s1-yes-no-cases.prompt"}], "schema_version": 1}', '{"s1-yes-no-cases": {"applies_ids": ["c1", "c3"]}}', '{"units": {"s1-yes-no-cases.hint.0": {"url": "http://localhost:4006/files/lesson-audio/80bee585d76a5c329fb2fecb8b1453857e11052fdd8ffb553c20d4bdab0d255c.mp3", "hash": "6ff680569fb65a4ae7a223e2f0cb2fee984b8f9bc9d23390f4dbb81846b994f1", "bytes": 28224, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/80bee585d76a5c329fb2fecb8b1453857e11052fdd8ffb553c20d4bdab0d255c.mp3", "duration_ms": 4640}, "s1-yes-no-cases.hint.1": {"url": "http://localhost:4006/files/lesson-audio/0b4023f5a7f88ffa669105d125bc11cb49ca969f26458cb4c1208d59859390f8.mp3", "hash": "0c113160606c6d88a2d63a61399d46f8a579be4b4665496e6b0c4c05ca2ac4e1", "bytes": 20448, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0b4023f5a7f88ffa669105d125bc11cb49ca969f26458cb4c1208d59859390f8.mp3", "duration_ms": 3360}, "s1-yes-no-cases.prompt": {"url": "http://localhost:4006/files/lesson-audio/b675744064fe57e33de9cae12a0f6ed09a2c78a88b6a627827513b86d1fa36dc.mp3", "hash": "53231541cdc075507ff4a0e98671fa56b59ed1474c6797c0b8ba2c30cd0c9e3a", "bytes": 24768, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b675744064fe57e33de9cae12a0f6ed09a2c78a88b6a627827513b86d1fa36dc.mp3", "duration_ms": 4080}, "s1-yes-no-cases.choices": {"url": "http://localhost:4006/files/lesson-audio/dd0218c52e55207ac5d9546da1499bb0ac370a25b458114d706671fda785c710.mp3", "hash": "404b3e7f4ace2db1e7db85155badaeda529070c2ee5bb0959ecc44ab10bea1c1", "bytes": 85248, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/dd0218c52e55207ac5d9546da1499bb0ac370a25b458114d706671fda785c710.mp3", "duration_ms": 14160}, "s1-yes-no-cases.explanation": {"url": "http://localhost:4006/files/lesson-audio/e4a1a457633bb69ad9a486b5c916a5154fbff79a563483ac00c8c28fa8f9e6e7.mp3", "hash": "c95dfbdd9b3ced2471b1d2279d599d3b0a35f5688a71f1420dbc0d1ffc338ab2", "bytes": 48384, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/e4a1a457633bb69ad9a486b5c916a5154fbff79a563483ac00c8c28fa8f9e6e7.mp3", "duration_ms": 8000}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9bdad6a7-ed32-42f2-83c9-554afe044403', 'es-MX', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "savings-goal", "title": "El plan de ahorro de Liruf", "locale": "es-MX", "subject": "money", "objectives": ["Calcular cuántas semanas se necesita ahorrar para alcanzar una meta de 80 pesos con diferentes ahorros semanales."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-plan-ahorro", "xp": 15, "type": "savings_goal", "hints": ["Cuenta de 10 en 10 hasta llegar a 80: 10, 20, 30... ¿cuántos saltos?"], "title": "Semanas para la guitarra", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [10]}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Liruf pone 10 pesos en su alcancía cada semana. ¿Cuántas semanas hasta tener 80 pesos?", "difficulty": 1, "explanation_md": "Cada semana son 10 pesos. Para llegar a 80, necesitas 8 semanas: 10+10+10+10+10+10+10+10 = 80. ¡Así Liruf puede comprar la guitarra!", "audio_segment_id": "s1-plan-ahorro.prompt"}], "schema_version": 1}', '{"s1-plan-ahorro": {"correct": {"10": 8}}}', '{"units": {"s1-plan-ahorro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/7ab5daa2c076c65f1ba3c225e089318d2cfad65b8efe57714e714ef624265fa1.mp3", "hash": "a688c579d80b99039ac729b68a35a87b3b0c059739dad8ca1e6e05012cf36bf6", "bytes": 44064, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/7ab5daa2c076c65f1ba3c225e089318d2cfad65b8efe57714e714ef624265fa1.mp3", "duration_ms": 7280}, "s1-plan-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/ca98668d4693ff7e087a70c0bd5eaced95716bfa27d4698703815c52beb4abe8.mp3", "hash": "34a9e2043772795c4b8cb41238291e219ffe1f0f53c1daa84111568cf2d3b67a", "bytes": 42624, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/ca98668d4693ff7e087a70c0bd5eaced95716bfa27d4698703815c52beb4abe8.mp3", "duration_ms": 7040}, "s1-plan-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/471ded42fc43faadab0050aa2657ac6c869868163791a30beaa6b64c2582a5d0.mp3", "hash": "e8303cb4dfe5fb5069d2dc737219cd73d2b772bc003fabc5e030a80be63b4d1d", "bytes": 85824, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/471ded42fc43faadab0050aa2657ac6c869868163791a30beaa6b64c2582a5d0.mp3", "duration_ms": 14240}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08f47096-e44f-4b4e-822f-472c6fd87425', 'es-MX', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "speed-tap", "title": "¡Rápido! ¿Ayuda o capricho?", "locale": "es-MX", "subject": "money", "objectives": ["Distinguir gastos que ayudan al puesto de limonada de caprichos que no ayudan.", "Tomar decisiones rápidas bajo presión de tiempo."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-speed-tap", "xp": 15, "type": "speed_tap", "hints": ["Piensa: ¿esto ayuda a hacer o vender limonada?", "Los caprichos no ayudan al puesto, solo gastan dinero."], "title": "Atrapa lo que ayuda", "payload": {"items": [{"id": "limones", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/a24db5a22058562ecb2a66839878b257aeae7c5f1070f9f30016ca5141b1fe7f.png"}, {"id": "vasos", "text_md": "Vasos", "image_url": "http://localhost:4006/files/lesson-images/38acc98095a6a99be59da2b351a6b49a776583ba527451c07e865bb4edf8f526.png"}, {"id": "azucar", "text_md": "Azúcar", "image_url": "http://localhost:4006/files/lesson-images/85fece69c95d9cc7682f486924847f002e4f3dad7896671c725de82a19bc9321.png"}, {"id": "hielo", "text_md": "Hielo", "image_url": "http://localhost:4006/files/lesson-images/606d113c486c060304af239efe523f3c5e2dcec06f5393008cb4925f81bf1c1e.png"}, {"id": "cartel", "text_md": "Cartel llamativo", "image_url": "http://localhost:4006/files/lesson-images/5dc8b8de4238d7d70b3fe1ae8eb346f6241b6265a6421ba0fd4624b716b11084.png"}, {"id": "calcomania", "text_md": "Calcomanía de dinosaurio", "image_url": "http://localhost:4006/files/lesson-images/1503a41d870e9997d62fa9c66dd19bcd206dcab330f1c9a1769485d526a65f63.png"}, {"id": "dulce", "text_md": "Dulce", "image_url": "http://localhost:4006/files/lesson-images/b7710e4133ef3251810a0129f3a69b49d853cd19084a690d08d3a39e4af7f35f.png"}, {"id": "juguete", "text_md": "Juguete", "image_url": "http://localhost:4006/files/lesson-images/196112c6676f17aa11d1a303c21b1b4463cfab5216d96c12a512d368d22416e5.png"}], "seconds": 15, "instruction_md": "Toca las tarjetas que ayudan al puesto de limonada. ¡Rápido!"}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "¡Recuerdas decidir si un gasto ayuda al puesto? Toca solo lo que ayuda a vender más limonada.", "difficulty": 2, "explanation_md": "Los limones, vasos, azúcar, hielo y el cartel ayudan a vender más limonada. La calcomanía, el dulce y el juguete son caprichos que no ayudan al puesto.", "audio_segment_id": "s1-speed-tap.prompt"}], "schema_version": 1}', '{"s1-speed-tap": {"target_ids": ["limones", "vasos", "azucar", "hielo", "cartel"]}}', '{"units": {"s1-speed-tap.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e82d2a09dab665b3f4404e00c6130374bb765f5e43d54bebd89e75af5686adac.mp3", "hash": "b74c6a35b9c21ba38793887f8364602e372009ad7af6ed37f22293a99f7ea736", "bytes": 21024, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/e82d2a09dab665b3f4404e00c6130374bb765f5e43d54bebd89e75af5686adac.mp3", "duration_ms": 3440}, "s1-speed-tap.hint.1": {"url": "http://localhost:4006/files/lesson-audio/d3ee91b4b93e39750ed2d14e8a0a01fafcbf0228b3241063620f1ec851a520f8.mp3", "hash": "17b95cb4eb8fba513db9fce3d2b39bfc2d98a6558372d6c628f26281a3279c9d", "bytes": 23328, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/d3ee91b4b93e39750ed2d14e8a0a01fafcbf0228b3241063620f1ec851a520f8.mp3", "duration_ms": 3840}, "s1-speed-tap.prompt": {"url": "http://localhost:4006/files/lesson-audio/960122950e5eebb6af0c45b4d970470751c17f60bc012fa6e8b71179238e2c96.mp3", "hash": "fa377c9b03ff99157b69eef6ce2ef96aeb685a9e5842da4098ed11339236f010", "bytes": 39744, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/960122950e5eebb6af0c45b4d970470751c17f60bc012fa6e8b71179238e2c96.mp3", "duration_ms": 6560}, "s1-speed-tap.explanation": {"url": "http://localhost:4006/files/lesson-audio/3d04efd763b93efc6872ac7621ae8582a56ef71d3f88ab370558b8f6b962ad05.mp3", "hash": "e28f8c453ebc11c198405ee21b677a65dbca34ff99b71f390ecda15aaed6a1ab", "bytes": 73728, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/3d04efd763b93efc6872ac7621ae8582a56ef71d3f88ab370558b8f6b962ad05.mp3", "duration_ms": 12240}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ea98847f-02a1-4527-97a4-36921728b56d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "cause-effect", "title": "Causa e efeito na barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Conectar causas e efeitos da barraca: dia ensolarado → mais sede → mais copos vendidos; aumentar o preço para o dobro → menos clientes."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-causa-efecto", "xp": 10, "type": "cause_effect", "hints": ["Pense: o que aconteceu primeiro no dia?"], "title": "O que aconteceu na barraca?", "payload": {"slots": 5, "events": [{"id": "e1", "text_md": "Faz muito sol"}, {"id": "e2", "text_md": "As pessoas têm mais sede"}, {"id": "e3", "text_md": "Liruf vende 10 copos a $2"}, {"id": "e4", "text_md": "Liruf aumenta o preço para $4"}, {"id": "e5", "text_md": "Só vende 3 copos"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf vendeu 10 copos a $2 cada. Depois aumentou o preço para $4 e vendeu 3. Ordene os eventos.", "difficulty": 1, "explanation_md": "Com sol, as pessoas têm mais sede e compram mais. Mas se o preço sobe muito, compram menos. Liruf aprendeu que não deve aumentar tanto o preço.", "audio_segment_id": "s1-causa-efecto.prompt"}], "schema_version": 1}', '{"s1-causa-efecto": {"chain": ["e1", "e2", "e3", "e4", "e5"]}}', '{"units": {"s1-causa-efecto.hint.0": {"url": "http://localhost:4006/files/lesson-audio/aaf584c326d9283f025c22b2357ab43a7ee189796fe454312be52b1ea8d7e458.mp3", "hash": "47f058ae10e31154d1205753fd3facc662d86b66783b8bd045b785d08bb859d7", "bytes": 15696, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/aaf584c326d9283f025c22b2357ab43a7ee189796fe454312be52b1ea8d7e458.mp3", "duration_ms": 2560}, "s1-causa-efecto.prompt": {"url": "http://localhost:4006/files/lesson-audio/c9cfa6b950753a0cac1541413e47787a8640d87c3df6f7520b4c8150f81706bc.mp3", "hash": "f8d2b419d7c914dab7c47c6906e671beba0a6c05e494896fa09204e005a1afb1", "bytes": 57456, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c9cfa6b950753a0cac1541413e47787a8640d87c3df6f7520b4c8150f81706bc.mp3", "duration_ms": 9520}, "s1-causa-efecto.explanation": {"url": "http://localhost:4006/files/lesson-audio/7da900c1bce49ad3f88923002821b19244494863e88b67c06a8862b5f16a25f5.mp3", "hash": "cbec3a27b8cd8208823e1b8821babada11ec9d304a194833c05fd2526bc1c22e", "bytes": 60336, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7da900c1bce49ad3f88923002821b19244494863e88b67c06a8862b5f16a25f5.mp3", "duration_ms": 10000}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5bcbf28d-86a2-47d1-9003-23897d9d4f57', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "group-sets", "title": "Sort the money from the box", "locale": "en-US", "subject": "mixed", "objectives": ["Group coins with coins and bills with bills to count more easily."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-group-money", "xp": 10, "type": "group_sets", "hints": ["Coins are round and made of metal; bills are paper and rectangular.", "Look for the group that says ''Coins'' for coins, and ''Bills'' for bills."], "title": "Separate the money", "payload": {"items": [{"id": "coin1", "text_md": "$1 coin", "image_url": "http://localhost:4006/files/lesson-images/bfc0a85734f8a789fa2750b221d3830001718e847a8b1c5bdb746d182b3ef055.png"}, {"id": "coin2", "text_md": "$2 coin", "image_url": "http://localhost:4006/files/lesson-images/473e6fccc789502d165c5fa9d50665f6b482d7c2791427d86c829b2a1dacb24a.png"}, {"id": "coin3", "text_md": "$5 coin", "image_url": "http://localhost:4006/files/lesson-images/6e5385d7d7d836bb126754da7794fe73cbcaa6b0eacbdd15d0791ff2a269ebfd.png"}, {"id": "bill1", "text_md": "$20 bill"}, {"id": "bill2", "text_md": "$50 bill"}], "set_a": "Coins", "set_b": "Bills"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Tap each coin and each bill to put them in their group.", "difficulty": 1, "explanation_md": "Liruf separated 3 coins and 2 bills. This makes it easier to count how much money there is.", "audio_segment_id": "s1-group-money.prompt"}], "schema_version": 1}', '{"s1-group-money": {"zones": {"bill1": "b", "bill2": "b", "coin1": "a", "coin2": "a", "coin3": "a"}}}', '{"units": {"s1-group-money.hint.0": {"url": "http://localhost:4006/files/lesson-audio/70996a8826ee55d6c7069eff5bd91b82196780f91c5d3c35e359952b5cc02640.mp3", "hash": "c7159ecb2fafecd182c0909cb3639966954850105d81fb27815323f796454078", "bytes": 23904, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/70996a8826ee55d6c7069eff5bd91b82196780f91c5d3c35e359952b5cc02640.mp3", "duration_ms": 3920}, "s1-group-money.hint.1": {"url": "http://localhost:4006/files/lesson-audio/2ef672eb7bcf73561a340eaebcea9c9aeafa780ba324d1fb9402762bf2bfb977.mp3", "hash": "c5814b108ced5d74f4ca26040b20b114dd852ea9e9b0b0fb3556afb10f86bd5b", "bytes": 22464, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/2ef672eb7bcf73561a340eaebcea9c9aeafa780ba324d1fb9402762bf2bfb977.mp3", "duration_ms": 3680}, "s1-group-money.prompt": {"url": "http://localhost:4006/files/lesson-audio/fa46a14a3ffd2d4df4b12e272bb73de037ddc213ddc72a5f3ee429f28b04cc7d.mp3", "hash": "f941a4a684db0fadbf590f034d7b394d00ed66c269f63ee2110d10505a93028b", "bytes": 17568, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/fa46a14a3ffd2d4df4b12e272bb73de037ddc213ddc72a5f3ee429f28b04cc7d.mp3", "duration_ms": 2880}, "s1-group-money.explanation": {"url": "http://localhost:4006/files/lesson-audio/55deca23b3050ef8263bd962c9d2ea27f02b7308e8f26f578fb2b9d6b799a8d6.mp3", "hash": "48806bf70b78f692766c36ced7e90d752d54e2bc48ee35ebb518dc6738f2dfb7", "bytes": 31968, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/55deca23b3050ef8263bd962c9d2ea27f02b7308e8f26f578fb2b9d6b799a8d6.mp3", "duration_ms": 5280}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('bd130a62-6800-475b-8af6-59f14ffebc50', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "number-input", "title": "Escrever números: lucro da barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular e escrever quanto Liruf ganhou no total se vendeu 4 copos a 5 pesos cada (20 pesos)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia-total", "xp": 10, "type": "number_input", "hints": ["Cada copo dá 5 pesos. Quanto dão 4 copos?", "Você pode somar 5 + 5 + 5 + 5."], "title": "Lucro do dia", "payload": {"unit": "pesos", "decimals_hint": 0}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/60b48070049fcff4e830f88af3a4e07e1021819df53b46be8a09fdd6397e8610.png", "prompt_md": "Liruf vendeu 4 copos de limonada a 5 pesos cada. Quanto dinheiro há na caixa?", "difficulty": 1, "explanation_md": "Liruf ganhou 20 pesos porque 4 copos × 5 pesos cada = 20 pesos.", "audio_segment_id": "s1-ganancia-total.prompt"}], "schema_version": 1}', '{"s1-ganancia-total": {"value": 20, "tolerance": 0}}', '{"units": {"s1-ganancia-total.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9df87013f454b56a830a056655e46981ba4b4d4dc5365f85a4672c26d9f46acd.mp3", "hash": "2a3e41e626740e9aacd63e875a412d1679c62e1edcca7ef657b10511e1a77587", "bytes": 27648, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/9df87013f454b56a830a056655e46981ba4b4d4dc5365f85a4672c26d9f46acd.mp3", "duration_ms": 4560}, "s1-ganancia-total.hint.1": {"url": "http://localhost:4006/files/lesson-audio/5be556fb34305903bf122c63bd37d8111ab65710386808a7ee748d4ece9d3595.mp3", "hash": "faf9d063790335cfb6a16f0407707704ce5b541930a5b759251a7ba2575f19b3", "bytes": 28656, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5be556fb34305903bf122c63bd37d8111ab65710386808a7ee748d4ece9d3595.mp3", "duration_ms": 4720}, "s1-ganancia-total.prompt": {"url": "http://localhost:4006/files/lesson-audio/0662cd706f8ea4318e59a1ae93372276a0e4e5f4708d93e0a1d075ffaa981dba.mp3", "hash": "146d911e404e83a6e823d303062a9a972a1dcc1b66f023c1e7cd30a3677b3f4d", "bytes": 44496, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0662cd706f8ea4318e59a1ae93372276a0e4e5f4708d93e0a1d075ffaa981dba.mp3", "duration_ms": 7360}, "s1-ganancia-total.explanation": {"url": "http://localhost:4006/files/lesson-audio/985127e913029858329d88970aa0f721d449539c36d08ddabd5bc9522d1335ee.mp3", "hash": "6a5d08b2b53ad45a5bcc8eaf20363aface9af75f2b85445a90de44efc6530667", "bytes": 39744, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/985127e913029858329d88970aa0f721d449539c36d08ddabd5bc9522d1335ee.mp3", "duration_ms": 6560}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('e0e06311-1e57-4b7b-a3ee-04c82227ceae', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fair-trade", "title": "Trueque justo", "locale": "es-MX", "subject": "money", "objectives": ["Decidir si un trueque es justo comparando el valor de dos ofertas"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fair-trade", "xp": 15, "type": "fair_trade", "hints": ["Cada vaso cuesta 5 pesos. ¿Cuánto valen los 2 vasos juntos?", "La bolsa de limones cuesta 10 pesos. Compara ese número con el valor de los 2 vasos."], "title": "Trueque justo", "payload": {"offer_a": {"qty": 2, "icon": "local_drink", "label": "Vaso de limonada", "image_url": "http://localhost:4006/files/lesson-images/18b0546541eab9afa6c6a368dfa2ea118a0c365835b50d7392f9c6ecdb51e2b0.png"}, "offer_b": {"qty": 1, "icon": "agriculture", "label": "Bolsa de limones", "image_url": "http://localhost:4006/files/lesson-images/b8950d5268abfb01e8691c7b7142b344ddd0f066f5c07784a3ba820260f7ff57.png"}, "rate_md": "Cada vaso cuesta 5 pesos. La bolsa de limones cuesta 10 pesos."}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "¿Es justo cambiar 2 vasos de limonada por una bolsa de limones?", "difficulty": 2, "explanation_md": "2 vasos valen 10 pesos (5+5) y la bolsa de limones también vale 10 pesos. ¡Es un trueque justo!", "audio_segment_id": "s1-fair-trade.prompt"}], "schema_version": 1}', '{"s1-fair-trade": {"verdict": "fair"}}', '{"units": {"s1-fair-trade.hint.0": {"url": "http://localhost:4006/files/lesson-audio/52caced3049b3ac20ff139b0552873a9c870fa2fa8813c319fb1418bf43f344a.mp3", "hash": "0e509fdb94b2f88d3a01da6b24089b100e9183ba6c071cbfdfefba77b7c860bc", "bytes": 29088, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/52caced3049b3ac20ff139b0552873a9c870fa2fa8813c319fb1418bf43f344a.mp3", "duration_ms": 4800}, "s1-fair-trade.hint.1": {"url": "http://localhost:4006/files/lesson-audio/77fe0d5843a0be517cbe2c52453eeaddd0aa732e3f805b232400f836a0d92a6f.mp3", "hash": "f8f35d414fb99784c2ebd989ffa86b751c2cedd90a553e63dd99161964fbf841", "bytes": 37728, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/77fe0d5843a0be517cbe2c52453eeaddd0aa732e3f805b232400f836a0d92a6f.mp3", "duration_ms": 6240}, "s1-fair-trade.prompt": {"url": "http://localhost:4006/files/lesson-audio/d94a30fe5488503563343b5618e5e1e33f56970423a530e7508b7808eaca23eb.mp3", "hash": "adab3faee9796e2c7f9580d374234d183be7992b33b8ca5a3a631f3621813d4e", "bytes": 25776, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/d94a30fe5488503563343b5618e5e1e33f56970423a530e7508b7808eaca23eb.mp3", "duration_ms": 4240}, "s1-fair-trade.explanation": {"url": "http://localhost:4006/files/lesson-audio/a583dacc7d392a5043786376257996851a5a440c0fbe39f6272959e4abe2663f.mp3", "hash": "56766449e9ec977b81765cd6795d53e03b1b53316abdbaad3c90ac76df0f0178", "bytes": 48816, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/a583dacc7d392a5043786376257996851a5a440c0fbe39f6272959e4abe2663f.mp3", "duration_ms": 8080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('99bea18a-9bc0-4fca-91fe-aa5b44c0ea6e', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "picture-choice", "title": "¿Dónde guardar las ganancias?", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir el lugar más seguro para guardar dinero comparando opciones"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-guardar-ganancias", "xp": 10, "type": "picture_choice", "hints": ["Piensa: ¿dónde no se puede caer ni perder el dinero?", "Busca un lugar que tenga candado o llave."], "title": "Lugar seguro", "payload": {"options": [{"id": "alcancia", "icon": "savings", "label": "Alcancía con llave", "image_url": "http://localhost:4006/files/lesson-images/fc53490dcfdebcbd1c908e67f9cfd5dfbace2ec64bb17a3760c5b410e23a5ca1.png"}, {"id": "bolsillo", "icon": "checkroom", "label": "Bolsillo roto", "image_url": "http://localhost:4006/files/lesson-images/3ed6394fc1abacd88a06145cd482977b16e457ec3e203c3995af07f6b4210993.png", "rationale_md": "El bolsillo roto deja caer las monedas, así que no es seguro."}, {"id": "mesa", "icon": "table_restaurant", "label": "Mesa del puesto", "image_url": "http://localhost:4006/files/lesson-images/d667355eaf618db630a17da6e8598bb71fe4c801dfa628caeee5bb03ac2b5b43.png", "rationale_md": "La mesa del puesto está a la vista de todos y cualquiera puede tomar el dinero."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Ayer Liruf ahorró 5 pesos de cada venta. Hoy ya tiene 20 pesos. ¿Dónde los guarda mejor?", "difficulty": 1, "explanation_md": "La alcancía con llave es la más segura porque nadie más puede abrirla. El bolsillo roto deja caer las monedas y la mesa del puesto está a la vista de todos.", "audio_segment_id": "s1-guardar-ganancias.prompt"}], "schema_version": 1}', '{"s1-guardar-ganancias": {"correct_option_id": "alcancia"}}', '{"units": {"s1-guardar-ganancias.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f9ce2cc8ae130d785d9c55e4fb9b58bd656cf457d9caec99e11bca395d039fc1.mp3", "hash": "a300413174c7f3f320882b0021c19ba7890c8960cf72ef8ce66ce4f60569c4b5", "bytes": 22896, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/f9ce2cc8ae130d785d9c55e4fb9b58bd656cf457d9caec99e11bca395d039fc1.mp3", "duration_ms": 3760}, "s1-guardar-ganancias.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c0f4f0a8c0293bd8c53f34acbabfdfcb619ae22de665b5bfbabfe446b1c17e5a.mp3", "hash": "d2a339ba3fb912cea5d6af9425b3fc7d1a764fbb00a75ccf7e5a4d380806af0c", "bytes": 16704, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/c0f4f0a8c0293bd8c53f34acbabfdfcb619ae22de665b5bfbabfe446b1c17e5a.mp3", "duration_ms": 2720}, "s1-guardar-ganancias.prompt": {"url": "http://localhost:4006/files/lesson-audio/b0d22984217c2293af58e7f1dae628fd22d2dd6ce2bc7675ab25417023ec7397.mp3", "hash": "052598a3fe4488988292011b5b20fa1dd9e60d995e75171b20d9751d4f8fd5ba", "bytes": 44496, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/b0d22984217c2293af58e7f1dae628fd22d2dd6ce2bc7675ab25417023ec7397.mp3", "duration_ms": 7360}, "s1-guardar-ganancias.choices": {"url": "http://localhost:4006/files/lesson-audio/23d21a887ac581a8ab4ee2e1df05095f36b3ce516d4e378b56a8905b4e4ff0e9.mp3", "hash": "ae9efcc8b3b806657c089dd124203e91622ce26eedf0698e44cfbb0bfdb2701e", "bytes": 31968, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/23d21a887ac581a8ab4ee2e1df05095f36b3ce516d4e378b56a8905b4e4ff0e9.mp3", "duration_ms": 5280}, "s1-guardar-ganancias.explanation": {"url": "http://localhost:4006/files/lesson-audio/8011f12663132b2aef2522d3d6cf98e216252aeb0545b6b7801696c2f21a5d39.mp3", "hash": "bf5efe64cf4082e44adb426c6a14d22a66fc485bacb6bc3d7c4b360e3dd3b842", "bytes": 63648, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/8011f12663132b2aef2522d3d6cf98e216252aeb0545b6b7801696c2f21a5d39.mp3", "duration_ms": 10560}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4a340725-6bd9-48c4-9c1a-d8641c86b7a1', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "evidence-hunt", "title": "Cacería de evidencia en el recibo", "locale": "es-MX", "subject": "mixed", "objectives": ["Buscar en el recibo del mercado la evidencia exacta de cuánto costaron los limones."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-evidence-hunt", "xp": 10, "type": "evidence_hunt", "hints": ["Busca la palabra ''limones'' en el recibo.", "El precio está al lado de la palabra ''limones''."], "title": "El recibo arrugado", "payload": {"claim_md": "Liruf dice: ''Gasté 20 pesos en limones en el mercado.''", "sentences": [{"id": "s1-line1", "text_md": "Limones — 15"}, {"id": "s1-line2", "text_md": "Azúcar — 5"}, {"id": "s1-line3", "text_md": "Vasos — 8"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/2d8df33f938e88337dc34b0a4a5edfa6eb5cfd087d7d6657bf77e7a38f313ada.png", "prompt_md": "Toca la línea del recibo que muestra cuánto costaron los limones.", "difficulty": 1, "explanation_md": "La línea que dice ''limones'' y ''15'' es la evidencia exacta del costo de los limones. Así como en la gráfica de la clase pasada buscaste el día con más ventas, aquí buscas la línea correcta en el recibo.", "audio_segment_id": "s1-evidence-hunt.prompt"}], "schema_version": 1}', '{"s1-evidence-hunt": {"evidence_ids": ["s1-line1"]}}', '{"units": {"s1-evidence-hunt.hint.0": {"url": "http://localhost:4006/files/lesson-audio/fb7826e464462a148179aa5e5b36e777579a6f5bc320d03a029f7271eda9657f.mp3", "hash": "9dc348d6c577ded367e5e2bf3a932d02ece2acbca1b1d167b64fc01a29331253", "bytes": 16704, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/fb7826e464462a148179aa5e5b36e777579a6f5bc320d03a029f7271eda9657f.mp3", "duration_ms": 2720}, "s1-evidence-hunt.hint.1": {"url": "http://localhost:4006/files/lesson-audio/3a6f686e16f55a7341a97a13d23493147a924560451be9fe4b8f969998d7c7d3.mp3", "hash": "3b035e369b5683425980ac1cf002d7fdeb3c392bfba61e7dcada1eb4c2299943", "bytes": 19008, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3a6f686e16f55a7341a97a13d23493147a924560451be9fe4b8f969998d7c7d3.mp3", "duration_ms": 3120}, "s1-evidence-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/040eeec38f32ca12b748db9be17340314a9d10f1116b9e1689d068c18877a015.mp3", "hash": "9df416b6bab82548f1347ea6a8e1666f1e821b0da508b10a71436727d690c856", "bytes": 27648, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/040eeec38f32ca12b748db9be17340314a9d10f1116b9e1689d068c18877a015.mp3", "duration_ms": 4560}, "s1-evidence-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/83e0501397ed1ba813477a485a4fe816201f1e4fe59288aed5ff970c52f2eedf.mp3", "hash": "62624fc231e48474d09f02d4f064f7593bcf0914a21f36d0b9257df6b892b4b1", "bytes": 78048, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/83e0501397ed1ba813477a485a4fe816201f1e4fe59288aed5ff970c52f2eedf.mp3", "duration_ms": 12960}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5cfeb5fa-1115-414d-9498-5cf6271b6245', 'pt-BR', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "robot-path", "title": "A rota do entregador", "locale": "pt-BR", "subject": "mixed", "objectives": ["Guiar o carrinho entregador pela grade do bairro até a casa do cliente gastando a menor quantidade de passos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-robot-path", "xp": 15, "type": "robot_path", "hints": ["O carrinho começa olhando para cima. Para onde ele deve ir primeiro?", "Conte as casinhas da saída até a meta."], "title": "Rota até o cliente", "payload": {"goal": {"x": 2, "y": 2}, "grid": {"h": 3, "w": 3}, "start": {"x": 0, "y": 0, "dir": "up"}, "walls": [], "commands": ["forward", "forward", "right"], "max_commands": 3}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "A bateria só dá para 3 passos. Leve o carrinho até a casa.", "difficulty": 2, "explanation_md": "O carrinho avançou para cima e depois para a direita para chegar à casa do cliente em 3 passos. Rota eficiente! Assim você economiza bateria, como economizar dinheiro.", "audio_segment_id": "s1-robot-path.prompt"}], "schema_version": 1}', '{"s1-robot-path": {}}', '{"units": {"s1-robot-path.hint.0": {"url": "http://localhost:4006/files/lesson-audio/58cbad30f66c4c4affc6a2074d96cc1d690050d0569a04aabb85db8de0d4e071.mp3", "hash": "e9f91caa3a26b8a09df56ad1bd60a3ebf22bb247624f10dfe6f95f0af356297c", "bytes": 29088, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/58cbad30f66c4c4affc6a2074d96cc1d690050d0569a04aabb85db8de0d4e071.mp3", "duration_ms": 4800}, "s1-robot-path.hint.1": {"url": "http://localhost:4006/files/lesson-audio/16a940af2b6c12f522da992a4a5370fc1d67404e8b7e1166dc489443073dd7cb.mp3", "hash": "07e87741811427bbee239519d651ca8e34788b2f0a7f41801a8955a8d135652b", "bytes": 16704, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/16a940af2b6c12f522da992a4a5370fc1d67404e8b7e1166dc489443073dd7cb.mp3", "duration_ms": 2720}, "s1-robot-path.prompt": {"url": "http://localhost:4006/files/lesson-audio/19b4e36439eb1e848bc1cdd3990f75ef167581bce01a52c06d01b7bb0471b47e.mp3", "hash": "b6d70a9c616b8e063d0d04a64462fe26767470e0c3dfc4cfa6c80f5fe8189e90", "bytes": 31968, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/19b4e36439eb1e848bc1cdd3990f75ef167581bce01a52c06d01b7bb0471b47e.mp3", "duration_ms": 5280}, "s1-robot-path.explanation": {"url": "http://localhost:4006/files/lesson-audio/7bb909ad7570081d0776c2d4d24c113b36c13e023a7ec02144def4735dbc037d.mp3", "hash": "6aaab559b035956fff0afcbe4218993b43e4b0e5ac8778cee8830e875b895ee9", "bytes": 70416, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7bb909ad7570081d0776c2d4d24c113b36c13e023a7ec02144def4735dbc037d.mp3", "duration_ms": 11680}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8ee4aa69-44e4-4d40-9cde-af0d59cc6b99', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "true-false", "title": "Money Decisions: True or False?", "locale": "en-US", "subject": "mixed", "objectives": ["Make simple money decisions by comparing options: fair price, safe place to save, and distinguish a good deal from a bad one.", "Decide if it''s true or false: ''If I save 5 pesos from each sale, my savings GROWS every day.''"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 10, "type": "true_false", "hints": ["Think: if yesterday she had 5 pesos and today she saves another 5, does she have more or less now?", "Each day she saves, she adds more money to her savings."], "title": "True or false?", "payload": {"statement_md": "If I save 5 pesos from each sale, my savings GROWS every day.", "justifications": [{"id": "crece", "text_md": "Each day I save 5 pesos, the total of my savings is greater than the day before."}, {"id": "no-crece", "text_md": "If I save 5 pesos each day, the savings stays the same because I don''t add anything new."}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Zara sells lemonade for 5 pesos. Each day she saves 5 pesos in her piggy bank. Does her savings grow or stay the same?", "difficulty": 1, "explanation_md": "It''s true. If you save 5 pesos each day, your savings adds up more each time. For example, Monday 5, Tuesday 10, Wednesday 15. It grows!", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": true, "correct_justification_id": "crece"}}', '{"units": {"s1-true-false.hint.0": {"url": "http://localhost:4006/files/lesson-audio/deca6cd3d878df716096fc52e5e0f4f0f271275c9c598820783faa48bc25f7d6.mp3", "hash": "c992779d9c07abfcc138ca7cf2bbbe738f369fbd525adb8489f18433cf10d478", "bytes": 42624, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/deca6cd3d878df716096fc52e5e0f4f0f271275c9c598820783faa48bc25f7d6.mp3", "duration_ms": 7040}, "s1-true-false.hint.1": {"url": "http://localhost:4006/files/lesson-audio/45d42dd02d58b8dd3de672ac51b91bbb9ca73823cb7a48203635da7254eb9d80.mp3", "hash": "8d2f800d4651b026478a07e40caec9bece4258d84770af09b4b4b63ce6b50aa8", "bytes": 24336, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/45d42dd02d58b8dd3de672ac51b91bbb9ca73823cb7a48203635da7254eb9d80.mp3", "duration_ms": 4000}, "s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/1d8021cf59fd59ecd6cc8fb39346371ce1170a411ceaf21b40877c5b9719c6e1.mp3", "hash": "4d592c02b959853e14175a90de6e66327579eca09a13d5bbe0da94bdfd7acbcc", "bytes": 50256, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/1d8021cf59fd59ecd6cc8fb39346371ce1170a411ceaf21b40877c5b9719c6e1.mp3", "duration_ms": 8320}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/16384b0500cf2e9266f52c8c252a1d808537ea5a8a1d3bff38ae92e0b92468cc.mp3", "hash": "5b31797f6b59a5c0913b6e49bbd6952476de038c5dc118bdb0c76f958a0ecbd4", "bytes": 77616, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/16384b0500cf2e9266f52c8c252a1d808537ea5a8a1d3bff38ae92e0b92468cc.mp3", "duration_ms": 12880}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4b45b37b-19f0-4fd5-99c2-0bcf9fabfbcd', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "machine-io", "title": "The Tip Machine", "locale": "en-US", "subject": "mixed", "objectives": ["Discover the rule of the tip machine: double the input."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-machine-io", "xp": 15, "type": "machine_io", "hints": ["Observe: 1 → 2, 3 → 6. What operation repeats?", "Try: 1 × 2 = 2, 3 × 2 = 6. So 5 × ?"], "title": "The Tip Machine", "payload": {"options": [{"id": "opt-7", "text_md": "7"}, {"id": "opt-8", "text_md": "8"}, {"id": "opt-10", "text_md": "10"}, {"id": "opt-15", "text_md": "15"}], "examples": [{"in": 1, "out": 2}, {"in": 3, "out": 6}], "probe_in": 5}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Liruf puts in 1 coin and 2 come out. Then he puts in 3 and 6 come out. How many will come out if he puts in 5?", "difficulty": 2, "explanation_md": "The machine doubles what goes in. 1 becomes 2, 3 becomes 6, so 5 becomes 10.", "audio_segment_id": "s1-machine-io.prompt"}], "schema_version": 1}', '{"s1-machine-io": {"value": 10, "correct_option_id": "opt-10"}}', '{"units": {"s1-machine-io.hint.0": {"url": "http://localhost:4006/files/lesson-audio/73c2f5be22de5223c437cdc83775a8e65093c612e32247af0466bf6ff476f7d2.mp3", "hash": "41000e7cc9d4339e51550e0869ebbe41871d2e48dfc3acfb7d34848868757465", "bytes": 25344, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/73c2f5be22de5223c437cdc83775a8e65093c612e32247af0466bf6ff476f7d2.mp3", "duration_ms": 4160}, "s1-machine-io.hint.1": {"url": "http://localhost:4006/files/lesson-audio/39c6b880c95cccb822b2a55de0403cca6e75170bc534e2641c874b3862228709.mp3", "hash": "0ca4b2b03e7c3749c4187ff3627dbbd9af0a850d08419ea22a7a42e71cf23603", "bytes": 31968, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/39c6b880c95cccb822b2a55de0403cca6e75170bc534e2641c874b3862228709.mp3", "duration_ms": 5280}, "s1-machine-io.prompt": {"url": "http://localhost:4006/files/lesson-audio/bddb5daa1daf3b746c150c152b0bda89c662fbdfefefc2af875927ff20db285e.mp3", "hash": "bd444b990371181d21129488eba94d54341c5a04644fa4462f866e4df3046fbb", "bytes": 40608, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/bddb5daa1daf3b746c150c152b0bda89c662fbdfefefc2af875927ff20db285e.mp3", "duration_ms": 6720}, "s1-machine-io.explanation": {"url": "http://localhost:4006/files/lesson-audio/fa2317f6bd8115aae8cc461ed1b4b3e4d9202db2edf876aba7e9c31e78495b09.mp3", "hash": "60ba58697540ecfebad9800202d2de2c50414dbbaab68c6671741c8c50c70669", "bytes": 35424, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/fa2317f6bd8115aae8cc461ed1b4b3e4d9202db2edf876aba7e9c31e78495b09.mp3", "duration_ms": 5840}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('cf7bec3a-945e-4d4a-828c-5535f3a7e69c', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "equation-builder", "title": "Monte a soma da tarde", "locale": "pt-BR", "subject": "money", "objectives": ["Montar com fichas a soma da tarde: 5 + 5 + 5 = 15 reais (três copos vendidos)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-arma-suma", "xp": 15, "type": "equation_builder", "hints": ["Liruf vendeu três copos de limonada. Cada copo vale 5 reais."], "title": "Monte a soma", "payload": {"slots": 5, "tokens": [{"id": "t1", "text": "5"}, {"id": "t2", "text": "+"}, {"id": "t3", "text": "5"}, {"id": "t4", "text": "+"}, {"id": "t5", "text": "5"}, {"id": "t6", "text": "3"}, {"id": "t7", "text": "15"}], "target_result": 15}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "Toque nas fichas para mostrar quanto Liruf ganhou hoje.", "difficulty": 2, "explanation_md": "Liruf vendeu três copos de 5 reais cada, então a soma é 5 + 5 + 5 = 15 reais. Ele já tem 15 reais para o violão de 80!", "audio_segment_id": "s1-arma-suma.prompt"}], "schema_version": 1}', '{"s1-arma-suma": {"accepted": ["t1 t2 t3 t4 t5"]}}', '{"units": {"s1-arma-suma.hint.0": {"url": "http://localhost:4006/files/lesson-audio/61720a3eb0c8b824d924e5b78fc96903dbafce78668ffd2a67eae64f441b830e.mp3", "hash": "9bbd5537d448c285694b2c5a34073dca7823e1552f28b57c4cf1c44f3f33eda0", "bytes": 35424, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/61720a3eb0c8b824d924e5b78fc96903dbafce78668ffd2a67eae64f441b830e.mp3", "duration_ms": 5840}, "s1-arma-suma.prompt": {"url": "http://localhost:4006/files/lesson-audio/718aca010b22e209165620936deb68ef70cff59b19435d3baa501a94936f501c.mp3", "hash": "d3c72a1c437789cb1ae72a629251674d7c17fd9af42cbbd9a30356cae585874c", "bytes": 21888, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/718aca010b22e209165620936deb68ef70cff59b19435d3baa501a94936f501c.mp3", "duration_ms": 3600}, "s1-arma-suma.explanation": {"url": "http://localhost:4006/files/lesson-audio/9f2d535009be069de95d062201c234ab9f10d30040ec5207d487dc45058fd85a.mp3", "hash": "e5baa8041d42f577ec9991b0ccb22d85c63cfe3fdfae2587199bf0b143f616fe", "bytes": 80496, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/9f2d535009be069de95d062201c234ab9f10d30040ec5207d487dc45058fd85a.mp3", "duration_ms": 13360}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8d0292b9-0597-4d9c-8b65-84f2fd19b142', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "red-flags", "title": "Señales de alerta en un trato", "locale": "es-MX", "subject": "mixed", "objectives": ["Detectar las señales de alerta en la oferta de un desconocido: promesas demasiado buenas no son de fiar."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-red-flags", "xp": 10, "type": "red_flags", "hints": ["Piensa: ¿cuánto te prometen y cuánto tienes que dar?", "¿Conoces a esa persona? ¿Parece apurado?"], "title": "El negocio mágico", "payload": {"flags": [{"id": "promesa-dinero", "text_md": "Promete mucho dinero rápido"}, {"id": "desconocido", "text_md": "Es un desconocido"}, {"id": "apurado", "text_md": "Dice ''solo hoy'' y tiene prisa"}, {"id": "poco-tiempo", "text_md": "Te pide decidir ya"}], "artifact_md": "Un cartel escrito a mano que dice: ''¡NEGOCIO MÁGICO! Dame 20 pesos hoy y mañana te doy 100. ¡Solo hoy!''. El cartel está pegado en un poste.", "artifact_kind": "ad"}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/44fdebc198a159cf51c12a5287a5de2ee0ca383a2703760452d502cc0e694362.png", "prompt_md": "Liruf está en su puesto de limonada. Un señor apurado le dice: ''Dame tus 20 pesos hoy y mañana te doy 100''. ¿Qué señales de alerta ves?", "difficulty": 1, "explanation_md": "Las promesas de ganar mucho dinero muy rápido, de un desconocido y con apuro, son señales de alerta. Liruf hizo bien en desconfiar.", "audio_segment_id": "s1-red-flags.prompt"}], "schema_version": 1}', '{"s1-red-flags": {"redflag_ids": ["promesa-dinero", "desconocido", "apurado", "poco-tiempo"]}}', '{"units": {"s1-red-flags.hint.0": {"url": "http://localhost:4006/files/lesson-audio/93a6bf85e51f7fa1c3a8351a3ed28bf2fe81286cae27927895286118c960e739.mp3", "hash": "4981a696af260f1abd9a5cec774efc490af5e7b625ff274e7a37d1e10f5fbc5d", "bytes": 21888, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/93a6bf85e51f7fa1c3a8351a3ed28bf2fe81286cae27927895286118c960e739.mp3", "duration_ms": 3600}, "s1-red-flags.hint.1": {"url": "http://localhost:4006/files/lesson-audio/23942cd91b590cfdcdaff6fd1fffc947233fec804bb24075151179ddaadeedb5.mp3", "hash": "cd5b45e0da4d52a0b00b17a4bec284bb5b0a71cf9571bb118d10eebc5cdefd2a", "bytes": 16704, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/23942cd91b590cfdcdaff6fd1fffc947233fec804bb24075151179ddaadeedb5.mp3", "duration_ms": 2720}, "s1-red-flags.prompt": {"url": "http://localhost:4006/files/lesson-audio/cac036723db2383c5fd6dba5d81c2e3c9fe668f5c630e95f646505e67de94da6.mp3", "hash": "c8e01968d71bd77641396b94ec20590bf50834fa22e94c38b91f8fa6cd97e188", "bytes": 62208, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/cac036723db2383c5fd6dba5d81c2e3c9fe668f5c630e95f646505e67de94da6.mp3", "duration_ms": 10320}, "s1-red-flags.explanation": {"url": "http://localhost:4006/files/lesson-audio/cd4fa653aed0bade777073d8a06bc480e55e3853208a9e0baaf27dfe549c0628.mp3", "hash": "564e5dbd548913fab99e75ff2b282678ad7f70673d6077e89804e2702f7d0a12", "bytes": 57888, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/cd4fa653aed0bade777073d8a06bc480e55e3853208a9e0baaf27dfe549c0628.mp3", "duration_ms": 9600}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f75b3e23-fb31-40cf-9b58-e918769e51b9', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "yes-no-cases", "title": "Yes or no: does it help the stand?", "locale": "en-US", "subject": "money", "objectives": ["Decide if an expense helps the lemonade stand (yes) or is a temptation (no)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-yes-no-cases", "xp": 10, "type": "yes_no_cases", "hints": ["Think: does this help sell more lemonade or save money?", "If it''s just to play today, better wait."], "title": "Yes or no: does it help the stand?", "payload": {"cases": [{"id": "c1", "text_md": "Buying 10 lemons to make more lemonade.", "image_url": "http://localhost:4006/files/lesson-images/18c94c5a82f982a947a88d11ab698899087d233d1492ef96c8d15d7d4c47109d.png"}, {"id": "c2", "text_md": "Buying a $5 toy to play with today.", "image_url": "http://localhost:4006/files/lesson-images/cbf825b7a65a0adef293c83809b0972a95aa99a094a48f75dd3f3f396c7cfa7f.png"}, {"id": "c3", "text_md": "Buying 20 disposable cups to serve the lemonade.", "image_url": "http://localhost:4006/files/lesson-images/e3ad5890bf2a9691eff0a3c52434b6ee8c400f1989b91838a4f38478a41fdd46.png"}, {"id": "c4", "text_md": "Buying a $3 bag of candy for yourself.", "image_url": "http://localhost:4006/files/lesson-images/1ae048298ec543e884d245fd1e3c38b5c18d5e2979b29dcca0e06bdbe3a5201a.png"}], "rule_md": "Ask yourself: **does this help the stand run better or earn more money?** If yes, it''s a worthwhile expense. If no, it''s a temptation that can wait."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Tap YES if it helps the stand, NO if it''s a temptation.", "difficulty": 1, "explanation_md": "Buying more lemons helps make more lemonade and sell more. A new toy doesn''t help the stand today.", "audio_segment_id": "s1-yes-no-cases.prompt"}], "schema_version": 1}', '{"s1-yes-no-cases": {"applies_ids": ["c1", "c3"]}}', '{"units": {"s1-yes-no-cases.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6f170008e53da3c0396812b5bba6b94bf36aca078fc2fa10aa12b4a0418eb109.mp3", "hash": "1ea07400a96bb6fb8c3fdd38be571417194b11fe8d965dc13f22196a679b4a76", "bytes": 20016, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6f170008e53da3c0396812b5bba6b94bf36aca078fc2fa10aa12b4a0418eb109.mp3", "duration_ms": 3280}, "s1-yes-no-cases.hint.1": {"url": "http://localhost:4006/files/lesson-audio/d9bd5ee621b1330e9cfa3c45bf51581afeff8b7ba689e51f812c2d920fc246c2.mp3", "hash": "75dd260f09910caa89cc5579514922b27a3694df95b70fb4bc30d0bfd7d7be34", "bytes": 15264, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/d9bd5ee621b1330e9cfa3c45bf51581afeff8b7ba689e51f812c2d920fc246c2.mp3", "duration_ms": 2480}, "s1-yes-no-cases.prompt": {"url": "http://localhost:4006/files/lesson-audio/e28fab0d6cbd3c9956d16d2ddecb0c5b29d0c1cbb7faa9c4f381f8522a12db4d.mp3", "hash": "1264cf36ce1ea118fc2bdc5f4491d2650fe660ea89d6df8c86a31e3f2fe95568", "bytes": 22464, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e28fab0d6cbd3c9956d16d2ddecb0c5b29d0c1cbb7faa9c4f381f8522a12db4d.mp3", "duration_ms": 3680}, "s1-yes-no-cases.choices": {"url": "http://localhost:4006/files/lesson-audio/52b4ab9647734d54c6d09dbc045601fd7d3e2c794f06bda6b2ecd928626c00de.mp3", "hash": "151909b4ca93a896a45323e2d05f48ec79ce9a1b13b561000d739088ef1eb7a3", "bytes": 57456, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/52b4ab9647734d54c6d09dbc045601fd7d3e2c794f06bda6b2ecd928626c00de.mp3", "duration_ms": 9520}, "s1-yes-no-cases.explanation": {"url": "http://localhost:4006/files/lesson-audio/44426c2c4b242a6c8d0bb88367eb01473a5a92077355f7e0ec195de3e14714ea.mp3", "hash": "fdd4c0fd523a7a5afc387cda438c89be806289dd81c16ebd60b6d169f1d4b089", "bytes": 30528, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/44426c2c4b242a6c8d0bb88367eb01473a5a92077355f7e0ec195de3e14714ea.mp3", "duration_ms": 5040}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b979bce6-8935-480e-8471-33053faa2321', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "sort-buckets", "title": "Classifique as compras da barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Classificar compras entre necessidades da barraca e vontades que podem esperar"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-sort-buckets", "xp": 10, "type": "sort_buckets", "hints": ["Os limões custam $2 e os copos $5. A barraca precisa disso para vender limonada?"], "title": "Classifique as compras", "payload": {"items": [{"id": "limones", "text_md": "Limões ($2)", "image_url": "http://localhost:4006/files/lesson-images/dd8fc7c9e7ef41dbecf99720eacb8ce29a1ccfeacb43a6a95fc6651ef2b577ed.png"}, {"id": "vasos", "text_md": "Copos ($5)", "image_url": "http://localhost:4006/files/lesson-images/bcf021ac4ffb157f2c823102066ef9a32608ef0009e25214d29348c387206f32.png"}, {"id": "stickers", "text_md": "Adesivos ($3)", "image_url": "http://localhost:4006/files/lesson-images/b299789ee3ee0d6f9eada795bfa5eb5a4d2a1780fe37fb250c891127b9a40280.png"}, {"id": "globos", "text_md": "Balões ($4)", "image_url": "http://localhost:4006/files/lesson-images/3708d8a769b4dd2d0e873a23054fc5e485561283b236d1e4362fe4d1c5534302.png"}], "buckets": [{"id": "necesidad", "label": "NECESSIDADE da barraca"}, {"id": "gusto", "label": "VONTADE que pode esperar"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Você se lembra dos preços da barraca? Liruf tem $10. O que ele precisa comprar hoje?", "difficulty": 1, "explanation_md": "Os limões e os copos são necessários para fazer e servir a limonada. Os adesivos e os balões são vontades que podem esperar.", "audio_segment_id": "s1-sort-buckets.prompt"}], "schema_version": 1}', '{"s1-sort-buckets": {"assignments": {"vasos": "necesidad", "globos": "gusto", "limones": "necesidad", "stickers": "gusto"}}}', '{"units": {"s1-sort-buckets.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6b8680062b6a17db5b472df2b7e70a80b9cf0c668edc644ee052603dacc82ed7.mp3", "hash": "01da3a484a4afb4ca05d798f3d0cf8d60ebce8c08cd564e603ebe35e97e98a0a", "bytes": 42048, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/6b8680062b6a17db5b472df2b7e70a80b9cf0c668edc644ee052603dacc82ed7.mp3", "duration_ms": 6960}, "s1-sort-buckets.prompt": {"url": "http://localhost:4006/files/lesson-audio/25ef83ab7e67725aafffec5e9a8feb053246f422c693fe28155143fbb3505d16.mp3", "hash": "d16e682972771cf0070f1d69a9cd7de643b62b99bad9d12d3ef45e550c92c738", "bytes": 43056, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/25ef83ab7e67725aafffec5e9a8feb053246f422c693fe28155143fbb3505d16.mp3", "duration_ms": 7120}, "s1-sort-buckets.explanation": {"url": "http://localhost:4006/files/lesson-audio/9ce595ea603e5d55c4d91060e3e16f9837d476df0ebedac58147142628090b2d.mp3", "hash": "34f840e01f36d6cff4ab3f7f1b537674cb7a6e579d2bb72e15a87ec1e73d3b37", "bytes": 56016, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/9ce595ea603e5d55c4d91060e3e16f9837d476df0ebedac58147142628090b2d.mp3", "duration_ms": 9280}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b45d67a1-26c0-4ffa-b51c-76340c35e459', 'en-US', '1', '{"meta": {"cast": ["liruf", "zara"], "slug": "order-steps", "title": "Order the stall''s purchases", "locale": "en-US", "subject": "mixed", "objectives": ["Order market purchases by sales priority", "Distinguish between need and luxury at a stall"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-order-purchases", "xp": 15, "type": "order_steps", "hints": ["Think: without which can you not make even one glass of lemonade?", "Stickers are a luxury, they don''t help sell today."], "title": "Order the purchases", "payload": {"items": [{"id": "limones", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/24c4adabd035c7d03f661bb92a4df7157473c77d800d343c275501f50a810c98.png"}, {"id": "vasos", "text_md": "Cups", "image_url": "http://localhost:4006/files/lesson-images/795f93e9566f9d155ead96137221287d92afbb6e543d35bbe0bd3b568d0ef904.png"}, {"id": "azucar", "text_md": "Sugar", "image_url": "http://localhost:4006/files/lesson-images/511861592ee4ee607d9fbe9ca0733fb753421c3af63ec9a01df0b2d37f7697f6.png"}, {"id": "calcomanias", "text_md": "Stickers", "image_url": "http://localhost:4006/files/lesson-images/af7ab0faf0a29454770270371e91ca207341ad422db335093e29e19c0b61667e.png"}]}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Tap the 4 items in order: from what you need most to sell today to what can wait.", "difficulty": 2, "explanation_md": "Lemons come first because without them there is no lemonade. Cups are second because customers need something to serve in. Sugar improves the taste, but you can sell without it. Stickers are a treat that can wait.", "audio_segment_id": "s1-order-purchases.prompt"}], "schema_version": 1}', '{"s1-order-purchases": {"order": ["limones", "vasos", "azucar", "calcomanias"]}}', '{"units": {"s1-order-purchases.hint.0": {"url": "http://localhost:4006/files/lesson-audio/380e7d7576879124158f1a46c49c2a5927361ce4d7b060157ab2d5863383bab3.mp3", "hash": "9dd20e410c289102cdc56f10942c3aa4054de5a4a4bcfd0d8d34e00b621d7e28", "bytes": 26784, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/380e7d7576879124158f1a46c49c2a5927361ce4d7b060157ab2d5863383bab3.mp3", "duration_ms": 4400}, "s1-order-purchases.hint.1": {"url": "http://localhost:4006/files/lesson-audio/e67b9971c80ed521a203bd4cfcf8acd97fc6c7a9a1b77d3f904f096039828de3.mp3", "hash": "b15b6686b3655d48ec78f26b54a7268d8eb572268a8f0e0c2ef9393fc0612faa", "bytes": 20016, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/e67b9971c80ed521a203bd4cfcf8acd97fc6c7a9a1b77d3f904f096039828de3.mp3", "duration_ms": 3280}, "s1-order-purchases.prompt": {"url": "http://localhost:4006/files/lesson-audio/afdd2568add806d05bda60702b3efe4fad03673e505690b7ac0ad474d1ed2bbe.mp3", "hash": "6f7e9e11e5683601326aa96e39bc8bcdc3ba5d016a5e0627f593220761a03e1b", "bytes": 31536, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/afdd2568add806d05bda60702b3efe4fad03673e505690b7ac0ad474d1ed2bbe.mp3", "duration_ms": 5200}, "s1-order-purchases.explanation": {"url": "http://localhost:4006/files/lesson-audio/c08ed0e3cf1219fbd0f2c976ec41ad3160b220b438f6d78758c49bb1ff2359bf.mp3", "hash": "73398252034263a3d9c2612177eb97316bf5f79673ed3e92037f04dc7be5048a", "bytes": 80928, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/c08ed0e3cf1219fbd0f2c976ec41ad3160b220b438f6d78758c49bb1ff2359bf.mp3", "duration_ms": 13440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8d0292b9-0597-4d9c-8b65-84f2fd19b142', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "red-flags", "title": "Sinais de alerta em um negócio", "locale": "pt-BR", "subject": "mixed", "objectives": ["Detectar os sinais de alerta na oferta de um estranho: promessas boas demais não são confiáveis."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-red-flags", "xp": 10, "type": "red_flags", "hints": ["Pense: quanto te prometem e quanto você precisa dar?", "Você conhece essa pessoa? Ela parece apressada?"], "title": "O negócio mágico", "payload": {"flags": [{"id": "promesa-dinero", "text_md": "Promete muito dinheiro rápido"}, {"id": "desconocido", "text_md": "É um estranho"}, {"id": "apurado", "text_md": "Diz ''só hoje'' e está com pressa"}, {"id": "poco-tiempo", "text_md": "Te pede para decidir agora"}], "artifact_md": "Um cartaz escrito à mão que diz: ''NEGÓCIO MÁGICO! Me dê 20 reais hoje e amanhã te dou 100. Só hoje!''. O cartaz está colado em um poste.", "artifact_kind": "ad"}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/1f03fe20004b208bffd523ebd7398df740c7b590351399ed8a03d27440bf948f.png", "prompt_md": "Liruf está em sua barraca de limonada. Um senhor apressado diz: ''Me dê seus 20 reais hoje e amanhã te dou 100''. Que sinais de alerta você vê?", "difficulty": 1, "explanation_md": "Promessas de ganhar muito dinheiro muito rápido, de um estranho e com pressa, são sinais de alerta. Liruf fez bem em desconfiar.", "audio_segment_id": "s1-red-flags.prompt"}], "schema_version": 1}', '{"s1-red-flags": {"redflag_ids": ["promesa-dinero", "desconocido", "apurado", "poco-tiempo"]}}', '{"units": {"s1-red-flags.hint.0": {"url": "http://localhost:4006/files/lesson-audio/df869c15a43c362ca886fe68cb686c9d35a8c145499b9b8142dbb7d8b768b28a.mp3", "hash": "8d8199d0eda9fbd29e4b306e1767b140cda77d0f38985ce0f6ed412f0bfbce25", "bytes": 22464, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/df869c15a43c362ca886fe68cb686c9d35a8c145499b9b8142dbb7d8b768b28a.mp3", "duration_ms": 3680}, "s1-red-flags.hint.1": {"url": "http://localhost:4006/files/lesson-audio/f1772d7d99af47edb9eaad8efc91c9bc9ef5f901ca5b8258e8aa9860ddff9cb5.mp3", "hash": "66f18af0644391a8c6f777dbf2e0232b15022f1f13777160c8ec877dc9166cda", "bytes": 21888, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f1772d7d99af47edb9eaad8efc91c9bc9ef5f901ca5b8258e8aa9860ddff9cb5.mp3", "duration_ms": 3600}, "s1-red-flags.prompt": {"url": "http://localhost:4006/files/lesson-audio/313dff612732e455887254920b0717ad6660812cfd58c6d5e798bd47305a009f.mp3", "hash": "b690ca0aeab6c74794e79549677d5c792a31e0f385efedf296e4963dea9b62de", "bytes": 59904, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/313dff612732e455887254920b0717ad6660812cfd58c6d5e798bd47305a009f.mp3", "duration_ms": 9920}, "s1-red-flags.explanation": {"url": "http://localhost:4006/files/lesson-audio/40bbfbfb8cae82bef0922985838710af5984f91c657b29525ec57f55a5437b8a.mp3", "hash": "7d36614773fbd5282660d335dbae1e548c9b4842e8cbd7e9d1c82f6937b36131", "bytes": 57456, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/40bbfbfb8cae82bef0922985838710af5984f91c657b29525ec57f55a5437b8a.mp3", "duration_ms": 9520}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f8c5e4cf-232b-47dc-8484-3350558f5f27', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "needs-wants", "title": "El puesto come primero", "locale": "es-MX", "subject": "money", "objectives": ["Separar necesidades del puesto (limones, hielo) de deseos personales (paleta, cómic): el puesto come primero."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-needs-wants", "xp": 10, "type": "needs_wants", "hints": ["El puesto necesita lo que se usa para hacer la limonada.", "¿Qué se acaba y hay que comprar otra vez?"], "title": "Necesidades del puesto vs. deseos", "payload": {"items": [{"id": "limones", "icon": "eco", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/c5ce84b02e2ebe59e448a0c7ed3c69209782340cea0e4cd31f17e12576a337ae.png"}, {"id": "hielo", "icon": "ac_unit", "text_md": "Hielo", "image_url": "http://localhost:4006/files/lesson-images/7949c6e4f0d5de122f1aa59384409c593335a99ad51cd80e96f28902f902cd7b.png"}, {"id": "paleta", "icon": "icecream", "text_md": "Paleta", "image_url": "http://localhost:4006/files/lesson-images/26f7b0f0a81da7c922d5d595586e217dc183f85ae9b7fff3f858c048fe219d6d.png"}, {"id": "comic", "icon": "auto_stories", "text_md": "Cómic", "image_url": "http://localhost:4006/files/lesson-images/989d18c78971c05a665102ae6e7ee04e96736fbfc5a7429acd01181bb7e5f786.png"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Como ayer repartiste ganancias, hoy decide: ¿qué compras primero para que el puesto no cierre?", "difficulty": 1, "explanation_md": "Los limones y el hielo son necesidades del puesto porque sin ellos no hay limonada. La paleta y el cómic son deseos tuyos, no del puesto.", "audio_segment_id": "s1-needs-wants.prompt"}], "schema_version": 1}', '{"s1-needs-wants": {"needs_ids": ["limones", "hielo"]}}', '{"units": {"s1-needs-wants.hint.0": {"url": "http://localhost:4006/files/lesson-audio/3789ea489ee6ef348e7fbbc89b3a92eacf42742058e7dc62f1a0f379bdaacc52.mp3", "hash": "f4e8ec6e8558e2630ce8f379ff9ca157861d52ea8faae2e4784a37b36be817ac", "bytes": 21024, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3789ea489ee6ef348e7fbbc89b3a92eacf42742058e7dc62f1a0f379bdaacc52.mp3", "duration_ms": 3440}, "s1-needs-wants.hint.1": {"url": "http://localhost:4006/files/lesson-audio/7006d6f951a4c3c2162727b01890e2886931b0aaa2ed1063dbadcf095c07bde5.mp3", "hash": "c2965b8c90c806fa155435b9a09320edd8b29d557327a933c8d10de6d879bdb6", "bytes": 17568, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7006d6f951a4c3c2162727b01890e2886931b0aaa2ed1063dbadcf095c07bde5.mp3", "duration_ms": 2880}, "s1-needs-wants.prompt": {"url": "http://localhost:4006/files/lesson-audio/c7ce231eaeb881899af0f1efe26b5fde5eb38487dc5c3bf99eade912ebe51912.mp3", "hash": "fd3296937bb588796b9997b88f100b2f8fd57042876dbbadcd0f11f937bc37ac", "bytes": 40608, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c7ce231eaeb881899af0f1efe26b5fde5eb38487dc5c3bf99eade912ebe51912.mp3", "duration_ms": 6720}, "s1-needs-wants.explanation": {"url": "http://localhost:4006/files/lesson-audio/04f79801a33d4a29f97599c49c7d9155466f367d34f644486bd6ebeb97875023.mp3", "hash": "f3fc2e436c6106c4f9c3c5c2ee2be13477710f4329cf68a87c2ab89a556a6dd6", "bytes": 56016, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/04f79801a33d4a29f97599c49c7d9155466f367d34f644486bd6ebeb97875023.mp3", "duration_ms": 9280}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8f1a89c3-ae63-41f5-a2fa-70d1b7c6aac9', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "coin-count", "title": "Counting coins: the first sale", "locale": "en-US", "subject": "money", "objectives": ["Counting 1, 2, and 5 peso coins to add up to an exact amount."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-contar-monedas", "xp": 10, "type": "coin_count", "hints": ["First count the 2-peso coins, then the 1-peso coins.", "Put all the coins together and see if they add up to 5."], "title": "The first sale", "payload": {"target": 5, "currency": "MXN", "denominations": [1, 2]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/b34eb5bdd78526875acc6dcb2fff179a19313ef85a27f534bed3fde4e8a9dbc7.png", "prompt_md": "Count the coins the customer gave you. Is it exactly 5 pesos?", "difficulty": 1, "explanation_md": "You have one 2-peso coin and three 1-peso coins: 2 + 1 + 1 + 1 = 5. Yes, it''s exactly 5 pesos!", "audio_segment_id": "s1-contar-monedas.prompt"}], "schema_version": 1}', '{"s1-contar-monedas": {}}', '{"units": {"s1-contar-monedas.hint.0": {"url": "http://localhost:4006/files/lesson-audio/de9c88a9bec9ae70ebcc4e92bb3cd606597c6a89dcddc25721e5bf219672d192.mp3", "hash": "a346b4a1dc54ad8899b0ff48335368da04b07d7f38b8052be9ba8947fe2c4522", "bytes": 22464, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/de9c88a9bec9ae70ebcc4e92bb3cd606597c6a89dcddc25721e5bf219672d192.mp3", "duration_ms": 3680}, "s1-contar-monedas.hint.1": {"url": "http://localhost:4006/files/lesson-audio/3e050d72061f0894803dadcd83ae58d4a78179d81df3724d04e0b5840acd97c5.mp3", "hash": "810d781d9c30bb571ab56cd435aa9f3a7f6d59b506364241ed5a4b9355f8c8ab", "bytes": 17568, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3e050d72061f0894803dadcd83ae58d4a78179d81df3724d04e0b5840acd97c5.mp3", "duration_ms": 2880}, "s1-contar-monedas.prompt": {"url": "http://localhost:4006/files/lesson-audio/6ccd059c684c150e3c29a79346bb492705ef52d77ef0a4af90d02aa662cbc98a.mp3", "hash": "8392f2489e7a265111dbcee3aef1d1d214afa53a34b2994f265bebaccb832339", "bytes": 24768, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6ccd059c684c150e3c29a79346bb492705ef52d77ef0a4af90d02aa662cbc98a.mp3", "duration_ms": 4080}, "s1-contar-monedas.explanation": {"url": "http://localhost:4006/files/lesson-audio/73d2c092fee61065cefe9e33dda1c16aa41a0bad5ce76d409180d7fe79fb4082.mp3", "hash": "4645f809a7a169ab36d717aa54a8a4c9de0f58f7a26adcd2fcc576cd65475df5", "bytes": 60336, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/73d2c092fee61065cefe9e33dda1c16aa41a0bad5ce76d409180d7fe79fb4082.mp3", "duration_ms": 10000}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9b315200-00f0-4dc4-a2cd-13c1fb40e9aa', 'en-US', '1', E'{"meta": {"cast": ["liruf", "zara"], "slug": "build-sentence", "title": "The combo sign", "locale": "en-US", "subject": "mixed", "objectives": ["Calculate the price of 2 glasses of lemonade at 5 pesos each", "Select the correct tile to complete the combo sign"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-combo-letrero", "xp": 15, "type": "build_sentence", "hints": ["Each glass costs 5 pesos. How much do two glasses cost?", "Think: 5 + 5 = ?"], "title": "Complete the sign", "payload": {"slots": 5, "tokens": [{"id": "t1", "text_md": "2"}, {"id": "t2", "text_md": "glasses"}, {"id": "t3", "text_md": "for"}, {"id": "t4", "text_md": "___"}, {"id": "t5", "text_md": "pesos"}, {"id": "t6", "text_md": "5"}, {"id": "t7", "text_md": "10"}, {"id": "t8", "text_md": "15"}, {"id": "t9", "text_md": "20"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Tap the tiles in order to build the combo sign: \\"2 glasses for ___ pesos\\"", "difficulty": 2, "explanation_md": "Two glasses cost 10 pesos (5+5=10). If you put 5, they would only pay for one glass; if you put 15 or 20, you would scare away customers or give away money.", "audio_segment_id": "s1-combo-letrero.prompt"}], "schema_version": 1}', '{"s1-combo-letrero": {"order": ["t1", "t2", "t3", "t7", "t5"]}}', '{"units": {"s1-combo-letrero.hint.0": {"url": "http://localhost:4006/files/lesson-audio/145e0e5084854faa28fa814440ead3fa6cdf34816ef2becdbe147ef461be5c7c.mp3", "hash": "38b7add9ffa5897aff96a47bbae544a40130d2aada70b53345829cc7e1fda7e1", "bytes": 24768, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/145e0e5084854faa28fa814440ead3fa6cdf34816ef2becdbe147ef461be5c7c.mp3", "duration_ms": 4080}, "s1-combo-letrero.hint.1": {"url": "http://localhost:4006/files/lesson-audio/be18c90549e1f85399aa236bdd5d167861667c92e907190e33888571b56d3ff7.mp3", "hash": "d010beeda1d147c5d48ce7c5e2d6a2cce83d539d1563995baa4c20806adcbc7e", "bytes": 15264, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/be18c90549e1f85399aa236bdd5d167861667c92e907190e33888571b56d3ff7.mp3", "duration_ms": 2480}, "s1-combo-letrero.prompt": {"url": "http://localhost:4006/files/lesson-audio/7a37ad69a53d76e2a4ce59ab29ed033dca0459877cf44774d539c67bf5122a3d.mp3", "hash": "ba86adeebce46c98b4c29b7b323eae32ccb010c1b3ce96f7b409da094eaab863", "bytes": 28224, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/7a37ad69a53d76e2a4ce59ab29ed033dca0459877cf44774d539c67bf5122a3d.mp3", "duration_ms": 4640}, "s1-combo-letrero.explanation": {"url": "http://localhost:4006/files/lesson-audio/dae13813a91a35443a2979a702f220605817746f4c0ed7aacd2422a958a1b1a7.mp3", "hash": "10d06ee6c3cdf991e9ad39a4ff8e2738ffec993f6841bbb9cd6ad59832322b3b", "bytes": 68976, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/dae13813a91a35443a2979a702f220605817746f4c0ed7aacd2422a958a1b1a7.mp3", "duration_ms": 11440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('85c2a66b-c70b-43e4-8fd5-4862d4acb66b', 'es-MX', '1', '{"meta": {"cast": ["dina", "rho", "liruf"], "slug": "rank-choices", "title": "Ordena las compras del puesto", "locale": "es-MX", "subject": "money", "objectives": ["Ordenar de más a menos urgente en qué gastar la ganancia de hoy: reponer limones primero, luego vasos, y al final adornos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-rank", "xp": 15, "type": "rank_choices", "hints": ["Sin limones no hay limonada, sin vasos no se sirve.", "Los adornos son bonitos, pero no urgentes para vender hoy."], "title": "¿Qué comprar primero?", "payload": {"items": [{"id": "limones", "text_md": "Limones para la limonada", "image_url": "http://localhost:4006/files/lesson-images/ff4f87aaf64a1a8223cb6bd09bbe050417eabc8823814807b58b858b051ff55a.png"}, {"id": "vasos", "text_md": "Vasos para servir", "image_url": "http://localhost:4006/files/lesson-images/f92ea8257fc294f595e9a3869c1b2cc8edc28fe159591fe005b0f009e6bdc03d.png"}, {"id": "adornos", "text_md": "Adornos para el puesto", "image_url": "http://localhost:4006/files/lesson-images/fde74d428bcadf147a2578925d0e5116a298968a5f4a83fd5d55468fbece3984.png"}], "criterion_md": "Ordena de más a menos urgente para el puesto de Liruf"}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Liruf tiene $20. Toca los gastos en orden: el más urgente primero.", "difficulty": 2, "explanation_md": "Los limones son lo más urgente porque sin ellos no hay limonada. Los vasos van después, y los adornos al final, porque son un gusto que puede esperar.", "audio_segment_id": "s1-rank.prompt"}], "schema_version": 1}', '{"s1-rank": {"order": ["limones", "vasos", "adornos"]}}', '{"units": {"s1-rank.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d88d06bab671b7546c3cf350faa53c2ed1b5cefbf05023f521952dca1cc35679.mp3", "hash": "5cbbaca89df87214fc6d199f92dc6c5cf862f42f2f3aee006528b101dbd8b3b7", "bytes": 31104, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/d88d06bab671b7546c3cf350faa53c2ed1b5cefbf05023f521952dca1cc35679.mp3", "duration_ms": 5120}, "s1-rank.hint.1": {"url": "http://localhost:4006/files/lesson-audio/6d7258973485567f360a90cca33e59bab7d7f79707ab0b0dbaeebf2bb9c3a9a2.mp3", "hash": "c20e46478670da75134c161a912c3362f6aca2a6bd41e4603108ae4a88f50377", "bytes": 25344, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/6d7258973485567f360a90cca33e59bab7d7f79707ab0b0dbaeebf2bb9c3a9a2.mp3", "duration_ms": 4160}, "s1-rank.prompt": {"url": "http://localhost:4006/files/lesson-audio/caaaf18b98bdabfcbb85412f6d3b15ed558b13e5580952e057cf1a952b4ada94.mp3", "hash": "062d76d15556f2a3be2b511bc99e89c215ea95a9ba8133e908a1c614521481a7", "bytes": 34416, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/caaaf18b98bdabfcbb85412f6d3b15ed558b13e5580952e057cf1a952b4ada94.mp3", "duration_ms": 5680}, "s1-rank.explanation": {"url": "http://localhost:4006/files/lesson-audio/02340d38f3c6c2546ff837f232e9a744c1978a01c331671aaefc4b8867b382bb.mp3", "hash": "7c086d3054a9968d6aaf4eb4dde98cd1a38a394711b8b5e5cfc522421888c37f", "bytes": 62784, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/02340d38f3c6c2546ff837f232e9a744c1978a01c331671aaefc4b8867b382bb.mp3", "duration_ms": 10400}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('36624bae-eea6-49e3-8767-c43ffbdf09e7', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "compare-table", "title": "Compare lemon suppliers", "locale": "en-US", "subject": "mixed", "objectives": ["Read a table of two lemon suppliers (price and quantity) and choose the one that gives more for less."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-compare-table", "xp": 15, "type": "compare_table", "hints": ["Look at how many lemons each gives for 5 pesos."], "title": "Choose the best supplier", "payload": {"cols": [{"id": "precio", "label": "Price"}, {"id": "cantidad", "label": "Number of lemons"}], "rows": [{"id": "proveedor-a", "label": "Supplier A"}, {"id": "proveedor-b", "label": "Supplier B"}], "tokens": [{"id": "t1", "text_md": "5 pesos"}, {"id": "t2", "text_md": "10 lemons"}, {"id": "t3", "text_md": "5 pesos"}, {"id": "t4", "text_md": "8 lemons"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/cb05f7ecece6d7a2dbd8520acc3f1d2416221e0c1e680e58f460561d2c766bfb.png", "prompt_md": "Dina has 5 pesos. Which supplier gives her more lemons?", "difficulty": 1, "explanation_md": "With supplier A, Dina gets 10 lemons for her 5 pesos. With B, only 8. A gives her more lemons for the same money!", "audio_segment_id": "s1-compare-table.prompt"}], "schema_version": 1}', '{"s1-compare-table": {"cells": {"proveedor-a:precio": "t1", "proveedor-b:precio": "t3", "proveedor-a:cantidad": "t2", "proveedor-b:cantidad": "t4"}}}', '{"units": {"s1-compare-table.hint.0": {"url": "http://localhost:4006/files/lesson-audio/bb3509d30081d5ce33526da4b1f93b944d635b2218fb13671fc1b368ddd29ec1.mp3", "hash": "9d26f11f9ffb7f40a0d31837b02cf9850c4c03dbb88eca806b450dd829362765", "bytes": 18144, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/bb3509d30081d5ce33526da4b1f93b944d635b2218fb13671fc1b368ddd29ec1.mp3", "duration_ms": 2960}, "s1-compare-table.prompt": {"url": "http://localhost:4006/files/lesson-audio/d72a4995cec83646513bd39a9296776558a14cc5998113cd62be6c44ded18825.mp3", "hash": "54f9aa564bf37ac227fdbda9096e5a2afb0288be0c3d9b319b510ab244c227a8", "bytes": 21024, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/d72a4995cec83646513bd39a9296776558a14cc5998113cd62be6c44ded18825.mp3", "duration_ms": 3440}, "s1-compare-table.explanation": {"url": "http://localhost:4006/files/lesson-audio/eb8dadb5113e9a13113415d34ad7cd8767627d85aced559c2b3607553d6c3ff3.mp3", "hash": "03bf760022efe43381361ec1b195ad8d764074121ba7606765aac83c6e742b1c", "bytes": 45936, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/eb8dadb5113e9a13113415d34ad7cd8767627d85aced559c2b3607553d6c3ff3.mp3", "duration_ms": 7600}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('574fb312-93f9-4f2f-adea-606bbb0ca99d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "best-decision", "title": "A melhor decisão de Liruf", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher a melhor decisão quando um cliente paga com nota de 20 por um copo de 5: contar o troco com calma."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-best-decision", "xp": 15, "type": "best_decision", "hints": ["Pense: se o copo custa 5 e te pagam com 20, quanto você deve devolver?", "Imagine que você é Liruf: prefere contar devagar ou adivinhar?"], "title": "O troco de Liruf", "payload": {"options": [{"id": "contar", "text_md": "Contar o troco com calma: 15 reais", "rationale_md": "Contar com calma é a melhor decisão porque garante que o troco esteja correto."}, {"id": "adivinar", "text_md": "Adivinhar o troco rápido e dar 10 reais", "rationale_md": "Adivinhar pode fazer você dar o troco errado e a cliente perder dinheiro."}, {"id": "quedarse", "text_md": "Ficar com toda a nota e não dar troco", "rationale_md": "Ficar com a nota inteira é incorreto porque a cliente pagou a mais e merece seu troco."}], "scenario_md": "Liruf já aprendeu que a limonada precisa de limões e açúcar, e que isso custa dinheiro. Agora ele atende sua primeira cliente. Ela dá a ele uma nota de 20 reais por um copo de limonada de 5 reais. Liruf está nervoso e não sabe o que fazer."}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/9f7ed2dd956371bf24ff45f64020da131fb8a68bf68ff5f3608190bb7349322d.png", "prompt_md": "A cliente paga com 20 reais. O copo custa 5. O que você faz?", "difficulty": 2, "explanation_md": "Contar o troco com calma garante que você não erre. 20 menos 5 são 15 reais de troco.", "audio_segment_id": "s1-best-decision.prompt"}], "schema_version": 1}', '{"s1-best-decision": {"qualities": {"contar": 100, "adivinar": 20, "quedarse": 0}}}', '{"units": {"s1-best-decision.hint.0": {"url": "http://localhost:4006/files/lesson-audio/865765c085f7e243550b9446d46a3145c27995b8c066b327ba937ab76c7fce11.mp3", "hash": "6efaa1307d49a951b75fe21a862262788d6d9d29a144952fc99784398abcd462", "bytes": 37296, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/865765c085f7e243550b9446d46a3145c27995b8c066b327ba937ab76c7fce11.mp3", "duration_ms": 6160}, "s1-best-decision.hint.1": {"url": "http://localhost:4006/files/lesson-audio/efa0f51e659548896c3bf6676c6e2735f9805c1a5cbebae4dbae0019fbf9b526.mp3", "hash": "f746adeb61f4004ae4be10e9b79fea4bd4f2b1a182605adfda55a9a904c9a927", "bytes": 29664, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/efa0f51e659548896c3bf6676c6e2735f9805c1a5cbebae4dbae0019fbf9b526.mp3", "duration_ms": 4880}, "s1-best-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/62a7ae61f93a1fdca88c4de42dbbe7a3e4c984130aaec4ec9f69152e5113550f.mp3", "hash": "0a50f3416922ac5618da176492b4e467b72dda3753197e7a184871abcf11f47d", "bytes": 34416, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/62a7ae61f93a1fdca88c4de42dbbe7a3e4c984130aaec4ec9f69152e5113550f.mp3", "duration_ms": 5680}, "s1-best-decision.choices": {"url": "http://localhost:4006/files/lesson-audio/9625a09520d136479bb4c7f5af0842fa30bb6fccd377bdc33a1ed28b81c538c0.mp3", "hash": "e8326716ce12836614109ca1e21cebf7fb96e80920ef86f54bdee1a2a74d00d6", "bytes": 60768, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/9625a09520d136479bb4c7f5af0842fa30bb6fccd377bdc33a1ed28b81c538c0.mp3", "duration_ms": 10080}, "s1-best-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/061d40bf049bee452bb543261ac6c3199900e8977cb29b40133f32f2ae6b3c2e.mp3", "hash": "5f7c909438eb5c12f310042d609a6e9266aa56fc6b2337b87e6af0dc9d1ccf38", "bytes": 40608, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/061d40bf049bee452bb543261ac6c3199900e8977cb29b40133f32f2ae6b3c2e.mp3", "duration_ms": 6720}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7f76a2de-27d1-4660-8203-c9ddad8fb861', 'en-US', '1', '{"meta": {"cast": ["zara"], "slug": "estimate-slider", "title": "Estimating lemonade cups", "locale": "en-US", "subject": "mixed", "objectives": ["Estimating quantities using a slider bar", "Developing number sense by estimating before counting"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-estimate-jar", "xp": 15, "type": "estimate_slider", "hints": ["Liruf sold 4 cups with a smaller pitcher. This pitcher is bigger.", "Think: if the small pitcher made 4 cups, this bigger one makes more."], "title": "How many cups does it make?", "payload": {"max": 20, "min": 1, "step": 1, "unit": "vasos", "scale": "linear"}, "narrator": {"emotion": "thinking", "character": "zara"}, "image_url": "http://localhost:4006/files/lesson-images/cd6881af18309cd9f7e1fc4699d1ffd2e7d5ae811a42ba5744d39e7dfdf15aa0.png", "prompt_md": "Zara sees the full pitcher. How many cups do you think she can sell?", "difficulty": 2, "explanation_md": "That''s right! This big pitcher makes 8 cups. Zara can sell them and earn money, just like Liruf did with his 4 cups.", "audio_segment_id": "s1-estimate-jar.prompt"}], "schema_version": 1}', '{"s1-estimate-jar": {"value": 8, "full_credit_delta": 2, "zero_credit_delta": 7}}', '{"units": {"s1-estimate-jar.hint.0": {"url": "http://localhost:4006/files/lesson-audio/25bb91d5c85cb3a6c15101d68f56ba8b40d02b0dcced5931f71f5490b766e678.mp3", "hash": "92fd795b7835ba1a82e84cafdf77bab87d73ba08aa2235531e82d9935183cc71", "bytes": 28656, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/25bb91d5c85cb3a6c15101d68f56ba8b40d02b0dcced5931f71f5490b766e678.mp3", "duration_ms": 4720}, "s1-estimate-jar.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c69231e2bc3b4b6d4e477ad592f2f63cfc459628331eca95010f86fdb5492428.mp3", "hash": "01d63c99787b3445b831f8a375cfe9477e8726e78df150b6c9d99e4b4436efdd", "bytes": 32544, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/c69231e2bc3b4b6d4e477ad592f2f63cfc459628331eca95010f86fdb5492428.mp3", "duration_ms": 5360}, "s1-estimate-jar.prompt": {"url": "http://localhost:4006/files/lesson-audio/58210a5025ed7cd93b6d2d2c1b6d9964c08109ee8d55249113a4f217751b8736.mp3", "hash": "c8ebcaa2434bb148798559dc70fcc958d7f371a7f7ea9dc5767a3778cd9329e1", "bytes": 25776, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/58210a5025ed7cd93b6d2d2c1b6d9964c08109ee8d55249113a4f217751b8736.mp3", "duration_ms": 4240}, "s1-estimate-jar.explanation": {"url": "http://localhost:4006/files/lesson-audio/75525239e454561b95217a9340c1eb0a063692b82f6ef794469f73e70908a773.mp3", "hash": "ea0770309bfcac9feb85494e07abdf804b5353306f421011011e3bbc60ec5fcc", "bytes": 47376, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/75525239e454561b95217a9340c1eb0a063692b82f6ef794469f73e70908a773.mp3", "duration_ms": 7840}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a0b48602-bbeb-4aac-8309-90ec3cdeba90', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "number-line", "title": "A reta da economia", "locale": "pt-BR", "subject": "mixed", "objectives": ["Localizar quantidades em uma reta numérica de 0 a 100", "Identificar quanto falta para alcançar uma meta de economia"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-line", "xp": 15, "type": "number_line", "hints": ["Conte de 10 em 10 de 20 até 80.", "20 + 10 = 30, 30 + 10 = 40... quantos 10s até 80?"], "title": "A reta da economia", "payload": {"max": 100, "min": 0, "ticks": 10, "labels": false}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Liruf tem 20 reais. O patinete custa 80. Quanto falta?", "difficulty": 2, "explanation_md": "Faltam 60 reais. 20 + 60 = 80. Se você colocou 80, somou o que ele já tem; se colocou 20, subtraiu o que ele já tem. Parabéns por tentar!", "audio_segment_id": "s1-number-line.prompt"}], "schema_version": 1}', '{"s1-number-line": {"value": 60, "full_credit_delta": 5, "zero_credit_delta": 15}}', '{"units": {"s1-number-line.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a243aa5d88a80328ac173c7885c55178ab42940974927a0d13d2dd8a0138cfde.mp3", "hash": "06b7a1b9eab37a8461d06a72db787a767541dfbc3493fdb8ec4336ebbfca8ae6", "bytes": 23328, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/a243aa5d88a80328ac173c7885c55178ab42940974927a0d13d2dd8a0138cfde.mp3", "duration_ms": 3840}, "s1-number-line.hint.1": {"url": "http://localhost:4006/files/lesson-audio/2a43fffc80afab38efccc9ee676781584d8ee25b9ca77456c2b641d79d756295.mp3", "hash": "b700875dc308442750959f30cc8c187c3cecd1df0a6e3156e89b9a053df73000", "bytes": 48384, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/2a43fffc80afab38efccc9ee676781584d8ee25b9ca77456c2b641d79d756295.mp3", "duration_ms": 8000}, "s1-number-line.prompt": {"url": "http://localhost:4006/files/lesson-audio/9b906d6e0fa34f7ac04aaecddcdb1ea9173ecf2cbbc3b51a700996c6dd3b3132.mp3", "hash": "fc142c5522fc5d0e4fca2253f508bc95de8d60f0d3af6c52b965cb92558514ba", "bytes": 36288, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/9b906d6e0fa34f7ac04aaecddcdb1ea9173ecf2cbbc3b51a700996c6dd3b3132.mp3", "duration_ms": 6000}, "s1-number-line.explanation": {"url": "http://localhost:4006/files/lesson-audio/fd2501784c6f99dfac81da8d5e136f782ecc80788764d611fc27938f76eb2116.mp3", "hash": "cd4337ecba2834edc35ae9580c3505137d64ae223f0ffdf20b4046e5d041ad71", "bytes": 83808, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/fd2501784c6f99dfac81da8d5e136f782ecc80788764d611fc27938f76eb2116.mp3", "duration_ms": 13920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('462e0be5-c40d-4de9-840d-6f696539d27e', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-dialogo-doble-choice", "title": "Dos vecinos opinan del puesto", "locale": "es-MX", "subject": "money", "objectives": ["Escuchar una conversación entre clientes sobre la limonada y responder preguntas de comprensión."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogo", "xp": 0, "type": "story_dialogue", "title": "Vecinos en la mesa", "payload": {"lines": [{"action": "idle", "emotion": "neutral", "text_md": "Oye, ¿ya viste el puesto de limonada de Liruf?", "character": "dina"}, {"action": "idle", "emotion": "neutral", "text_md": "Sí, venden vasos a 5 pesos. ¡Qué buen precio!", "character": "liruf"}, {"action": "idle", "emotion": "thinking", "text_md": "Sí, pero ayer compré uno y solo traía 3 pesos. Me faltaron 2.", "character": "dina"}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/fe77d573494685f84d5d65f742667ef2c70d7c33a8bfce0c07c62530e702aae8.png", "prompt_md": "Escucha lo que dicen los vecinos.", "difficulty": 1, "audio_segment_id": "s1-dialogo.prompt"}, {"id": "s2-true-false", "xp": 10, "type": "true_false", "title": "¿Cierto o falso?", "payload": {"statement_md": "Dina dice que el vaso de limonada cuesta 5 pesos.", "justifications": [{"id": "j1", "text_md": "Sí, porque Liruf dijo que el precio es 5 pesos."}, {"id": "j2", "text_md": "No, porque Dina dijo que solo traía 3 pesos."}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Según la conversación, elige si la afirmación es cierta o falsa.", "difficulty": 1, "explanation_md": "Liruf dijo ''venden vasos a 5 pesos'', así que es cierto. Dina solo dijo que traía 3 pesos, pero eso no cambia el precio.", "audio_segment_id": "s2-true-false.prompt"}, {"id": "s3-picture-choice", "xp": 10, "type": "picture_choice", "title": "¿Cuánto le faltó a Dina?", "payload": {"options": [{"id": "opt1", "icon": "monetization_on", "label": "2 monedas de 1 peso", "image_url": "http://localhost:4006/files/lesson-images/a4a0aa7370a7472e314745ad9a74ea76e36ab75861e0463949faaf813a9faccf.png", "rationale_md": "Correcto. 5 - 3 = 2, así que le faltaron 2 pesos."}, {"id": "opt2", "icon": "monetization_on", "label": "3 monedas de 1 peso", "image_url": "http://localhost:4006/files/lesson-images/43ba16097d757b34c0173e3ef37b37e03db0bb5f63c37d859ea2fb0ca0d7659c.png", "rationale_md": "Casi, pero 3 + 3 = 6, que es más de 5. Le faltaron solo 2 pesos."}, {"id": "opt3", "icon": "monetization_on", "label": "1 moneda de 5 pesos", "image_url": "http://localhost:4006/files/lesson-images/0f4f9cdf6ea523f309cee5d40ad4012aceb695a85c86d108c3d73a8835e52eee.png", "rationale_md": "Eso es más de lo que necesita. Le faltaron 2 pesos, no 5."}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Dina quería comprar un vaso de 5 pesos pero solo traía 3. ¿Cuánto le faltó?", "difficulty": 1, "explanation_md": "El vaso cuesta 5 pesos y Dina traía 3. 5 menos 3 son 2, por eso le faltaron 2 pesos.", "audio_segment_id": "s3-picture-choice.prompt"}], "schema_version": 1}', '{"s2-true-false": {"is_true": true, "correct_justification_id": "j1"}, "s3-picture-choice": {"correct_option_id": "opt1"}}', '{"units": {"s1-dialogo.line.0": {"url": "http://localhost:4006/files/lesson-audio/56248926d6d6ba310a99694549604ad41b5015af441d5dbf24a9f248b19d6f9d.mp3", "hash": "4bd42054524c0c054c4c22e8be98381f4a0fdb41990a98b8abe9811f58a213b2", "bytes": 18144, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/56248926d6d6ba310a99694549604ad41b5015af441d5dbf24a9f248b19d6f9d.mp3", "duration_ms": 2960}, "s1-dialogo.line.1": {"url": "http://localhost:4006/files/lesson-audio/f1249f26204c01472a427af54b6c32bfa65d8c0463ae07fd78e75f67d7646a31.mp3", "hash": "695c4bad8fc5c03da2b4e630abd14187232c5e7cb99839135dfefd4a93127c38", "bytes": 26208, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/f1249f26204c01472a427af54b6c32bfa65d8c0463ae07fd78e75f67d7646a31.mp3", "duration_ms": 4320}, "s1-dialogo.line.2": {"url": "http://localhost:4006/files/lesson-audio/34a43462435070e59b366caba669bb2dbdd81c701dc94130f4d052e27fb42e22.mp3", "hash": "4ef838088122181578c549b138ff07ec6cda4278e50bed83814e2f7c505dc48b", "bytes": 31968, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/34a43462435070e59b366caba669bb2dbdd81c701dc94130f4d052e27fb42e22.mp3", "duration_ms": 5280}, "s1-dialogo.prompt": {"url": "http://localhost:4006/files/lesson-audio/036e51622ab44f09b31b011c2f339e90cfc9daef85b216c2999e97465329e9fe.mp3", "hash": "754adaf1a5d4d96fdee4347f10f3db6807658d034fe95b65723713a79daace3b", "bytes": 13824, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/036e51622ab44f09b31b011c2f339e90cfc9daef85b216c2999e97465329e9fe.mp3", "duration_ms": 2240}, "s2-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/90988878a8ba21410183b670400e26aa9702fbde3c54ffd177981a7e78cdda04.mp3", "hash": "5806d5e0ff885965ae94abf382c63bfd129b9bb01f4246581e2acecc76906dfe", "bytes": 30096, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/90988878a8ba21410183b670400e26aa9702fbde3c54ffd177981a7e78cdda04.mp3", "duration_ms": 4960}, "s3-picture-choice.prompt": {"url": "http://localhost:4006/files/lesson-audio/e9e52657a454ea10e081c97e419edd67f08072044e4f3f48a9fe06c3a25de58e.mp3", "hash": "f8cec5b9053b3077a7c0c4788be399307da9214bb998b4b57a0a3d51cbd373aa", "bytes": 36288, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/e9e52657a454ea10e081c97e419edd67f08072044e4f3f48a9fe06c3a25de58e.mp3", "duration_ms": 6000}, "s2-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/e80019f5115895dea354447ea76d9447cb8049546e7cefbc1089d04b2bf69452.mp3", "hash": "3231477146b1cda3ef51da431467ca47214fc37a4009b67a91919d771917f52c", "bytes": 54576, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/e80019f5115895dea354447ea76d9447cb8049546e7cefbc1089d04b2bf69452.mp3", "duration_ms": 9040}, "s3-picture-choice.choices": {"url": "http://localhost:4006/files/lesson-audio/a695c0af0b3b91cd9355385ed73e84aff463127b2828b844845748e6fe890675.mp3", "hash": "63865bfa4aa3e49fe7319335d35a17c2fdd40fa2cc07175ab3f9a849b1abef7c", "bytes": 42048, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/a695c0af0b3b91cd9355385ed73e84aff463127b2828b844845748e6fe890675.mp3", "duration_ms": 6960}, "s3-picture-choice.explanation": {"url": "http://localhost:4006/files/lesson-audio/13df664a6e794c24415234065ac156179f79986b26153162f90d6640a3b496bf.mp3", "hash": "5562a180d2ce7221a84636bca18284c269b2a5cf28024ff56de7056ab42fb0f0", "bytes": 51264, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/13df664a6e794c24415234065ac156179f79986b26153162f90d6640a3b496bf.mp3", "duration_ms": 8480}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0754f3ae-1483-4dd4-bc05-e1f681fd5bcf', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-narrativa-choice", "title": "A Saturday at the stand", "locale": "en-US", "subject": "mixed", "objectives": ["Chain several skills in one lesson: listen to the situation, decide, calculate, and charge."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-apertura-sabado", "xp": 0, "type": "story_scene", "title": "Saturday opening", "payload": {"art": {"icon": "storefront", "tint": "primary", "image_url": "http://localhost:4006/files/lesson-images/1d6e2b04eb5d0da734ff351867b038e215c15fcc031db5d8dc057e7ccde2f5ba.png"}, "action": "idle", "body_md": "Yesterday you learned that the tip machine doubles what you put in. Today Liruf opens his lemonade stand. There''s already a line of customers. At what price will he sell each cup? If he sells 3 cups at 5 pesos, he earns 15 pesos. What if he sells them at 6?", "emotion": "excited", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "excited", "character": "liruf"}, "prompt_md": "Saturday is here!", "difficulty": 1, "audio_segment_id": "s1-apertura-sabado.prompt"}, {"id": "s2-precio-del-dia", "xp": 15, "type": "quiz_mcq", "hints": ["Think: 3 cups, each at 5 pesos. How much is 3 times 5?", "Use what you learned from the machine: doubling helps, but here it''s adding 5+5+5."], "title": "Price of the day", "payload": {"options": [{"id": "a", "text_md": "15 pesos", "rationale_md": "Correct: 3 cups × 5 pesos = 15 pesos. Great job!"}, {"id": "b", "text_md": "10 pesos", "rationale_md": "Almost: 3 cups at 5 pesos is not 10. Remember to add 5 three times."}, {"id": "c", "text_md": "18 pesos", "rationale_md": "That would be if each cup cost 6 pesos. But here each cup is 5 pesos."}], "shuffle": true}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf has 3 cups. How much does he earn if he sells each cup at 5 pesos?", "difficulty": 2, "explanation_md": "3 cups at 5 pesos each is 15 pesos total. If he sold them at 6, it would be 18, but maybe he would sell fewer cups. Better to keep a fair price.", "audio_segment_id": "s2-precio-del-dia.prompt"}], "schema_version": 1}', '{"s2-precio-del-dia": {"correct_option_id": "a"}}', '{"units": {"s1-apertura-sabado.body": {"url": "http://localhost:4006/files/lesson-audio/226cc9d5dc41686f23bf017dd22c22d4ffed2abc8118b15ce160f7f008c6603d.mp3", "hash": "96ad22714f6ec2e9062649f484baa66b0462e4bb6c7fa39df96f9e4ec14ae29c", "bytes": 96768, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/226cc9d5dc41686f23bf017dd22c22d4ffed2abc8118b15ce160f7f008c6603d.mp3", "duration_ms": 16080}, "s2-precio-del-dia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/428eb57429ce1c32b924922fb2c27b2df8f6183ce177572366529dbfb1a9106c.mp3", "hash": "0cee6e10946512a339d55718cd064a9c22904297319f3177e5148dd04edfdb6c", "bytes": 28656, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/428eb57429ce1c32b924922fb2c27b2df8f6183ce177572366529dbfb1a9106c.mp3", "duration_ms": 4720}, "s2-precio-del-dia.hint.1": {"url": "http://localhost:4006/files/lesson-audio/6f33f43bb3fb1e78b5ab6e4cf5f9ddedab7397283aaf2ec559be6183f22fa070.mp3", "hash": "def39dfaa05c36f9194991ad49a25ac2e9aa545eb9f888b3b49132763a491990", "bytes": 35424, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/6f33f43bb3fb1e78b5ab6e4cf5f9ddedab7397283aaf2ec559be6183f22fa070.mp3", "duration_ms": 5840}, "s2-precio-del-dia.prompt": {"url": "http://localhost:4006/files/lesson-audio/414d0e17563592ce9951f85a49273a7e42c42223a5e852fe906bb4391fdc22c7.mp3", "hash": "da966f3365e0c8a6d4d3ed4527bf9c6bb126575fe01c03892b716c6d03b2cd8f", "bytes": 31536, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/414d0e17563592ce9951f85a49273a7e42c42223a5e852fe906bb4391fdc22c7.mp3", "duration_ms": 5200}, "s1-apertura-sabado.prompt": {"url": "http://localhost:4006/files/lesson-audio/0fb49c663d0b30955646955a0e7d19f4cfb359805bc90e9c9023c4a9e51c0e58.mp3", "hash": "1f25ec6107a1b8ce06c7af7d8a3dbcbee177d05751c6a0c059a46f3e59df7e76", "bytes": 8496, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/0fb49c663d0b30955646955a0e7d19f4cfb359805bc90e9c9023c4a9e51c0e58.mp3", "duration_ms": 1360}, "s2-precio-del-dia.choices": {"url": "http://localhost:4006/files/lesson-audio/b5641ecd4c8f311266d1e66a582c626d13c2316dee37314a7c87020bb7d6be51.mp3", "hash": "f981741f12b661fb7b50d4b3721bc5704124c5611d206ede421a3896e0bf4afd", "bytes": 23904, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/b5641ecd4c8f311266d1e66a582c626d13c2316dee37314a7c87020bb7d6be51.mp3", "duration_ms": 3920}, "s2-precio-del-dia.explanation": {"url": "http://localhost:4006/files/lesson-audio/32ae0103aea8e6cea663186ea2fd46b53204fa5e36e5264cb77844025918d7a0.mp3", "hash": "4ea3d57a65fc7f88dba701808c2f0838f0903c78bd48849d446d66c6b3931104", "bytes": 61776, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/32ae0103aea8e6cea663186ea2fd46b53204fa5e36e5264cb77844025918d7a0.mp3", "duration_ms": 10240}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8f1a89c3-ae63-41f5-a2fa-70d1b7c6aac9', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "coin-count", "title": "Contar monedas: la primera venta", "locale": "es-MX", "subject": "money", "objectives": ["Contar monedas de 1, 2 y 5 pesos para sumar una cantidad exacta."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-contar-monedas", "xp": 10, "type": "coin_count", "hints": ["Primero cuenta las monedas de 2, luego las de 1.", "Junta todas las monedas y mira si suman 5."], "title": "La primera venta", "payload": {"target": 5, "currency": "MXN", "denominations": [1, 2]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/9fb8dbf390269b12dc88727b60a448d1b94f3cd8ebe247f695721a6285e7d053.png", "prompt_md": "Cuenta las monedas que te dio el cliente. ¿Son 5 pesos exactos?", "difficulty": 1, "explanation_md": "Tienes una moneda de 2 y tres de 1: 2 + 1 + 1 + 1 = 5. ¡Sí son 5 pesos exactos!", "audio_segment_id": "s1-contar-monedas.prompt"}], "schema_version": 1}', '{"s1-contar-monedas": {}}', '{"units": {"s1-contar-monedas.hint.0": {"url": "http://localhost:4006/files/lesson-audio/07beac5783aa5246ef9436ec22268d569ca89c352af9094c57b2368bba0adf8d.mp3", "hash": "c46f371c768125c93c99fe2d424665a34f81efae160932400c900ee6e18e38f7", "bytes": 22464, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/07beac5783aa5246ef9436ec22268d569ca89c352af9094c57b2368bba0adf8d.mp3", "duration_ms": 3680}, "s1-contar-monedas.hint.1": {"url": "http://localhost:4006/files/lesson-audio/b01375b95674d0a2a38333e2e3266bd52d3442c710bb14442fa7ca1a4ce8dc07.mp3", "hash": "c08a9bc49a246e6c06505cd8fceb44be660223a3e89554b8f80acc9c9edb995c", "bytes": 22896, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b01375b95674d0a2a38333e2e3266bd52d3442c710bb14442fa7ca1a4ce8dc07.mp3", "duration_ms": 3760}, "s1-contar-monedas.prompt": {"url": "http://localhost:4006/files/lesson-audio/7f2898a8d5b87cdcd34bbb8e95cf69e24f92de06638f36720099b26ee5230ea2.mp3", "hash": "b2283f404845fa27d2eb50d5ba7c94fc3d463c8830b498788be249b814535f49", "bytes": 27216, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7f2898a8d5b87cdcd34bbb8e95cf69e24f92de06638f36720099b26ee5230ea2.mp3", "duration_ms": 4480}, "s1-contar-monedas.explanation": {"url": "http://localhost:4006/files/lesson-audio/570a94a81ca640e9c6c9700d6496ece1cc68b83a9ba79ad7c71bf76c2deaa331.mp3", "hash": "c9e13778eaabc9562ac26f7fee63c25b536f82bc5fddb80dc4504297d3b64fd8", "bytes": 53136, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/570a94a81ca640e9c6c9700d6496ece1cc68b83a9ba79ad7c71bf76c2deaa331.mp3", "duration_ms": 8800}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ec92e8b8-2834-4bff-88e8-59733b2e617a', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "repaso-quiz-mcq", "title": "Quick job review", "locale": "en-US", "subject": "money", "objectives": ["Recall from memory the profit per glass of lemonade", "Remember the fair price and savings"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia-vaso", "xp": 10, "type": "quiz_mcq", "hints": ["How much do you have left after paying for ingredients?"], "title": "Profit per glass", "payload": {"options": [{"id": "a", "text_md": "3 pesos", "rationale_md": "Correct. 5 - 2 = 3 pesos profit per glass."}, {"id": "b", "text_md": "2 pesos", "rationale_md": "That''s the cost of ingredients, not profit. Profit is what''s left after paying for ingredients."}, {"id": "c", "text_md": "5 pesos", "rationale_md": "That''s the price of the glass, but you haven''t subtracted the cost of ingredients. Profit is less."}, {"id": "d", "text_md": "7 pesos", "rationale_md": "You added the price and cost, but profit is calculated by subtracting, not adding."}], "shuffle": true}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Each glass costs 5 pesos. Ingredients cost 2 pesos. How much do you earn per glass?", "difficulty": 1, "explanation_md": "You earn 3 pesos per glass: 5 pesos you charge minus 2 pesos for ingredients. That''s how you calculated profit yesterday.", "audio_segment_id": "s1-ganancia-vaso.prompt"}], "schema_version": 1}', '{"s1-ganancia-vaso": {"correct_option_id": "a"}}', '{"units": {"s1-ganancia-vaso.hint.0": {"url": "http://localhost:4006/files/lesson-audio/8632fdceb3afc567eda8a65aaaf10f7291751513ae56969a58f92f94d4a4471c.mp3", "hash": "b848861b784574bc132d84ee68334ee5e0de1c871cfb6102012209ea73e858a5", "bytes": 17136, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/8632fdceb3afc567eda8a65aaaf10f7291751513ae56969a58f92f94d4a4471c.mp3", "duration_ms": 2800}, "s1-ganancia-vaso.prompt": {"url": "http://localhost:4006/files/lesson-audio/a20e5585b5ff933a6a052f0e7c924147be089944202ab6c0ce72dc7be5a57887.mp3", "hash": "33c084574aa2ee7b9389b71574958cf5b632f3ae1135885d2e61e0449c5d65b0", "bytes": 35424, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/a20e5585b5ff933a6a052f0e7c924147be089944202ab6c0ce72dc7be5a57887.mp3", "duration_ms": 5840}, "s1-ganancia-vaso.choices": {"url": "http://localhost:4006/files/lesson-audio/44cdaf26ffac940aff922b305a9e0eb7750caef33c2577dd586c323adeebb7f2.mp3", "hash": "239956bc4f6bb7eb5c1d1e82809c1c6065ca58c38c75129d21a10b06179f83a8", "bytes": 27648, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/44cdaf26ffac940aff922b305a9e0eb7750caef33c2577dd586c323adeebb7f2.mp3", "duration_ms": 4560}, "s1-ganancia-vaso.explanation": {"url": "http://localhost:4006/files/lesson-audio/5473a574587ce58ba03244b24ed964167921f51b6b47c14bc07f20a61c19c3c4.mp3", "hash": "b7166a4e4b51010f35b65decedbb14b93fd78c505c735378db27e845ef358252", "bytes": 52704, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5473a574587ce58ba03244b24ed964167921f51b6b47c14bc07f20a61c19c3c4.mp3", "duration_ms": 8720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('462e0be5-c40d-4de9-840d-6f696539d27e', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-dialogo-doble-choice", "title": "Two neighbors talk about the stand", "locale": "en-US", "subject": "money", "objectives": ["Listen to a conversation between customers about the lemonade and answer comprehension questions."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogo", "xp": 0, "type": "story_dialogue", "title": "Neighbors at the table", "payload": {"lines": [{"action": "idle", "emotion": "neutral", "text_md": "Hey, have you seen Liruf''s lemonade stand?", "character": "dina"}, {"action": "idle", "emotion": "neutral", "text_md": "Yes, they sell cups for 5 pesos. What a good price!", "character": "liruf"}, {"action": "idle", "emotion": "thinking", "text_md": "Yes, but yesterday I bought one and only had 3 pesos. I was short 2.", "character": "dina"}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/4370e5c5f47f0ad49e1b490df1f8db00a06e413b7b2580bcbc522479d194d67b.png", "prompt_md": "Listen to what the neighbors say.", "difficulty": 1, "audio_segment_id": "s1-dialogo.prompt"}, {"id": "s2-true-false", "xp": 10, "type": "true_false", "title": "True or false?", "payload": {"statement_md": "Dina says the lemonade cup costs 5 pesos.", "justifications": [{"id": "j1", "text_md": "Yes, because Liruf said the price is 5 pesos."}, {"id": "j2", "text_md": "No, because Dina said she only had 3 pesos."}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Based on the conversation, choose whether the statement is true or false.", "difficulty": 1, "explanation_md": "Liruf said ''they sell cups for 5 pesos'', so it''s true. Dina only said she had 3 pesos, but that doesn''t change the price.", "audio_segment_id": "s2-true-false.prompt"}, {"id": "s3-picture-choice", "xp": 10, "type": "picture_choice", "title": "How much was Dina short?", "payload": {"options": [{"id": "opt1", "icon": "monetization_on", "label": "2 one-peso coins", "image_url": "http://localhost:4006/files/lesson-images/a4a0aa7370a7472e314745ad9a74ea76e36ab75861e0463949faaf813a9faccf.png", "rationale_md": "Correct. 5 - 3 = 2, so she was short 2 pesos."}, {"id": "opt2", "icon": "monetization_on", "label": "3 one-peso coins", "image_url": "http://localhost:4006/files/lesson-images/43ba16097d757b34c0173e3ef37b37e03db0bb5f63c37d859ea2fb0ca0d7659c.png", "rationale_md": "Almost, but 3 + 3 = 6, which is more than 5. She was short only 2 pesos."}, {"id": "opt3", "icon": "monetization_on", "label": "1 five-peso coin", "image_url": "http://localhost:4006/files/lesson-images/0f4f9cdf6ea523f309cee5d40ad4012aceb695a85c86d108c3d73a8835e52eee.png", "rationale_md": "That''s more than she needs. She was short 2 pesos, not 5."}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Dina wanted to buy a cup for 5 pesos but only had 3. How much was she short?", "difficulty": 1, "explanation_md": "The cup costs 5 pesos and Dina had 3. 5 minus 3 is 2, so she was short 2 pesos.", "audio_segment_id": "s3-picture-choice.prompt"}], "schema_version": 1}', '{"s2-true-false": {"is_true": true, "correct_justification_id": "j1"}, "s3-picture-choice": {"correct_option_id": "opt1"}}', '{"units": {"s1-dialogo.line.0": {"url": "http://localhost:4006/files/lesson-audio/0846fdbfd27bb708e997046addf996245b774f92b442a02b4eab4d53989b27a4.mp3", "hash": "7b671f683f1da028a00cb565965fc90070548f67e6c04cf6a1e8a7a31c9724ff", "bytes": 16128, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/0846fdbfd27bb708e997046addf996245b774f92b442a02b4eab4d53989b27a4.mp3", "duration_ms": 2640}, "s1-dialogo.line.1": {"url": "http://localhost:4006/files/lesson-audio/152dfd5e12cbb9684ccf63519a27f13d3e77dd1a2460d80bb58462fbc6191615.mp3", "hash": "c301e9795e2c2aa559daaed3dae308b1ac383899b0e49dcdbdb8422475820648", "bytes": 23904, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/152dfd5e12cbb9684ccf63519a27f13d3e77dd1a2460d80bb58462fbc6191615.mp3", "duration_ms": 3920}, "s1-dialogo.line.2": {"url": "http://localhost:4006/files/lesson-audio/111eec55c98027ab2e4d4bb49a60f562a99fdf4809708a585a17a4d2d3bd6868.mp3", "hash": "c675b9a70de3de4214bd92e3538acde4fafa847523df47f291f92ea77c782400", "bytes": 28656, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/111eec55c98027ab2e4d4bb49a60f562a99fdf4809708a585a17a4d2d3bd6868.mp3", "duration_ms": 4720}, "s1-dialogo.prompt": {"url": "http://localhost:4006/files/lesson-audio/854e07bfff019831e52530ef71f9dd8a466c4d5a20ecfa0718f3165841a6a5ae.mp3", "hash": "5a880ae4b0199f0b38600768add8b865dfa98fe8786b2625bc231aab97315527", "bytes": 10944, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/854e07bfff019831e52530ef71f9dd8a466c4d5a20ecfa0718f3165841a6a5ae.mp3", "duration_ms": 1760}, "s2-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/661554cdd587ab517ce84dc43b21b59b0e61c43e169e2a5d7da36c661148b56d.mp3", "hash": "a28768ab272f3f5af23162983132127b67531fff14f5f2f38d6b48ef5c3d6d60", "bytes": 26208, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/661554cdd587ab517ce84dc43b21b59b0e61c43e169e2a5d7da36c661148b56d.mp3", "duration_ms": 4320}, "s3-picture-choice.prompt": {"url": "http://localhost:4006/files/lesson-audio/181e75ae7ae2b8622b9798a130c1b466acf708a72a311a35a14cd7990c1965f4.mp3", "hash": "766426da64985a3a8bb91f1560d3221743aa17876903f179b6f44578c5cf8a29", "bytes": 32976, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/181e75ae7ae2b8622b9798a130c1b466acf708a72a311a35a14cd7990c1965f4.mp3", "duration_ms": 5440}, "s2-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/935558308f1479c108c49fd33f39c1b7f33abf94f496743982a292296368427a.mp3", "hash": "e5a562c5714aa9a2e27808fe427eefceb5d5edbbdbb2672121d53bb55eecab38", "bytes": 51264, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/935558308f1479c108c49fd33f39c1b7f33abf94f496743982a292296368427a.mp3", "duration_ms": 8480}, "s3-picture-choice.choices": {"url": "http://localhost:4006/files/lesson-audio/92f9ac5a0d6843d63fa1b6a7c553c7709c9a92f627c0aa066c679fc05f6f153e.mp3", "hash": "7d8fad3692c5c323c9ef2c6357d30fe93c598e3f6c402e4691b0c9c5da57e844", "bytes": 35424, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/92f9ac5a0d6843d63fa1b6a7c553c7709c9a92f627c0aa066c679fc05f6f153e.mp3", "duration_ms": 5840}, "s3-picture-choice.explanation": {"url": "http://localhost:4006/files/lesson-audio/6495b620ab948276cf6114bc7c90609aa09e609654792f4ec6a40fe12c74b584.mp3", "hash": "234afe4d9403b325e94ebe4d316e7c0042a9098a1a9727e5e229c810a9550b8a", "bytes": 40608, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/6495b620ab948276cf6114bc7c90609aa09e609654792f4ec6a40fe12c74b584.mp3", "duration_ms": 6720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b45d67a1-26c0-4ffa-b51c-76340c35e459', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "zara"], "slug": "order-steps", "title": "Ordene as compras da barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar as compras do mercado por prioridade de venda", "Distinguir entre necessidade e luxo em uma barraca"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-order-purchases", "xp": 15, "type": "order_steps", "hints": ["Pense: sem qual você não consegue fazer nem um copo de limonada?", "Os adesivos são um luxo, não ajudam a vender hoje."], "title": "Ordene as compras", "payload": {"items": [{"id": "limones", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/7eb45c97024f5d67dff96a1bf0872ceb848f39c5c3812a5cb20ecc6c01823644.png"}, {"id": "vasos", "text_md": "Copos", "image_url": "http://localhost:4006/files/lesson-images/6db97eba66a49009234e57846e0a19489f3baa386b68528ad2a4d025d197ebb6.png"}, {"id": "azucar", "text_md": "Açúcar", "image_url": "http://localhost:4006/files/lesson-images/36dff2f4a620b58e1eb341504616d6690d764a0ad45fc9e3f1754a798326833e.png"}, {"id": "calcomanias", "text_md": "Adesivos", "image_url": "http://localhost:4006/files/lesson-images/fb23424ac8b54802d75b4e66a5d4bb0612f7b798c368b39a37bd11ff6a03fdaa.png"}]}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Toque nos 4 itens em ordem: do que você mais precisa para vender hoje ao que pode esperar.", "difficulty": 2, "explanation_md": "Os limões vêm primeiro porque sem eles não há limonada. Os copos vêm em segundo porque os clientes precisam de onde servir. O açúcar melhora o sabor, mas você pode vender sem ele. Os adesivos são um capricho que espera.", "audio_segment_id": "s1-order-purchases.prompt"}], "schema_version": 1}', '{"s1-order-purchases": {"order": ["limones", "vasos", "azucar", "calcomanias"]}}', '{"units": {"s1-order-purchases.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b3351c858c74121a3a54bd05a18e5defcbd7f89d28783784353d8a66da4f0bfe.mp3", "hash": "c253db86470805bfc8272e86e20c7b2c47b6ca7676c3db162dcefd637e0f2eb7", "bytes": 28656, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/b3351c858c74121a3a54bd05a18e5defcbd7f89d28783784353d8a66da4f0bfe.mp3", "duration_ms": 4720}, "s1-order-purchases.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c2ef2d6df8bbea80308368fa763ee8dc02f8678202e9051637a77456e7c596b8.mp3", "hash": "373918061ec668d0458aaa118c94f7996d2d050e3416463630ee69e76ebef8a7", "bytes": 27216, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/c2ef2d6df8bbea80308368fa763ee8dc02f8678202e9051637a77456e7c596b8.mp3", "duration_ms": 4480}, "s1-order-purchases.prompt": {"url": "http://localhost:4006/files/lesson-audio/21240939c373c0b79e2bdb1ebccf347ef90ae04b944021e6b01e4dfbc5f12a8f.mp3", "hash": "f00925644a43a2c1531a6e96ddbe017243c772977838a0147842ffb1c3926453", "bytes": 33984, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/21240939c373c0b79e2bdb1ebccf347ef90ae04b944021e6b01e4dfbc5f12a8f.mp3", "duration_ms": 5600}, "s1-order-purchases.explanation": {"url": "http://localhost:4006/files/lesson-audio/a8a3b86c7004d914aae021eebf7ef3cf37b70f318ae186b06f34584df0d798e9.mp3", "hash": "b79a5bd85d4913a1918273f938340bab3171656e4a6b827da7c48ff47b335086", "bytes": 92016, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/a8a3b86c7004d914aae021eebf7ef3cf37b70f318ae186b06f34584df0d798e9.mp3", "duration_ms": 15280}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1f15af49-9573-4e17-a4ee-0685fa854b90', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "timeline-order", "title": "Order the sale day", "locale": "en-US", "subject": "mixed", "objectives": ["Order the steps of the sale day in chronological order."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ordenar-dia", "xp": 10, "type": "timeline_order", "hints": ["Think: what do you need before selling?", "After selling, what do you do with the money?"], "title": "Order the sale day", "payload": {"events": [{"id": "comprar", "icon": "shopping_cart", "text_md": "Buy lemons and sugar", "image_url": "http://localhost:4006/files/lesson-images/dd28f945a3198e47d206fd868e4e6ccac3e67c77c509828732c6d68818216d2d.png"}, {"id": "preparar", "icon": "local_drink", "text_md": "Prepare the lemonade", "image_url": "http://localhost:4006/files/lesson-images/1758e1e715482137899c455cfa0c75c5c7271e47acbd6f79b29d498cf015e6eb.png"}, {"id": "vender", "icon": "storefront", "text_md": "Sell lemonade at noon", "image_url": "http://localhost:4006/files/lesson-images/ac2d7fd17ff9eef30ed835cc6e3adcb964d0bb6e2b03c04deea47d5e69b6214f.png"}, {"id": "contar", "icon": "account_balance_wallet", "text_md": "Count money and save it", "image_url": "http://localhost:4006/files/lesson-images/0dd71418707314254d6719237f66292fff626cfd011b3d5ee2450e442bba1c29.png"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf already knows that 2 lemonades cost $10. What does he do first in his day?", "difficulty": 1, "explanation_md": "First you buy the ingredients, then you prepare the lemonade, then you sell at noon, and finally you count and save the money. That way Liruf doesn''t skip any steps!", "audio_segment_id": "s1-ordenar-dia.prompt"}], "schema_version": 1}', '{"s1-ordenar-dia": {"order": ["comprar", "preparar", "vender", "contar"]}}', '{"units": {"s1-ordenar-dia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c22cd6a50c594afddfaef759cfea1f5c9cef9654c30c492e840cdb857ea0a674.mp3", "hash": "fa3a3f0f9a85c1f73dcc98bee0582c0039b2c88a3f0b4e6f95e08e2945467c97", "bytes": 14688, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/c22cd6a50c594afddfaef759cfea1f5c9cef9654c30c492e840cdb857ea0a674.mp3", "duration_ms": 2400}, "s1-ordenar-dia.hint.1": {"url": "http://localhost:4006/files/lesson-audio/bec2c8a55b020e81c4d9516cca7798f59c730466e8fe338e64e6cfa5ee5cc589.mp3", "hash": "fe85db7a7b2715775df4c1e0939a055c3a1f9c24dd52d33271111cee4db64ebc", "bytes": 15696, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/bec2c8a55b020e81c4d9516cca7798f59c730466e8fe338e64e6cfa5ee5cc589.mp3", "duration_ms": 2560}, "s1-ordenar-dia.prompt": {"url": "http://localhost:4006/files/lesson-audio/fae9e6b9f138be6d5ff4d35e6806690d299ae3bcb9db4c4c2cdf7a341da9436f.mp3", "hash": "ae9ca4fa43b092d3856c05e008de01d5283da3f961db0493c3f52560eb4f37e5", "bytes": 32544, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/fae9e6b9f138be6d5ff4d35e6806690d299ae3bcb9db4c4c2cdf7a341da9436f.mp3", "duration_ms": 5360}, "s1-ordenar-dia.explanation": {"url": "http://localhost:4006/files/lesson-audio/f95610827a07a2be5ad82494ea7eaf92bbaa0ac0efbbc490897e84d9dde9ed7a.mp3", "hash": "58e7556edf9624da1dd540c7d279c2fc15e86fa3efd4a8dbbf438252e85c5a6c", "bytes": 57456, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/f95610827a07a2be5ad82494ea7eaf92bbaa0ac0efbbc490897e84d9dde9ed7a.mp3", "duration_ms": 9520}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('64ccde87-2312-4acf-a950-409fd6a622c9', 'pt-BR', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "read-chart", "title": "O gráfico de vendas da Zara", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ler o gráfico de barras de copos vendidos por dia e responder qual foi o melhor dia da semana."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-read-chart", "xp": 10, "type": "read_chart", "hints": ["Procure a barra mais alta do gráfico.", "A barra mais alta significa mais copos vendidos."], "title": "O melhor dia da Zara", "payload": {"chart": {"kind": "bar", "unit": "vasos", "series": [{"label": "Copos vendidos", "points": [{"x": "Segunda-feira", "y": 3}, {"x": "Terça-feira", "y": 5}, {"x": "Quarta-feira", "y": 2}, {"x": "Quinta-feira", "y": 4}, {"x": "Sexta-feira", "y": 7}]}]}, "questions": [{"id": "q1", "options": [{"id": "lunes", "text_md": "Segunda-feira"}, {"id": "martes", "text_md": "Terça-feira"}, {"id": "miercoles", "text_md": "Quarta-feira"}, {"id": "jueves", "text_md": "Quinta-feira"}, {"id": "viernes", "text_md": "Sexta-feira"}], "prompt_md": "Qual dia vendeu mais copos?"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Zara desenhou um gráfico com os copos que vendeu cada dia. Qual foi o dia que ela vendeu mais?", "difficulty": 1, "explanation_md": "Na sexta-feira a barra chega até 7, que é mais alto que os outros dias. Esse foi o melhor dia dela!", "audio_segment_id": "s1-read-chart.prompt"}], "schema_version": 1}', '{"s1-read-chart": {"correct": {"q1": "viernes"}}}', '{"units": {"s1-read-chart.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0b8f9b9faf81d13ef93121616209b9277925a6d6d67d90880d5a868babddd073.mp3", "hash": "6a5993f67cc5a56a8a3142da4857322729daa8de1da0be1d55e55ba4afab2548", "bytes": 16128, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0b8f9b9faf81d13ef93121616209b9277925a6d6d67d90880d5a868babddd073.mp3", "duration_ms": 2640}, "s1-read-chart.hint.1": {"url": "http://localhost:4006/files/lesson-audio/63bb8cb96d937cc193a6c41f9a51f6911544f1b71cd55549aab9794570831241.mp3", "hash": "d1dfe61282dbf4d748e5e3680bb1ec98e0e2927544e0ee1657f4b4c281303a08", "bytes": 21024, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/63bb8cb96d937cc193a6c41f9a51f6911544f1b71cd55549aab9794570831241.mp3", "duration_ms": 3440}, "s1-read-chart.prompt": {"url": "http://localhost:4006/files/lesson-audio/ab577d671f5ed607b6385f812e99a74fc5804bad896038594e814edf678d2966.mp3", "hash": "e03881eb3a8e052035ad4b14d3667867096db94f63b9f72694104d92243692d5", "bytes": 37728, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/ab577d671f5ed607b6385f812e99a74fc5804bad896038594e814edf678d2966.mp3", "duration_ms": 6240}, "s1-read-chart.explanation": {"url": "http://localhost:4006/files/lesson-audio/2c324b0f32c9758b9d7bb7574321f954d9160cae6dd0c649b5445a51ca7175ca.mp3", "hash": "3b1245920449fcbd7c373e5ac24288071f09cc43221ef417eb7188eb2ea9179e", "bytes": 43056, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2c324b0f32c9758b9d7bb7574321f954d9160cae6dd0c649b5445a51ca7175ca.mp3", "duration_ms": 7120}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('cf7bec3a-945e-4d4a-828c-5535f3a7e69c', 'en-US', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "equation-builder", "title": "Build the afternoon sum", "locale": "en-US", "subject": "money", "objectives": ["Build the afternoon sum with chips: 5 + 5 + 5 = 15 pesos (three cups sold)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-arma-suma", "xp": 15, "type": "equation_builder", "hints": ["Liruf sold three cups of lemonade. Each cup costs 5 pesos."], "title": "Build the sum", "payload": {"slots": 5, "tokens": [{"id": "t1", "text": "5"}, {"id": "t2", "text": "+"}, {"id": "t3", "text": "5"}, {"id": "t4", "text": "+"}, {"id": "t5", "text": "5"}, {"id": "t6", "text": "3"}, {"id": "t7", "text": "15"}], "target_result": 15}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "Tap the chips to show how much Liruf earned today.", "difficulty": 2, "explanation_md": "Liruf sold three cups of 5 pesos each, so the sum is 5 + 5 + 5 = 15 pesos. Now he has 15 pesos for his 80-peso guitar!", "audio_segment_id": "s1-arma-suma.prompt"}], "schema_version": 1}', '{"s1-arma-suma": {"accepted": ["t1 t2 t3 t4 t5"]}}', '{"units": {"s1-arma-suma.hint.0": {"url": "http://localhost:4006/files/lesson-audio/54e36ec388e8cde4827531757fbc39c67808d14033d6359644d5e207b752a927.mp3", "hash": "cb2b1419ce340e21c79c2fda7e52dd771c0f22314d30c5ec166ce4b8a99638fd", "bytes": 34848, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/54e36ec388e8cde4827531757fbc39c67808d14033d6359644d5e207b752a927.mp3", "duration_ms": 5760}, "s1-arma-suma.prompt": {"url": "http://localhost:4006/files/lesson-audio/52dea0e8168bee9f56ab1cdfd2ad185dbe129099c23b7920c8d7b2e0c48f431d.mp3", "hash": "09f360e9e1e1316c763949c3e78b66f31dfcec27ecd34bce074dcd3ec39523a4", "bytes": 22464, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/52dea0e8168bee9f56ab1cdfd2ad185dbe129099c23b7920c8d7b2e0c48f431d.mp3", "duration_ms": 3680}, "s1-arma-suma.explanation": {"url": "http://localhost:4006/files/lesson-audio/3d609917dd5908b853801607b4eefb1b05b1d67d2694026f3baa36a75bd78da6.mp3", "hash": "0e4c326154e1b59392c90ed8856fb429f60d9b0c7435578b41be01e931354a5c", "bytes": 76608, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/3d609917dd5908b853801607b4eefb1b05b1d67d2694026f3baa36a75bd78da6.mp3", "duration_ms": 12720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('bd130a62-6800-475b-8af6-59f14ffebc50', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "number-input", "title": "Escribir números: ganancia del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular y escribir cuánto ganó Liruf en total si vendió 4 vasos a 5 pesos cada uno (20 pesos)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia-total", "xp": 10, "type": "number_input", "hints": ["Cada vaso da 5 pesos. ¿Cuánto dan 4 vasos?", "Puedes sumar 5 + 5 + 5 + 5."], "title": "Ganancia del día", "payload": {"unit": "pesos", "decimals_hint": 0}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/98ba5a6b7caf3a8b577247a4b89b3d677b54d95acf78d6ff1725dc69647786af.png", "prompt_md": "Liruf vendió 4 vasos de limonada a 5 pesos cada uno. ¿Cuánto dinero hay en la caja?", "difficulty": 1, "explanation_md": "Liruf ganó 20 pesos porque 4 vasos × 5 pesos cada uno = 20 pesos.", "audio_segment_id": "s1-ganancia-total.prompt"}], "schema_version": 1}', '{"s1-ganancia-total": {"value": 20, "tolerance": 0}}', '{"units": {"s1-ganancia-total.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0e259643d0fb689c0f3b877c75fc4a7c90f952f6e06068607bbe54570efe0884.mp3", "hash": "1a2870f09bb3d2a26b5a9795b367f4b4951f5509ba172d19a079fe6a03a0ac53", "bytes": 24336, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/0e259643d0fb689c0f3b877c75fc4a7c90f952f6e06068607bbe54570efe0884.mp3", "duration_ms": 4000}, "s1-ganancia-total.hint.1": {"url": "http://localhost:4006/files/lesson-audio/b6a7341359a7f8771557e221853cf5dd3d1d4549a38a8e89b04236d7008d82be.mp3", "hash": "053ae85a8a60aba40ec946b3f67fa630b3b58596a503731f9732b9ac6ff57b70", "bytes": 26208, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b6a7341359a7f8771557e221853cf5dd3d1d4549a38a8e89b04236d7008d82be.mp3", "duration_ms": 4320}, "s1-ganancia-total.prompt": {"url": "http://localhost:4006/files/lesson-audio/66b215eb9fb928333a2ad329e88a8ed3f6c86a4c1cbf7bd7d87937058fd71b4c.mp3", "hash": "b3cfa4a0b48c39348bd57a1fec0b4e70d15891bac6d5e46ff92584a822aaeefe", "bytes": 46368, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/66b215eb9fb928333a2ad329e88a8ed3f6c86a4c1cbf7bd7d87937058fd71b4c.mp3", "duration_ms": 7680}, "s1-ganancia-total.explanation": {"url": "http://localhost:4006/files/lesson-audio/828c41d5e9acc5139f8c2cc8c0cbc42559953797663e709d46aba20ce313197d.mp3", "hash": "19d347a7f7a4c049359e87f1bf516b9e12eb66e1655a4d273758b09a2ab21b9c", "bytes": 40176, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/828c41d5e9acc5139f8c2cc8c0cbc42559953797663e709d46aba20ce313197d.mp3", "duration_ms": 6640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('98f38e44-71ba-4294-87ea-7a6684eb8359', 'es-MX', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "balance-scale", "title": "Equilibra la balanza del trueque", "locale": "es-MX", "subject": "mixed", "objectives": ["Equilibrar la balanza del trueque colocando galletas hasta que ambos platos valgan lo mismo."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-balance-trueque", "xp": 15, "type": "balance_scale", "hints": ["Cada vaso vale 5 pesos. ¿Cuánto suman 3 vasos?", "Cada galleta vale 3 pesos. ¿Cuántas galletas necesitas para igualar el total de los vasos?"], "title": "La balanza del trueque", "payload": {"weights": [{"id": "galleta1", "label": "galleta", "value": 3}, {"id": "galleta2", "label": "galleta", "value": 3}, {"id": "galleta3", "label": "galleta", "value": 3}, {"id": "galleta4", "label": "galleta", "value": 3}, {"id": "galleta5", "label": "galleta", "value": 3}], "left_fixed": [{"label": "vaso de limonada", "value": 5}, {"label": "vaso de limonada", "value": 5}, {"label": "vaso de limonada", "value": 5}], "unknown_label": "galleta"}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf pone 3 vasos de limonada (5 pesos cada uno). Coloca galletas de 3 pesos hasta que la balanza se nivele.", "difficulty": 2, "explanation_md": "3 vasos de 5 pesos suman 15 pesos. 5 galletas de 3 pesos también suman 15 pesos. ¡La balanza se equilibra!", "audio_segment_id": "s1-balance-trueque.prompt"}], "schema_version": 1}', '{"s1-balance-trueque": {}}', '{"units": {"s1-balance-trueque.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e0b7f38ae8b212d67cf48640dcab0d905dae491c83bbb36bc681efc43353867b.mp3", "hash": "7fda3bc202c77341c4d05f6f86dbd1fee1984dad274d435e48d81acc7fd73ca5", "bytes": 28224, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/e0b7f38ae8b212d67cf48640dcab0d905dae491c83bbb36bc681efc43353867b.mp3", "duration_ms": 4640}, "s1-balance-trueque.hint.1": {"url": "http://localhost:4006/files/lesson-audio/5bb88a7b72aa92cc8b38110c7b3b8158276fec1b3b92a55704a07c488421b24c.mp3", "hash": "8d0d4fc6cbbdd2b6c0654b9968afe3e90e880f87accd29096a001bfcc7b1d007", "bytes": 37296, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/5bb88a7b72aa92cc8b38110c7b3b8158276fec1b3b92a55704a07c488421b24c.mp3", "duration_ms": 6160}, "s1-balance-trueque.prompt": {"url": "http://localhost:4006/files/lesson-audio/36fff4dcace5badf3848ce6df4348dd9166a02b54fdd4408d3992dd03c2a8c3b.mp3", "hash": "88542cb201c94c494a3853b26c180905e69fbea97613b30e990ac29d3dd74020", "bytes": 47808, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/36fff4dcace5badf3848ce6df4348dd9166a02b54fdd4408d3992dd03c2a8c3b.mp3", "duration_ms": 7920}, "s1-balance-trueque.explanation": {"url": "http://localhost:4006/files/lesson-audio/dec6afe1a12af05e5f97d572e1243319dbaf32e63e1ae787795b15302490a79b.mp3", "hash": "fe3702f5acdb55ac2abed37a88fdef72516273fdb1c8e13365e41f7dc5b97984", "bytes": 55584, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/dec6afe1a12af05e5f97d572e1243319dbaf32e63e1ae787795b15302490a79b.mp3", "duration_ms": 9200}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58ff84ee-6d0e-4e43-a182-5b9ffd992543', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "memory-flip", "title": "Empareja productos con su pago exacto", "locale": "es-MX", "subject": "mixed", "objectives": ["Emparejar de memoria cada producto con las monedas que lo pagan, usando los precios del puesto: galleta = 3 (1+2), vaso chico = 5, jarra grande = 20 (10+10)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-memory-flip", "xp": 10, "type": "memory_flip", "hints": ["La galleta cuesta 3, el vaso chico 5 y la jarra grande 20."], "title": "Precios del puesto", "payload": {"pairs": [{"a_md": "Galleta", "b_md": "1 + 2", "a_icon": "cookie", "b_icon": "payments", "a_image_url": "http://localhost:4006/files/lesson-images/f6a651de0e0476e1e039511e898773c0ee5678eeccd886462288d46bceb62bee.png", "b_image_url": "http://localhost:4006/files/lesson-images/c4fcfe2407afd7420e3a9412b4c5c52aa70ea539362fd43756792143001a6c31.png"}, {"a_md": "Vaso chico", "b_md": "5", "a_icon": "water_drop", "b_icon": "payments", "a_image_url": "http://localhost:4006/files/lesson-images/ed2b34291d93c8e55fa9e893d00549d7426d8370e2707952ec300615298c3985.png", "b_image_url": "http://localhost:4006/files/lesson-images/82048d6ce67c385dbdc9d4bddd50737d50bd412ebeedf9dc853a8d5971d1eb53.png"}, {"a_md": "Jarra grande", "b_md": "10 + 10", "a_icon": "local_bar", "b_icon": "payments", "a_image_url": "http://localhost:4006/files/lesson-images/94a48eabffbf92903e39f230fab01edc2ce1eadb0ee32cb3f6ca6c9aae0fbccc.png", "b_image_url": "http://localhost:4006/files/lesson-images/56490c7515ec208f4812c0edb0412c35617fb239a1f511ca6892e1062acdb80b.png"}]}, "narrator": {"emotion": "encouraging", "character": "zara"}, "prompt_md": "Toca las cartas para emparejar cada producto con su pago exacto. Precios: galleta 3, vaso chico 5, jarra grande 20.", "difficulty": 1, "explanation_md": "Cada producto tiene un precio fijo: galleta 3, vaso chico 5, jarra grande 20. Al emparejar bien, recuerdas cuánto cobrar.", "audio_segment_id": "s1-memory-flip.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-memory-flip.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a30d0fe6f427d4df6c8921c9bcb7d4226bb91df14c15501895762a26eb570fa7.mp3", "hash": "ed74922c3d0fe80838b32b473141e704da285c3b36e76cc8b4fa0e4607db00d0", "bytes": 27648, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/a30d0fe6f427d4df6c8921c9bcb7d4226bb91df14c15501895762a26eb570fa7.mp3", "duration_ms": 4560}, "s1-memory-flip.prompt": {"url": "http://localhost:4006/files/lesson-audio/36299a9e7bc4c36fc02ff58f7e097b6a131446efcc192bb8443a73469517f9d5.mp3", "hash": "b99383c1be793c885792e7e2700dcc27069e24f37f38fe60c799199200f5477d", "bytes": 53136, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/36299a9e7bc4c36fc02ff58f7e097b6a131446efcc192bb8443a73469517f9d5.mp3", "duration_ms": 8800}, "s1-memory-flip.explanation": {"url": "http://localhost:4006/files/lesson-audio/624800fc144f86b7dad13d68af2446ea17b9e2e4e5cff29bf25c6cc5b745a4c3.mp3", "hash": "753207e3ac870dc4515e5c20df70e0980a4b52a2ec5566d1ff817b60dd14d0dc", "bytes": 52704, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/624800fc144f86b7dad13d68af2446ea17b9e2e4e5cff29bf25c6cc5b745a4c3.mp3", "duration_ms": 8720}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('59260361-67d7-4d0e-9c68-8c5e00637103', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "price-compare", "title": "Comparar precios de limones", "locale": "es-MX", "subject": "mixed", "objectives": ["Comparar precios de limones en dos puestos del mercado y elegir el más barato para gastar menos (costo más bajo = más ganancia)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-compare", "xp": 10, "type": "price_compare", "hints": ["Cuenta cuántos limones dan en cada puesto por 6 pesos.", "El puesto que da más limones por el mismo precio es más barato."], "title": "¿Cuál puesto de limones es más barato?", "payload": {"offers": [{"id": "puesto-a", "qty": 3, "unit": "limones", "label": "Puesto A: 3 limones por 6 pesos", "price": 6, "image_url": "http://localhost:4006/files/lesson-images/3171605e406df5c1f2aa677d54f083de3c30d2572fb4ff7b660bf5c80457b0f9.png"}, {"id": "puesto-b", "qty": 2, "unit": "limones", "label": "Puesto B: 2 limones por 6 pesos", "price": 6, "image_url": "http://localhost:4006/files/lesson-images/7183bba13bcc87b93bda24ed462242ec946a77198664a1e14af67d1af6bb4b0f.png"}], "currency": "MXN"}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Dina quiere comprar limones para su limonada. ¿Cuál puesto le da más limones por 6 pesos?", "difficulty": 1, "explanation_md": "El puesto A da 3 limones por 6 pesos, el puesto B da 2 limones por 6 pesos. ¡El puesto A te da un limón extra por el mismo dinero! Así te sobra más para tu guitarra.", "audio_segment_id": "s1-price-compare.prompt"}], "schema_version": 1}', '{"s1-price-compare": {"best_offer_id": "puesto-a"}}', '{"units": {"s1-price-compare.hint.0": {"url": "http://localhost:4006/files/lesson-audio/8a159003a15f16bc1220d1634e3b22dc6c6929b40bab9345f8f44b043a5a14b0.mp3", "hash": "e8ca7805aa882b865ee175d14d5589a3a4e34c3bee474a97496afd96af1b0c2a", "bytes": 21456, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/8a159003a15f16bc1220d1634e3b22dc6c6929b40bab9345f8f44b043a5a14b0.mp3", "duration_ms": 3520}, "s1-price-compare.hint.1": {"url": "http://localhost:4006/files/lesson-audio/cef727d224329eada0bde2a2bd3ec2a7dc2d76d12f6a2767425e774224ce2a4f.mp3", "hash": "593cb107e443b2e06188944bcc00bef25313c0bd7e37b1ed96740dd5aa0d6952", "bytes": 24768, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/cef727d224329eada0bde2a2bd3ec2a7dc2d76d12f6a2767425e774224ce2a4f.mp3", "duration_ms": 4080}, "s1-price-compare.prompt": {"url": "http://localhost:4006/files/lesson-audio/7985ee61dcf8a299424e18db18d069f9c2f4397be5901f5a07399161a3645952.mp3", "hash": "db4c0d9d2b5976904659ea9793d88d1a18bc2a80930bb5a20055ee44a0fca258", "bytes": 35856, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7985ee61dcf8a299424e18db18d069f9c2f4397be5901f5a07399161a3645952.mp3", "duration_ms": 5920}, "s1-price-compare.explanation": {"url": "http://localhost:4006/files/lesson-audio/691d8763f29c96d4b46e115881d00a4f96ac50f16b5c7d7ae3d81f16a6f388c7.mp3", "hash": "906b350453d030dceb494e8fdd3fe1e81f71243ebd1e632d50410a80c98f9f65", "bytes": 78048, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/691d8763f29c96d4b46e115881d00a4f96ac50f16b5c7d7ae3d81f16a6f388c7.mp3", "duration_ms": 12960}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58172086-898d-4095-acf1-3502b8607e76', 'es-MX', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "story-branch", "title": "El precio del día", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir el precio de la limonada considerando el costo de producción y la ganancia por vaso.", "Observar cómo el precio afecta las ventas y el avance hacia una meta de ahorro."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio", "xp": 20, "type": "story_branch", "hints": ["Si cobra muy caro, quizá nadie compre. Si cobra muy barato, ganará poco por vaso."], "title": "Elige el precio", "payload": {"nodes": [{"id": "inicio", "choices": [{"id": "precio5", "next": "final5", "text_md": "5 pesos (el de siempre)"}, {"id": "precio3", "next": "final3", "text_md": "3 pesos (más barato)"}, {"id": "precio10", "next": "final10", "text_md": "10 pesos (el doble)"}], "emotion": "thinking", "text_md": "Hace mucho calor y seis vecinos hacen fila en el puesto de Liruf. Cada vaso de limonada cuesta 2 pesos hacerlo. ¿Qué precio pone Liruf hoy?", "character": "liruf"}, {"id": "final5", "choices": [{"id": "fin5", "next": null, "text_md": "Fin"}], "emotion": "happy", "text_md": "¡Los 6 vecinos compran! Cada vaso da 3 pesos de ganancia (5 - 2 = 3). Liruf gana 18 pesos hoy. ¡Buen avance hacia la guitarra de 80!", "character": "liruf"}, {"id": "final3", "choices": [{"id": "fin3", "next": null, "text_md": "Fin"}], "emotion": "surprised", "text_md": "Los 6 compran, pero solo ganas 1 peso por vaso (3 - 2 = 1). Liruf gana solo 6 pesos. Casi no avanza hacia la guitarra.", "character": "liruf"}, {"id": "final10", "choices": [{"id": "fin10", "next": null, "text_md": "Fin"}], "emotion": "surprised", "text_md": "Los vecinos hacen mueca y se van a la nieve. Liruf se queda con la jarra llena. No vende nada y no gana nada para la guitarra.", "character": "liruf"}], "start_node": "inicio"}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/336176999bbfd7a9495e4b56a3176283b7b82605f05da1475ae8d143a6736319.png", "prompt_md": "Liruf tiene que poner el precio de hoy. Cada vaso le cuesta 2 pesos hacerlo. ¿Cuánto cobrará?", "difficulty": 2, "explanation_md": "Liruf eligió un precio y vio cuánto avanzó hacia la guitarra de 80 pesos.", "audio_segment_id": "s1-precio.prompt"}], "schema_version": 1}', '{"s1-precio": {"qualities": [{"score": 100, "node_id": "inicio", "choice_id": "precio5"}, {"score": 30, "node_id": "inicio", "choice_id": "precio3"}, {"score": 0, "node_id": "inicio", "choice_id": "precio10"}]}}', '{"units": {"s1-precio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ade7e45494d3d6e70f2569c52f1cb3a23aa8f242615e42706e9cfaeb9dddf351.mp3", "hash": "de336c28e3da8e6a0e7cfb27f59048a499ff1b022755781d81891e84b026be9d", "bytes": 36864, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/ade7e45494d3d6e70f2569c52f1cb3a23aa8f242615e42706e9cfaeb9dddf351.mp3", "duration_ms": 6080}, "s1-precio.prompt": {"url": "http://localhost:4006/files/lesson-audio/12e947c27bb2b47be3ab593780754425f7fae6304d41980b85b74b15d7a69f93.mp3", "hash": "c851ad90ac46d6e03ea2352cfb1ee41b135f3255fefac26e00161e01d3ee6121", "bytes": 39744, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/12e947c27bb2b47be3ab593780754425f7fae6304d41980b85b74b15d7a69f93.mp3", "duration_ms": 6560}, "s1-precio.explanation": {"url": "http://localhost:4006/files/lesson-audio/0885659c235530000ad13f3a12e111477f27de5ce28f537d76d8a54a59b4cfc8.mp3", "hash": "b56c6a268c28b46c596112036b214f08db82ad19689d8acd8d7bfb4534b3a9c5", "bytes": 31104, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/0885659c235530000ad13f3a12e111477f27de5ce28f537d76d8a54a59b4cfc8.mp3", "duration_ms": 5120}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('29159ba6-6f90-42be-9578-fda50515f345', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "budget-fit", "title": "Faça a feira com $20", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular quanto dinheiro sobra depois de comprar necessidades", "Decidir quais extras cabem em um orçamento limitado"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-surte", "xp": 15, "type": "budget_fit", "hints": ["Primeiro, some o preço dos limões e do açúcar.", "Subtraia essa soma de $20 para saber quanto sobra."], "title": "Faça a feira com $20", "payload": {"items": [{"id": "limones", "icon": "eco", "need": true, "label": "Limões", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/d3b2922829636fdf8af119326dc1405c5e67e7cb85d47a9a5aa9d6a7ea3e4961.png"}, {"id": "azucar", "icon": "bakery_dining", "need": true, "label": "Açúcar", "price": 6, "image_url": "http://localhost:4006/files/lesson-images/169617e6810d4a4d5b606d3947035610ed2de2883706ac9b7600d9769e34c69a.png"}, {"id": "hielo", "icon": "ac_unit", "need": false, "label": "Gelo", "price": 5, "image_url": "http://localhost:4006/files/lesson-images/e2a9fd005a7dd5db7a5d578e3379932ae3c48d2f5b7bd514815ead5fcd4aa178.png"}, {"id": "popotes", "icon": "local_drink", "need": false, "label": "Canudos", "price": 3, "image_url": "http://localhost:4006/files/lesson-images/ade3e1a5fc2e0f0cda6803f90886bdffda02fbd5485bcfc78b61ffec6c9f642c.png"}, {"id": "jarra", "icon": "local_cafe", "need": false, "label": "Jarra bonita", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/65bd49e63b09a579950a0f41d357d97a43f680f011cb021b162037d0447529c1.png"}], "budget": 20, "currency": "MXN", "must_buy_needs": true}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf tem $20. Precisa comprar limões ($8) e açúcar ($6). Qual extra cabe no que sobra?", "difficulty": 2, "explanation_md": "Limões ($8) + açúcar ($6) = $14. Sobram $6. O gelo custa $5, os canudos $3, a jarra $8. Com $6, você pode comprar gelo ($5) ou canudos ($3), mas não a jarra ($8). Se comprar a jarra, não sobra para o açúcar e a limonada fica amarga.", "audio_segment_id": "s1-surte.prompt"}], "schema_version": 1}', '{"s1-surte": {}}', '{"units": {"s1-surte.hint.0": {"url": "http://localhost:4006/files/lesson-audio/8163359cbb53671a043a4ff6a2ec28ac9dc27d67f5d5b08360d78ba0abe6e3b3.mp3", "hash": "325ecb4197a7949a94a9da8b0963a901d6fb32c545a23ec5b744d4e68a1b0dbf", "bytes": 21456, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/8163359cbb53671a043a4ff6a2ec28ac9dc27d67f5d5b08360d78ba0abe6e3b3.mp3", "duration_ms": 3520}, "s1-surte.hint.1": {"url": "http://localhost:4006/files/lesson-audio/7cc3f31e6c45e0a9a6e910000da8f9cb5cd8405fc8dd917b2d8af07b3795f96b.mp3", "hash": "cc6a58b4b01c83b11b4a8ff8c2a3a407d8a877d57fbf59c80b9441275c6a3fe4", "bytes": 28656, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7cc3f31e6c45e0a9a6e910000da8f9cb5cd8405fc8dd917b2d8af07b3795f96b.mp3", "duration_ms": 4720}, "s1-surte.prompt": {"url": "http://localhost:4006/files/lesson-audio/78863c0f954750857f7c4a13d2cb1de499d8556fdc3a9d7929318ad1697a1c34.mp3", "hash": "3104be452c46056a902752c9106f61058f6df12cc093bd5900c5cd83fc00e7e9", "bytes": 54576, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/78863c0f954750857f7c4a13d2cb1de499d8556fdc3a9d7929318ad1697a1c34.mp3", "duration_ms": 9040}, "s1-surte.explanation": {"url": "http://localhost:4006/files/lesson-audio/ccff6b8bee1bb8e9715ee132927f8e10da62f31a2428bc13867bf2aab1b27541.mp3", "hash": "6a4cdd91f748ba93369d4180db703c75a067e716c9a3f694b044eeb05e23223a", "bytes": 174096, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/ccff6b8bee1bb8e9715ee132927f8e10da62f31a2428bc13867bf2aab1b27541.mp3", "duration_ms": 28960}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('59260361-67d7-4d0e-9c68-8c5e00637103', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "price-compare", "title": "Comparing lemon prices", "locale": "en-US", "subject": "mixed", "objectives": ["Compare lemon prices at two market stalls and choose the cheapest one to spend less (lower cost = more profit)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-compare", "xp": 10, "type": "price_compare", "hints": ["Count how many lemons each stall gives for 6 pesos.", "The stall that gives more lemons for the same price is cheaper."], "title": "Which lemon stall is cheaper?", "payload": {"offers": [{"id": "puesto-a", "qty": 3, "unit": "limones", "label": "Stall A: 3 lemons for 6 pesos", "price": 6, "image_url": "http://localhost:4006/files/lesson-images/d435bb5e6ebae0d1d05f341a76b17ee61aa8882d9378b3805797258111127535.png"}, {"id": "puesto-b", "qty": 2, "unit": "limones", "label": "Stall B: 2 lemons for 6 pesos", "price": 6, "image_url": "http://localhost:4006/files/lesson-images/57d3eb9bfbd963d1147d29ac15d1e65f9257f8418bc7781e7f8e6df0836cfdbf.png"}], "currency": "MXN"}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Dina wants to buy lemons for her lemonade. Which stall gives her more lemons for 6 pesos?", "difficulty": 1, "explanation_md": "Stall A gives 3 lemons for 6 pesos, stall B gives 2 lemons for 6 pesos. Stall A gives you an extra lemon for the same money! So you have more left for your guitar.", "audio_segment_id": "s1-price-compare.prompt"}], "schema_version": 1}', '{"s1-price-compare": {"best_offer_id": "puesto-a"}}', '{"units": {"s1-price-compare.hint.0": {"url": "http://localhost:4006/files/lesson-audio/81a908395fb2b259d18b477d09b6f88fbf86b43e95ca3646aaaa436e8ad49708.mp3", "hash": "84d6929eb0fdac574d39611a3ba63777352bc9331dd56853e4e2ee238b16ca4d", "bytes": 18576, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/81a908395fb2b259d18b477d09b6f88fbf86b43e95ca3646aaaa436e8ad49708.mp3", "duration_ms": 3040}, "s1-price-compare.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c0024c82fccd4f7f6abff24667779def24498af56fa541f82964c031746ac43a.mp3", "hash": "c0bad49988a2b8718bc7f9843cbc37cab9e98d624090c8825aeef230cf8108df", "bytes": 20016, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c0024c82fccd4f7f6abff24667779def24498af56fa541f82964c031746ac43a.mp3", "duration_ms": 3280}, "s1-price-compare.prompt": {"url": "http://localhost:4006/files/lesson-audio/3d2826b5c87ea25c7ddba59e1689d40614e513aa2121a761c735b3f3748b87a7.mp3", "hash": "f7db5ac19ef89abbdccc4cf0f238fdf1679d9ad6cf8812dbc5abd2c2a74b4906", "bytes": 31968, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3d2826b5c87ea25c7ddba59e1689d40614e513aa2121a761c735b3f3748b87a7.mp3", "duration_ms": 5280}, "s1-price-compare.explanation": {"url": "http://localhost:4006/files/lesson-audio/d21afd862c8bd39ce318997815c8bf87ecdef05da23242c24a727f4bf4c6f5a3.mp3", "hash": "01e6f25f66e26ed13671841096391d42e7ce9a7bb5763e54f4a7cf684c1476d2", "bytes": 61776, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/d21afd862c8bd39ce318997815c8bf87ecdef05da23242c24a727f4bf4c6f5a3.mp3", "duration_ms": 10240}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1f15af49-9573-4e17-a4ee-0685fa854b90', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "timeline-order", "title": "Organize the sale day", "locale": "pt-BR", "subject": "mixed", "objectives": ["Arrange the steps of the sale day in chronological order."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ordenar-dia", "xp": 10, "type": "timeline_order", "hints": ["Think: what do you need before selling?", "After selling, what do you do with the money?"], "title": "Organize the sale day", "payload": {"events": [{"id": "comprar", "icon": "shopping_cart", "text_md": "Buy lemons and sugar", "image_url": "http://localhost:4006/files/lesson-images/dd28f945a3198e47d206fd868e4e6ccac3e67c77c509828732c6d68818216d2d.png"}, {"id": "preparar", "icon": "local_drink", "text_md": "Prepare the lemonade", "image_url": "http://localhost:4006/files/lesson-images/1758e1e715482137899c455cfa0c75c5c7271e47acbd6f79b29d498cf015e6eb.png"}, {"id": "vender", "icon": "storefront", "text_md": "Sell lemonade at noon", "image_url": "http://localhost:4006/files/lesson-images/ac2d7fd17ff9eef30ed835cc6e3adcb964d0bb6e2b03c04deea47d5e69b6214f.png"}, {"id": "contar", "icon": "account_balance_wallet", "text_md": "Count money and save it", "image_url": "http://localhost:4006/files/lesson-images/0dd71418707314254d6719237f66292fff626cfd011b3d5ee2450e442bba1c29.png"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf already knows that 2 lemonades cost $10. What does he do first in his day?", "difficulty": 1, "explanation_md": "First you buy the ingredients, then you prepare the lemonade, then you sell at noon, and finally you count and save the money. That way Liruf doesn''t skip any steps!", "audio_segment_id": "s1-ordenar-dia.prompt"}], "schema_version": 1}', '{"s1-ordenar-dia": {"order": ["comprar", "preparar", "vender", "contar"]}}', '{"units": {"s1-ordenar-dia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a44ee47ef20e44e35ad627ac033f684a619d07e69a9b22318e60aeefc873ba80.mp3", "hash": "b67f248d81b4ad1a22bcc807593220b487167bc37cee164673f6efcf35132a67", "bytes": 17136, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/a44ee47ef20e44e35ad627ac033f684a619d07e69a9b22318e60aeefc873ba80.mp3", "duration_ms": 2800}, "s1-ordenar-dia.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a0a49eac5cca426743e3019fc8946c58ac6fc1b1ce10a22748c8244818d3c54b.mp3", "hash": "8af4554af244c5eb49315cebc56b6f58f3f581a1591fe070e2efc45bf6ee9d79", "bytes": 16704, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/a0a49eac5cca426743e3019fc8946c58ac6fc1b1ce10a22748c8244818d3c54b.mp3", "duration_ms": 2720}, "s1-ordenar-dia.prompt": {"url": "http://localhost:4006/files/lesson-audio/7ab5b905f0ed1ca9b79e3e8e14f5d9595687848b5ed30ee4a526e82d875b9042.mp3", "hash": "19a278ea31864d87f207feeec5ba667c3ed30e75969215dd0a8e19264ad2ba12", "bytes": 39744, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/7ab5b905f0ed1ca9b79e3e8e14f5d9595687848b5ed30ee4a526e82d875b9042.mp3", "duration_ms": 6560}, "s1-ordenar-dia.explanation": {"url": "http://localhost:4006/files/lesson-audio/e81ce5d716950a3e1d4dda9fe3eea6b0b58274426e6072afdb8a11dae89e6eb2.mp3", "hash": "6f702d992cdf913d4231bdef0b931c2100fb30c4d1abeaae4d98e210aff2bf78", "bytes": 62208, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/e81ce5d716950a3e1d4dda9fe3eea6b0b58274426e6072afdb8a11dae89e6eb2.mp3", "duration_ms": 10320}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7d51bf02-4dd4-4263-9e53-aa5ccb8a1e03', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "interest-peek", "title": "La alcancía que agradece la paciencia", "locale": "es-MX", "subject": "money", "objectives": ["Decidir si dejar dinero en una alcancía que da moneditas extra cada semana conviene más que gastarlo ya.", "Predecir el total después de esperar, entendiendo que crece un poco pero no se duplica."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-interest-peek", "xp": 10, "type": "interest_peek", "hints": ["Cada semana la alcancía da 2 monedas de 1 peso. ¿Cuántas monedas extra da en 2 semanas?", "Empieza con 20. Suma las moneditas extra."], "title": "¿Dejar los 20 o sacarlos ya?", "payload": {"periods": 2, "currency": "MXN", "rate_pct": 10, "principal": 20, "prediction": {"kind": "choice", "options": [{"id": "opt1", "text_md": "Se queda en 20"}, {"id": "opt2", "text_md": "24 pesos"}, {"id": "opt3", "text_md": "Casi 40 pesos"}]}}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf tiene 20 pesos ahorrados para una guitarra que cuesta 80. Rho le dice: ''Si guardas tu dinero en esta alcancía especial, cada semana te da 2 monedas de 1 peso extra por dejarlo ahí.'' Liruf mete sus 20 pesos. Piensa: ''Si espero 2 semanas, ¿tendré más o menos que si gasto todo ahora?'' ¿Cuánto tendrá Liruf después de 2 semanas?", "difficulty": 1, "explanation_md": "La alcancía da 2 monedas de 1 peso cada semana, así que en 2 semanas da 4 pesos extra. 20 + 4 = 24. ¡El dinero crece poquito a poquito hacia la guitarra! Si hubiera gastado todo ahora, no tendría esos 4 pesos extra.", "audio_segment_id": "s1-interest-peek.prompt"}], "schema_version": 1}', '{"s1-interest-peek": {"value": 24, "tolerance": 1, "correct_option_id": "opt2"}}', '{"units": {"s1-interest-peek.hint.0": {"url": "http://localhost:4006/files/lesson-audio/668ab78163ee044ba3efd11e77b6e3eec662ac301caa366cdc069a4a6dc98a2b.mp3", "hash": "3dc18383d9a32c406d7fbe70048d4c251d4877228f2348bcfeef02d3057b0217", "bytes": 40608, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/668ab78163ee044ba3efd11e77b6e3eec662ac301caa366cdc069a4a6dc98a2b.mp3", "duration_ms": 6720}, "s1-interest-peek.hint.1": {"url": "http://localhost:4006/files/lesson-audio/0ec9032c2aa437cfaaac7e397a9407c360275eb841b0372c911b3802ec3b3fd3.mp3", "hash": "ac7225036bac770feb6907a8d2cdac588fcdfe82d73be88200379222db2cac7f", "bytes": 21024, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/0ec9032c2aa437cfaaac7e397a9407c360275eb841b0372c911b3802ec3b3fd3.mp3", "duration_ms": 3440}, "s1-interest-peek.prompt": {"url": "http://localhost:4006/files/lesson-audio/4713ac3a791be4ee9f44e0de9ba4fa32ce5a19be02bf391a7b1aa0027b175ba5.mp3", "hash": "bb23ce2312a94c7ed78d3215c8a47b3b4ddc843eb4ca2970f9243cfe474e18df", "bytes": 131328, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4713ac3a791be4ee9f44e0de9ba4fa32ce5a19be02bf391a7b1aa0027b175ba5.mp3", "duration_ms": 21840}, "s1-interest-peek.explanation": {"url": "http://localhost:4006/files/lesson-audio/56ed1be12a6d3a85e0602e52b13ba8b9bb1a113b29b8de014b9331aa3ca45dbd.mp3", "hash": "e4009c6e87dc657fc8d8b2b77b6ceafab722fa548a5d58601a4ec344defe357a", "bytes": 100224, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/56ed1be12a6d3a85e0602e52b13ba8b9bb1a113b29b8de014b9331aa3ca45dbd.mp3", "duration_ms": 16640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('43eb7cc6-46cc-44ee-9a87-14d05d8f357d', 'es-MX', '1', '{"meta": {"cast": ["liruf", "zara"], "slug": "dialogue-choice", "title": "¿Me lo dejas en 3?", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir una respuesta amable pero firme ante un cliente que pide rebaja, sin perder la ganancia."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cliente-rebaja", "xp": 15, "type": "dialogue_choice", "hints": ["Si le dices que sí, ganas menos de lo que cuesta hacer el vaso.", "Puedes ser amable y explicarle por qué el precio es justo."], "title": "La clienta pide rebaja", "payload": {"turns": [{"id": "turn1", "npc_md": "Hola, joven. Se ve muy rica su limonada. ¿Me la deja en 3 pesos? Es que traigo justo.", "replies": [{"id": "r1a", "text_md": "Lo siento, el precio es 5 pesos. No puedo bajarlo."}, {"id": "r1b", "text_md": "Está bien, se la dejo en 3 pesos."}, {"id": "r1c", "text_md": "No, señora. Si no quiere pagar 5, no le vendo."}]}, {"id": "turn2", "npc_md": "Ay, es que 5 pesos se me hace caro para un vaso.", "replies": [{"id": "r2a", "text_md": "Entiendo, pero cada vaso lleva limones frescos y azúcar. 5 pesos es justo."}, {"id": "r2b", "text_md": "Bueno, se lo dejo en 4, pero es mi última oferta."}, {"id": "r2c", "text_md": "Pues vaya a otro puesto."}]}], "persona": {"name": "Zara", "role_md": "Clienta del puesto de limonada", "character": "zara"}, "opening_md": "Liruf está en su puesto de limonada. Una señora llamada Zara se acerca y sonríe."}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/4e9387d654602532ba6ce9af861a2c16d7f9c7e84390a2f45fc47024a0570508.png", "prompt_md": "Una clienta quiere pagar 3 pesos por un vaso que cuesta 5. ¿Qué le dices?", "difficulty": 2, "explanation_md": "Cada vaso cuesta 5 pesos porque con eso cubres los limones y el azúcar, y además ahorras para tu meta. Si lo vendes en 3, pierdes dinero.", "audio_segment_id": "s1-cliente-rebaja.prompt"}], "schema_version": 1}', '{"s1-cliente-rebaja": {"turns": [{"turn_id": "turn1", "qualities": {"r1a": 90, "r1b": 10, "r1c": 30}, "reactions": {"r1a": "Zara asiente, pensativa.", "r1b": "Zara sonríe y paga 3 pesos, pero Liruf pierde dinero.", "r1c": "Zara frunce el ceño y se va."}}, {"turn_id": "turn2", "qualities": {"r2a": 100, "r2b": 60, "r2c": 0}, "reactions": {"r2a": "Zara sonríe y dice: ''Tiene razón, deme un vaso.''", "r2b": "Zara duda, pero acepta. Ganas 4 pesos, pero podrías haber ganado 5.", "r2c": "Zara se va enojada y no compra nada."}}]}}', '{"units": {"s1-cliente-rebaja.hint.0": {"url": "http://localhost:4006/files/lesson-audio/cfe17ffae824fa85442cbf35ca4fada1aca721537a35d01a1084462267855071.mp3", "hash": "32b0743b33b7cdccce61af457f109837a789e5d73c850e8d1593a60147799086", "bytes": 25776, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/cfe17ffae824fa85442cbf35ca4fada1aca721537a35d01a1084462267855071.mp3", "duration_ms": 4240}, "s1-cliente-rebaja.hint.1": {"url": "http://localhost:4006/files/lesson-audio/5f56f457a7ae3dec060eec205dd9906c11d25df15d5cd392d44ab21ec3f4726a.mp3", "hash": "216ac1a6da8ed446eddc55839435d2b0ecbe871209b236e07bb4487920b8efec", "bytes": 23328, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/5f56f457a7ae3dec060eec205dd9906c11d25df15d5cd392d44ab21ec3f4726a.mp3", "duration_ms": 3840}, "s1-cliente-rebaja.prompt": {"url": "http://localhost:4006/files/lesson-audio/3c2e5b00853394f09f4b0fc7fb680db038dc74ad217390464121ee4932d3e28e.mp3", "hash": "7bdc2739a7b141077bd22d828c74ff768cd6337129220ae8cf2fd6173d07ebaf", "bytes": 32976, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/3c2e5b00853394f09f4b0fc7fb680db038dc74ad217390464121ee4932d3e28e.mp3", "duration_ms": 5440}, "s1-cliente-rebaja.explanation": {"url": "http://localhost:4006/files/lesson-audio/7e85f1b3d2563ec64bb7d5967e9489c2fa3ceafc340f2d20409cb1393a601619.mp3", "hash": "6ea88ffe4e81847cece87f74caa9274431804b59b69c0eb11e57c2dfe5ee5a23", "bytes": 64224, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/7e85f1b3d2563ec64bb7d5967e9489c2fa3ceafc340f2d20409cb1393a601619.mp3", "duration_ms": 10640}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b831d60b-c492-4356-824e-7fce5f662a0a', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "match-pairs", "title": "Match the prices", "locale": "en-US", "subject": "mixed", "objectives": ["Match each product from the stand with its correct price (small cup–5, pitcher–20, cookie–3)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-prices", "xp": 10, "type": "match_pairs", "hints": ["The small cup costs 5 pesos, the pitcher costs 20, and the cookie costs 3."], "title": "Match the prices", "payload": {"left": [{"id": "vaso", "text_md": "Small cup", "image_url": "http://localhost:4006/files/lesson-images/f1eedcef9295036c44a103056c1ae7a73eba47c7602f62b01730fc8d8b7ff1a4.png"}, {"id": "jarra", "text_md": "Pitcher", "image_url": "http://localhost:4006/files/lesson-images/86fbdc57fac9549d69f72852fe635fad88f3a69598bac6bd16b8a2671a4634ac.png"}, {"id": "galleta", "text_md": "Cookie", "image_url": "http://localhost:4006/files/lesson-images/d7efa6016113d96152fc4ec52a97b2a08183a816cfb081e9dbe274c68583dbf8.png"}], "right": [{"id": "precio5", "text_md": "5 pesos"}, {"id": "precio20", "text_md": "20 pesos"}, {"id": "precio3", "text_md": "3 pesos"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Dina sold 3 cups at 5 pesos each yesterday. Today Liruf sets the prices. Match each product with its price.", "difficulty": 1, "explanation_md": "The small cup costs 5 pesos because it is small. The pitcher costs 20 pesos because it is bigger and has more lemonade. The cookie costs 3 pesos because it is a cheap dessert. That way Liruf can charge correctly and buy more lemons!", "audio_segment_id": "s1-match-prices.prompt"}], "schema_version": 1}', '{"s1-match-prices": {"pairs": [["vaso", "precio5"], ["jarra", "precio20"], ["galleta", "precio3"]]}}', '{"units": {"s1-match-prices.hint.0": {"url": "http://localhost:4006/files/lesson-audio/3f442a674de3f16a6ac83034c6fbb58857e89d71d754ed477bdb05e2e36f9cb3.mp3", "hash": "c5478190b30d0823146d22dac6c239362cd674c8a3d08fd07ad395585b635f03", "bytes": 30528, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3f442a674de3f16a6ac83034c6fbb58857e89d71d754ed477bdb05e2e36f9cb3.mp3", "duration_ms": 5040}, "s1-match-prices.prompt": {"url": "http://localhost:4006/files/lesson-audio/878db8eadedd5e7b08cb2ea270e68509f3458ca53a3f2297e65226b2c11a3342.mp3", "hash": "bd6f4706f43798010ed2a70c6c444f8bb4141cbb2659f3268d556458f1e1be53", "bytes": 44064, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/878db8eadedd5e7b08cb2ea270e68509f3458ca53a3f2297e65226b2c11a3342.mp3", "duration_ms": 7280}, "s1-match-prices.explanation": {"url": "http://localhost:4006/files/lesson-audio/dbafbd472b2d8b005532172475135c4c3719d58a2f11a528d5052b36c2448971.mp3", "hash": "d99820c7feaef3237b5541204d519c5a989b41ab1746a008988a81c557627ccd", "bytes": 76608, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/dbafbd472b2d8b005532172475135c4c3719d58a2f11a528d5052b36c2448971.mp3", "duration_ms": 12720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9bdad6a7-ed32-42f2-83c9-554afe044403', 'en-US', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "savings-goal", "title": "Liruf''s savings plan", "locale": "en-US", "subject": "money", "objectives": ["Calculate how many weeks it takes to save up to a goal of 80 pesos with different weekly savings."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-plan-ahorro", "xp": 15, "type": "savings_goal", "hints": ["Count by 10s up to 80: 10, 20, 30... how many jumps?"], "title": "Weeks for the guitar", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [10]}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Liruf puts 10 pesos in his piggy bank each week. How many weeks until he has 80 pesos?", "difficulty": 1, "explanation_md": "Each week is 10 pesos. To reach 80, you need 8 weeks: 10+10+10+10+10+10+10+10 = 80. That''s how Liruf can buy the guitar!", "audio_segment_id": "s1-plan-ahorro.prompt"}], "schema_version": 1}', '{"s1-plan-ahorro": {"correct": {"10": 8}}}', '{"units": {"s1-plan-ahorro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/90de4624386a5b83ee2de5ab86690e9851783845accc0549a0b5ab69cf45245f.mp3", "hash": "bc1530ccdc0e9e7065f0b02362938040e74b5ad54f734e1fd0658b4edca3efb2", "bytes": 40176, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/90de4624386a5b83ee2de5ab86690e9851783845accc0549a0b5ab69cf45245f.mp3", "duration_ms": 6640}, "s1-plan-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/c3fbf1e9c9a9944d284c0287ac160a4026e3e703e9833a17acc7482e62708cd5.mp3", "hash": "df4be267520ffecce8dbfbdc37094dc88607f6529b9cb1a5bbdfad047a15d2da", "bytes": 42624, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/c3fbf1e9c9a9944d284c0287ac160a4026e3e703e9833a17acc7482e62708cd5.mp3", "duration_ms": 7040}, "s1-plan-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/5c05718132d662b32cd0cbf09da4a8d2884995aec73b30e2151111229637229c.mp3", "hash": "0d71a2e0c08805840d70df73f4f6afc427524e4e5b1473b6c89ae41961d278bd", "bytes": 92448, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/5c05718132d662b32cd0cbf09da4a8d2884995aec73b30e2151111229637229c.mp3", "duration_ms": 15360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f8c5e4cf-232b-47dc-8484-3350558f5f27', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "needs-wants", "title": "O negócio vem primeiro", "locale": "pt-BR", "subject": "money", "objectives": ["Separar necessidades do negócio (limões, gelo) de desejos pessoais (picolé, gibi): o negócio vem primeiro."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-needs-wants", "xp": 10, "type": "needs_wants", "hints": ["O negócio precisa do que é usado para fazer a limonada.", "O que acaba e precisa comprar de novo?"], "title": "Necessidades do negócio vs. desejos", "payload": {"items": [{"id": "limones", "icon": "eco", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/e7b0e04deb75c07cde3bde15f904ec7fc0cda31fdeb3f0582108293949de06d1.png"}, {"id": "hielo", "icon": "ac_unit", "text_md": "Gelo", "image_url": "http://localhost:4006/files/lesson-images/bdc70e2a2a6fa178461221b28ecd751ac4b49daf1cf897f3cd3a5f2ff003bf85.png"}, {"id": "paleta", "icon": "icecream", "text_md": "Picolé", "image_url": "http://localhost:4006/files/lesson-images/3afc0910027341646abd2dce5958c7b7eb57fec17e92e0b8b74f0dc0a838c11e.png"}, {"id": "comic", "icon": "auto_stories", "text_md": "Gibi"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Como ontem você dividiu os lucros, hoje decida: o que comprar primeiro para o negócio não fechar?", "difficulty": 1, "explanation_md": "Os limões e o gelo são necessidades do negócio porque sem eles não há limonada. O picolé e o gibi são seus desejos, não do negócio.", "audio_segment_id": "s1-needs-wants.prompt"}], "schema_version": 1}', '{"s1-needs-wants": {"needs_ids": ["limones", "hielo"]}}', '{"units": {"s1-needs-wants.hint.0": {"url": "http://localhost:4006/files/lesson-audio/27a7064554b2b21ee50e3b5c4fd21e3fa97a7f22dc57fdf26ab6a5261f9c4c4c.mp3", "hash": "eb3fd2eeb8474a752ca7c9d010fe6a4b3f8b8843f1a44d2b85dac44fe4df8721", "bytes": 23904, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/27a7064554b2b21ee50e3b5c4fd21e3fa97a7f22dc57fdf26ab6a5261f9c4c4c.mp3", "duration_ms": 3920}, "s1-needs-wants.hint.1": {"url": "http://localhost:4006/files/lesson-audio/0bc70087268fa36195b0b310cb3f9264803f1884f6dfbe3f5be6e901586de3f9.mp3", "hash": "7d107028226eb06d7fe7a42acf746ea6ef617f8f1ab73376832b03a1ec3a40da", "bytes": 16128, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0bc70087268fa36195b0b310cb3f9264803f1884f6dfbe3f5be6e901586de3f9.mp3", "duration_ms": 2640}, "s1-needs-wants.prompt": {"url": "http://localhost:4006/files/lesson-audio/a74ed080381567b5fc81f9afb2e96e70638e1925c4ba531966acd3be72c3c902.mp3", "hash": "a423a3ba438b8c5656e3f3a8c0510106db70a981cd2be6baf4d8fec1c7115de5", "bytes": 42624, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a74ed080381567b5fc81f9afb2e96e70638e1925c4ba531966acd3be72c3c902.mp3", "duration_ms": 7040}, "s1-needs-wants.explanation": {"url": "http://localhost:4006/files/lesson-audio/dcda07100765883bc34ecd6b149cdd14080b576ec8a286c8ff26051437f5cc3f.mp3", "hash": "b2f374e33f738911fc38b4142f6d4d2a6b240cf736e2fd15e772b5ce0b72f7b3", "bytes": 59904, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/dcda07100765883bc34ecd6b149cdd14080b576ec8a286c8ff26051437f5cc3f.mp3", "duration_ms": 9920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b45d67a1-26c0-4ffa-b51c-76340c35e459', 'es-MX', '1', '{"meta": {"cast": ["liruf", "zara"], "slug": "order-steps", "title": "Ordena las compras del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar las compras del mercado por prioridad de venta", "Distinguir entre necesidad y lujo en un puesto"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-order-purchases", "xp": 15, "type": "order_steps", "hints": ["Piensa: ¿sin cuál no puedes hacer ni un vaso de limonada?", "Las calcomanías son un lujo, no ayudan a vender hoy."], "title": "Ordena las compras", "payload": {"items": [{"id": "limones", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/5df7024bc09768d45b596b978750f3ec6ebf30a9cb8a9e376f8d1f44e01de402.png"}, {"id": "vasos", "text_md": "Vasos", "image_url": "http://localhost:4006/files/lesson-images/f1919920278621f5cf5d35217cbaa03fe969e53a779468d607163d95102c4e17.png"}, {"id": "azucar", "text_md": "Azúcar", "image_url": "http://localhost:4006/files/lesson-images/edcacd60e3ee9a49be91fbbea865d641cfa4d0ec7f7524e5713671f93e13760d.png"}, {"id": "calcomanias", "text_md": "Calcomanías", "image_url": "http://localhost:4006/files/lesson-images/c6d08970230f6de4df2a22a818c977c11f9222c6f9a90b565988a08c06bdeb55.png"}]}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Toca los 4 artículos en orden: del que más necesitas para vender hoy al que puede esperar.", "difficulty": 2, "explanation_md": "Los limones son primero porque sin ellos no hay limonada. Los vasos son segundo porque los clientes necesitan dónde servir. El azúcar mejora el sabor, pero puedes vender sin ella. Las calcomanías son un gusto que espera.", "audio_segment_id": "s1-order-purchases.prompt"}], "schema_version": 1}', '{"s1-order-purchases": {"order": ["limones", "vasos", "azucar", "calcomanias"]}}', '{"units": {"s1-order-purchases.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9ce83dc02906ee5328a92ed99d512028051055e1d8ba9951f6722067042802b2.mp3", "hash": "96c57bd720ef6b895d5c77c8cda9f0292d69a0732437c1c60a79c8bad9022074", "bytes": 21024, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/9ce83dc02906ee5328a92ed99d512028051055e1d8ba9951f6722067042802b2.mp3", "duration_ms": 3440}, "s1-order-purchases.hint.1": {"url": "http://localhost:4006/files/lesson-audio/7b5143cd0a7791c5fdded391dd6995628637f74ca240514f4444c4a56e382707.mp3", "hash": "d08f39d9a9a318e56232ee7985a8de7220f8b1c1e08b89cdfb2c57a80497b1b7", "bytes": 21456, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/7b5143cd0a7791c5fdded391dd6995628637f74ca240514f4444c4a56e382707.mp3", "duration_ms": 3520}, "s1-order-purchases.prompt": {"url": "http://localhost:4006/files/lesson-audio/16d9921ae6c9888f4fd5283c2368cc539fc2ee0e74cdc2d5d33a8b282cc0bf85.mp3", "hash": "6d66c7cf1186fdb92e2beb4b73eda483c804db3c1e3f7a26f6cfcb361bcde470", "bytes": 33408, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/16d9921ae6c9888f4fd5283c2368cc539fc2ee0e74cdc2d5d33a8b282cc0bf85.mp3", "duration_ms": 5520}, "s1-order-purchases.explanation": {"url": "http://localhost:4006/files/lesson-audio/d1e4ed2d01cc8eea3cd2cd1b699fed3693b55640b6e7f4d770df4dafb15b4656.mp3", "hash": "f253535b4dbe5b683fd0fcc93615f06e59c8cddfc02a0850308eb35fcd197517", "bytes": 75168, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/d1e4ed2d01cc8eea3cd2cd1b699fed3693b55640b6e7f4d770df4dafb15b4656.mp3", "duration_ms": 12480}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f62a6048-4f69-4ab4-9256-d87525c8e112', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "make-change", "title": "Dar cambio exacto", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular cambio de un billete de 20 al comprar dos productos de 5 y 3 pesos", "Armar el cambio con monedas de 1, 2, 5 y 10"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cambio-don-beto", "xp": 15, "type": "make_change", "hints": ["Suma el costo del vaso y la galleta.", "El cambio es lo que sobra del billete de 20 después de pagar."], "title": "El cambio de don Beto", "payload": {"price": 8, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/a0b870f1cb860a296e2f665e463d1f72025c3c636a9271a142f55401584a6736.png", "prompt_md": "Don Beto compra 1 vaso (5 pesos) y 1 galleta (3 pesos). Paga con 20 pesos. Arma su cambio con monedas.", "difficulty": 2, "explanation_md": "Vaso 5 + galleta 3 = 8 pesos. De 20 sobran 12. Las monedas que suman 12 son 10 + 2.", "audio_segment_id": "s1-cambio-don-beto.prompt"}], "schema_version": 1}', '{"s1-cambio-don-beto": {}}', '{"units": {"s1-cambio-don-beto.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4ee39296f05d3aaae4e304d3f43063928ab97ec585347f743bb92615a35ab6e6.mp3", "hash": "eb24bd4c491ed639b013a41fdd78a61238fcccf95720ed1b903d7934e719d592", "bytes": 16704, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/4ee39296f05d3aaae4e304d3f43063928ab97ec585347f743bb92615a35ab6e6.mp3", "duration_ms": 2720}, "s1-cambio-don-beto.hint.1": {"url": "http://localhost:4006/files/lesson-audio/106382b18d63f21ecc30529a1f27102485ae18b52ffd26860dbeba55e72c1336.mp3", "hash": "2258f97958a366b3a5b1c7c2a999bb040a1d82027a0391f2b03d5bc6b4472016", "bytes": 26208, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/106382b18d63f21ecc30529a1f27102485ae18b52ffd26860dbeba55e72c1336.mp3", "duration_ms": 4320}, "s1-cambio-don-beto.prompt": {"url": "http://localhost:4006/files/lesson-audio/36e38f5216265d512a9eadf744e2a19d3dc76e6859939564aad986aa2a7e4867.mp3", "hash": "19495d5fbb82edd7d2b962e017e9125c00a7a705ede33b0f9a3acb80fe26e35c", "bytes": 59904, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/36e38f5216265d512a9eadf744e2a19d3dc76e6859939564aad986aa2a7e4867.mp3", "duration_ms": 9920}, "s1-cambio-don-beto.explanation": {"url": "http://localhost:4006/files/lesson-audio/5e7874834b898e556f640776970a61cbd35da17ce6704248a99ac6f9e85c20f8.mp3", "hash": "da0c494340c83ed8669ead5fb6c2e29dacf6aad4e99190051011652ec369ee71", "bytes": 58464, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/5e7874834b898e556f640776970a61cbd35da17ce6704248a99ac6f9e85c20f8.mp3", "duration_ms": 9680}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b831d60b-c492-4356-824e-7fce5f662a0a', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "match-pairs", "title": "Combine os preços", "locale": "pt-BR", "subject": "mixed", "objectives": ["Combine cada produto da barraca com seu preço correto (copo pequeno–5, jarra–20, biscoito–3)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-prices", "xp": 10, "type": "match_pairs", "hints": ["O copo pequeno custa 5 pesos, a jarra custa 20 e o biscoito custa 3."], "title": "Combine os preços", "payload": {"left": [{"id": "vaso", "text_md": "Copo pequeno", "image_url": "http://localhost:4006/files/lesson-images/e487ede9c29e7786393923311e3da4b98df1da79839855384be1be2c5c8ba45f.png"}, {"id": "jarra", "text_md": "Jarra", "image_url": "http://localhost:4006/files/lesson-images/8997e1fe858acfeb54c8327e70383584db1f39e066c6dd2fa53c705cda055239.png"}, {"id": "galleta", "text_md": "Biscoito", "image_url": "http://localhost:4006/files/lesson-images/9a5e14715112c2ee915948be4f4e6dfa8f6f703642430882247ec62c8d50a2ec.png"}], "right": [{"id": "precio5", "text_md": "5 pesos"}, {"id": "precio20", "text_md": "20 pesos"}, {"id": "precio3", "text_md": "3 pesos"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Dina vendeu 3 copos a 5 pesos cada ontem. Hoje Liruf coloca os preços. Ligue cada produto ao seu preço.", "difficulty": 1, "explanation_md": "O copo pequeno custa 5 pesos porque é pequeno. A jarra custa 20 pesos porque é maior e tem mais limonada. O biscoito custa 3 pesos porque é uma sobremesa barata. Assim Liruf pode cobrar bem e comprar mais limões!", "audio_segment_id": "s1-match-prices.prompt"}], "schema_version": 1}', '{"s1-match-prices": {"pairs": [["vaso", "precio5"], ["jarra", "precio20"], ["galleta", "precio3"]]}}', '{"units": {"s1-match-prices.hint.0": {"url": "http://localhost:4006/files/lesson-audio/7b7a744feed21315c4b24c5b6e9a2199e601ecef2c89e0537338bb7d03d23f68.mp3", "hash": "d4966325f8af1e48003010700c57f69b382772afb10ba3c82770c61c00e0e063", "bytes": 37728, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7b7a744feed21315c4b24c5b6e9a2199e601ecef2c89e0537338bb7d03d23f68.mp3", "duration_ms": 6240}, "s1-match-prices.prompt": {"url": "http://localhost:4006/files/lesson-audio/dbca3cae4fd5b42f79d8133cb2804fae19ea80788fadd6f634e6dedf705890a1.mp3", "hash": "6af1b89122f54c0aa8caad9d01fbb0019eb296629e774b5058d5e3ff841c5647", "bytes": 53568, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/dbca3cae4fd5b42f79d8133cb2804fae19ea80788fadd6f634e6dedf705890a1.mp3", "duration_ms": 8880}, "s1-match-prices.explanation": {"url": "http://localhost:4006/files/lesson-audio/4fb339a968d68ab73fe242ec44ed9875a5981443ae5555e9aafe91347d5d3a9d.mp3", "hash": "8e2e1c6ea64e23d10f554e50378a1b39d2ca20aae3cd7fb9db68fbff9413bf56", "bytes": 99648, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4fb339a968d68ab73fe242ec44ed9875a5981443ae5555e9aafe91347d5d3a9d.mp3", "duration_ms": 16560}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9bdad6a7-ed32-42f2-83c9-554afe044403', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "savings-goal", "title": "O plano de poupança do Liruf", "locale": "pt-BR", "subject": "money", "objectives": ["Calcular quantas semanas são necessárias para poupar para atingir uma meta de 80 pesos com diferentes economias semanais."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-plan-ahorro", "xp": 15, "type": "savings_goal", "hints": ["Conte de 10 em 10 até chegar a 80: 10, 20, 30... quantos saltos?"], "title": "Semanas para o violão", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [10]}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Liruf coloca 10 pesos em seu cofrinho toda semana. Quantas semanas até ter 80 pesos?", "difficulty": 1, "explanation_md": "Cada semana são 10 pesos. Para chegar a 80, você precisa de 8 semanas: 10+10+10+10+10+10+10+10 = 80. Assim Liruf pode comprar o violão!", "audio_segment_id": "s1-plan-ahorro.prompt"}], "schema_version": 1}', '{"s1-plan-ahorro": {"correct": {"10": 8}}}', '{"units": {"s1-plan-ahorro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/29070987c5b833f5f7186a5b5cc476025abb7c1405c7fdbfdedf0a3eaed87ef4.mp3", "hash": "c86e770e5d1d1a8a94e3d344def906a07b46d2ce984283057acf5561dce6b7df", "bytes": 40608, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/29070987c5b833f5f7186a5b5cc476025abb7c1405c7fdbfdedf0a3eaed87ef4.mp3", "duration_ms": 6720}, "s1-plan-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/a51b3c3e4e26f65badc13ac40982d2d71fc1e5222ef3f2ffbe8bf4050fe82eff.mp3", "hash": "46ce43aaeb38212bd3143262eb4ddbf2ff205ea546284c848221ac6f6b8aed84", "bytes": 42048, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/a51b3c3e4e26f65badc13ac40982d2d71fc1e5222ef3f2ffbe8bf4050fe82eff.mp3", "duration_ms": 6960}, "s1-plan-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/7f462cee90fa464b7fd520d8600865dae9f25d401fc371f0e2dcc1563b048f0d.mp3", "hash": "68540ec7992337b7d55360562e606225da5e040911c34d1c55be284b275ccefa", "bytes": 105984, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/7f462cee90fa464b7fd520d8600865dae9f25d401fc371f0e2dcc1563b048f0d.mp3", "duration_ms": 17600}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a0b48602-bbeb-4aac-8309-90ec3cdeba90', 'en-US', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "number-line", "title": "The Savings Line", "locale": "en-US", "subject": "mixed", "objectives": ["Locate amounts on a number line from 0 to 100", "Identify how much is needed to reach a savings goal"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-line", "xp": 15, "type": "number_line", "hints": ["Count by 10s from 20 to 80.", "20 + 10 = 30, 30 + 10 = 40... how many 10s until 80?"], "title": "The Savings Line", "payload": {"max": 100, "min": 0, "ticks": 10, "labels": false}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Liruf has 20 pesos. The scooter costs 80. How much is missing?", "difficulty": 2, "explanation_md": "60 pesos are missing. 20 + 60 = 80. If you put 80, you added what he already has; if you put 20, you subtracted what he already has. Good for trying!", "audio_segment_id": "s1-number-line.prompt"}], "schema_version": 1}', '{"s1-number-line": {"value": 60, "full_credit_delta": 5, "zero_credit_delta": 15}}', '{"units": {"s1-number-line.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4120fd05b8ea8fbd187d6a9e7d73dc3a51808dacb2d18b10a314218039a294dc.mp3", "hash": "626ddee26df5942d90856f1a4c0f8ec7899392b44f3e02449b32a16c4f30165f", "bytes": 19008, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/4120fd05b8ea8fbd187d6a9e7d73dc3a51808dacb2d18b10a314218039a294dc.mp3", "duration_ms": 3120}, "s1-number-line.hint.1": {"url": "http://localhost:4006/files/lesson-audio/7a6ca0f127e667a73d59a11c0a441b3d13897fa4f2e89557699e1e1fa5f478cb.mp3", "hash": "dc6c3f70de0520f981f3c92bd966d3c20f9ebb03a6d7b64802e07ce9c4385527", "bytes": 48816, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/7a6ca0f127e667a73d59a11c0a441b3d13897fa4f2e89557699e1e1fa5f478cb.mp3", "duration_ms": 8080}, "s1-number-line.prompt": {"url": "http://localhost:4006/files/lesson-audio/71f77bb0a6efbc6571dd98051015ae9229a269a15c723fbd9d3fe3f84adc374e.mp3", "hash": "a097cab4ebe2242084966d9e6dbb2526ffcf3c7230a6ec4b3f81348d5277273a", "bytes": 32976, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/71f77bb0a6efbc6571dd98051015ae9229a269a15c723fbd9d3fe3f84adc374e.mp3", "duration_ms": 5440}, "s1-number-line.explanation": {"url": "http://localhost:4006/files/lesson-audio/7be222986533c90b1d696aa10b7e774ad8324a25cee1da02b63c9bdbcdf51871.mp3", "hash": "3f3e4f7dc60bbc142c82cafd2aa7bbf58b15c5c376562e9bc7356f942ee33f86", "bytes": 80496, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/7be222986533c90b1d696aa10b7e774ad8324a25cee1da02b63c9bdbcdf51871.mp3", "duration_ms": 13360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('21c29ede-4ec5-4118-8e88-04f1068e985b', 'en-US', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "count-objects", "title": "Counting coins from the spilled jar", "locale": "en-US", "subject": "mixed", "objectives": ["Counting coins at a glance (up to 12) and matching each coin to a glass of lemonade sold."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-count-coins", "xp": 10, "type": "count_objects", "hints": ["Look only at the coins, not the cookies or the glass.", "You can touch them one by one to count them."], "title": "Coins in the jar", "payload": {"scene": [{"icon": "monetization_on", "tint": "primary", "count": 8}, {"icon": "cookie", "tint": "accent", "count": 3}, {"icon": "local_drink", "tint": "accent", "count": 1}], "ask_icon": "monetization_on"}, "narrator": {"emotion": "surprised", "character": "liruf"}, "prompt_md": "Count the coins that fell out of the jar. How many are there?", "difficulty": 1, "explanation_md": "There are 8 coins. Each coin is a 5-peso glass that Liruf sold today. That number is what adds up to the 80-peso guitar.", "audio_segment_id": "s1-count-coins.prompt"}], "schema_version": 1}', '{"s1-count-coins": {"value": 8}}', '{"units": {"s1-count-coins.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4b0f60107cde3108a41a355245de4c218ca2b87224a028f30e14614726e2f204.mp3", "hash": "d4d3003e854aedf907de9c13fde8ef0bc42dee1be2510fb4fedcd277e58dbebb", "bytes": 21024, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/4b0f60107cde3108a41a355245de4c218ca2b87224a028f30e14614726e2f204.mp3", "duration_ms": 3440}, "s1-count-coins.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a68d1380930c36fc929058ff9af2b303a0d80f43c0bb341e2223f16ba13cae9f.mp3", "hash": "2a7b9e07dc01f42a59b162af681d01f75236ccacd827d1c6b2399a283f3ee8b3", "bytes": 15696, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/a68d1380930c36fc929058ff9af2b303a0d80f43c0bb341e2223f16ba13cae9f.mp3", "duration_ms": 2560}, "s1-count-coins.prompt": {"url": "http://localhost:4006/files/lesson-audio/9fbf3d83fcc622a997c5229bfb1b04e9294e7485050b970a3e96feade1d9b3bb.mp3", "hash": "511a4f72e38daa4e84fd4416ceb7bf40369a79d85210380f867a47f9cce28a0e", "bytes": 22464, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/9fbf3d83fcc622a997c5229bfb1b04e9294e7485050b970a3e96feade1d9b3bb.mp3", "duration_ms": 3680}, "s1-count-coins.explanation": {"url": "http://localhost:4006/files/lesson-audio/067a2d65aeb59b66814c342198545b2e7c255d5a644f7b7a84a3d3bdc401d2e6.mp3", "hash": "3e0893a208a72b92fccabb14886ab064b85cb3b41e95439482a904b82f33dd35", "bytes": 47808, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/067a2d65aeb59b66814c342198545b2e7c255d5a644f7b7a84a3d3bdc401d2e6.mp3", "duration_ms": 7920}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4dcc7a9f-f2f6-4b40-abd4-a522d168e446', 'es-MX', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "flash-match", "title": "Flash Match: Conceptos del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Relacionar palabras clave del puesto (ahorro, costo, ganancia) con sus ejemplos concretos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-flash-match", "xp": 10, "type": "flash_match", "hints": ["Piensa en lo que cada palabra significa en el puesto de limonada."], "title": "¡Conexión rápida!", "payload": {"left": [{"id": "ahorro", "text_md": "Ahorro", "image_url": "http://localhost:4006/files/lesson-images/3656b0c652f20e5b8f927805ca9684ecad22d1a3f23d2bc92bb9e8c657a3e3b8.png"}, {"id": "costo", "text_md": "Costo", "image_url": "http://localhost:4006/files/lesson-images/f681686a1724486be9e3f0d9012eed45a8c6d5a3e0815909db6cd330a8a56903.png"}, {"id": "ganancia", "text_md": "Ganancia", "image_url": "http://localhost:4006/files/lesson-images/d45f6f91133d63a964c3740b92f778f1551ea85abaaa15238ec87300882f4186.png"}], "right": [{"id": "alcancia", "text_md": "Alcancía de Dina"}, {"id": "limones", "text_md": "5 limones para limonada"}, {"id": "lo-que-sobra", "text_md": "Monedas que sobran"}], "seconds": 30}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Une cada palabra con su ejemplo.", "difficulty": 1, "explanation_md": "Ahorro es lo que Dina guarda en su alcancía para la patineta. Costo son los 5 limones que compró para hacer limonada. Ganancia es lo que sobra después de vender.", "audio_segment_id": "s1-flash-match.prompt"}], "schema_version": 1}', '{"s1-flash-match": {"pairs": [["ahorro", "alcancia"], ["costo", "limones"], ["ganancia", "lo-que-sobra"]]}}', '{"units": {"s1-flash-match.hint.0": {"url": "http://localhost:4006/files/lesson-audio/1ab73c17d783948e6523bb46a1352708bd18d53cf3a5af7a3321bbbcdee5e591.mp3", "hash": "e9a376a3f3db8b869f3d350e120b0a559179aec837d73122d770f45a2ce30d5b", "bytes": 25344, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/1ab73c17d783948e6523bb46a1352708bd18d53cf3a5af7a3321bbbcdee5e591.mp3", "duration_ms": 4160}, "s1-flash-match.prompt": {"url": "http://localhost:4006/files/lesson-audio/efc153260d8ccb7c73c17042c87216c6c6f3ac5a25df46b241565d4a1973698c.mp3", "hash": "02e199bf0f44b7e6ec1ff2f8bdb7c33633c379c2914d9117577e11974f46d3c3", "bytes": 13248, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/efc153260d8ccb7c73c17042c87216c6c6f3ac5a25df46b241565d4a1973698c.mp3", "duration_ms": 2160}, "s1-flash-match.explanation": {"url": "http://localhost:4006/files/lesson-audio/1cf7841c613772942fe3b8083ecfb97098feee409cfe57939164b0fb4072866b.mp3", "hash": "e65b7c44a70b504d74e8c07d49604b62fa41f525496229a848491f58691c8bb7", "bytes": 59904, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/1cf7841c613772942fe3b8083ecfb97098feee409cfe57939164b0fb4072866b.mp3", "duration_ms": 9920}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1f15af49-9573-4e17-a4ee-0685fa854b90', 'es-MX', '1', '{"meta": {"cast": ["liruf"], "slug": "timeline-order", "title": "Ordena el día de venta", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar los pasos del día de venta en orden cronológico."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ordenar-dia", "xp": 10, "type": "timeline_order", "hints": ["Piensa: ¿qué necesitas antes de vender?", "Después de vender, ¿qué haces con el dinero?"], "title": "Ordena el día de venta", "payload": {"events": [{"id": "comprar", "icon": "shopping_cart", "text_md": "Comprar limones y azúcar", "image_url": "http://localhost:4006/files/lesson-images/c6e8821d12b6e2564161cbc05a32a1f2b258ea9a49d7a0366c430749bdc1801e.png"}, {"id": "preparar", "icon": "local_drink", "text_md": "Preparar la limonada", "image_url": "http://localhost:4006/files/lesson-images/c65e2bd92a6837d42bccb239f3edacd93522e669f01df622c86dba8fe1788b72.png"}, {"id": "vender", "icon": "storefront", "text_md": "Vender limonada al mediodía", "image_url": "http://localhost:4006/files/lesson-images/4ffe563812ed02e470f89a79a892fcbfb112d57ebdb014af2f1e59d3d5726d69.png"}, {"id": "contar", "icon": "account_balance_wallet", "text_md": "Contar dinero y guardarlo", "image_url": "http://localhost:4006/files/lesson-images/31711a9f98d3e1b68a84f3f236d0ee1c5e24372d06073cba759ab58055de15f5.png"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf ya sabe que 2 limonadas cuestan $10. ¿Qué hace primero en su día?", "difficulty": 1, "explanation_md": "Primero compras los ingredientes, luego preparas la limonada, después vendes al mediodía y al final cuentas y guardas el dinero. ¡Así Liruf no se salta ningún paso!", "audio_segment_id": "s1-ordenar-dia.prompt"}], "schema_version": 1}', '{"s1-ordenar-dia": {"order": ["comprar", "preparar", "vender", "contar"]}}', '{"units": {"s1-ordenar-dia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/53f5788d39c730ed6a7cc28132e170ac1974e996bb479a5ef24abe38ce4c23f5.mp3", "hash": "63a2dd10c32d5df0c4904a3d7bb6cde6a7a0d64a495120bd483843231ed7c1ed", "bytes": 21024, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/53f5788d39c730ed6a7cc28132e170ac1974e996bb479a5ef24abe38ce4c23f5.mp3", "duration_ms": 3440}, "s1-ordenar-dia.hint.1": {"url": "http://localhost:4006/files/lesson-audio/0e8610124c193b8c811da372bf3f5d41c688c90650da976c556dfa2f1a5be8a1.mp3", "hash": "e6d1b2710150b1e3b53246c0f67155460bb5321b8d1503ecf500388168ec91ee", "bytes": 19008, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/0e8610124c193b8c811da372bf3f5d41c688c90650da976c556dfa2f1a5be8a1.mp3", "duration_ms": 3120}, "s1-ordenar-dia.prompt": {"url": "http://localhost:4006/files/lesson-audio/dba67c03df4467b55091912817dfbc2dffc078ea6ae66cf7a7c1bdd161e1599b.mp3", "hash": "1f2752a46d4a87eaf01e8c6a9237c0316781d7e99d7df3bea51670d15e501042", "bytes": 35856, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/dba67c03df4467b55091912817dfbc2dffc078ea6ae66cf7a7c1bdd161e1599b.mp3", "duration_ms": 5920}, "s1-ordenar-dia.explanation": {"url": "http://localhost:4006/files/lesson-audio/0f09b29404e4879161715ba852320ea3648c798a3051f81a48416108d75464d5.mp3", "hash": "6634379903489a04847b61841e84c640573657f35a2dc4c842250df71e7810db", "bytes": 67968, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/0f09b29404e4879161715ba852320ea3648c798a3051f81a48416108d75464d5.mp3", "duration_ms": 11280}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('376d331c-9296-4bfd-9d4f-d2f052be4db4', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "piggy-split", "title": "Repartir la ganancia", "locale": "es-MX", "subject": "money", "objectives": ["Repartir 10 pesos de ganancia entre dos alcancías: una para la meta de la guitarra y otra para reponer ingredientes."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "repartir-ganancia", "xp": 15, "type": "piggy_split", "hints": ["La guitarra cuesta 80 pesos, así que conviene ahorrar más para ella.", "Pero si no pones nada en el puesto, mañana no podrás comprar limones."], "title": "Repartir la ganancia", "payload": {"jars": [{"id": "guitarra", "icon": "savings", "label": "Alcancía de la guitarra", "hint_md": "Para la guitarra de 80 pesos", "image_url": "http://localhost:4006/files/lesson-images/828209ea01b1b82be01e9ee8af30d618cdd610c9906aa195bd097b4fd20a4b38.png"}, {"id": "puesto", "icon": "store", "label": "Alcancía del puesto", "hint_md": "Para reponer limones y vasos", "image_url": "http://localhost:4006/files/lesson-images/e096a586a9675955ef97a507a4e7d569fede6176e0a187ff81149dd834c6e642.png"}], "step": 1, "unit": "MXN", "income": 10}, "narrator": {"emotion": "happy", "character": "dina"}, "prompt_md": "Liruf ganó 10 pesos. Pon más en la alcancía de la guitarra que en la del puesto.", "difficulty": 2, "explanation_md": "Liruf puso 6 en la guitarra y 4 en el puesto. Así ahorra más para su meta y aún tiene para ingredientes.", "audio_segment_id": "repartir-ganancia.prompt"}], "schema_version": 1}', '{"repartir-ganancia": {"targets": {"puesto": {"max": 4, "min": 1}, "guitarra": {"max": 9, "min": 6}}, "rationale_md": "Debes poner más en la guitarra que en el puesto, pero al menos 1 en el puesto para poder seguir vendiendo."}}', '{"units": {"repartir-ganancia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4f371eea8bf7db6e8ac77986486674fb8364eb53948e692e6058e3f438f633b9.mp3", "hash": "5888af94cdd151b2f19eb497f5e9804e724f3529d69da466f96e1ada1e7101b6", "bytes": 29664, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4f371eea8bf7db6e8ac77986486674fb8364eb53948e692e6058e3f438f633b9.mp3", "duration_ms": 4880}, "repartir-ganancia.hint.1": {"url": "http://localhost:4006/files/lesson-audio/ae49fe3c1334a1dae685e182e9a9157c7557bd27cd66260b9002a73471f8ae16.mp3", "hash": "6a46924a094267bca6df42cc9aaf119a079e0c11d9d62674ad5d428a6d607d4c", "bytes": 29664, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/ae49fe3c1334a1dae685e182e9a9157c7557bd27cd66260b9002a73471f8ae16.mp3", "duration_ms": 4880}, "repartir-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/beddc2a24f8c96b11bbfb3f43f950d1f047cea10a9a136a4fc7b652226fc46a5.mp3", "hash": "9376a74f298c6daa346224f5e49530021a11cf64651e8c9646c2f8c37ea0167e", "bytes": 33408, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/beddc2a24f8c96b11bbfb3f43f950d1f047cea10a9a136a4fc7b652226fc46a5.mp3", "duration_ms": 5520}, "repartir-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/7e8a72a297a2866537f1123d30da27e0ca79e86148e053e43ad4b66c067adf98.mp3", "hash": "e3d7402db726ac38fba9a91d927c27034d9974b7ff9def46e233a32301709c86", "bytes": 49248, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7e8a72a297a2866537f1123d30da27e0ca79e86148e053e43ad4b66c067adf98.mp3", "duration_ms": 8160}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('98f38e44-71ba-4294-87ea-7a6684eb8359', 'en-US', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "balance-scale", "title": "Balance the barter scale", "locale": "en-US", "subject": "mixed", "objectives": ["Balance the barter scale by placing cookies until both sides are worth the same."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-balance-trueque", "xp": 15, "type": "balance_scale", "hints": ["Each glass is worth 5 pesos. How much do 3 glasses add up to?", "Each cookie is worth 3 pesos. How many cookies do you need to equal the total of the glasses?"], "title": "The barter scale", "payload": {"weights": [{"id": "galleta1", "label": "cookie", "value": 3}, {"id": "galleta2", "label": "cookie", "value": 3}, {"id": "galleta3", "label": "cookie", "value": 3}, {"id": "galleta4", "label": "cookie", "value": 3}, {"id": "galleta5", "label": "cookie", "value": 3}], "left_fixed": [{"label": "glass of lemonade", "value": 5}, {"label": "glass of lemonade", "value": 5}, {"label": "glass of lemonade", "value": 5}], "unknown_label": "cookie"}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf puts 3 glasses of lemonade (5 pesos each). Place 3-peso cookies until the scale balances.", "difficulty": 2, "explanation_md": "3 glasses of 5 pesos add up to 15 pesos. 5 cookies of 3 pesos also add up to 15 pesos. The scale balances!", "audio_segment_id": "s1-balance-trueque.prompt"}], "schema_version": 1}', '{"s1-balance-trueque": {}}', '{"units": {"s1-balance-trueque.hint.0": {"url": "http://localhost:4006/files/lesson-audio/06848605b79c110d3f515453f5f11ec0591e39fdd97389d1e803bfac70df8b1a.mp3", "hash": "3cd3ccd5067455091e768af55fe59447aae80cb41d11ca1c74017bf5b9f9ced1", "bytes": 30528, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/06848605b79c110d3f515453f5f11ec0591e39fdd97389d1e803bfac70df8b1a.mp3", "duration_ms": 5040}, "s1-balance-trueque.hint.1": {"url": "http://localhost:4006/files/lesson-audio/eddbd5876087f97717b05986eacabafd94b0940980a8d681dee824d4c2605c2c.mp3", "hash": "3d53cdd900b946718bf6339f8632a8269eae6b9d8cf4b8011e5fdd9969877e34", "bytes": 36288, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/eddbd5876087f97717b05986eacabafd94b0940980a8d681dee824d4c2605c2c.mp3", "duration_ms": 6000}, "s1-balance-trueque.prompt": {"url": "http://localhost:4006/files/lesson-audio/4f3fec08ed8eed40df0980bfa7ed93c3e7992adeefd21ad106317ea8c72106eb.mp3", "hash": "78611c466c4a239384956987fa533428503557d4d03795032b462cefc7fc97be", "bytes": 40608, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/4f3fec08ed8eed40df0980bfa7ed93c3e7992adeefd21ad106317ea8c72106eb.mp3", "duration_ms": 6720}, "s1-balance-trueque.explanation": {"url": "http://localhost:4006/files/lesson-audio/d26a37562bc7a00ca62814410e2ba1b0ff16ae05d6aa85254ed535ae7af14c40.mp3", "hash": "559e8ed19cb4a2dbf11fa0018743594ee61772e5737358adbf9a006ff88283bb", "bytes": 57024, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/d26a37562bc7a00ca62814410e2ba1b0ff16ae05d6aa85254ed535ae7af14c40.mp3", "duration_ms": 9440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('98f38e44-71ba-4294-87ea-7a6684eb8359', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "balance-scale", "title": "Equilibra a balança do escambo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Equilibrar a balança do escambo colocando biscoitos até que ambos os pratos valham o mesmo."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-balance-trueque", "xp": 15, "type": "balance_scale", "hints": ["Cada copo vale 5 pesos. Quanto somam 3 copos?", "Cada biscoito vale 3 pesos. Quantos biscoitos você precisa para igualar o total dos copos?"], "title": "A balança do escambo", "payload": {"weights": [{"id": "galleta1", "label": "biscoito", "value": 3}, {"id": "galleta2", "label": "biscoito", "value": 3}, {"id": "galleta3", "label": "biscoito", "value": 3}, {"id": "galleta4", "label": "biscoito", "value": 3}, {"id": "galleta5", "label": "biscoito", "value": 3}], "left_fixed": [{"label": "copo de limonada", "value": 5}, {"label": "copo de limonada", "value": 5}, {"label": "copo de limonada", "value": 5}], "unknown_label": "biscoito"}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf coloca 3 copos de limonada (5 pesos cada). Coloque biscoitos de 3 pesos até a balança se equilibrar.", "difficulty": 2, "explanation_md": "3 copos de 5 pesos somam 15 pesos. 5 biscoitos de 3 pesos também somam 15 pesos. A balança se equilibra!", "audio_segment_id": "s1-balance-trueque.prompt"}], "schema_version": 1}', '{"s1-balance-trueque": {}}', '{"units": {"s1-balance-trueque.hint.0": {"url": "http://localhost:4006/files/lesson-audio/95551584bbb31f02d3d68c82847244a6eed194c68df55b5cb4cf79a11ff183f9.mp3", "hash": "76252bf0c9f6da1d00174a4ae30682c6f5a03f3d44c0032c15b87082aa06e7ab", "bytes": 29088, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/95551584bbb31f02d3d68c82847244a6eed194c68df55b5cb4cf79a11ff183f9.mp3", "duration_ms": 4800}, "s1-balance-trueque.hint.1": {"url": "http://localhost:4006/files/lesson-audio/df8a0efce5514d96e0a1dc65f777585fea51896d0071e249806cd0bd235c56ec.mp3", "hash": "f43a62fd3c63b1806ed6f35ea8d680908bb7fea95a5e2f54d049cf626d29b1fd", "bytes": 38304, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/df8a0efce5514d96e0a1dc65f777585fea51896d0071e249806cd0bd235c56ec.mp3", "duration_ms": 6320}, "s1-balance-trueque.prompt": {"url": "http://localhost:4006/files/lesson-audio/2ef6c4c42c8e0bfd51b55bdd1bddcd9011754155c9c4a40417f44df3b24fc696.mp3", "hash": "2c9f584d6c9bd582fb03d6df848a8657f7470d9433f376c935a28ecf8febbc7d", "bytes": 50688, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/2ef6c4c42c8e0bfd51b55bdd1bddcd9011754155c9c4a40417f44df3b24fc696.mp3", "duration_ms": 8400}, "s1-balance-trueque.explanation": {"url": "http://localhost:4006/files/lesson-audio/623d65f48ee6ec340b713b2f2c976d7fc2b5000955f6ad8df3b77e33fddcb434.mp3", "hash": "4445a20062b6c05cdf5d56cf17a653df40fef69ce5107d8aad71603671c6b48d", "bytes": 56448, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/623d65f48ee6ec340b713b2f2c976d7fc2b5000955f6ad8df3b77e33fddcb434.mp3", "duration_ms": 9360}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b979bce6-8935-480e-8471-33053faa2321', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "sort-buckets", "title": "Clasifica las compras del puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Clasificar compras entre necesidades del puesto y gustos que pueden esperar"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-sort-buckets", "xp": 10, "type": "sort_buckets", "hints": ["Los limones cuestan $2 y los vasos $5. ¿El puesto necesita eso para vender limonada?"], "title": "Clasifica las compras", "payload": {"items": [{"id": "limones", "text_md": "Limones ($2)", "image_url": "http://localhost:4006/files/lesson-images/c70a486103e6eb0c83e26f0e6163af87b1174100157cf3713e16605cb5f4f0eb.png"}, {"id": "vasos", "text_md": "Vasos ($5)", "image_url": "http://localhost:4006/files/lesson-images/8ee7c074bbe99c82ac522bfc44798896334115a4eab2c3c44371dbc6354b591c.png"}, {"id": "stickers", "text_md": "Stickers ($3)", "image_url": "http://localhost:4006/files/lesson-images/7bff0b7690e975342e8bb5dc61d1c1f49716f440b9e647d75e709d77b37981ce.png"}, {"id": "globos", "text_md": "Globos ($4)", "image_url": "http://localhost:4006/files/lesson-images/a624235b2518e564e3e342749bca3f148042eed2452b889f7feb0f0654a1fc76.png"}], "buckets": [{"id": "necesidad", "label": "NECESIDAD del puesto"}, {"id": "gusto", "label": "GUSTO que puede esperar"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "¡Recuerdas los precios del puesto? Liruf tiene $10. ¿Qué necesita comprar hoy?", "difficulty": 1, "explanation_md": "Los limones y los vasos son necesarios para hacer y servir la limonada. Los stickers y los globos son gustos que pueden esperar.", "audio_segment_id": "s1-sort-buckets.prompt"}], "schema_version": 1}', '{"s1-sort-buckets": {"assignments": {"vasos": "necesidad", "globos": "gusto", "limones": "necesidad", "stickers": "gusto"}}}', '{"units": {"s1-sort-buckets.hint.0": {"url": "http://localhost:4006/files/lesson-audio/1b2bcea60b437944645f0163aabb2b5590ea4277a74ac205d124af31d42789ce.mp3", "hash": "4d606e27aceaaab95f9ca2c48b8efddcf0df604e7bfcbaa23b2632bba44b73dd", "bytes": 45936, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1b2bcea60b437944645f0163aabb2b5590ea4277a74ac205d124af31d42789ce.mp3", "duration_ms": 7600}, "s1-sort-buckets.prompt": {"url": "http://localhost:4006/files/lesson-audio/f95c580b29f4e0770510c325df1b8e25be3f2310e32f454e8bd1f4a7f1768a31.mp3", "hash": "0e2dc98746d229b83f76dc57aceb9e9a53382093311c98241cf2188dbfbd9fc2", "bytes": 38736, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f95c580b29f4e0770510c325df1b8e25be3f2310e32f454e8bd1f4a7f1768a31.mp3", "duration_ms": 6400}, "s1-sort-buckets.explanation": {"url": "http://localhost:4006/files/lesson-audio/3845223b3e73117bae0dbd878d8836958f3e6dca1d26426f509a500b98adfbc7.mp3", "hash": "847c47a38a7fd14b8f09b1042a94b0e789b9c2be07770e29e30ea6100e76d2c6", "bytes": 52704, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/3845223b3e73117bae0dbd878d8836958f3e6dca1d26426f509a500b98adfbc7.mp3", "duration_ms": 8720}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('462e0be5-c40d-4de9-840d-6f696539d27e', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-dialogo-doble-choice", "title": "Dois vizinhos opinam sobre a barraca", "locale": "pt-BR", "subject": "money", "objectives": ["Ouvir uma conversa entre clientes sobre a limonada e responder perguntas de compreensão."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogo", "xp": 0, "type": "story_dialogue", "title": "Vizinhos na mesa", "payload": {"lines": [{"action": "idle", "emotion": "neutral", "text_md": "Ei, você já viu a barraca de limonada do Liruf?", "character": "dina"}, {"action": "idle", "emotion": "neutral", "text_md": "Sim, eles vendem copos por 5 pesos. Que bom preço!", "character": "liruf"}, {"action": "idle", "emotion": "thinking", "text_md": "Sim, mas ontem comprei um e só tinha 3 pesos. Faltaram 2.", "character": "dina"}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/13df88ff8efede4f2eaa16e68faacfc81ae44bff71f038136c20ced354c66bcf.png", "prompt_md": "Ouça o que os vizinhos dizem.", "difficulty": 1, "audio_segment_id": "s1-dialogo.prompt"}, {"id": "s2-true-false", "xp": 10, "type": "true_false", "title": "Certo ou falso?", "payload": {"statement_md": "Dina diz que o copo de limonada custa 5 pesos.", "justifications": [{"id": "j1", "text_md": "Sim, porque Liruf disse que o preço é 5 pesos."}, {"id": "j2", "text_md": "Não, porque Dina disse que só tinha 3 pesos."}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "De acordo com a conversa, escolha se a afirmação é certa ou falsa.", "difficulty": 1, "explanation_md": "Liruf disse ''vendem copos por 5 pesos'', então é certo. Dina só disse que tinha 3 pesos, mas isso não muda o preço.", "audio_segment_id": "s2-true-false.prompt"}, {"id": "s3-picture-choice", "xp": 10, "type": "picture_choice", "title": "Quanto faltou para Dina?", "payload": {"options": [{"id": "opt1", "icon": "monetization_on", "label": "2 moedas de 1 peso", "image_url": "http://localhost:4006/files/lesson-images/a4a0aa7370a7472e314745ad9a74ea76e36ab75861e0463949faaf813a9faccf.png", "rationale_md": "Correto. 5 - 3 = 2, então faltaram 2 pesos."}, {"id": "opt2", "icon": "monetization_on", "label": "3 moedas de 1 peso", "image_url": "http://localhost:4006/files/lesson-images/43ba16097d757b34c0173e3ef37b37e03db0bb5f63c37d859ea2fb0ca0d7659c.png", "rationale_md": "Quase, mas 3 + 3 = 6, que é mais que 5. Faltaram só 2 pesos."}, {"id": "opt3", "icon": "monetization_on", "label": "1 moeda de 5 pesos", "image_url": "http://localhost:4006/files/lesson-images/0f4f9cdf6ea523f309cee5d40ad4012aceb695a85c86d108c3d73a8835e52eee.png", "rationale_md": "Isso é mais do que ela precisa. Faltaram 2 pesos, não 5."}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Dina queria comprar um copo de 5 pesos mas só tinha 3. Quanto faltou?", "difficulty": 1, "explanation_md": "O copo custa 5 pesos e Dina tinha 3. 5 menos 3 são 2, por isso faltaram 2 pesos.", "audio_segment_id": "s3-picture-choice.prompt"}], "schema_version": 1}', '{"s2-true-false": {"is_true": true, "correct_justification_id": "j1"}, "s3-picture-choice": {"correct_option_id": "opt1"}}', '{"units": {"s1-dialogo.line.0": {"url": "http://localhost:4006/files/lesson-audio/c0dea577c428151f6299f35c7d7a188032e9e7112a3e67e53e1707ef0e8a5b03.mp3", "hash": "4d5b75d563e2497d218bff035bbe691e1ee758e6051f20e1608f1c332f0bf874", "bytes": 21024, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c0dea577c428151f6299f35c7d7a188032e9e7112a3e67e53e1707ef0e8a5b03.mp3", "duration_ms": 3440}, "s1-dialogo.line.1": {"url": "http://localhost:4006/files/lesson-audio/a23a5f76f1c482b5eb4b3a559066a260f44ef7e2961ba0ee2b1406a487fdffbe.mp3", "hash": "bbe7e5eef5dc915d30ad3d1e304c24ed9788b45268faae5c77680d82904e4fae", "bytes": 24768, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/a23a5f76f1c482b5eb4b3a559066a260f44ef7e2961ba0ee2b1406a487fdffbe.mp3", "duration_ms": 4080}, "s1-dialogo.line.2": {"url": "http://localhost:4006/files/lesson-audio/2e3b6951c958a88f798eb8294353d34e2b09f37146d8e16d56bd791db312ec15.mp3", "hash": "b6fe91c74dc621fb277869984eda15c8d2e9bd733021eef7373669ad0e834eda", "bytes": 29664, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2e3b6951c958a88f798eb8294353d34e2b09f37146d8e16d56bd791db312ec15.mp3", "duration_ms": 4880}, "s1-dialogo.prompt": {"url": "http://localhost:4006/files/lesson-audio/feb36060651371cc55c12b4bd00db4ccaf7f9c910398c131a10dd1625ec6761d.mp3", "hash": "57df99e7993968f806d735ce5fa663745f515ef053d55dbcd7a074c3dff5f298", "bytes": 14256, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/feb36060651371cc55c12b4bd00db4ccaf7f9c910398c131a10dd1625ec6761d.mp3", "duration_ms": 2320}, "s2-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/940a283509a57778281a5b5b9b71b43a50d8c564cfab1a0ddb6ffb3d003cef5a.mp3", "hash": "94b26a8bf3ef133c7ab92261cbcd68ab9c14e0bfcc66ca262cd295d7083884aa", "bytes": 27648, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/940a283509a57778281a5b5b9b71b43a50d8c564cfab1a0ddb6ffb3d003cef5a.mp3", "duration_ms": 4560}, "s3-picture-choice.prompt": {"url": "http://localhost:4006/files/lesson-audio/b3690b2d9f672e5e262f80e77e7dd49be30b9b432ecd6bf8ba45dc9ebd5fb715.mp3", "hash": "c31b986f337e7c46dd169b44f9832903c702c78aade66ecc9d2309bca1c93ef4", "bytes": 33984, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/b3690b2d9f672e5e262f80e77e7dd49be30b9b432ecd6bf8ba45dc9ebd5fb715.mp3", "duration_ms": 5600}, "s2-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/7399cbade88a6678c00a5d58c98e7351ffceff3b0b2b2f8c14db622e574bf7d8.mp3", "hash": "7d06a4bdf6d23f02a2d32b2ea557d464328bdfc322ec64f2384ef337ff3b5007", "bytes": 50688, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/7399cbade88a6678c00a5d58c98e7351ffceff3b0b2b2f8c14db622e574bf7d8.mp3", "duration_ms": 8400}, "s3-picture-choice.choices": {"url": "http://localhost:4006/files/lesson-audio/2d4e63ae768e7ba7814d3921e4965faa49b759a8af3ced0088d61be585fd0c02.mp3", "hash": "1e693498c489ad7227065f67dc725d0d31a21b91ba82bd2ca72a109db5c4601e", "bytes": 35856, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/2d4e63ae768e7ba7814d3921e4965faa49b759a8af3ced0088d61be585fd0c02.mp3", "duration_ms": 5920}, "s3-picture-choice.explanation": {"url": "http://localhost:4006/files/lesson-audio/9322082cce001351c09311152c0c6cd836255265581d5e35b93df61797e7769b.mp3", "hash": "c6f9cee02d91be96f8162d564baaef0df6499bc33adfbea6211928d1f2c231b5", "bytes": 52128, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/9322082cce001351c09311152c0c6cd836255265581d5e35b93df61797e7769b.mp3", "duration_ms": 8640}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b979bce6-8935-480e-8471-33053faa2321', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "sort-buckets", "title": "Classify the stand''s purchases", "locale": "en-US", "subject": "mixed", "objectives": ["Classify purchases between stand needs and wants that can wait"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-sort-buckets", "xp": 10, "type": "sort_buckets", "hints": ["Lemons cost $2 and cups cost $5. Does the stand need those to sell lemonade?"], "title": "Classify the purchases", "payload": {"items": [{"id": "limones", "text_md": "Lemons ($2)", "image_url": "http://localhost:4006/files/lesson-images/615a9c35450d44297c9447af5fbb0d0a66f55787faefd922ae5f1baac975ca4e.png"}, {"id": "vasos", "text_md": "Cups ($5)", "image_url": "http://localhost:4006/files/lesson-images/0dcfda50947aba1f542d7dd5031a8565909d27a5cdbd29a176c2989b9ec57969.png"}, {"id": "stickers", "text_md": "Stickers ($3)", "image_url": "http://localhost:4006/files/lesson-images/4ba2383273a0614d38a49ef37e261cc5aa1cc07562df1cb289b3c46543189750.png"}, {"id": "globos", "text_md": "Balloons ($4)", "image_url": "http://localhost:4006/files/lesson-images/82fe3d61a3f01494ad1b42a068649d3da8f2c1d895d6e13d1b58cb11bba27c69.png"}], "buckets": [{"id": "necesidad", "label": "STAND NEED"}, {"id": "gusto", "label": "WANT that can wait"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Do you remember the stand''s prices? Liruf has $10. What does he need to buy today?", "difficulty": 1, "explanation_md": "Lemons and cups are necessary to make and serve lemonade. Stickers and balloons are wants that can wait.", "audio_segment_id": "s1-sort-buckets.prompt"}], "schema_version": 1}', '{"s1-sort-buckets": {"assignments": {"vasos": "necesidad", "globos": "gusto", "limones": "necesidad", "stickers": "gusto"}}}', '{"units": {"s1-sort-buckets.hint.0": {"url": "http://localhost:4006/files/lesson-audio/19001971a6b6869b14d26f043187115022d023b7102f226153f1b076c1d142a2.mp3", "hash": "974eaa31fec73fb377e9d177244dd1e1a13fb13366be748bb163769d7020de5e", "bytes": 31104, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/19001971a6b6869b14d26f043187115022d023b7102f226153f1b076c1d142a2.mp3", "duration_ms": 5120}, "s1-sort-buckets.prompt": {"url": "http://localhost:4006/files/lesson-audio/593efd6c066600d5d1a954afd6fbe89c1821d7dbfda756a4754e73806cf47622.mp3", "hash": "7af28402b56847d3063306a094f1d1478f5472e31eee5a17f52cdbc819f3b0f1", "bytes": 30528, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/593efd6c066600d5d1a954afd6fbe89c1821d7dbfda756a4754e73806cf47622.mp3", "duration_ms": 5040}, "s1-sort-buckets.explanation": {"url": "http://localhost:4006/files/lesson-audio/d0e7e06740f3974bab926280d9e269c92b27b767b89d446b630b6a1d9596d053.mp3", "hash": "073f531a579bd472042cba688beb328ac3e9ab1ad06c5d72d49fbd4617587073", "bytes": 34848, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/d0e7e06740f3974bab926280d9e269c92b27b767b89d446b630b6a1d9596d053.mp3", "duration_ms": 5760}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f62a6048-4f69-4ab4-9256-d87525c8e112', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "make-change", "title": "Dar troco exato", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular o troco de uma nota de 20 ao comprar dois produtos de 5 e 3 reais", "Montar o troco com moedas de 1, 2, 5 e 10"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cambio-don-beto", "xp": 15, "type": "make_change", "hints": ["Some o custo do copo e do biscoito.", "O troco é o que sobra da nota de 20 depois de pagar."], "title": "O troco do seu Beto", "payload": {"price": 8, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/9855e56389821b495c00b8fe1c97659be3cae4fb0b148642f49380fae2a3c5b3.png", "prompt_md": "Seu Beto compra 1 copo (5 reais) e 1 biscoito (3 reais). Paga com 20 reais. Monta seu troco com moedas.", "difficulty": 2, "explanation_md": "Copo 5 + biscoito 3 = 8 reais. De 20 sobram 12. As moedas que somam 12 são 10 + 2.", "audio_segment_id": "s1-cambio-don-beto.prompt"}], "schema_version": 1}', '{"s1-cambio-don-beto": {}}', '{"units": {"s1-cambio-don-beto.hint.0": {"url": "http://localhost:4006/files/lesson-audio/379221ae376dac4eda2a6ab0cfb44a33964779a1933dfcac791a8d086c80c45f.mp3", "hash": "8035df88703da7fa62d8175ff6454a554d195450d0877ab523d30e71680804b2", "bytes": 16128, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/379221ae376dac4eda2a6ab0cfb44a33964779a1933dfcac791a8d086c80c45f.mp3", "duration_ms": 2640}, "s1-cambio-don-beto.hint.1": {"url": "http://localhost:4006/files/lesson-audio/6dab5170a3cf83c700bcf73a5df9be82fdbf7ba5087a4eaa3507a13bc75842e0.mp3", "hash": "b63bc84208bee7e1db2bb5d2f1d8103e15a714e50c34a99549ea82a9b7d86a69", "bytes": 24768, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/6dab5170a3cf83c700bcf73a5df9be82fdbf7ba5087a4eaa3507a13bc75842e0.mp3", "duration_ms": 4080}, "s1-cambio-don-beto.prompt": {"url": "http://localhost:4006/files/lesson-audio/b10e164d262524ccfdd0af7950f27f2a605e0a1430c4b3c958272ff751ce009d.mp3", "hash": "02d6a01df064467bcbec789ade3e610e7987b2f731b50819087a27d26d7f036c", "bytes": 58896, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/b10e164d262524ccfdd0af7950f27f2a605e0a1430c4b3c958272ff751ce009d.mp3", "duration_ms": 9760}, "s1-cambio-don-beto.explanation": {"url": "http://localhost:4006/files/lesson-audio/0e42d4cd018fe2849d3f23d5a779156dcfec1694e49285ba2c7a91eda3b70fc0.mp3", "hash": "88dc400a6be600a7ff49754d3feccab0a6774f812e4c4763daca68ae97551d35", "bytes": 54576, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/0e42d4cd018fe2849d3f23d5a779156dcfec1694e49285ba2c7a91eda3b70fc0.mp3", "duration_ms": 9040}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('376d331c-9296-4bfd-9d4f-d2f052be4db4', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "piggy-split", "title": "Sharing the profit", "locale": "en-US", "subject": "money", "objectives": ["Share a profit of 10 pesos between two piggy banks: one for the guitar goal and one to restock ingredients."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "repartir-ganancia", "xp": 15, "type": "piggy_split", "hints": ["The guitar costs 80 pesos, so it''s better to save more for it.", "But if you don''t put anything in the stand, you won''t be able to buy lemons tomorrow."], "title": "Sharing the profit", "payload": {"jars": [{"id": "guitarra", "icon": "savings", "label": "Guitar piggy bank", "hint_md": "For the 80-peso guitar", "image_url": "http://localhost:4006/files/lesson-images/49ed0dda1f0ecf17d91906ca3e3ba6ccce3eba0827239c0d8d97af7365a0b7e2.png"}, {"id": "puesto", "icon": "store", "label": "Stand piggy bank", "hint_md": "To restock lemons and cups", "image_url": "http://localhost:4006/files/lesson-images/cfdd3d80eb97e91552e33255f161a1612649e62034afa2593ff453b407f13972.png"}], "step": 1, "unit": "MXN", "income": 10}, "narrator": {"emotion": "happy", "character": "dina"}, "prompt_md": "Liruf earned 10 pesos. Put more in the guitar piggy bank than in the stand piggy bank.", "difficulty": 2, "explanation_md": "Liruf put 6 in the guitar and 4 in the stand. That way, he saves more for his goal and still has money for ingredients.", "audio_segment_id": "repartir-ganancia.prompt"}], "schema_version": 1}', '{"repartir-ganancia": {"targets": {"puesto": {"max": 4, "min": 1}, "guitarra": {"max": 9, "min": 6}}, "rationale_md": "Debes poner más en la guitarra que en el puesto, pero al menos 1 en el puesto para poder seguir vendiendo."}}', '{"units": {"repartir-ganancia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b0d0b2bc7f1b89869f80e53567e1ddf85dba85242feab93ccf350537821f1169.mp3", "hash": "abea57a8ead34e48169b4fa52a658c15d4106d13cbf479d55c6904eec96e24b4", "bytes": 21024, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/b0d0b2bc7f1b89869f80e53567e1ddf85dba85242feab93ccf350537821f1169.mp3", "duration_ms": 3440}, "repartir-ganancia.hint.1": {"url": "http://localhost:4006/files/lesson-audio/c23d3c65081b31c18f4e3efbb4a3471dd08076b3094545af2be8e0ad40a908fe.mp3", "hash": "d53c6b22cb4a6fc4333f73c3360ff15c50d7071883f16d3a312a2a8bd25fae10", "bytes": 24768, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c23d3c65081b31c18f4e3efbb4a3471dd08076b3094545af2be8e0ad40a908fe.mp3", "duration_ms": 4080}, "repartir-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/6b5c85524a0c695c24c58b7e40d648e4611582a1f1b6d4cb7cdd3ea3f801f8f9.mp3", "hash": "e47a0c26ecb2ce088655ee18254af618fbfc9d68471acb8f1df22318e706b945", "bytes": 30096, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6b5c85524a0c695c24c58b7e40d648e4611582a1f1b6d4cb7cdd3ea3f801f8f9.mp3", "duration_ms": 4960}, "repartir-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/4f5a9150f73e3f45d4fa5deffb683bd22e8125514653df31733ba06ff6e5c29c.mp3", "hash": "f2e8ab4d4335c2dde338df033e4a617ae9372e42e94a0d1b647a460386aa7aca", "bytes": 40176, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4f5a9150f73e3f45d4fa5deffb683bd22e8125514653df31733ba06ff6e5c29c.mp3", "duration_ms": 6640}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4785eb58-e0ca-4b5c-a796-a6f01b2ab3ae', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "pattern-complete", "title": "Escalera de precios", "locale": "es-MX", "subject": "money", "objectives": ["Ordenar pasos, emparejar productos con precios y clasificar compras entre necesidades del puesto y gustos que pueden esperar."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-escalera", "xp": 15, "type": "pattern_complete", "hints": ["Observa cómo sube el precio: chico $5, mediano $10, grande $15, luego vuelve a empezar. ¿Qué tamaño sigue después de mediano?", "La escalera siempre sube de precio: chico → mediano → grande → chico → mediano → ¿? El siguiente debe ser el más caro."], "title": "Escalera de precios", "payload": {"options": [{"id": "grande", "icon": "local_cafe", "tint": "success"}, {"id": "chico", "icon": "local_cafe", "tint": "primary"}, {"id": "limon", "icon": "nutrition", "tint": "delight"}], "sequence": [{"icon": "local_cafe", "tint": "primary"}, {"icon": "local_cafe", "tint": "accent"}, {"icon": "local_cafe", "tint": "success"}, {"icon": "local_cafe", "tint": "primary"}, {"icon": "local_cafe", "tint": "accent"}, {"icon": "local_cafe", "tint": "warning"}], "missing_slots": 1}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Toca el vaso que completa la escalera: chico $5, mediano $10, grande $15, chico $5, mediano $10, ¿?", "difficulty": 2, "explanation_md": "Después del mediano de $10 viene el grande de $15, porque la escalera sube de precio: chico ($5), mediano ($10), grande ($15) y vuelve a empezar.", "audio_segment_id": "s1-escalera.prompt"}], "schema_version": 1}', '{"s1-escalera": {"correct": {"5": "grande"}}}', '{"units": {"s1-escalera.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0f4494469960cf826b6307fb6302726a4bf6bb39dce5053b180da85115335747.mp3", "hash": "f36f819396cb9d0463b6c3957822c46df0b093475da83b52abd0d15ce31f3c2e", "bytes": 58896, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/0f4494469960cf826b6307fb6302726a4bf6bb39dce5053b180da85115335747.mp3", "duration_ms": 9760}, "s1-escalera.hint.1": {"url": "http://localhost:4006/files/lesson-audio/eeda14917df598e805d86e33ea313d69e1c76953473dc99b6277ee9a8b47bf22.mp3", "hash": "84bd4993de6dcce1fcfa726c9fdb065e94eca1212f37584ac3751f0a8391f126", "bytes": 45936, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/eeda14917df598e805d86e33ea313d69e1c76953473dc99b6277ee9a8b47bf22.mp3", "duration_ms": 7600}, "s1-escalera.prompt": {"url": "http://localhost:4006/files/lesson-audio/97927482e31c76e00a07ff952b1d051769dae441b4a0dda303e02fec84740b07.mp3", "hash": "8e8791db286aade0ee26387495a55447cf3b5ec9f7e75d470100b60c65e397de", "bytes": 54144, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/97927482e31c76e00a07ff952b1d051769dae441b4a0dda303e02fec84740b07.mp3", "duration_ms": 8960}, "s1-escalera.explanation": {"url": "http://localhost:4006/files/lesson-audio/dfdf36e6afbc0cd0ec93442892a89428282ab1074812acc1b7950f42f6b023b2.mp3", "hash": "29411a28a9fbcdd27d4b95135f451db5b6ede498175bfe62438ccea4e8725874", "bytes": 70416, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/dfdf36e6afbc0cd0ec93442892a89428282ab1074812acc1b7950f42f6b023b2.mp3", "duration_ms": 11680}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('000a07f3-d716-40f9-bb5f-2d175c582162', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "spot-error", "title": "Find the error in the account", "locale": "en-US", "subject": "mixed", "objectives": ["Detect an error in a sales sum", "Read a simple graph of cups sold per day", "Recognize signs of a bad deal"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-spot-error", "xp": 15, "type": "spot_error", "hints": ["Count how many cups Liruf sold: 5, then 5, then 5. How much do they add up to?", "If each cup costs 5 pesos, three cups are 5+5+5. Does that equal 20?"], "title": "The account that doesn''t add up", "payload": {"steps": [{"id": "paso1", "text_md": "5 (first cup)"}, {"id": "paso2", "text_md": "+ 5 (second cup)"}, {"id": "paso3", "text_md": "+ 5 (third cup)"}, {"id": "paso4", "text_md": "= 20 (total)"}], "context_md": "Liruf sold 3 lemonade cups at 5 pesos each. In his notebook he wrote: 5 + 5 + 5 = 20."}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/e81fb681d1ae08857c7d67efa5ab2d0eab4a8255a3b729fdbf491040a59fe073.png", "prompt_md": "Liruf wrote: 5 + 5 + 5 = 20. Which step is wrong?", "difficulty": 2, "explanation_md": "5 + 5 + 5 is 15, not 20. Liruf added the last step wrong: he put 20 instead of 15.", "audio_segment_id": "s1-spot-error.prompt"}], "schema_version": 1}', '{"s1-spot-error": {"error_ids": ["paso4"], "correction_md": "El error está en el total: 5 + 5 + 5 = 15, no 20."}}', '{"units": {"s1-spot-error.hint.0": {"url": "http://localhost:4006/files/lesson-audio/1563260c2841d330db12e59a44c6b8a2df33a85585af6aac953fd69bd7d2a2d5.mp3", "hash": "ddb71c8300ea9072f4e1de45aaf2221e7f2f9bab2eb1bc0de9bfac92bac67562", "bytes": 36288, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/1563260c2841d330db12e59a44c6b8a2df33a85585af6aac953fd69bd7d2a2d5.mp3", "duration_ms": 6000}, "s1-spot-error.hint.1": {"url": "http://localhost:4006/files/lesson-audio/6b8bffeedd1928d920eddf52b3278c24b55795aa2c6c8a2e5d045efba7509293.mp3", "hash": "d3da007864a71cfd4b97ab780aabed67b329f4c9bbb8121d36a2f696c1b38752", "bytes": 43488, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6b8bffeedd1928d920eddf52b3278c24b55795aa2c6c8a2e5d045efba7509293.mp3", "duration_ms": 7200}, "s1-spot-error.prompt": {"url": "http://localhost:4006/files/lesson-audio/c4650277a6d7fe9da2ee0d211e8a2c2cc81f95180f0f077d08b982a6c0c1e3a1.mp3", "hash": "0eda3dcb4906d17f272f1562d735fe7d2071249d2159d51e485bfc91bf3e6df3", "bytes": 28224, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c4650277a6d7fe9da2ee0d211e8a2c2cc81f95180f0f077d08b982a6c0c1e3a1.mp3", "duration_ms": 4640}, "s1-spot-error.explanation": {"url": "http://localhost:4006/files/lesson-audio/888b0efb5d0b540056d3aa85088ba93449aac0c14676dc10838b7031033eb951.mp3", "hash": "d6b45ff9780f2802538e0512d95b2101b5ed3cbd499a836313c132e1860dcc2b", "bytes": 45936, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/888b0efb5d0b540056d3aa85088ba93449aac0c14676dc10838b7031033eb951.mp3", "duration_ms": 7600}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('000a07f3-d716-40f9-bb5f-2d175c582162', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "spot-error", "title": "Encontre o erro na conta", "locale": "pt-BR", "subject": "mixed", "objectives": ["Detectar um erro em uma soma de vendas", "Ler um gráfico simples de copos vendidos por dia", "Reconhecer sinais de um mau negócio"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-spot-error", "xp": 15, "type": "spot_error", "hints": ["Conte quantos copos Liruf vendeu: 5, depois 5, depois 5. Quanto dá a soma?", "Se cada copo custa 5 pesos, três copos são 5+5+5. Isso dá 20?"], "title": "A conta que não fecha", "payload": {"steps": [{"id": "paso1", "text_md": "5 (primeiro copo)"}, {"id": "paso2", "text_md": "+ 5 (segundo copo)"}, {"id": "paso3", "text_md": "+ 5 (terceiro copo)"}, {"id": "paso4", "text_md": "= 20 (total)"}], "context_md": "Liruf vendeu 3 copos de limonada a 5 pesos cada. No caderno dele, escreveu: 5 + 5 + 5 = 20."}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/ae4d6c7a9b1b788bceb4d01070e6abd650b2274343740e86381584e7a280a208.png", "prompt_md": "Liruf anotou: 5 + 5 + 5 = 20. Qual passo está errado?", "difficulty": 2, "explanation_md": "5 + 5 + 5 é 15, não 20. Liruf somou errado o último passo: colocou 20 em vez de 15.", "audio_segment_id": "s1-spot-error.prompt"}], "schema_version": 1}', '{"s1-spot-error": {"error_ids": ["paso4"], "correction_md": "El error está en el total: 5 + 5 + 5 = 15, no 20."}}', '{"units": {"s1-spot-error.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d2f603e76bbf9c2dd17f2fa72e2933c0867c1d7dfc064aa6ec309a62c3e7ccb2.mp3", "hash": "ca4570dfb0349f20a04573c49138f7d9887364a82863fc89b65388e78b0cf999", "bytes": 44496, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d2f603e76bbf9c2dd17f2fa72e2933c0867c1d7dfc064aa6ec309a62c3e7ccb2.mp3", "duration_ms": 7360}, "s1-spot-error.hint.1": {"url": "http://localhost:4006/files/lesson-audio/6b6cd6ed390020343eae72729a81671af0bd39f1b9bb3c524a1bfc65300f76ff.mp3", "hash": "21c977508f6c022fd8a39ada5d2a92e9fa4b11735a7bf8d1e92108e9127108ac", "bytes": 44064, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/6b6cd6ed390020343eae72729a81671af0bd39f1b9bb3c524a1bfc65300f76ff.mp3", "duration_ms": 7280}, "s1-spot-error.prompt": {"url": "http://localhost:4006/files/lesson-audio/7cdb54eae79f345f30bd9685db09406c295ab81c6f7750df885a1b71bb589239.mp3", "hash": "1d34b45bb3bda80a8e31794b1bbdcd93b9c90af4d221b84f1b603cbed0dfde76", "bytes": 41184, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7cdb54eae79f345f30bd9685db09406c295ab81c6f7750df885a1b71bb589239.mp3", "duration_ms": 6800}, "s1-spot-error.explanation": {"url": "http://localhost:4006/files/lesson-audio/18fc484cc6797ee6eb5610922e17735bd66c1c71f4bd2b7cea69a1cd370c5fc6.mp3", "hash": "3bfea3a7a24975d91097360f629cefabe94bd3f1ddff34a6382e0ea6800958b1", "bytes": 58896, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/18fc484cc6797ee6eb5610922e17735bd66c1c71f4bd2b7cea69a1cd370c5fc6.mp3", "duration_ms": 9760}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ea98847f-02a1-4527-97a4-36921728b56d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "cause-effect", "title": "Causa y efecto en el puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Conectar causas y efectos del puesto: día soleado → más sed → más vasos vendidos; subir el precio al doble → menos clientes."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-causa-efecto", "xp": 10, "type": "cause_effect", "hints": ["Piensa: ¿qué pasó primero en el día?"], "title": "¿Qué pasó en el puesto?", "payload": {"slots": 5, "events": [{"id": "e1", "text_md": "Hace mucho sol"}, {"id": "e2", "text_md": "La gente tiene más sed"}, {"id": "e3", "text_md": "Liruf vende 10 vasos a $2"}, {"id": "e4", "text_md": "Liruf sube el precio a $4"}, {"id": "e5", "text_md": "Solo vende 3 vasos"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf vendió 10 vasos a $2 cada uno. Luego subió el precio a $4 y vendió 3. Ordena los eventos.", "difficulty": 1, "explanation_md": "Con sol, la gente tiene más sed y compra más. Pero si el precio sube mucho, compran menos. Liruf aprendió que no debe subir tanto el precio.", "audio_segment_id": "s1-causa-efecto.prompt"}], "schema_version": 1}', '{"s1-causa-efecto": {"chain": ["e1", "e2", "e3", "e4", "e5"]}}', '{"units": {"s1-causa-efecto.hint.0": {"url": "http://localhost:4006/files/lesson-audio/2b15e77eb45691c092b3833f487951e687d8cf67410b48070a3e51a617e30898.mp3", "hash": "fdb7d96ed54f0072ad6d104495c6ae84be4fb85c3b19c93ae63348c0d08a7c67", "bytes": 15264, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/2b15e77eb45691c092b3833f487951e687d8cf67410b48070a3e51a617e30898.mp3", "duration_ms": 2480}, "s1-causa-efecto.prompt": {"url": "http://localhost:4006/files/lesson-audio/b607bd7cc94f3e1fca26fb43f92f3f5ba56e53dd9908744dc4f81f93f59e4d19.mp3", "hash": "21fbe9b13a91e5f98dc5b7b5fc70d46727f757e4d1d9f530f01983e2739c7661", "bytes": 50688, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/b607bd7cc94f3e1fca26fb43f92f3f5ba56e53dd9908744dc4f81f93f59e4d19.mp3", "duration_ms": 8400}, "s1-causa-efecto.explanation": {"url": "http://localhost:4006/files/lesson-audio/7ba5d09b6732a80a0380b3882525646b9e4b2838a3b5e08278cb7e987fc746bd.mp3", "hash": "83a13c47391c2916996eb8950fe8578dc309efbc7fc3c9c8d2d1a58dc3cd3967", "bytes": 56448, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7ba5d09b6732a80a0380b3882525646b9e4b2838a3b5e08278cb7e987fc746bd.mp3", "duration_ms": 9360}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c9d7856b-a75e-414e-ae61-e324a19a350d', 'es-MX', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "measure-read", "title": "Medir la limonada justa", "locale": "es-MX", "subject": "mixed", "objectives": ["Leer la línea del líquido en una jarra medidora para servir vasos parejos de 5 pesos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-leer-jarra", "xp": 10, "type": "measure_read", "hints": ["Observa la línea azul del líquido. ¿Está en la marca de 200, 250 o 300 ml?"], "title": "¿Hasta dónde llegó?", "payload": {"max": 300, "min": 0, "unit": "ml", "ticks": 3, "instrument": "beaker", "pointer_value": 250}, "narrator": {"emotion": "neutral", "character": "rho"}, "image_url": "http://localhost:4006/files/lesson-images/fe4921695dfa95453812e07cbb3c5304bafb6fb426ef391fae16a176d46e7b25.png", "prompt_md": "Rho sirvió limonada. ¿Hasta qué línea llegó el líquido?", "difficulty": 1, "explanation_md": "El líquido llegó hasta la línea de 250 ml. Así todos los vasos de 5 pesos quedan iguales, como en la balanza del trueque.", "audio_segment_id": "s1-leer-jarra.prompt"}], "schema_version": 1}', '{"s1-leer-jarra": {"value": 250, "tolerance": 0}}', '{"units": {"s1-leer-jarra.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d96f31632424d3002301ab158e8860a6f3eea57f0b18ec62e96bb900dc732637.mp3", "hash": "983e09d95c5793e01eb4256b5c812bfd389c2ff95ea3f3599f7b8398e40940ea", "bytes": 44064, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/d96f31632424d3002301ab158e8860a6f3eea57f0b18ec62e96bb900dc732637.mp3", "duration_ms": 7280}, "s1-leer-jarra.prompt": {"url": "http://localhost:4006/files/lesson-audio/5338ac5eb651005fe2dbe1a4ad46b2146df9786ed462f945ccc1d71690207f8b.mp3", "hash": "7a8948fd5d6df1e7f248509c018fafbfcc8b17584187fa7e24a7f892e27e1c58", "bytes": 25344, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/5338ac5eb651005fe2dbe1a4ad46b2146df9786ed462f945ccc1d71690207f8b.mp3", "duration_ms": 4160}, "s1-leer-jarra.explanation": {"url": "http://localhost:4006/files/lesson-audio/435ad7ed3e47b5372f7107e4f337f990823ba308dc6ef60e0c1a47fd41400374.mp3", "hash": "1f0dd4d854cba79412e76eee7c6e06c26fe0d0ea16a0a6f3e5476330df5b4846", "bytes": 60336, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/435ad7ed3e47b5372f7107e4f337f990823ba308dc6ef60e0c1a47fd41400374.mp3", "duration_ms": 10000}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('85c2a66b-c70b-43e4-8fd5-4862d4acb66b', 'pt-BR', '1', '{"meta": {"cast": ["dina", "rho", "liruf"], "slug": "rank-choices", "title": "Ordene as compras da barraca", "locale": "pt-BR", "subject": "money", "objectives": ["Ordene do mais ao menos urgente em que gastar o lucro de hoje: repor limões primeiro, depois copos, e por último enfeites."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-rank", "xp": 15, "type": "rank_choices", "hints": ["Sem limões não tem limonada, sem copos não se serve.", "Os enfeites são bonitos, mas não urgentes para vender hoje."], "title": "O que comprar primeiro?", "payload": {"items": [{"id": "limones", "text_md": "Limões para a limonada", "image_url": "http://localhost:4006/files/lesson-images/543a421ba861e851300bb234b4fae64b24eddbab4df254329d6979e50beeae43.png"}, {"id": "vasos", "text_md": "Copos para servir", "image_url": "http://localhost:4006/files/lesson-images/f2d1252091f2ad34ef9ee33ecf5c4a511ea697e484f5b74724c0fbeb3d8ba442.png"}, {"id": "adornos", "text_md": "Enfeites para a barraca", "image_url": "http://localhost:4006/files/lesson-images/8bad7bc4b511bea1efb045645b5eade0f149dcb431cf82d22c07aa77a26d41f0.png"}], "criterion_md": "Ordene do mais ao menos urgente para a barraca de Liruf"}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Liruf tem $20. Toque nas despesas em ordem: a mais urgente primeiro.", "difficulty": 2, "explanation_md": "Os limões são o mais urgente porque sem eles não tem limonada. Os copos vêm depois, e os enfeites por último, porque são um capricho que pode esperar.", "audio_segment_id": "s1-rank.prompt"}], "schema_version": 1}', '{"s1-rank": {"order": ["limones", "vasos", "adornos"]}}', '{"units": {"s1-rank.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e2dc63c22f7992c7001c2a197d808378a595a56f53ae79b14b0cd55732db69b6.mp3", "hash": "93d36c5895f3b70eb3c89742e5dbd6056650084141a530e1b2467c51b743e90a", "bytes": 27648, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/e2dc63c22f7992c7001c2a197d808378a595a56f53ae79b14b0cd55732db69b6.mp3", "duration_ms": 4560}, "s1-rank.hint.1": {"url": "http://localhost:4006/files/lesson-audio/e251b1be6452abfa5e341e8709ce6b104cf14643cffcf8c57992dd42a6817870.mp3", "hash": "63846c10dee3cbbe896a3dc3a474de22218518bbef1d1311da9b46f76f84a9c6", "bytes": 27648, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/e251b1be6452abfa5e341e8709ce6b104cf14643cffcf8c57992dd42a6817870.mp3", "duration_ms": 4560}, "s1-rank.prompt": {"url": "http://localhost:4006/files/lesson-audio/b51c7f1499c5f569e9644e5798ab0f05a9bf3d2a48ec722a74dc08de34e82002.mp3", "hash": "c5166835e0aa64744e3718137fdf034bdc7a958ad377a4aefaf9be1858163a80", "bytes": 40176, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/b51c7f1499c5f569e9644e5798ab0f05a9bf3d2a48ec722a74dc08de34e82002.mp3", "duration_ms": 6640}, "s1-rank.explanation": {"url": "http://localhost:4006/files/lesson-audio/c5bae2bc2bffd460df6547bffc9da2df5ff3e1630c0758e9488e7df8a149e8d0.mp3", "hash": "0cdcd96d8e993b86e6176666ab140a887fda6e57648edd569088bd263e282144", "bytes": 64656, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/c5bae2bc2bffd460df6547bffc9da2df5ff3e1630c0758e9488e7df8a149e8d0.mp3", "duration_ms": 10720}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('df879f53-8479-4b98-9651-889fcae66fdc', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "repaso-true-false", "title": "Revisão: Verdadeiro ou Falso?", "locale": "pt-BR", "subject": "mixed", "objectives": ["Distinguir entre receita e lucro em uma barraca de limonada", "Lembrar que cada copo custa 2 reais de insumos"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 10, "type": "true_false", "hints": ["Lembre-se que Liruf teve que comprar limões e açúcar para fazer a limonada."], "title": "Verdadeiro ou Falso?", "payload": {"statement_md": "Liruf vendeu 10 copos a 5 reais, então ganhou 50 reais.", "justifications": [{"id": "verdadero", "text_md": "Verdadeiro, porque 10 × 5 = 50 e isso é o que ele recebeu"}, {"id": "falso", "text_md": "Falso, porque ele gastou 20 reais em ingredientes"}]}, "narrator": {"emotion": "happy", "character": "rho"}, "prompt_md": "Liruf vendeu 10 copos a 5 reais cada. Gastou 20 reais em limões e açúcar. Ele ganhou 50 reais?", "difficulty": 1, "explanation_md": "É falso. Liruf recebeu 50 reais pelas vendas, mas gastou 20 reais nos ingredientes. Então o que ele realmente ganhou foi 50 - 20 = 30 reais. Nem tudo que entra é lucro!", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": false, "correct_justification_id": "falso"}}', '{"units": {"s1-true-false.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9f681cc16366eeb734c28b0e981821fa13b4100f5860482b819274d96d024213.mp3", "hash": "e062220f0d8b872bdbe17613a364aa6bc72ef3a5f47eacfdbd8c9bb0c7d8c91d", "bytes": 31536, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/9f681cc16366eeb734c28b0e981821fa13b4100f5860482b819274d96d024213.mp3", "duration_ms": 5200}, "s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/4c70801735c65da55bc642a014ee7ca677e0ad4b44b56fe0d15c75ce60b3907a.mp3", "hash": "46303bc9f31377c59c6a3f7c41131c5942d5818fd1a83074887535061be593aa", "bytes": 55584, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/4c70801735c65da55bc642a014ee7ca677e0ad4b44b56fe0d15c75ce60b3907a.mp3", "duration_ms": 9200}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/c0000bf23abed516f269e75f5a0fc80d3e3a3b5a02ebee28166fcd5df9850f2d.mp3", "hash": "f1c0372983c56a5736c1005d60c8a14b9432c307970cdb8ee7d9c7685faeb758", "bytes": 89136, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/c0000bf23abed516f269e75f5a0fc80d3e3a3b5a02ebee28166fcd5df9850f2d.mp3", "duration_ms": 14800}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1b29b755-c45e-46e4-a8d8-25624cad27a3', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-arrange-largo", "title": "Fechar a barraca: tudo junto", "locale": "pt-BR", "subject": "mixed", "objectives": ["Emparelhar pagamentos com o troco correto", "Ordenar os passos para calcular o lucro", "Separar necessidades da barraca de desejos", "Ordenar eventos do dia para manter troco no caixa"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-pagos", "xp": 15, "type": "match_pairs", "hints": ["O copo custa 5 pesos. Se pagarem com 10, quanto sobra?", "Subtraia o preço do copo da nota ou moeda que derem."], "title": "Troco para cada pagamento", "payload": {"left": [{"id": "pago10", "text_md": "Pagam com 10", "image_url": "http://localhost:4006/files/lesson-images/d7d9f94e2f4a546bcbad9392673669c9bb92f0d3b743403e08780059760f9b16.png"}, {"id": "pago20", "text_md": "Pagam com 20", "image_url": "http://localhost:4006/files/lesson-images/a4a9e5f8cebe6d51d1c4fe94e40dfe2be8ef6a6014476716013f68ac7f4592da.png"}, {"id": "pago6", "text_md": "Pagam com 6", "image_url": "http://localhost:4006/files/lesson-images/86df5904d33b9389b6a9ee1b7fd83c98da390bb503ee52fecd4d444b5d3ba617.png"}], "right": [{"id": "cambio5", "text_md": "Troco: 5"}, {"id": "cambio15", "text_md": "Troco: 15"}, {"id": "cambio1", "text_md": "Troco: 1"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Toque em cada pagamento com o troco que você deve dar.", "difficulty": 2, "explanation_md": "Se pagarem com 10, o troco é 5; com 20, são 15; com 6, só sobra 1 peso.", "audio_segment_id": "s1-match-pagos.prompt"}, {"id": "s2-order-ganancia", "xp": 15, "type": "order_steps", "hints": ["Primeiro, é preciso separar o que custou fazer a limonada.", "Depois de subtrair o custo, o que sobra é o lucro."], "title": "Ordem para calcular o lucro", "payload": {"items": [{"id": "costo", "text_md": "Separar o custo dos limões e copos", "image_url": "http://localhost:4006/files/lesson-images/498008c4466d0909d2a4b9e3da186c5c4072f8d0d094dd3de76753c05406a162.png"}, {"id": "ganancia", "text_md": "Contar o que sobra: o lucro", "image_url": "http://localhost:4006/files/lesson-images/20a024786d30dcbd3e8d6633dcdafc7d8beedfb791276e65d57e9c97d68fd068.png"}, {"id": "vender", "text_md": "Vender limonada e receber dinheiro", "image_url": "http://localhost:4006/files/lesson-images/9735074fefb992250a43283a09e19645f0ce3af8aa8747a02945ff59a11bacb6.png"}], "slots": 3}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Ordene os passos para calcular o lucro do dia.", "difficulty": 2, "explanation_md": "Primeiro separa-se o custo dos limões e copos, depois conta-se o que sobra: esse é o lucro.", "audio_segment_id": "s2-order-ganancia.prompt"}, {"id": "s3-sort-necesidades", "xp": 15, "type": "sort_buckets", "hints": ["Sem limões e copos não se pode vender limonada.", "O gelo e os adesivos são desejos, não urgentes."], "title": "O que a barraca precisa", "payload": {"items": [{"id": "limones", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/7b1de6a5133bdf22c087ef64cbd3c2660180f3a39d361af0cbaa409770cde1d4.png"}, {"id": "vasos", "text_md": "Copos", "image_url": "http://localhost:4006/files/lesson-images/73cda242872711b87783720152c6e2e28f5a8717809a5bcf091eebf94be754c5.png"}, {"id": "hielo", "text_md": "Gelo", "image_url": "http://localhost:4006/files/lesson-images/ea27060a951769dc3ea54fa01b612c50fc253f3b7624bc2c2bd2098f16d87f46.png"}, {"id": "calcomania", "text_md": "Adesivo", "image_url": "http://localhost:4006/files/lesson-images/4d08298036a4a52b908a05212419b141e0815ef5bbcec7b0cb1b67cb7bbc5bf4.png"}], "buckets": [{"id": "necesidad", "label": "Necessidade"}, {"id": "deseo", "label": "Desejo"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Separe o que a barraca PRECISA para abrir do que pode esperar.", "difficulty": 2, "explanation_md": "Limões e copos são necessários para abrir; o gelo e os adesivos podem esperar.", "audio_segment_id": "s3-sort-necesidades.prompt"}, {"id": "s4-timeline-caja", "xp": 25, "type": "timeline_order", "hints": ["Se você precisa dar troco, primeiro deve entrar uma venda.", "Um gasto grande sem venda antes deixa o caixa sem troco."], "title": "Mantenha troco no caixa", "payload": {"events": [{"id": "venta1", "icon": "payments", "text_md": "Vendem 2 copos (10 pesos)", "image_url": "http://localhost:4006/files/lesson-images/86b874a2239f22dbed7b09cdfe4aa3204c2194ce9a7df4ea88a1d71aea06e6b7.png"}, {"id": "gasto", "icon": "shopping_cart", "text_md": "Compram mais copos (8 pesos)", "image_url": "http://localhost:4006/files/lesson-images/e6bcedceb18c6bd956efb4428b2818419d3e0e5a638c5b0f8882065c83b46195.png"}, {"id": "venta2", "icon": "payments", "text_md": "Vendem 1 copo (5 pesos)", "image_url": "http://localhost:4006/files/lesson-images/2f29b015e44fa995fc25bce72995260975876c745b250575400a9b0fdaf85b36.png"}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Ordene os eventos do dia para que o caixa nunca fique sem troco.", "difficulty": 3, "explanation_md": "Primeiro chega uma venda para ter troco, depois se pode gastar em mais copos.", "audio_segment_id": "s4-timeline-caja.prompt"}], "schema_version": 1}', '{"s1-match-pagos": {"pairs": [["pago10", "cambio5"], ["pago20", "cambio15"], ["pago6", "cambio1"]]}, "s4-timeline-caja": {"order": ["venta1", "gasto", "venta2"]}, "s2-order-ganancia": {"order": ["vender", "costo", "ganancia"]}, "s3-sort-necesidades": {"assignments": {"hielo": "deseo", "vasos": "necesidad", "limones": "necesidad", "calcomania": "deseo"}}}', '{"units": {"s1-match-pagos.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9ac65775f09568809d2dbcdd3f6379e38385a3e74c8ab6da0e53fed70d7ec77c.mp3", "hash": "c3c09