bytes": 35856, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/c7429dbaa452bca2e3dc455957b50c36898956b85d907383923b27986880166a.mp3", "duration_ms": 5920}, "s3-sort-necesidades.explanation": {"url": "http://localhost:4006/files/lesson-audio/c2460a99a205d7a6908975591b8b71ca7996540bc65e484b52a238141c4ca45a.mp3", "hash": "5eb184c00e3ad0731388d16d6c325ce2710ef50d4fba303dca9bc5f9c4487b30", "bytes": 40608, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c2460a99a205d7a6908975591b8b71ca7996540bc65e484b52a238141c4ca45a.mp3", "duration_ms": 6720}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('df879f53-8479-4b98-9651-889fcae66fdc', 'en-US', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "repaso-true-false", "title": "Review: True or False?", "locale": "en-US", "subject": "mixed", "objectives": ["Distinguishing between income and profit at a lemonade stand", "Remembering that each glass costs 2 pesos in supplies"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 10, "type": "true_false", "hints": ["Remember that Liruf had to buy lemons and sugar to make the lemonade."], "title": "True or False?", "payload": {"statement_md": "Liruf sold 10 glasses at 5 pesos, so he earned 50 pesos.", "justifications": [{"id": "verdadero", "text_md": "True, because 10 × 5 = 50 and that''s what he received"}, {"id": "falso", "text_md": "False, because he spent 20 pesos on ingredients"}]}, "narrator": {"emotion": "happy", "character": "rho"}, "prompt_md": "Liruf sold 10 glasses at 5 pesos each. He spent 20 pesos on lemons and sugar. Did he earn 50 pesos?", "difficulty": 1, "explanation_md": "It is false. Liruf received 50 pesos from sales, but he spent 20 pesos on ingredients. So what he actually earned was 50 - 20 = 30 pesos. Not everything that comes in is profit!", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": false, "correct_justification_id": "falso"}}', '{"units": {"s1-true-false.hint.0": {"url": "http://localhost:4006/files/lesson-audio/387c05402e58dcd20c6fb8f57c9a7f69a6236822201bdfb2c513ccd7f827411a.mp3", "hash": "a98c629c4552748853b4407bd2ccbbed4f47a875960865a52d663499f0c889f4", "bytes": 28224, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/387c05402e58dcd20c6fb8f57c9a7f69a6236822201bdfb2c513ccd7f827411a.mp3", "duration_ms": 4640}, "s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/deaeface4dc8b8cdf34d3e8f6c376d001e29118a0cddc1970794c18694961a76.mp3", "hash": "2a023aa0edf490ea955d31d04828bca12fb07dba64dfe1f3553d076fc2b18e01", "bytes": 56016, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/deaeface4dc8b8cdf34d3e8f6c376d001e29118a0cddc1970794c18694961a76.mp3", "duration_ms": 9280}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/de9714d3fb27ae0e3dd0d198387d1fdf8a122fdca693cd3137c919e2e2955dbb.mp3", "hash": "5b515968f7bf49c28ae622baaae909de8498906f756556266dfcf2d5f064b147", "bytes": 94896, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/de9714d3fb27ae0e3dd0d198387d1fdf8a122fdca693cd3137c919e2e2955dbb.mp3", "duration_ms": 15760}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('e0e06311-1e57-4b7b-a3ee-04c82227ceae', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fair-trade", "title": "Troca justa", "locale": "pt-BR", "subject": "money", "objectives": ["Decidir se uma troca é justa comparando o valor de duas ofertas"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fair-trade", "xp": 15, "type": "fair_trade", "hints": ["Cada copo custa 5 reais. Quanto valem os 2 copos juntos?", "O saco de limões custa 10 reais. Compare esse número com o valor dos 2 copos."], "title": "Troca justa", "payload": {"offer_a": {"qty": 2, "icon": "local_drink", "label": "Copo de limonada", "image_url": "http://localhost:4006/files/lesson-images/4a6e47c3ac7fcff0b58473a0e108a1f4ce545bb716f20c5c1c5e38a95aa7ed7e.png"}, "offer_b": {"qty": 1, "icon": "agriculture", "label": "Saco de limões", "image_url": "http://localhost:4006/files/lesson-images/dead24c05a379f6ab5afe90391cc7754007cdf9164ce7c153b9b191d414127fc.png"}, "rate_md": "Cada copo custa 5 reais. O saco de limões custa 10 reais."}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "É justo trocar 2 copos de limonada por um saco de limões?", "difficulty": 2, "explanation_md": "2 copos valem 10 reais (5+5) e o saco de limões também vale 10 reais. É uma troca justa!", "audio_segment_id": "s1-fair-trade.prompt"}], "schema_version": 1}', '{"s1-fair-trade": {"verdict": "fair"}}', '{"units": {"s1-fair-trade.hint.0": {"url": "http://localhost:4006/files/lesson-audio/43fd4d51401fe0f9f358cbc839db9abf49ed75b4347d758d6eca3c1678e88a17.mp3", "hash": "ec8dcb05894539c64495e64a3a52daddf56fcc5a153af7e8be6043567300b355", "bytes": 32544, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/43fd4d51401fe0f9f358cbc839db9abf49ed75b4347d758d6eca3c1678e88a17.mp3", "duration_ms": 5360}, "s1-fair-trade.hint.1": {"url": "http://localhost:4006/files/lesson-audio/e9735f67fa5bdee88c23157dc9a7e8a434b5dd8ec29dee30394d4b05af79e9cf.mp3", "hash": "ca20e96c6a2dc4564e29bba647d22a4d2bca18ea2a3c35fab9e06a988fd0a32d", "bytes": 36288, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/e9735f67fa5bdee88c23157dc9a7e8a434b5dd8ec29dee30394d4b05af79e9cf.mp3", "duration_ms": 6000}, "s1-fair-trade.prompt": {"url": "http://localhost:4006/files/lesson-audio/2346e8d27c3ce01fb2265f40b7c83b3e806b66b5e37dc5f37d22f6fbc611d2f7.mp3", "hash": "c5476ba5f7794bab37320e481029e9a7b2367b126ab7c9289ff0a9f2799b5f82", "bytes": 24336, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/2346e8d27c3ce01fb2265f40b7c83b3e806b66b5e37dc5f37d22f6fbc611d2f7.mp3", "duration_ms": 4000}, "s1-fair-trade.explanation": {"url": "http://localhost:4006/files/lesson-audio/fcb7c6c0f65142821cce3e0e4316c44ef77511ffa1b2898b98f8fe0f3c6f8312.mp3", "hash": "5f1f730111efc83e52fdad729d1ea5195a3d0cbf5c0e867b8ec4de243b0d3e42", "bytes": 50688, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/fcb7c6c0f65142821cce3e0e4316c44ef77511ffa1b2898b98f8fe0f3c6f8312.mp3", "duration_ms": 8400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('b831d60b-c492-4356-824e-7fce5f662a0a', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "match-pairs", "title": "Empareja los precios", "locale": "es-MX", "subject": "mixed", "objectives": ["Emparejar cada producto del puesto con su precio correcto (vaso chico–5, jarra–20, galleta–3)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-prices", "xp": 10, "type": "match_pairs", "hints": ["El vaso chico cuesta 5 pesos, la jarra cuesta 20 y la galleta cuesta 3."], "title": "Empareja los precios", "payload": {"left": [{"id": "vaso", "text_md": "Vaso chico", "image_url": "http://localhost:4006/files/lesson-images/d4c7ee98ae63c32e74eeeb0873ddbd87b132b7bcb62fd657a6b191bed6adfbc7.png"}, {"id": "jarra", "text_md": "Jarra", "image_url": "http://localhost:4006/files/lesson-images/c8111c5a87e84fe907d9d45a73d9572a6f386f99dfc5ce14a3f6cbe6523f331b.png"}, {"id": "galleta", "text_md": "Galleta", "image_url": "http://localhost:4006/files/lesson-images/d85a309c4d5db7803474ede0b1bcc86616f89ed1a2ddb15ce0964b4507e6e545.png"}], "right": [{"id": "precio5", "text_md": "5 pesos"}, {"id": "precio20", "text_md": "20 pesos"}, {"id": "precio3", "text_md": "3 pesos"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Dina vendió 3 vasos a 5 pesos cada uno ayer. Hoy Liruf pone los precios. Une cada producto con su precio.", "difficulty": 1, "explanation_md": "El vaso chico cuesta 5 pesos porque es pequeño. La jarra cuesta 20 pesos porque es más grande y tiene más limonada. La galleta cuesta 3 pesos porque es un postre barato. ¡Así Liruf puede cobrar bien y comprar más limones!", "audio_segment_id": "s1-match-prices.prompt"}], "schema_version": 1}', '{"s1-match-prices": {"pairs": [["vaso", "precio5"], ["jarra", "precio20"], ["galleta", "precio3"]]}}', '{"units": {"s1-match-prices.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6f2742cd755c9c29cf2dea0564310857795ec5a878db20334709c8fcc298e0fa.mp3", "hash": "c289ce46eeb2bc8aad718d2c0a30975a3a50d7e12334114d466cf36bac299334", "bytes": 35424, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/6f2742cd755c9c29cf2dea0564310857795ec5a878db20334709c8fcc298e0fa.mp3", "duration_ms": 5840}, "s1-match-prices.prompt": {"url": "http://localhost:4006/files/lesson-audio/4eebbd5e1c19a9a6db4797802ae38fcd0657463d49c631024cc2b6b0f0a98983.mp3", "hash": "9ca5671e792cdf004ded12e415ec5416bf82801ae4158965059907715fe45e23", "bytes": 50256, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4eebbd5e1c19a9a6db4797802ae38fcd0657463d49c631024cc2b6b0f0a98983.mp3", "duration_ms": 8320}, "s1-match-prices.explanation": {"url": "http://localhost:4006/files/lesson-audio/c1ec754c6f1bfbaf180680341f399926ecb58f85b3a0ab267bb2035e997409a9.mp3", "hash": "06f81f12b134110109ada10967396c3bd28138895ecb30281f37f0a5f0844f3a", "bytes": 90576, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c1ec754c6f1bfbaf180680341f399926ecb58f85b3a0ab267bb2035e997409a9.mp3", "duration_ms": 15040}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7d51bf02-4dd4-4263-9e53-aa5ccb8a1e03', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "interest-peek", "title": "The piggy bank that rewards patience", "locale": "en-US", "subject": "money", "objectives": ["Deciding whether leaving money in a piggy bank that gives extra coins each week is better than spending it now.", "Predicting the total after waiting, understanding that it grows a little but doesn''t double."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-interest-peek", "xp": 10, "type": "interest_peek", "hints": ["Each week the piggy bank gives 2 coins of 1 peso. How many extra coins does it give in 2 weeks?", "Start with 20. Add the extra coins."], "title": "Leave the 20 or take them out now?", "payload": {"periods": 2, "currency": "MXN", "rate_pct": 10, "principal": 20, "prediction": {"kind": "choice", "options": [{"id": "opt1", "text_md": "Stays at 20"}, {"id": "opt2", "text_md": "24 pesos"}, {"id": "opt3", "text_md": "Almost 40 pesos"}]}}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf has 20 pesos saved for a guitar that costs 80. Rho tells him: ''If you keep your money in this special piggy bank, it gives you 2 extra 1-peso coins each week for leaving it there.'' Liruf puts in his 20 pesos. He thinks: ''If I wait 2 weeks, will I have more or less than if I spend everything now?'' How much will Liruf have after 2 weeks?", "difficulty": 1, "explanation_md": "The piggy bank gives 2 coins of 1 peso each week, so in 2 weeks it gives 4 extra pesos. 20 + 4 = 24. The money grows little by little toward the guitar! If he had spent everything now, he wouldn''t have those 4 extra pesos.", "audio_segment_id": "s1-interest-peek.prompt"}], "schema_version": 1}', '{"s1-interest-peek": {"value": 24, "tolerance": 1, "correct_option_id": "opt2"}}', '{"units": {"s1-interest-peek.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4a5700d8d7b93dd2db63d59f3749fcbcf6a67b294b3e1c8b6b4b676ba6e8c866.mp3", "hash": "e3ea14dc8606d826d144eb6363d4368856117ed4d8f67dadc689bfe55e4c73ae", "bytes": 35424, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4a5700d8d7b93dd2db63d59f3749fcbcf6a67b294b3e1c8b6b4b676ba6e8c866.mp3", "duration_ms": 5840}, "s1-interest-peek.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a82f3ebf19baf7e9138309a130b71f757267c05925caf540b44c44cfbea0dfb0.mp3", "hash": "f8bc08ef72f497b9b77b2307f928554ffa4b3b6cc12fc571460ffce20f85865a", "bytes": 14688, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/a82f3ebf19baf7e9138309a130b71f757267c05925caf540b44c44cfbea0dfb0.mp3", "duration_ms": 2400}, "s1-interest-peek.prompt": {"url": "http://localhost:4006/files/lesson-audio/b49a04c24d33234aaeaaf63490164a18df1ed618b6c733bd37179b830457b80d.mp3", "hash": "06bcab7bd0bd3055f199a09c2880c35f064564fca791d36fd206176edd6790db", "bytes": 111744, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/b49a04c24d33234aaeaaf63490164a18df1ed618b6c733bd37179b830457b80d.mp3", "duration_ms": 18560}, "s1-interest-peek.explanation": {"url": "http://localhost:4006/files/lesson-audio/179506ab0a47a00b58d140453e8731475a2c2f74df181290002d2c3b1fd26cd9.mp3", "hash": "a23efb9b593ec86ce6a5983bd0d2b921db12b5e029c2f53aeed641521e81bdb1", "bytes": 83376, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/179506ab0a47a00b58d140453e8731475a2c2f74df181290002d2c3b1fd26cd9.mp3", "duration_ms": 13840}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c9d7856b-a75e-414e-ae61-e324a19a350d', 'en-US', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "measure-read", "title": "Measuring the Fair Lemonade", "locale": "en-US", "subject": "mixed", "objectives": ["Read the liquid line in a measuring pitcher to serve even 5-peso cups."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-leer-jarra", "xp": 10, "type": "measure_read", "hints": ["Look at the blue liquid line. Is it at the 200, 250, or 300 ml mark?"], "title": "How far did it reach?", "payload": {"max": 300, "min": 0, "unit": "ml", "ticks": 3, "instrument": "beaker", "pointer_value": 250}, "narrator": {"emotion": "neutral", "character": "rho"}, "image_url": "http://localhost:4006/files/lesson-images/9b9261a6db9cfccca11cfadb2ac5d6af3dbd07104461eb1dd2b9ff5007cb9eca.png", "prompt_md": "Rho poured lemonade. Which line did the liquid reach?", "difficulty": 1, "explanation_md": "The liquid reached the 250 ml line. That way all 5-peso cups are equal, like on the barter scale.", "audio_segment_id": "s1-leer-jarra.prompt"}], "schema_version": 1}', '{"s1-leer-jarra": {"value": 250, "tolerance": 0}}', '{"units": {"s1-leer-jarra.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0c648745cd57f49f90bae96a0c695ea8cdd44e4271f7d2fdb4e7897b24e02b57.mp3", "hash": "c438ca09ca0d805ba4c6a625798e6e063d0af4d56246e682fdfa9e6c4f802ae5", "bytes": 51264, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/0c648745cd57f49f90bae96a0c695ea8cdd44e4271f7d2fdb4e7897b24e02b57.mp3", "duration_ms": 8480}, "s1-leer-jarra.prompt": {"url": "http://localhost:4006/files/lesson-audio/b752b930570c2c5a29040d8b6c10b89ab0ebff2358cb7269c0cbf5718fd80122.mp3", "hash": "f611d6d77e7108058eaf0a09993acf185f15153e56434733975f83bb302d8768", "bytes": 24336, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/b752b930570c2c5a29040d8b6c10b89ab0ebff2358cb7269c0cbf5718fd80122.mp3", "duration_ms": 4000}, "s1-leer-jarra.explanation": {"url": "http://localhost:4006/files/lesson-audio/d517300443ff0bd97bf2922b6764599ee9b05cff67f7c7270fe22fd6960e8e84.mp3", "hash": "4ddc8f6b3373324157868ea84bfbb40170c59701e8b671c99fa3d0dddb8f5678", "bytes": 52128, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/d517300443ff0bd97bf2922b6764599ee9b05cff67f7c7270fe22fd6960e8e84.mp3", "duration_ms": 8640}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08604886-c155-4f4b-85dd-0b5b853997e1', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "quiz-mcq", "title": "Preço justo para a limonada", "locale": "pt-BR", "subject": "money", "objectives": ["Escolher o preço justo para um copo de limonada comparando opções."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-justo", "xp": 10, "type": "quiz_mcq", "hints": ["Pense: se custar muito, ninguém compra; se custar pouco, Liruf perde dinheiro.", "Um copo custa 5 pesos para fazer. Qual preço dá lucro sem espantar clientes?"], "title": "Quanto custa o copo?", "payload": {"options": [{"id": "op1", "text_md": "50 pesos", "rationale_md": "50 pesos é muito caro para um copo de limonada. Os clientes iriam para outra barraca."}, {"id": "op2", "text_md": "5 pesos"}, {"id": "op3", "text_md": "1 peso", "rationale_md": "1 peso não dá nem para comprar os limões. Liruf perderia dinheiro em cada copo."}], "shuffle": true}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf define o preço do copo de limonada. Qual é justo?", "difficulty": 1, "explanation_md": "5 pesos é justo: cobre o custo de 5 pesos e as pessoas compram. 50 pesos é caro demais; 1 peso não cobre nem os limões.", "audio_segment_id": "s1-precio-justo.prompt"}], "schema_version": 1}', '{"s1-precio-justo": {"correct_option_id": "op2"}}', '{"units": {"s1-precio-justo.hint.0": {"url": "http://localhost:4006/files/lesson-audio/020a3ef469602192e6871b38f0c3c14218c616ba3d782c6549cd46312ccd49e7.mp3", "hash": "5b638a8b5fcb0ba402d9575421cfe40a85d1adc1bfcfda6f5e27f1b534ea3fc8", "bytes": 39744, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/020a3ef469602192e6871b38f0c3c14218c616ba3d782c6549cd46312ccd49e7.mp3", "duration_ms": 6560}, "s1-precio-justo.hint.1": {"url": "http://localhost:4006/files/lesson-audio/73ffadba03aaff161910c310cdd06d94f9dcdf951c9ce441c0e9882792e491f4.mp3", "hash": "1016d6ee380155231a8934634a891299dc1fcf984017bd19a03084697358fa7f", "bytes": 40176, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/73ffadba03aaff161910c310cdd06d94f9dcdf951c9ce441c0e9882792e491f4.mp3", "duration_ms": 6640}, "s1-precio-justo.prompt": {"url": "http://localhost:4006/files/lesson-audio/32f116093191189d3ac8d7bbd33d5457f1ea1105e54b519dd72bfd5d6440c610.mp3", "hash": "ac8b5d27b3578eb51561406e8aa494597f6a4107c0bd990199989b3842591040", "bytes": 26784, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/32f116093191189d3ac8d7bbd33d5457f1ea1105e54b519dd72bfd5d6440c610.mp3", "duration_ms": 4400}, "s1-precio-justo.choices": {"url": "http://localhost:4006/files/lesson-audio/de6eb34fa9fa7fe2a0734416f6923cf6fa321eca01d2d3461868c61cb8bccb44.mp3", "hash": "3057e8dcf094da77380a09ad9e08ab54a08b6c8f5ae41f485188fe10efb9ee3e", "bytes": 22896, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/de6eb34fa9fa7fe2a0734416f6923cf6fa321eca01d2d3461868c61cb8bccb44.mp3", "duration_ms": 3760}, "s1-precio-justo.explanation": {"url": "http://localhost:4006/files/lesson-audio/6443ccfefb901fbd08799101ae1d5638e1129d877e8dcab45ec8a3b8c4214f2b.mp3", "hash": "841bbc97e92f5850872f7594bc30eb1d7c71aeaf5a676021229875502089cae8", "bytes": 69984, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/6443ccfefb901fbd08799101ae1d5638e1129d877e8dcab45ec8a3b8c4214f2b.mp3", "duration_ms": 11600}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7d51bf02-4dd4-4263-9e53-aa5ccb8a1e03', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "interest-peek", "title": "O cofrinho que agradece a paciência", "locale": "pt-BR", "subject": "money", "objectives": ["Decidir se deixar dinheiro em um cofrinho que dá moedinhas extras toda semana vale mais do que gastá-lo agora.", "Prever o total depois de esperar, entendendo que cresce um pouco, mas não dobra."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-interest-peek", "xp": 10, "type": "interest_peek", "hints": ["Cada semana o cofrinho dá 2 moedas de 1 real. Quantas moedas extras ele dá em 2 semanas?", "Começa com 20. Soma as moedinhas extras."], "title": "Deixar os 20 ou tirá-los agora?", "payload": {"periods": 2, "currency": "MXN", "rate_pct": 10, "principal": 20, "prediction": {"kind": "choice", "options": [{"id": "opt1", "text_md": "Fica em 20"}, {"id": "opt2", "text_md": "24 reais"}, {"id": "opt3", "text_md": "Quase 40 reais"}]}}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf tem 20 reais guardados para um violão que custa 80. Rho diz: ''Se você guardar seu dinheiro neste cofrinho especial, toda semana ele te dá 2 moedas de 1 real extra por deixá-lo lá.'' Liruf coloca seus 20 reais. Ele pensa: ''Se eu esperar 2 semanas, terei mais ou menos do que se gastar tudo agora?'' Quanto Liruf terá depois de 2 semanas?", "difficulty": 1, "explanation_md": "O cofrinho dá 2 moedas de 1 real por semana, então em 2 semanas dá 4 reais extras. 20 + 4 = 24. O dinheiro cresce pouquinho a pouquinho em direção ao violão! Se tivesse gasto tudo agora, não teria esses 4 reais extras.", "audio_segment_id": "s1-interest-peek.prompt"}], "schema_version": 1}', '{"s1-interest-peek": {"value": 24, "tolerance": 1, "correct_option_id": "opt2"}}', '{"units": {"s1-interest-peek.hint.0": {"url": "http://localhost:4006/files/lesson-audio/15c8d42a81e76e915fe3887eff8a429983acd363dc96705d1e4ec0e628271e2c.mp3", "hash": "196538f34b2819eb47de5903748f77e7b49d10d4e2c8ca5d7ae70a964f276120", "bytes": 41184, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/15c8d42a81e76e915fe3887eff8a429983acd363dc96705d1e4ec0e628271e2c.mp3", "duration_ms": 6800}, "s1-interest-peek.hint.1": {"url": "http://localhost:4006/files/lesson-audio/94246887ec011f654238fff79533392c4fa267c9a6a7176754cf81c2c0fba8f2.mp3", "hash": "68205f29a78766e858fb87c5bed3698e0edd3e76f3e3815689d9c9fdf3bf0983", "bytes": 21024, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/94246887ec011f654238fff79533392c4fa267c9a6a7176754cf81c2c0fba8f2.mp3", "duration_ms": 3440}, "s1-interest-peek.prompt": {"url": "http://localhost:4006/files/lesson-audio/8d2446827b5dfe079ef7c4af2f81ab70d70f224adcc231c88e5428650ba17a0e.mp3", "hash": "a49d13c1d700898ab76f3de6d66edef95a7a3fc75e1a1d6b73c925bba2331ffd", "bytes": 152064, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/8d2446827b5dfe079ef7c4af2f81ab70d70f224adcc231c88e5428650ba17a0e.mp3", "duration_ms": 25280}, "s1-interest-peek.explanation": {"url": "http://localhost:4006/files/lesson-audio/502978ab8beb65b2716a40ddd32d3108471507f848c1584c75807ed5a8039f28.mp3", "hash": "10d7c733f96ddee36b970195711bac0efc7e1d2b84b73366148a2065d5f44a1a", "bytes": 110736, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/502978ab8beb65b2716a40ddd32d3108471507f848c1584c75807ed5a8039f28.mp3", "duration_ms": 18400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5bcbf28d-86a2-47d1-9003-23897d9d4f57', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "group-sets", "title": "Ordena el dinero de la caja", "locale": "es-MX", "subject": "mixed", "objectives": ["Agrupar monedas con monedas y billetes con billetes para contar más fácil."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-group-money", "xp": 10, "type": "group_sets", "hints": ["Las monedas son redondas y de metal; los billetes son de papel y rectangulares.", "Busca el grupo que dice ''Monedas'' para las monedas, y ''Billetes'' para los billetes."], "title": "Separa el dinero", "payload": {"items": [{"id": "coin1", "text_md": "Moneda de $1", "image_url": "http://localhost:4006/files/lesson-images/e49eed35aebb19ff667668c36fe9eaaf6e0b83a5f66480d5dd57bb8e31f5f01a.png"}, {"id": "coin2", "text_md": "Moneda de $2", "image_url": "http://localhost:4006/files/lesson-images/6f2f05ff974b29602c7ee70ece56c22ec8dde6619a54596a3ead7694c13ed1b7.png"}, {"id": "coin3", "text_md": "Moneda de $5", "image_url": "http://localhost:4006/files/lesson-images/f2f73a0b07390d4c5a17591cde54a72091170e947a279e822d648b6439ae4ed4.png"}, {"id": "bill1", "text_md": "Billete de $20", "image_url": "http://localhost:4006/files/lesson-images/227f9e5d9d3279c9db4c3a6851aad746ff231b2a1897cef163ae56a3fa39c1ff.png"}, {"id": "bill2", "text_md": "Billete de $50", "image_url": "http://localhost:4006/files/lesson-images/3bd31e575ce1877dee34bc2de5c4dd38fd73913c3b9321b5d5ac360f5a64d5ac.png"}], "set_a": "Monedas", "set_b": "Billetes"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Toca cada moneda y cada billete para ponerlos en su grupo.", "difficulty": 1, "explanation_md": "Liruf separó 3 monedas y 2 billetes. Así es más fácil contar cuánto dinero hay.", "audio_segment_id": "s1-group-money.prompt"}], "schema_version": 1}', '{"s1-group-money": {"zones": {"bill1": "b", "bill2": "b", "coin1": "a", "coin2": "a", "coin3": "a"}}}', '{"units": {"s1-group-money.hint.0": {"url": "http://localhost:4006/files/lesson-audio/10467ef01b9695d9574a4ba05563293031da538774ca68e7d991b0edb06590cf.mp3", "hash": "9e228164b8e8f6ca6ddcc72aa073088ebbfdfba8ccb666240254708f956a6f56", "bytes": 33408, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/10467ef01b9695d9574a4ba05563293031da538774ca68e7d991b0edb06590cf.mp3", "duration_ms": 5520}, "s1-group-money.hint.1": {"url": "http://localhost:4006/files/lesson-audio/0de562b9a3750cf660d2ecffc563734e60fbeae8f27e153826a733b4ee89a3d4.mp3", "hash": "894749493407f9e85fef205485a02f572e82246c9c3c8f6f7cf2c980e5aa0da1", "bytes": 33984, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/0de562b9a3750cf660d2ecffc563734e60fbeae8f27e153826a733b4ee89a3d4.mp3", "duration_ms": 5600}, "s1-group-money.prompt": {"url": "http://localhost:4006/files/lesson-audio/1f1ce846eb5ac2c56ec627f8a7daa4de99db1e797cb3f6dba4d9dd59a03accb6.mp3", "hash": "efef0d6ed27bd321941b95720f511dbc7b287ea03bed881ca80fd97d8a6c72e1", "bytes": 24336, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1f1ce846eb5ac2c56ec627f8a7daa4de99db1e797cb3f6dba4d9dd59a03accb6.mp3", "duration_ms": 4000}, "s1-group-money.explanation": {"url": "http://localhost:4006/files/lesson-audio/6dc4a41a40cf203a6918c674b69e95b70517c76e2d77894184b9259f784d71dd.mp3", "hash": "bf70bc891659e803c4e4de3ac7eb48a439b3875aa146c1e633f2e095f05a2335", "bytes": 37728, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/6dc4a41a40cf203a6918c674b69e95b70517c76e2d77894184b9259f784d71dd.mp3", "duration_ms": 6240}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08f47096-e44f-4b4e-822f-472c6fd87425', 'en-US', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "speed-tap", "title": "Quick! Help or treat?", "locale": "en-US", "subject": "money", "objectives": ["Distinguish expenses that help the lemonade stand from treats that don''t help.", "Make quick decisions under time pressure."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-speed-tap", "xp": 15, "type": "speed_tap", "hints": ["Think: does this help make or sell lemonade?", "Treats don''t help the stand, they just spend money."], "title": "Catch what helps", "payload": {"items": [{"id": "limones", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/7e89efd945b0cda33dd1f6cac1095b0dea7820a1be323e684c003becaef35074.png"}, {"id": "vasos", "text_md": "Cups", "image_url": "http://localhost:4006/files/lesson-images/bae57d6a5b104493ad2a8b4443b2332d4eb74ad05735fcecf28cac80fc0ae45b.png"}, {"id": "azucar", "text_md": "Sugar", "image_url": "http://localhost:4006/files/lesson-images/e8fa96e4c35a9acb6675841f3f95bc646e48dab4b3e93ab1e736f52874c09d3a.png"}, {"id": "hielo", "text_md": "Ice", "image_url": "http://localhost:4006/files/lesson-images/21778d6d6f69fc8c4de0d0d9705fedf2139f8498c4dfeb90d871955afb2ff7d6.png"}, {"id": "cartel", "text_md": "Eye-catching sign", "image_url": "http://localhost:4006/files/lesson-images/0f2bd71a456d4602e479948a4ba9c23d52f1d36f27871909e3b720811646e430.png"}, {"id": "calcomania", "text_md": "Dinosaur sticker", "image_url": "http://localhost:4006/files/lesson-images/e726bb40b0eb0ea09ec2776806dc1fce4c1575cb26bb29bcddea3805b291d587.png"}, {"id": "dulce", "text_md": "Candy", "image_url": "http://localhost:4006/files/lesson-images/4132ffca2352693df8022cdfd9383885ae0353cf31eae1c0060e8eb3177bbc52.png"}, {"id": "juguete", "text_md": "Toy", "image_url": "http://localhost:4006/files/lesson-images/f53bf066dca65ac3cc3132afe0e97db24f8c19a0edd051f522fd753426993a8c.png"}], "seconds": 15, "instruction_md": "Tap the cards that help the lemonade stand. Quick!"}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Remember to decide if an expense helps the stand? Tap only what helps sell more lemonade.", "difficulty": 2, "explanation_md": "Lemons, cups, sugar, ice, and the sign help sell more lemonade. The dinosaur sticker, candy, and toy are treats that don''t help the stand.", "audio_segment_id": "s1-speed-tap.prompt"}], "schema_version": 1}', '{"s1-speed-tap": {"target_ids": ["limones", "vasos", "azucar", "hielo", "cartel"]}}', '{"units": {"s1-speed-tap.hint.0": {"url": "http://localhost:4006/files/lesson-audio/01da8c9c65a85aced5437d920188ead7c922e74d6c245dfa037bcbdbad91e3a4.mp3", "hash": "7b5cd823d44c18768fd6c6eee908f50ddc0ac55be238d6b0df47cab8eab4d2a7", "bytes": 22464, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/01da8c9c65a85aced5437d920188ead7c922e74d6c245dfa037bcbdbad91e3a4.mp3", "duration_ms": 3680}, "s1-speed-tap.hint.1": {"url": "http://localhost:4006/files/lesson-audio/feb6e86a63f9568a88601cdf45dfe6dd8d51a6a9739f8e1735815b156930a7bc.mp3", "hash": "a5df6ec0a8696749245bb59af5d274e6a84ef71844ca8d889c6ebf843842fc66", "bytes": 23904, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/feb6e86a63f9568a88601cdf45dfe6dd8d51a6a9739f8e1735815b156930a7bc.mp3", "duration_ms": 3920}, "s1-speed-tap.prompt": {"url": "http://localhost:4006/files/lesson-audio/be143c00ad3dd63152149ec91866517756415f2dd5d5a3b9f1d40ec23330fd1d.mp3", "hash": "58855c7ecb9f4bc2c97e7fefc2b53c09fac1587b59895ccd9cd4f3a1201e41d9", "bytes": 42624, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/be143c00ad3dd63152149ec91866517756415f2dd5d5a3b9f1d40ec23330fd1d.mp3", "duration_ms": 7040}, "s1-speed-tap.explanation": {"url": "http://localhost:4006/files/lesson-audio/34bdc569938f36079c4017db560925696ff20023bdee58bd8dce06122dccd9a2.mp3", "hash": "39925f0d871e1cc48c0ebdd93806c32402830220d4c5b29fba1fb68dbd9d9b9e", "bytes": 68976, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/34bdc569938f36079c4017db560925696ff20023bdee58bd8dce06122dccd9a2.mp3", "duration_ms": 11440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4785eb58-e0ca-4b5c-a796-a6f01b2ab3ae', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "pattern-complete", "title": "Price ladder", "locale": "en-US", "subject": "money", "objectives": ["Order steps, match products with prices, and sort purchases between needs for the job and wants that can wait."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-escalera", "xp": 15, "type": "pattern_complete", "hints": ["Notice how the price goes up: small $5, medium $10, large $15, then it starts over. Which size comes after medium?", "The ladder always goes up in price: small → medium → large → small → medium → ? The next one must be the most expensive."], "title": "Price ladder", "payload": {"options": [{"id": "grande", "icon": "local_cafe", "tint": "success"}, {"id": "chico", "icon": "local_cafe", "tint": "primary"}, {"id": "limon", "icon": "nutrition", "tint": "delight"}], "sequence": [{"icon": "local_cafe", "tint": "primary"}, {"icon": "local_cafe", "tint": "accent"}, {"icon": "local_cafe", "tint": "success"}, {"icon": "local_cafe", "tint": "primary"}, {"icon": "local_cafe", "tint": "accent"}, {"icon": "local_cafe", "tint": "warning"}], "missing_slots": 1}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Tap the cup that completes the ladder: small $5, medium $10, large $15, small $5, medium $10, ?", "difficulty": 2, "explanation_md": "After the medium at $10 comes the large at $15, because the ladder goes up in price: small ($5), medium ($10), large ($15) and then starts over.", "audio_segment_id": "s1-escalera.prompt"}], "schema_version": 1}', '{"s1-escalera": {"correct": {"5": "grande"}}}', '{"units": {"s1-escalera.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4041ec8cb00439a2cb8f8281334324e9065d7f1eefd4b954bc6bfb302b785035.mp3", "hash": "465af43337a06b483d4d3c90077dd06bd66b2373f5528bc1b6caa39b19e4dc4f", "bytes": 58896, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/4041ec8cb00439a2cb8f8281334324e9065d7f1eefd4b954bc6bfb302b785035.mp3", "duration_ms": 9760}, "s1-escalera.hint.1": {"url": "http://localhost:4006/files/lesson-audio/83ce466304b0bbe8dc90a0e9d6595f1bd903bd34473ec218c4a8994f88249138.mp3", "hash": "029475b9ed0c0bb77c51029271a237e34528b7531375f3e1378e358e9f786478", "bytes": 54144, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/83ce466304b0bbe8dc90a0e9d6595f1bd903bd34473ec218c4a8994f88249138.mp3", "duration_ms": 8960}, "s1-escalera.prompt": {"url": "http://localhost:4006/files/lesson-audio/8d0c34891e7e6b7f8de0eb5df6a46db2857017f4b6a553aa1dca8545d948726b.mp3", "hash": "5f1216289e024c990af1b4b3320512e525329ec7a437db294745250b8459b93a", "bytes": 58464, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/8d0c34891e7e6b7f8de0eb5df6a46db2857017f4b6a553aa1dca8545d948726b.mp3", "duration_ms": 9680}, "s1-escalera.explanation": {"url": "http://localhost:4006/files/lesson-audio/91948f44c307573f438037323994337b2794f2f0268a80256f0bb1d6d283e83d.mp3", "hash": "91c4c7037d3d5b2c9c59c3e1abd4b731f26d95608cd2f72a3cc73b30240ba85b", "bytes": 73728, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/91948f44c307573f438037323994337b2794f2f0268a80256f0bb1d6d283e83d.mp3", "duration_ms": 12240}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08f47096-e44f-4b4e-822f-472c6fd87425', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "speed-tap", "title": "Rápido! Ajuda ou capricho?", "locale": "pt-BR", "subject": "money", "objectives": ["Distinguir gastos que ajudam a barraca de limonada de caprichos que não ajudam.", "Tomar decisões rápidas sob pressão de tempo."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-speed-tap", "xp": 15, "type": "speed_tap", "hints": ["Pense: isso ajuda a fazer ou vender limonada?", "Caprichos não ajudam a barraca, só gastam dinheiro."], "title": "Pegue o que ajuda", "payload": {"items": [{"id": "limones", "text_md": "Limões", "image_url": "http://localhost:4006/files/lesson-images/fd2ff9c91947bde98525ac322881fcd4c7ff289432d6e69751ccad3377fe0ee4.png"}, {"id": "vasos", "text_md": "Copos", "image_url": "http://localhost:4006/files/lesson-images/b48a14cf7db07a6a90dd683ad50ea82f91c29fda36c2b650881bad8de03c5d09.png"}, {"id": "azucar", "text_md": "Açúcar", "image_url": "http://localhost:4006/files/lesson-images/2262fc42e28e0f1d3527b480fef8b8261cce4d06d20ddca4a884c931d7d053a6.png"}, {"id": "hielo", "text_md": "Gelo", "image_url": "http://localhost:4006/files/lesson-images/50ad530c8dcb47e72be9c9180275b1cb38df715276b4dde528c8fe3594928c1a.png"}, {"id": "cartel", "text_md": "Placa chamativa", "image_url": "http://localhost:4006/files/lesson-images/89126612489b7e0fbc06974d8d97c03411f8312aeef749ce067c3f462a061835.png"}, {"id": "calcomania", "text_md": "Adesivo de dinossauro", "image_url": "http://localhost:4006/files/lesson-images/a706c5fa90c3bdf409f46bd7732ab841a5b6d6cb27ef75429eb1e3b9af30d078.png"}, {"id": "dulce", "text_md": "Doce", "image_url": "http://localhost:4006/files/lesson-images/4b322ffa476aafdb22197313ea4324876fb6578ba264388f2a87fc510f182f88.png"}, {"id": "juguete", "text_md": "Brinquedo", "image_url": "http://localhost:4006/files/lesson-images/4f96db303bf8b8c1a9e6aedbc73da7c63a26af9ac9a3690bfd23b10d89555f26.png"}], "seconds": 15, "instruction_md": "Toque nos cartões que ajudam a barraca de limonada. Rápido!"}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Você lembra de decidir se um gasto ajuda a barraca? Toque apenas no que ajuda a vender mais limonada.", "difficulty": 2, "explanation_md": "Limões, copos, açúcar, gelo e a placa ajudam a vender mais limonada. O adesivo, o doce e o brinquedo são caprichos que não ajudam a barraca.", "audio_segment_id": "s1-speed-tap.prompt"}], "schema_version": 1}', '{"s1-speed-tap": {"target_ids": ["limones", "vasos", "azucar", "hielo", "cartel"]}}', '{"units": {"s1-speed-tap.hint.0": {"url": "http://localhost:4006/files/lesson-audio/bc89dd03482898029f12d60db6f97360a85e774d8e1450201a767b0f39847ba0.mp3", "hash": "645def84edd1185cdbd851d0dca18b00d2b3c23ee3f4456994719952c73a0791", "bytes": 23904, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/bc89dd03482898029f12d60db6f97360a85e774d8e1450201a767b0f39847ba0.mp3", "duration_ms": 3920}, "s1-speed-tap.hint.1": {"url": "http://localhost:4006/files/lesson-audio/7a99b8cb5ba3f9ab6ed30c6404de5e5545f6388e0401c0c67847409f5bab7668.mp3", "hash": "7db7b9179a6bc2ee94fdfd80a4c279912a5d9d82629c34e6d40c500e12cef3a8", "bytes": 23328, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/7a99b8cb5ba3f9ab6ed30c6404de5e5545f6388e0401c0c67847409f5bab7668.mp3", "duration_ms": 3840}, "s1-speed-tap.prompt": {"url": "http://localhost:4006/files/lesson-audio/e1e6b57f63d1954d1aedb919145386771a8495d283d612b320f172874d92e43e.mp3", "hash": "8ccb7384019fa06276345adf6a351aef5a590588b2e6176b9b8f7635afe80d3f", "bytes": 45936, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/e1e6b57f63d1954d1aedb919145386771a8495d283d612b320f172874d92e43e.mp3", "duration_ms": 7600}, "s1-speed-tap.explanation": {"url": "http://localhost:4006/files/lesson-audio/7eee1403e5ac2f794fd13540a9adcfae29b66dc1af8fb43782f5ad1708824c26.mp3", "hash": "786e58ba39852607fb4926dfacd2749e830b24fbe1c00c8e60661502b796019a", "bytes": 74304, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/7eee1403e5ac2f794fd13540a9adcfae29b66dc1af8fb43782f5ad1708824c26.mp3", "duration_ms": 12320}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1b29b755-c45e-46e4-a8d8-25624cad27a3', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-arrange-largo", "title": "Close the stand: all together", "locale": "en-US", "subject": "mixed", "objectives": ["Match payments with their correct change", "Order the steps to calculate profit", "Separate stand needs from wants", "Order the day''s events to keep change in the cash box"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-pagos", "xp": 15, "type": "match_pairs", "hints": ["The cup costs 5 pesos. If they pay with 10, how much is left?", "Subtract the price of the cup from the bill or coin they give."], "title": "Change for each payment", "payload": {"left": [{"id": "pago10", "text_md": "They pay with 10", "image_url": "http://localhost:4006/files/lesson-images/d0ae3891878994161316103c77b897713d1988a79e75d39d9c8e86145d919512.png"}, {"id": "pago20", "text_md": "They pay with 20", "image_url": "http://localhost:4006/files/lesson-images/5cc9a030e36583aa33a2a0ef12cded5dc412c11499b67c24d00dfc529e21ae33.png"}, {"id": "pago6", "text_md": "They pay with 6", "image_url": "http://localhost:4006/files/lesson-images/ab446895376f0d346ca9206d7c6e7205addfb8fb4a1c315b35140d9d58fb9304.png"}], "right": [{"id": "cambio5", "text_md": "Change: 5"}, {"id": "cambio15", "text_md": "Change: 15"}, {"id": "cambio1", "text_md": "Change: 1"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Tap each payment with the change you must give.", "difficulty": 2, "explanation_md": "If they pay with 10, the change is 5; with 20, it''s 15; with 6, only 1 peso is left.", "audio_segment_id": "s1-match-pagos.prompt"}, {"id": "s2-order-ganancia", "xp": 15, "type": "order_steps", "hints": ["First, set aside what it cost to make the lemonade.", "After subtracting the cost, what remains is the profit."], "title": "Order to find profit", "payload": {"items": [{"id": "costo", "text_md": "Set aside the cost of lemons and cups", "image_url": "http://localhost:4006/files/lesson-images/160e04c0c5ee7c70ccf43a7f2bf86a987de9ba839c93ce7af3a1467129b5d133.png"}, {"id": "ganancia", "text_md": "Count what''s left: the profit", "image_url": "http://localhost:4006/files/lesson-images/4974e6ad123ec069da0881e262ee910ec1c53e65e97ade1e817a217fc5dfd03f.png"}, {"id": "vender", "text_md": "Sell lemonade and receive money", "image_url": "http://localhost:4006/files/lesson-images/cbc6f35210f1f45107065b71bad7e45352b850c6a79d3654bb7acb0c8a405a46.png"}], "slots": 3}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Order the steps to calculate the day''s profit.", "difficulty": 2, "explanation_md": "First set aside the cost of lemons and cups, then count what''s left: that''s the profit.", "audio_segment_id": "s2-order-ganancia.prompt"}, {"id": "s3-sort-necesidades", "xp": 15, "type": "sort_buckets", "hints": ["Without lemons and cups, you can''t sell lemonade.", "Ice and stickers are wants, not urgent."], "title": "What the stand needs", "payload": {"items": [{"id": "limones", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/04308aa845bd29e6438245508616998c2faf213cc0bfab1f346dc7a287cdab5e.png"}, {"id": "vasos", "text_md": "Cups", "image_url": "http://localhost:4006/files/lesson-images/fc81a2fb49d62d7ea1736a6fc31ccc792492610b7058f8d624aeafe5611fde8b.png"}, {"id": "hielo", "text_md": "Ice", "image_url": "http://localhost:4006/files/lesson-images/f2abb8cf9ddf134cc4ea5a99365d7dac9f154fa5cb86fa7930de4ea7bf744bad.png"}, {"id": "calcomania", "text_md": "Sticker", "image_url": "http://localhost:4006/files/lesson-images/ec424f5ede3396d57ba1fdab7888ac24cf2830b1cb2d24a0ee2db957b45677ba.png"}], "buckets": [{"id": "necesidad", "label": "Need"}, {"id": "deseo", "label": "Want"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Separate what the stand NEEDS to open from what can wait.", "difficulty": 2, "explanation_md": "Lemons and cups are necessary to open; ice and stickers can wait.", "audio_segment_id": "s3-sort-necesidades.prompt"}, {"id": "s4-timeline-caja", "xp": 25, "type": "timeline_order", "hints": ["If you need to give change, a sale must come first.", "A big expense without a sale before leaves the cash box without change."], "title": "Keep change in the cash box", "payload": {"events": [{"id": "venta1", "icon": "payments", "text_md": "Sell 2 cups (10 pesos)", "image_url": "http://localhost:4006/files/lesson-images/596aa2f85809dccbee0cd61ed2f92fbc0a755e0fab320918057fcda5f1e520e2.png"}, {"id": "gasto", "icon": "shopping_cart", "text_md": "Buy more cups (8 pesos)", "image_url": "http://localhost:4006/files/lesson-images/7c26ce4de78327ead77b5c8a3714b09c17aa4a547c8cb695deda1f6bac6d1c16.png"}, {"id": "venta2", "icon": "payments", "text_md": "Sell 1 cup (5 pesos)", "image_url": "http://localhost:4006/files/lesson-images/a8989be752065f0d40b447e06fb7e4fe7ea10c52b746e7c413df990f245a1a03.png"}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Order the day''s events so the cash box never runs out of change.", "difficulty": 3, "explanation_md": "First a sale comes to have change, then you can spend on more cups.", "audio_segment_id": "s4-timeline-caja.prompt"}], "schema_version": 1}', '{"s1-match-pagos": {"pairs": [["pago10", "cambio5"], ["pago20", "cambio15"], ["pago6", "cambio1"]]}, "s4-timeline-caja": {"order": ["venta1", "gasto", "venta2"]}, "s2-order-ganancia": {"order": ["vender", "costo", "ganancia"]}, "s3-sort-necesidades": {"assignments": {"hielo": "deseo", "vasos": "necesidad", "limones": "necesidad", "calcomania": "deseo"}}}', '{"units": {"s1-match-pagos.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e4a36e5c39a4a304cc832e835cfe35d9e1353059398cb4658c6af8a88503f36c.mp3", "hash": "1fda9a5e6ada5f6f86407ed292ddf1