qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/45ef30ef841c03de805cf0d69cb3d75a0cf8c67ecd8c15fa4467b6b709a19751.mp3", "duration_ms": 5520}, "s3-sort-necesidades.explanation": {"url": "http://localhost:4006/files/lesson-audio/9cea03f6bc8a220b91d99be1ae3bd15038947517b513d8237a7467143218252c.mp3", "hash": "4e6ee7caf48a15d050084cbf44b5b70c0dccebc549d6315bca7179c29b9f21fe", "bytes": 24336, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9cea03f6bc8a220b91d99be1ae3bd15038947517b513d8237a7467143218252c.mp3", "duration_ms": 4000}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5bcbf28d-86a2-47d1-9003-23897d9d4f57', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "group-sets", "title": "Organize o dinheiro da caixa", "locale": "pt-BR", "subject": "mixed", "objectives": ["Agrupar moedas com moedas e notas com notas para contar mais fácil."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-group-money", "xp": 10, "type": "group_sets", "hints": ["As moedas são redondas e de metal; as notas são de papel e retangulares.", "Procure o grupo que diz ''Moedas'' para as moedas, e ''Notas'' para as notas."], "title": "Separe o dinheiro", "payload": {"items": [{"id": "coin1", "text_md": "Moeda de R$1", "image_url": "http://localhost:4006/files/lesson-images/0f576cc4494640296b5d795f62058d6f060e77e9c90aa24682344b68ba76dd12.png"}, {"id": "coin2", "text_md": "Moeda de R$2", "image_url": "http://localhost:4006/files/lesson-images/2005117c2f6d3f3c3aa900bd74d4b756db4281fe19ba45108fde81d17f5f286b.png"}, {"id": "coin3", "text_md": "Moeda de R$5", "image_url": "http://localhost:4006/files/lesson-images/df10a54806a339caa17aa57e2b4e3ad0623e77e9c73694c43076e790f0d6c624.png"}, {"id": "bill1", "text_md": "Nota de R$20"}, {"id": "bill2", "text_md": "Nota de R$50"}], "set_a": "Moedas", "set_b": "Notas"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Toque em cada moeda e cada nota para colocá-los em seu grupo.", "difficulty": 1, "explanation_md": "Liruf separou 3 moedas e 2 notas. Assim é mais fácil contar quanto dinheiro há.", "audio_segment_id": "s1-group-money.prompt"}], "schema_version": 1}', '{"s1-group-money": {"zones": {"bill1": "b", "bill2": "b", "coin1": "a", "coin2": "a", "coin3": "a"}}}', '{"units": {"s1-group-money.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e5aa22ad3a2ff3c610e27271d36f05472de4a6880c86b4d8311e28e96037747c.mp3", "hash": "bb7f0715af2133b33c264efc609ed39b452f73ce776bde16ded0561634fc8956", "bytes": 32544, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/e5aa22ad3a2ff3c610e27271d36f05472de4a6880c86b4d8311e28e96037747c.mp3", "duration_ms": 5360}, "s1-group-money.hint.1": {"url": "http://localhost:4006/files/lesson-audio/faf55aa2a3e3b8269d1eaf1bbb9096e5757a5a28573adc12835902b474ebdaeb.mp3", "hash": "dfe10b446102af55328537ebb0d20e39ce759d5526cb7eb10ee1350a1f4608d8", "bytes": 32544, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/faf55aa2a3e3b8269d1eaf1bbb9096e5757a5a28573adc12835902b474ebdaeb.mp3", "duration_ms": 5360}, "s1-group-money.prompt": {"url": "http://localhost:4006/files/lesson-audio/26c4b7bd18f7b27c4dc84435d260f44ff36bc446306118d32f65eb3dba622530.mp3", "hash": "a7453d0c72f4ea8e21db44bbde71955a5b3fbc43b3245a59f219110ab69a0081", "bytes": 28224, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/26c4b7bd18f7b27c4dc84435d260f44ff36bc446306118d32f65eb3dba622530.mp3", "duration_ms": 4640}, "s1-group-money.explanation": {"url": "http://localhost:4006/files/lesson-audio/1cd9c6255896f9cbd30c99d5e65494b2a3fff4fb3ce5b7b94e17cfed5713f927.mp3", "hash": "2068dd68cac7024f39938c2620c43f34022530497f0f0a1c531a9f448afb3120", "bytes": 47376, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1cd9c6255896f9cbd30c99d5e65494b2a3fff4fb3ce5b7b94e17cfed5713f927.mp3", "duration_ms": 7840}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8ee4aa69-44e4-4d40-9cde-af0d59cc6b99', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "true-false", "title": "Decisões de dinheiro: Verdadeiro ou falso?", "locale": "pt-BR", "subject": "mixed", "objectives": ["Tomar decisões simples de dinheiro comparando opções: preço justo, lugar seguro para guardar e distinguir um bom negócio de um mau.", "Decida se é verdadeiro ou falso: ''Se eu guardar 5 pesos de cada venda, minha economia CRESCE a cada dia''."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 10, "type": "true_false", "hints": ["Pense: se ontem ela tinha 5 pesos e hoje guarda mais 5, agora ela tem mais ou menos?", "Cada dia que ela guarda, soma mais dinheiro à economia."], "title": "Verdadeiro ou falso?", "payload": {"statement_md": "Se eu guardo 5 pesos de cada venda, minha economia CRESCE a cada dia.", "justifications": [{"id": "crece", "text_md": "Cada dia que guardo 5 pesos, o total da minha economia é maior do que no dia anterior."}, {"id": "no-crece", "text_md": "Se eu guardo 5 pesos a cada dia, a economia fica igual porque não somo nada novo."}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Zara vende limonada a 5 pesos. Cada dia ela guarda 5 pesos no cofrinho. A economia dela cresce ou fica igual?", "difficulty": 1, "explanation_md": "É verdadeiro. Se você guarda 5 pesos a cada dia, sua economia soma mais a cada vez. Por exemplo, segunda-feira 5, terça-feira 10, quarta-feira 15. Cresce!", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": true, "correct_justification_id": "crece"}}', '{"units": {"s1-true-false.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b26be07ed3adc4d36a28499936ff93d1dd0cdad1819ec3732310f9bc96825383.mp3", "hash": "3796d011b460797f0530548a02be268e5803846fd7d6bbb6e8e83a2fd4e98081", "bytes": 40608, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/b26be07ed3adc4d36a28499936ff93d1dd0cdad1819ec3732310f9bc96825383.mp3", "duration_ms": 6720}, "s1-true-false.hint.1": {"url": "http://localhost:4006/files/lesson-audio/f13d6a05ae9905ffdba19f0a9208d74e592bcff3d9a3c9dc630dfbb0be909ef1.mp3", "hash": "164869c65cd83fff0d005a8e5e9ef44136fb444534e79a97a19617e9ca298a25", "bytes": 22896, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/f13d6a05ae9905ffdba19f0a9208d74e592bcff3d9a3c9dc630dfbb0be909ef1.mp3", "duration_ms": 3760}, "s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/b775abe7f0921891088b9af8226aa24afcec1ecc29b5a0fceb3472a2f994be5a.mp3", "hash": "373262c31c47cbc191a82b9fed62f71353cd2bd24f3c031caacb77fc8903ca7b", "bytes": 54144, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/b775abe7f0921891088b9af8226aa24afcec1ecc29b5a0fceb3472a2f994be5a.mp3", "duration_ms": 8960}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/a8c2461ea0938e1d3d92fa8ce08a83a8454dee91387c4572276067f94ed9b5d8.mp3", "hash": "6d10f16e4690dfab35e529192c4208186a56ba5ce68848ee67a6511645e1594c", "bytes": 71856, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/a8c2461ea0938e1d3d92fa8ce08a83a8454dee91387c4572276067f94ed9b5d8.mp3", "duration_ms": 11920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f8c5e4cf-232b-47dc-8484-3350558f5f27', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "needs-wants", "title": "The stand eats first", "locale": "en-US", "subject": "money", "objectives": ["Separate stand needs (lemons, ice) from personal wants (popsicle, comic): the stand eats first."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-needs-wants", "xp": 10, "type": "needs_wants", "hints": ["The stand needs what is used to make lemonade.", "What runs out and has to be bought again?"], "title": "Stand needs vs. wants", "payload": {"items": [{"id": "limones", "icon": "eco", "text_md": "Lemons", "image_url": "http://localhost:4006/files/lesson-images/8b0267a60982e524fe7a57b8b25b47efc2fd96342a930f0c3665e1be38d061e4.png"}, {"id": "hielo", "icon": "ac_unit", "text_md": "Ice", "image_url": "http://localhost:4006/files/lesson-images/a8060e32e4f934d1acafb87b37b5fe3bd8770ea92b7a395d13a9809cec3b1bd8.png"}, {"id": "paleta", "icon": "icecream", "text_md": "Popsicle", "image_url": "http://localhost:4006/files/lesson-images/ed653628f8c8ad4a42dbc0fd395933f85e68d1cc88377c9096f84680f9ef5082.png"}, {"id": "comic", "icon": "auto_stories", "text_md": "Comic", "image_url": "http://localhost:4006/files/lesson-images/c5cdaeddd7cadb17dc19bd8231c6f8d57d4ec7dd4849867147f59349ab530724.png"}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Since you shared profits yesterday, today decide: what do you buy first so the stand doesn''t close?", "difficulty": 1, "explanation_md": "Lemons and ice are stand needs because without them there is no lemonade. The popsicle and comic are your wants, not the stand''s.", "audio_segment_id": "s1-needs-wants.prompt"}], "schema_version": 1}', '{"s1-needs-wants": {"needs_ids": ["limones", "hielo"]}}', '{"units": {"s1-needs-wants.hint.0": {"url": "http://localhost:4006/files/lesson-audio/96e8fe5ddc2240f5bb0cbecf4e2e4d5d3baa2f69c6f531ea2c65b324c64496f5.mp3", "hash": "c73e22efb31502afe9094f5017e18a59f20cb0112d7c577f52435c1f562ff7de", "bytes": 14688, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/96e8fe5ddc2240f5bb0cbecf4e2e4d5d3baa2f69c6f531ea2c65b324c64496f5.mp3", "duration_ms": 2400}, "s1-needs-wants.hint.1": {"url": "http://localhost:4006/files/lesson-audio/523207f9cf7f7a6e5138f348accea6488a2481683d01899f7f945ebf2bcc52af.mp3", "hash": "f048944492c9319471042b8c881930634f43549ad68b6c5c2ad1d1c9678d363e", "bytes": 13824, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/523207f9cf7f7a6e5138f348accea6488a2481683d01899f7f945ebf2bcc52af.mp3", "duration_ms": 2240}, "s1-needs-wants.prompt": {"url": "http://localhost:4006/files/lesson-audio/5186ae330345171ff9ca9f4f948b92b8f457e30d138169b6083a0c1612f9179c.mp3", "hash": "6f0e633f6c5951d78e1b5864b0ababff74e8bc21741de1c286b9c7236ca9f488", "bytes": 34416, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5186ae330345171ff9ca9f4f948b92b8f457e30d138169b6083a0c1612f9179c.mp3", "duration_ms": 5680}, "s1-needs-wants.explanation": {"url": "http://localhost:4006/files/lesson-audio/dfb8573f183e1c93f35bcdef96573022ea7469a5d4d3f21cd171394a96ba17b4.mp3", "hash": "726963fc57316bdc074fa95bf6b765f95d7542f857eb77c32f558ddcfa9fc15d", "bytes": 44064, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/dfb8573f183e1c93f35bcdef96573022ea7469a5d4d3f21cd171394a96ba17b4.mp3", "duration_ms": 7280}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('1b29b755-c45e-46e4-a8d8-25624cad27a3', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-arrange-largo", "title": "Cerrar el puesto: todo junto", "locale": "es-MX", "subject": "mixed", "objectives": ["Emparejar pagos con su cambio correcto", "Ordenar los pasos para calcular la ganancia", "Separar necesidades del puesto de deseos", "Ordenar eventos del día para mantener cambio en caja"], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-match-pagos", "xp": 15, "type": "match_pairs", "hints": ["El vaso cuesta 5 pesos. Si pagan con 10, ¿cuánto sobra?", "Resta el precio del vaso al billete o moneda que dan."], "title": "Cambio para cada pago", "payload": {"left": [{"id": "pago10", "text_md": "Pagan con 10", "image_url": "http://localhost:4006/files/lesson-images/0d58cb72ffc98efc97a6d3b4189f8c6a6e16a58707fc259bf257888d632d60ca.png"}, {"id": "pago20", "text_md": "Pagan con 20", "image_url": "http://localhost:4006/files/lesson-images/e80606f353f1a84e06db843ef65f930c199f541997080aac301b91b47cfecd93.png"}, {"id": "pago6", "text_md": "Pagan con 6", "image_url": "http://localhost:4006/files/lesson-images/9ca11917acf93fefbf5b2e4d9529d2930c790bdd111c94afbce58efc4acf13af.png"}], "right": [{"id": "cambio5", "text_md": "Cambio: 5"}, {"id": "cambio15", "text_md": "Cambio: 15"}, {"id": "cambio1", "text_md": "Cambio: 1"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Toca cada pago con el cambio que debes dar.", "difficulty": 2, "explanation_md": "Si pagan con 10, el cambio es 5; con 20, son 15; con 6, solo sobra 1 peso.", "audio_segment_id": "s1-match-pagos.prompt"}, {"id": "s2-order-ganancia", "xp": 15, "type": "order_steps", "hints": ["Primero hay que apartar lo que costó hacer la limonada.", "Después de restar el costo, lo que queda es la ganancia."], "title": "Orden para sacar la ganancia", "payload": {"items": [{"id": "costo", "text_md": "Apartar el costo de limones y vasos", "image_url": "http://localhost:4006/files/lesson-images/c3493154bac1db721b31aabd3f0dba6539239ec9a591be08bee300624808870e.png"}, {"id": "ganancia", "text_md": "Contar lo que sobra: la ganancia", "image_url": "http://localhost:4006/files/lesson-images/426a8e29965a0a849eb85121be12846381720ea95b46cba0b6435eba61216f7e.png"}, {"id": "vender", "text_md": "Vender limonada y recibir dinero", "image_url": "http://localhost:4006/files/lesson-images/2cbbc244d26730d3a87e44e3904c6503603940bdfe1f56cd44b5a713c074d484.png"}], "slots": 3}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Ordena los pasos para calcular la ganancia del día.", "difficulty": 2, "explanation_md": "Primero se aparta el costo de los limones y vasos, luego se cuenta lo que sobra: esa es la ganancia.", "audio_segment_id": "s2-order-ganancia.prompt"}, {"id": "s3-sort-necesidades", "xp": 15, "type": "sort_buckets", "hints": ["Sin limones y vasos no se puede vender limonada.", "El hielo y las calcomanías son deseos, no urgentes."], "title": "Lo que el puesto necesita", "payload": {"items": [{"id": "limones", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/667c3a521bbe6a13557a8ea472ee1b2b8ab61d55720b0926b89ae068b5b559cb.png"}, {"id": "vasos", "text_md": "Vasos", "image_url": "http://localhost:4006/files/lesson-images/18001014b448af465ceb8b941d6dde14c0ca73ec4bc2053bff6901c48e8add9e.png"}, {"id": "hielo", "text_md": "Hielo", "image_url": "http://localhost:4006/files/lesson-images/8239e790642d6ca516d0d463e6b4f8a83e15f19035a546aeff95a27e85c1519c.png"}, {"id": "calcomania", "text_md": "Calcomanía", "image_url": "http://localhost:4006/files/lesson-images/7ac46a7e2ffeabf3b8194ea85207188e55596fb23b4f2a8b12526a5c72c9f775.png"}], "buckets": [{"id": "necesidad", "label": "Necesidad"}, {"id": "deseo", "label": "Deseo"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Separa lo que el puesto NECESITA para abrir de lo que puede esperar.", "difficulty": 2, "explanation_md": "Limones y vasos son necesarios para abrir; el hielo y las calcomanías pueden esperar.", "audio_segment_id": "s3-sort-necesidades.prompt"}, {"id": "s4-timeline-caja", "xp": 25, "type": "timeline_order", "hints": ["Si necesitas dar cambio, primero debe entrar una venta.", "Un gasto grande sin venta antes deja la caja sin cambio."], "title": "Mantén cambio en la caja", "payload": {"events": [{"id": "venta1", "icon": "payments", "text_md": "Venden 2 vasos (10 pesos)", "image_url": "http://localhost:4006/files/lesson-images/e961ef4c80f8216e7816a92847b39c59fe431e9e3f18bed87417115858285fff.png"}, {"id": "gasto", "icon": "shopping_cart", "text_md": "Compran más vasos (8 pesos)", "image_url": "http://localhost:4006/files/lesson-images/e54a78325eacacec10ee9ae0d5adaeb43a3317a5dcfd87aabb04491491433175.png"}, {"id": "venta2", "icon": "payments", "text_md": "Venden 1 vaso (5 pesos)", "image_url": "http://localhost:4006/files/lesson-images/49066cef642069877b32f261e348b44c4b4436e1c90278f8d18e6ba7dbd87280.png"}]}, "narrator": {"emotion": "neutral", "character": "liruf"}, "prompt_md": "Ordena los eventos del día para que la caja nunca se quede sin cambio.", "difficulty": 3, "explanation_md": "Primero llega una venta para tener cambio, luego se puede gastar en más vasos.", "audio_segment_id": "s4-timeline-caja.prompt"}], "schema_version": 1}', '{"s1-match-pagos": {"pairs": [["pago10", "cambio5"], ["pago20", "cambio15"], ["pago6", "cambio1"]]}, "s4-timeline-caja": {"order": ["venta1", "gasto", "venta2"]}, "s2-order-ganancia": {"order": ["vender", "costo", "ganancia"]}, "s3-sort-necesidades": {"assignments": {"hielo": "deseo", "vasos": "necesidad", "limones": "necesidad", "calcomania": "deseo"}}}', '{"units": {"s1-match-pagos.hint.0": {"url": "http://localhost:4006/files/lesson-audio/985149afaf1a511b1f83baf8d8cee6e76f41027649