INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('97238255-709d-4d86-8930-3ea433f54f7d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "checkpoint", "title": "The night before opening", "locale": "en-US", "subject": "mixed", "objectives": ["Review the goal of the 80-peso guitar, the lemonade price at 5 pesos per cup, and that profit is what''s left after paying costs and goes into the guitar jar."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "checkpoint-noche", "xp": 0, "type": "checkpoint", "hints": [], "title": "The night before opening", "payload": {"recap_md": "Liruf already has his goal posted on the wall: the **80-peso** guitar. The sign says: lemonade at **5 pesos per cup**. And most importantly: from each cup, what''s left after the cost is the **profit** that goes straight into the guitar jar. Tomorrow is the real test!", "mood_prompt_md": "How close do you feel that guitar is now, Liruf?"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Dina and Liruf review what they have ready.", "difficulty": 1, "explanation_md": "Having a clear goal, a price, and knowing that profit fills the jar makes tomorrow real.", "audio_segment_id": "checkpoint-noche.prompt"}], "schema_version": 1}', '{}', '{"units": {"checkpoint-noche.recap": {"url": "http://localhost:4006/files/lesson-audio/aee0546c708aea722657606381f141cdf1b5afef11fd733e3e6a29c371f7c873.mp3", "hash": "080009be256a1c5d0cd93160992d25700e6d662c0333292c3e5d3e0f78962bb6", "bytes": 86256, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/aee0546c708aea722657606381f141cdf1b5afef11fd733e3e6a29c371f7c873.mp3", "duration_ms": 14320}, "checkpoint-noche.prompt": {"url": "http://localhost:4006/files/lesson-audio/263fc69619ed710b95b3773cd748398b8489f14f84addf6e45e070a6ea2a2618.mp3", "hash": "05463e82397f68299cfd6bc27f1e88c7fcb97dda8c809f28671124ec37080641", "bytes": 18144, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/263fc69619ed710b95b3773cd748398b8489f14f84addf6e45e070a6ea2a2618.mp3", "duration_ms": 2960}, "checkpoint-noche.explanation": {"url": "http://localhost:4006/files/lesson-audio/d25e577eae889fe1fd9b64708954f316e084d9a65cdc8e4eace743e4b93577f4.mp3", "hash": "a42e58566d27a7d83ab987eff2a5f59d2d6dbfe081411162afa2b44c19663486", "bytes": 28224, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/d25e577eae889fe1fd9b64708954f316e084d9a65cdc8e4eace743e4b93577f4.mp3", "duration_ms": 4640}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a8fced2e-cab0-454c-866f-d7f94e9da924', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-dinero", "title": "Cerrar la caja del domingo", "locale": "es-MX", "subject": "mixed", "objectives": ["Contar monedas de 1, 5 y 10 pesos para saber el total de ventas del día.", "Calcular el cambio correcto al pagar con billete de 20 pesos un vaso de 5 pesos.", "Determinar cuántos domingos más se necesita ahorrar 20 pesos para llegar a 80 pesos."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cuenta", "xp": 10, "type": "coin_count", "hints": ["Agrupa las monedas del mismo valor y luego súmalas."], "title": "Contar las monedas", "payload": {"target": 20, "currency": "MXN", "denominations": [1, 5, 10]}, "narrator": {"emotion": "excited", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/e94616b986e7dc21dd0acc12bc1e3cf6c378bf11027e083189aa243c463abf36.png", "prompt_md": "Cuenta las monedas que dejaron los clientes hoy. ¿Cuánto dinero hay en total?", "difficulty": 1, "explanation_md": "Hay 20 pesos en total: 3 monedas de 1 peso (3), 2 de 5 pesos (10) y 1 de 10 pesos (10). 3+10+10=20.", "audio_segment_id": "s1-cuenta.prompt"}, {"id": "s2-cambio", "xp": 10, "type": "make_change", "hints": ["Resta el precio del vaso al billete que te dio."], "title": "Dar el cambio", "payload": {"price": 5, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10, 20]}, "narrator": {"emotion": "happy", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/8b35bbaa5904f9c65023ee43262af4142f7090043274c4d564e69ab835e1e190.png", "prompt_md": "La última clienta paga su vaso de 5 pesos con un billete de 20. ¿Cuánto cambio le das?", "difficulty": 1, "explanation_md": "El cambio es 15 pesos, porque 20 menos 5 es 15. Así la clienta se va contenta.", "audio_segment_id": "s2-cambio.prompt"}, {"id": "s3-ahorro", "xp": 10, "type": "savings_goal", "hints": ["Primero calcula cuánto dinero te falta para la guitarra.", "Luego divide lo que falta entre lo que ahorras cada domingo."], "title": "¿Cuántos domingos faltan?", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [20]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "La guitarra cuesta 80 pesos. Ya tienes 40 en la alcancía. Si cada domingo guardas 20, ¿cuántos domingos más necesitas?", "difficulty": 1, "explanation_md": "Faltan 40 pesos, y si cada domingo guardas 20, necesitas 2 domingos más: 40 ÷ 20 = 2.", "audio_segment_id": "s3-ahorro.prompt"}], "schema_version": 1}', '{"s1-cuenta": {}, "s2-cambio": {}, "s3-ahorro": {}}', '{"units": {"s1-cuenta.hint.0": {"url": "http://localhost:4006/files/lesson-audio/010bba160e97d51194400bf06c3eacddfcbeebe2cc604af22f48839290bcc813.mp3", "hash": "aa769f7fa5e93ccfb139714429c50485b4077cedcdf58c0c07389429b8a73312", "bytes": 22896, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/010bba160e97d51194400bf06c3eacddfcbeebe2cc604af22f48839290bcc813.mp3", "duration_ms": 3760}, "s1-cuenta.prompt": {"url": "http://localhost:4006/files/lesson-audio/86ffb7cfe6636428700ed55da1cf982b007e9ebfb13bdccbc50ece5924af4188.mp3", "hash": "7f7f244fc47ea2e610708329aed2aa2478dc9008b09cb11097c9d0593118d51c", "bytes": 31536, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/86ffb7cfe6636428700ed55da1cf982b007e9ebfb13bdccbc50ece5924af4188.mp3", "duration_ms": 5200}, "s2-cambio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/54d0d887e4a852d2204b775f9301df4b386277c38f73c787d5c2382b41ab2454.mp3", "hash": "253098dc2e16294b58f482c6af0a3c850d796d1ad8001925428bf5e89653d25a", "bytes": 18144, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/54d0d887e4a852d2204b775f9301df4b386277c38f73c7