79-761a", "file_id": "lesson-audio/3a2b9d032e6b7e8ace3fd2a13a144fc69902704020696329a16c7cf0d63c943e.mp3", "duration_ms": 11040}, "s2-cambio.explanation": {"url": "http://localhost:4006/files/lesson-audio/ea12cad1159a58dbf67258e51b5ce6eb5b90097375ce04f2f0105c8520078203.mp3", "hash": "04e6031ddabb4aae81ad4e711f8e04df2663bdd2b6d37fff889b6d376bf72de4", "bytes": 44064, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/ea12cad1159a58dbf67258e51b5ce6eb5b90097375ce04f2f0105c8520078203.mp3", "duration_ms": 7280}, "s3-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/390ae1208ae86ec8cedad69f40e2e78345f15ebd76b560de094a218a59362458.mp3", "hash": "2c1bdbe016ad851dabe72888789114c100530834940f0da57f82d17c746b61d6", "bytes": 46368, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/390ae1208ae86ec8cedad69f40e2e78345f15ebd76b560de094a218a59362458.mp3", "duration_ms": 7680}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58ff84ee-6d0e-4e43-a182-5b9ffd992543', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "memory-flip", "title": "Combine produtos com seu pagamento exato", "locale": "pt-BR", "subject": "mixed", "objectives": ["Combine de memória cada produto com as moedas que o pagam, usando os preços da barraca: biscoito = 3 (1+2), copo pequeno = 5, jarra grande = 20 (10+10)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-memory-flip", "xp": 10, "type": "memory_flip", "hints": ["O biscoito custa 3, o copo pequeno 5 e a jarra grande 20."], "title": "Preços da barraca", "payload": {"pairs": [{"a_md": "Biscoito", "b_md": "1 + 2", "a_icon": "cookie", "b_icon": "payments", "a_image_url": "http://localhost:4006/files/lesson-images/f6a651de0e0476e1e039511e898773c0ee5678eeccd886462288d46bceb62bee.png", "b_image_url": "http://localhost:4006/files/lesson-images/c4fcfe2407afd7420e3a9412b4c5c52aa70ea539362fd43756792143001a6c31.png"}, {"a_md": "Copo pequeno", "b_md": "5", "a_icon": "water_drop", "b_icon": "payments", "a_image_url": "http://localhost:4006/files/lesson-images/ed2b34291d93c8e55fa9e893d00549d7426d8370e2707952ec300615298c3985.png", "b_image_url": "http://localhost:4006/files/lesson-images/82048d6ce67c385dbdc9d4bddd50737d50bd412ebeedf9dc853a8d5971d1eb53.png"}, {"a_md": "Jarra grande", "b_md": "10 + 10", "a_icon": "local_bar", "b_icon": "payments", "a_image_url": "http://localhost:4006/files/lesson-images/94a48eabffbf92903e39f230fab01edc2ce1eadb0ee32cb3f6ca6c9aae0fbccc.png", "b_image_url": "http://localhost:4006/files/lesson-images/56490c7515ec208f4812c0edb0412c35617fb239a1f511ca6892e1062acdb80b.png"}]}, "narrator": {"emotion": "encouraging", "character": "zara"}, "prompt_md": "Toque nas cartas para combinar cada produto com seu pagamento exato. Preços: biscoito 3, copo pequeno 5, jarra grande 20.", "difficulty": 1, "explanation_md": "Cada produto tem um preço fixo: biscoito 3, copo pequeno 5, jarra grande 20. Ao combinar corretamente, você lembra quanto cobrar.", "audio_segment_id": "s1-memory-flip.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-memory-flip.hint.0": {"url": "http://localhost:4006/files/lesson-audio/5b662133215d9a906ac02d58880ab5d29e4ef87492197071330facab87c8dfcd.mp3", "hash": "0a87189c2fbe69dab8093864394af2f0fd206c9d7b627cba851ce6e2c704d3ce", "bytes": 30528, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/5b662133215d9a906ac02d58880ab5d29e4ef87492197071330facab87c8dfcd.mp3", "duration_ms": 5040}, "s1-memory-flip.prompt": {"url": "http://localhost:4006/files/lesson-audio/70e9eeadc0c1904b047312f03307da75cb787a7ad83485f9825be2d13bfb1ec7.mp3", "hash": "b1348f4b45ac94d2bf2b7fce5e1b0a988d5b66eb81f2b8fe6394f5d41af4324b", "bytes": 57888, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/70e9eeadc0c1904b047312f03307da75cb787a7ad83485f9825be2d13bfb1ec7.mp3", "duration_ms": 9600}, "s1-memory-flip.explanation": {"url": "http://localhost:4006/files/lesson-audio/5ae00bd1223c873e98e17a32db6de1247c870a2128ade0b1aa874e86b73bb677.mp3", "hash": "55c85ec988f83e7ba9dd8ae79c2c8f61178b7a7b037938750809b4bc7d26bb36", "bytes": 64224, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/5ae00bd1223c873e98e17a32db6de1247c870a2128ade0b1aa874e86b73bb677.mp3", "duration_ms": 10640}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9b315200-00f0-4dc4-a2cd-13c1fb40e9aa', 'pt-BR', '1', E'{"meta": {"cast": ["liruf", "zara"], "slug": "build-sentence", "title": "A placa do combo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Calcular o preço de 2 copos de limonada a 5 pesos cada", "Selecionar a ficha correta para completar a placa do combo"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-combo-letrero", "xp": 15, "type": "build_sentence", "hints": ["Cada copo custa 5 pesos. Quanto custam dois copos?", "Pense: 5 + 5 = ?"], "title": "Complete a placa", "payload": {"slots": 5, "tokens": [{"id": "t1", "text_md": "2"}, {"id": "t2", "text_md": "copos"}, {"id": "t3", "text_md": "por"}, {"id": "t4", "text_md": "___"}, {"id": "t5", "text_md": "pesos"}, {"id": "t6", "text_md": "5"}, {"id": "t7", "text_md": "10"}, {"id": "t8", "text_md": "15"}, {"id": "t9", "text_md": "20"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Toque as fichas em ordem para montar a placa do combo: \\"2 copos por ___ pesos\\"", "difficulty": 2, "explanation_md": "Dois copos custam 10 pesos (5+5=10). Se você colocar 5, pagariam apenas um copo; se colocar 15 ou 20, espantaria clientes ou daria dinheiro de graça.", "audio_segment_id": "s1-combo-letrero.prompt"}], "schema_version": 1}', '{"s1-combo-letrero": {"order": ["t1", "t2", "t3", "t7", "t5"]}}', '{"units": {"s1-combo-letrero.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d8e15380a62945c41cd2d34ecfa72aa1da9d0d736b6e638d14714477dfe14981.mp3", "hash": "ace11bda00622c739108680d9bdfdc384081d3d238aaad23cd2dda750f86d8fe", "bytes": 31536, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/d8e15380a62945c41cd2d34ecfa72aa1da9d0d736b6e638d14714477dfe14981.mp3", "duration_ms": 5200}, "s1-combo-letrero.hint.1": {"url": "http://localhost:4006/files/lesson-audio/02d0d82ab86fc748228a60e4e1fcab3f43acd91937bcf2a894b5b068d9748620.mp3", "hash": "b008493df8ab802fcfc3ec6d9522ba8cee1f2fa46f8ea94c43b3501bfb042b94", "bytes": 18576, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/02d0d82ab86fc748228a60e4e1fcab3f43acd91937bcf2a894b5b068d9748620.mp3", "duration_ms": 3040}, "s1-combo-letrero.prompt": {"url": "http://localhost:4006/files/lesson-audio/8ff153d23e46ba137683876f000c18af3968fa79dc979cae5abba5c824a595d0.mp3", "hash": "99e6a42c104534cb537eaa26df21c0a1760582e894489f5170d4f9b00149fca2", "bytes": 34848, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/8ff153d23e46ba137683876f000c18af3968fa79dc979cae5abba5c824a595d0.mp3", "duration_ms": 5760}, "s1-combo-letrero.explanation": {"url": "http://localhost:4006/files/lesson-audio/9b3dd558d3553afe28fa08d979f49da91b169bee693b0ec0f6f4fd5353ae7a58.mp3", "hash": "0c902ab6006adddb51f50e9dacc1d6c4d89f159ebbaba617149eb56ff71028e5", "bytes": 80496, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/9b3dd558d3553afe28fa08d979f49da91b169bee693b0ec0f6f4fd5353ae7a58.mp3", "duration_ms": 13360}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('29159ba6-6f90-42be-9578-fda50515f345', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "budget-fit", "title": "Stock the market with $20", "locale": "en-US", "subject": "mixed", "objectives": ["Calculate how much money is left after buying necessities", "Decide which extras fit in a limited budget"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-surte", "xp": 15, "type": "budget_fit", "hints": ["First, add the price of lemons and sugar.", "Subtract that sum from $20 to find out how much you have left."], "title": "Stock the market with $20", "payload": {"items": [{"id": "limones", "icon": "eco", "need": true, "label": "Lemons", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/bb3dab76d856b9f53410b92f0ebb30739ac1ffe9b9ed329b1e352ef38daaa486.png"}, {"id": "azucar", "icon": "bakery_dining", "need": true, "label": "Sugar", "price": 6, "image_url": "http://localhost:4006/files/lesson-images/f0c90dd987c4be436550d31c96c51147ec5eb923c84e4614337f6869dd308a89.png"}, {"id": "hielo", "icon": "ac_unit", "need": false, "label": "Ice", "price": 5, "image_url": "http://localhost:4006/files/lesson-images/b740fd20b8bf487b7b1df7ba8e7cc32322fd2e46ba24b4be8c2cd23dec721b75.png"}, {"id": "popotes", "icon": "local_drink", "need": false, "label": "Straws", "price": 3, "image_url": "http://localhost:4006/files/lesson-images/6018970747d0249050f96e3926f4f01bb1a7923eb542d5200460a4ddf4579db1.png"}, {"id": "jarra", "icon": "local_cafe", "need": false, "label": "Pretty pitcher", "price": 8, "image_url": "http://localhost:4006/files/lesson-images/656ce1bc281bc0e97193d2368521c1434415c5580abdc6573e80c7cf79f3bacb.png"}], "budget": 20, "currency": "MXN", "must_buy_needs": true}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Liruf has $20. He must buy lemons ($8) and sugar ($6). Which extra fits in what''s left?", "difficulty": 2, "explanation_md": "Lemons ($8) + sugar ($6) = $14. You have $6 left. Ice costs $5, straws $3, the pitcher $8. With $6 you can buy ice ($5) or straws ($3), but not the pitcher ($8). If you buy the pitcher, you won''t have enough for the sugar and the lemonade will be sour.", "audio_segment_id": "s1-surte.prompt"}], "schema_version": 1}', '{"s1-surte": {}}', '{"units": {"s1-surte.hint.0": {"url": "http://localhost:4006/files/lesson-audio/523a09c0272804c834fa77c2b4c959561e0bca903c9a86db6985491d823aaf29.mp3", "hash": "fd4c7b1d92a06e8f2ca77a25f4366d908a23eb080845278834a326c587325f5a", "bytes": 15264, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/523a09c0272804c834fa77c2b4c959561e0bca903c9a86db6985491d823aaf29.mp3", "duration_ms": 2480}, "s1-surte.hint.1": {"url": "http://localhost:4006/files/lesson-audio/3a338b1b9bdef0f3b808bb8521d5b20776b9fa2cfbb7d8d98bb47981c70b67a7.mp3", "hash": "fc0f0102adc71e61ceb8b10e4b2fa7769c5e5c21756c763cac3138c5c72fccf2", "bytes": 23328, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/3a338b1b9bdef0f3b808bb8521d5b20776b9fa2cfbb7d8d98bb47981c70b67a7.mp3", "duration_ms": 3840}, "s1-surte.prompt": {"url": "http://localhost:4006/files/lesson-audio/d61b6a0bbe1fb37387cc308f34aee0253b7e5a0c7e5264c60aea7db4ec1641ce.mp3", "hash": "a2391e4ae4efe4e68b226bc94e8d405fba3daa0c7f44c0a7d89a671a6a7fe874", "bytes": 38304, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/d61b6a0bbe1fb37387cc308f34aee0253b7e5a0c7e5264c60aea7db4ec1641ce.mp3", "duration_ms": 6320}, "s1-surte.explanation": {"url": "http://localhost:4006/files/lesson-audio/54eeb74be835134380486ec0add69207d25ad66ec420c16dac4f803502ff40a7.mp3", "hash": "24a126777a398666c5e457caee7ee8c7a9c930950b24752941847f58d0c23edf", "bytes": 124128, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/54eeb74be835134380486ec0add69207d25ad66ec420c16dac4f803502ff40a7.mp3", "duration_ms": 20640}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a6e01e69-b662-4c31-9021-3de01a60bbc7', 'es-MX', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "odd-one-out", "title": "El ingrediente que no es", "locale": "es-MX", "subject": "mixed", "objectives": ["Identificar qué artículos no son ingredientes de la limonada para distinguir gastos reales de distracciones."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-odd-one-out", "xp": 10, "type": "odd_one_out", "hints": ["Para la limonada necesitas cosas que se mezclan en el vaso.", "La pelota no se mezcla ni se vende, solo se juega."], "title": "El ingrediente que no es", "payload": {"items": [{"id": "item1", "text_md": "Limones", "image_url": "http://localhost:4006/files/lesson-images/f8db09d5b56c3551e7d5c7f4bb10be9fe050b26113332ffd1ee9c67f123f3547.png"}, {"id": "item2", "text_md": "Azúcar", "image_url": "http://localhost:4006/files/lesson-images/74bf27950564fcc5a9cb4e1c15e66efaf02801f895248d7579845da4a97fb70e.png"}, {"id": "item3", "text_md": "Agua", "image_url": "http://localhost:4006/files/lesson-images/c8de21f787594467ac614abdf2c0af71ad882e97dc31b324615be90c3763ef33.png"}, {"id": "item4", "text_md": "Pelota", "image_url": "http://localhost:4006/files/lesson-images/01610132f466e3cc3a66c7652129539405b94c86f70736cce209e4059e6ed066.png"}], "reasons": [{"id": "reason1", "text_md": "No se usa para hacer limonada"}, {"id": "reason2", "text_md": "Cuesta más que los demás"}, {"id": "reason3", "text_md": "No se vende en la tienda"}]}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Rho tiene $10 en su alcancía con llave. ¿Qué compra NO es para la limonada?", "difficulty": 1, "explanation_md": "La pelota no es un ingrediente de la limonada. Si gastas $3 en la pelota, te quedan solo $7 para los ingredientes. ¡Mejor guarda la llave de tu alcancía y gasta solo en lo que necesitas!", "audio_segment_id": "s1-odd-one-out.prompt"}], "schema_version": 1}', '{"s1-odd-one-out": {"odd_item_id": "item4", "correct_reason_id": "reason1"}}', '{"units": {"s1-odd-one-out.hint.0": {"url": "http://localhost:4006/files/lesson-audio/bc3efc29d3ddb6f85c4235f5bc903e03ad1b6646d6ce686aaf299ea7b3efdb5c.mp3", "hash": "588b6be5f4a8b0fe72ce66ebe54b3539c9e405987bb4c626efc72029d21eaab4", "bytes": 21888, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/bc3efc29d3ddb6f85c4235f5bc903e03ad1b6646d6ce686aaf299ea7b3efdb5c.mp3", "duration_ms": 3600}, "s1-odd-one-out.hint.1": {"url": "http://localhost:4006/files/lesson-audio/ca8d22f6559c0831f6ad4f2dd658d647d1eb7dd29d251921a85a648bf786a18b.mp3", "hash": "e1a5b2ac3a9463e2b1d8b3f469643c9ccb7d3dd96060bf625fd908e5ad60e5b6", "bytes": 21888, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/ca8d22f6559c0831f6ad4f2dd658d647d1eb7dd29d251921a85a648bf786a18b.mp3", "duration_ms": 3600}, "s1-odd-one-out.prompt": {"url": "http://localhost:4006/files/lesson-audio/796ead0a13d0255fccbf273332a37acdb70a8f182e4a4b9806c05b6f2a52a13e.mp3", "hash": "7e690fd17b5193c37b64b4bbbec15486777fbbb02e379e1eac1e9c395b9d82a5", "bytes": 41184, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/796ead0a13d0255fccbf273332a37acdb70a8f182e4a4b9806c05b6f2a52a13e.mp3", "duration_ms": 6800}, "s1-odd-one-out.choices": {"url": "http://localhost:4006/files/lesson-audio/3fc6c314ba2d7be88e7222f2a64c28cee4b063155bae5991d210ee1da7700b36.mp3", "hash": "a1a2bef575005d71f01810e0c5e01bc1f3b3ffeba747c0b6eca175da695f8cc5", "bytes": 21888, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/3fc6c314ba2d7be88e7222f2a64c28cee4b063155bae5991d210ee1da7700b36.mp3", "duration_ms": 3600}, "s1-odd-one-out.explanation": {"url": "http://localhost:4006/files/lesson-audio/783547ff77e9b1aebdfcaae4acefcdf04ab5cfc3b5187fe4af9829be6