INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('e0e06311-1e57-4b7b-a3ee-04c82227ceae', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fair-trade", "title": "Fair trade", "locale": "en-US", "subject": "money", "objectives": ["Deciding if a trade is fair by comparing the value of two offers"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fair-trade", "xp": 15, "type": "fair_trade", "hints": ["Each glass costs 5 pesos. How much are the 2 glasses together worth?", "The bag of lemons costs 10 pesos. Compare that number with the value of the 2 glasses."], "title": "Fair trade", "payload": {"offer_a": {"qty": 2, "icon": "local_drink", "label": "Glass of lemonade", "image_url": "http://localhost:4006/files/lesson-images/dfaef5cb5005281a7f7078e118c712d3092b9e08c11cb3abcebbcfcbba48cf82.png"}, "offer_b": {"qty": 1, "icon": "agriculture", "label": "Bag of lemons", "image_url": "http://localhost:4006/files/lesson-images/0247fd83d0a7d792a263a5ffbdd761d0d2943719333a67975ca5297ffe87696c.png"}, "rate_md": "Each glass costs 5 pesos. The bag of lemons costs 10 pesos."}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Is it fair to trade 2 glasses of lemonade for a bag of lemons?", "difficulty": 2, "explanation_md": "2 glasses are worth 10 pesos (5+5) and the bag of lemons is also worth 10 pesos. It''s a fair trade!", "audio_segment_id": "s1-fair-trade.prompt"}], "schema_version": 1}', '{"s1-fair-trade": {"verdict": "fair"}}', '{"units": {"s1-fair-trade.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9dc4afce41a1d325e47db7ff7f8f8e71956dc6d57f188062d8f3d05ac81452b6.mp3", "hash": "f79fb77b4305ef5ab32626f84d620f1843a0f45d76d81b204eb5ba0c89024c23", "bytes": 27648, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/9dc4afce41a1d325e47db7ff7f8f8e71956dc6d57f188062d8f3d05ac81452b6.mp3", "duration_ms": 4560}, "s1-fair-trade.hint.1": {"url": "http://localhost:4006/files/lesson-audio/9e582928a38be02199f519447c87601547bcbac91eb6b67097edc5dde9728fe3.mp3", "hash": "e7597c379e83fb68143e3517dd15b3071ccc13e8c1395fe75699cade2447dbca", "bytes": 31536, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/9e582928a38be02199f519447c87601547bcbac91eb6b67097edc5dde9728fe3.mp3", "duration_ms": 5200}, "s1-fair-trade.prompt": {"url": "http://localhost:4006/files/lesson-audio/1c528636b51ea3883e3f831ea6d8df5252d1b8bc906f4c0913ab87b6e964fcb8.mp3", "hash": "11c4d56251c64f47a86cdac5aaeb94e7691e163b467d2f386be25834f811531e", "bytes": 22896, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/1c528636b51ea3883e3f831ea6d8df5252d1b8bc906f4c0913ab87b6e964fcb8.mp3", "duration_ms": 3760}, "s1-fair-trade.explanation": {"url": "http://localhost:4006/files/lesson-audio/9f523415571de407dda1e45c7e6cdaf8b60880b4276d6a30c853eb3e7297ef86.mp3", "hash": "ecfad78f944aa0de506271e25ea1b0ee68cf1a7763cc6f5b7fd9581257f92bd2", "bytes": 45504, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/9f523415571de407dda1e45c7e6cdaf8b60880b4276d6a30c853eb3e7297ef86.mp3", "duration_ms": 7520}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('59260361-67d7-4d0e-9c68-8c5e00637103', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "price-compare", "title": "Comparar preços de limões", "locale": "pt-BR", "subject": "mixed", "objectives": ["Comparar preços de limões em duas barracas do mercado e escolher a mais barata para gastar menos (custo mais baixo = mais lucro)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-price-compare", "xp": 10, "type": "price_compare", "hints": ["Conte quantos limões cada barraca dá por 6 reais.", "A barraca que dá mais limões pelo mesmo preço é mais barata."], "title": "Qual barraca de limões é mais barata?", "payload": {"offers": [{"id": "puesto-a", "qty": 3, "unit": "limones", "label": "Barraca A: 3 limões por 6 reais", "price": 6, "image_url": "http://localhost:4006/files/lesson-images/a262c093e896275ab4cfe9e4723598f7a3c2d47fa57931285fc6375aca35d235.png"}, {"id": "puesto-b", "qty": 2, "unit": "limones", "label": "Barraca B: 2 limões por 6 reais", "price": 6, "image_url": "http://localhost:4006/files/lesson-images/406a00ee917eedd2f4d95db7395292a99f8b234db03b96ff1fb031c831b0d0c1.png"}], "currency": "MXN"}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Dina quer comprar limões para sua limonada. Qual barraca dá mais limões por 6 reais?", "difficulty": 1, "explanation_md": "A barraca A dá 3 limões por 6 reais, a barraca B dá 2 limões por 6 reais. A barraca A te dá um limão extra pelo mesmo dinheiro! Assim sobra mais para o seu violão.", "audio_segment_id": "s1-price-compare.prompt"}], "schema_version": 1}', '{"s1-price-compare": {"best_offer_id": "puesto-a"}}', '{"units": {"s1-price-compare.hint.0": {"url": "http://localhost:4006/files/lesson-audio/07be845e976f3df806fbb6f65abc2ea0d70c805944f7176d3ea64a5568584d5d.mp3", "hash": "ce9ee9746e3187855c51de56547f3306d44f13a4db4c5308514dd4600de3487c", "bytes": 25776, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/07be845e976f3df806fbb6f65abc2ea0d70c805944f7176d3ea64a5568584d5d.mp3", "duration_ms": 4240}, "s1-price-compare.hint.1": {"url": "http://localhost:4006/files/lesson-audio/1e0bc619c0ae8d99bdf849ade2cfe4107dc9f1f548bbf9ffa8bf9fc710526a98.mp3", "hash": "5f7347d078e226800c01dd2ffa731ad5e74d050766aa1305106d623a302f756e", "bytes": 27648, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1e0bc619c0ae8d99bdf849ade2cfe4107dc9f1f548bbf9ffa8bf9fc710526a98.mp3", "duration_ms": 4560}, "s1-price-compare.prompt": {"url": "http://localhost:4006/files/lesson-audio/b3e573dbda69a7bfb96da1ce31326e263478564e0d8bd20c52edc1b36894c137.mp3", "hash": "6105954c69448589fc47cc19a99e762e162e7c0c7e5727c35dd69ce49018581b", "bytes": 40176, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b3e573dbda69a7bfb96da1ce31326e263478564e0d8bd20c52edc1b36894c137.mp3", "duration_ms": 6640}, "s1-price-compare.explanation": {"url": "http://localhost:4006/files/lesson-audio/cc4b52ac4491879f7c4cac3e6b26715658acdf066b84e3967157d029a6578501.mp3", "hash": "a9959caa404877534adc9e2ff241046f1f98040e4c5b10fe7415accf8bf96106", "bytes": 83376, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/cc4b52ac4491879f7c4cac3e6b26715658acdf066b84e3967157d029a6578501.mp3", "duration_ms": 13840}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9b315200-00f0-4dc4-a2cd-13c1fb40e9aa', 'es-MX', '1', E'{"meta": {"cast": ["liruf", "zara"], "slug": "build-sentence", "title": "El letrero del combo", "locale": "es-MX", "subject": "mixed", "objectives": ["Calcular el precio de 2 vasos de limonada a 5 pesos cada uno", "Seleccionar la ficha correcta para completar el letrero del combo"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-combo-letrero", "xp": 15, "type": "build_sentence", "hints": ["Cada vaso cuesta 5 pesos. ¿Cuánto cuestan dos vasos?", "Piensa: 5 + 5 = ?"], "title": "Completa el letrero", "payload": {"slots": 5, "tokens": [{"id": "t1", "text_md": "2"}, {"id": "t2", "text_md": "vasos"}, {"id": "t3", "text_md": "por"}, {"id": "t4", "text_md": "___"}, {"id": "t5", "text_md": "pesos"}, {"id": "t6", "text_md": "5"}, {"id": "t7", "text_md": "10"}, {"id": "t8", "text_md": "15"}, {"id": "t9", "text_md": "20"}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Toca las fichas en orden para armar el letrero del combo: \\"2 vasos por ___ pesos\\"", "difficulty": 2, "explanation_md": "Dos vasos cuestan 10 pesos (5+5=10). Si pones 5, solo pagarían un vaso; si pones 15 o 20, espantarías clientes o regalarías dinero.", "audio_segment_id": "s1-combo-letrero.prompt"}], "schema_version": 1}', '{"s1-combo-letrero": {"order": ["t1", "t2", "t3", "t7", "t5"]}}', '{"units": {"s1-combo-letrero.hint.0": {"url": "http://localhost:4006/files/lesson-audio/014245c083259c4e4f495e19a16633a7d1a64098c8c4d7ab4ecb811a8bf223dc.mp3", "hash": "11745609486adae261192b4dae1501aa332d8227de0429fc2c9437ed2e2582ef", "bytes": 29088, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/014245c083259c4e4f495e19a16633a7d1a64098c8c4d7ab4ecb811a8bf223dc.mp3", "duration_ms": 4800}, "s1-combo-letrero.hint.1": {"url": "http://localhost:4006/files/lesson-audio/6f8388f02159e5401c0501ee020fbf7074c504c22ccc060c714a49618cfbcd00.mp3", "hash": "bb1922d3ceebe40df3a32bb9832489abfd4e2f5c740d25ed5f22c0bf120ab0d9", "bytes": 17568, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/6f8388f02159e5401c0501ee020fbf7074c504c22ccc060c714a49618cfbcd00.mp3", "duration_ms": 2880}, "s1-combo-letrero.prompt": {"url": "http://localhost:4006/files/lesson-audio/2fd0c4a73da22a973bf6e1eff5ec55561ed80f17c0408f733e570bfddd45dd3c.mp3", "hash": "c9efc269c22f591c6e4f10f9df6b985f9a438eac7ec9aefe1121fb3135a12ab9", "bytes": 35856, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/2fd0c4a73da22a973bf6e1eff5ec55561ed80f17c0408f733e570bfddd45dd3c.mp3", "duration_ms": 5920}, "s1-combo-letrero.explanation": {"url": "http://localhost:4006/files/lesson-audio/abbb59e8825bb4f96300577b188d071ab7eed6066ce0258910cbeb0126150d1f.mp3", "hash": "33842701910a9f5517f6e01c6f32ff3d1995d8a67bb254ea1dc33f79ba70e1f9", "bytes": 76608, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/abbb59e8825bb4f96300577b188d071ab7eed6066ce0258910cbeb0126150d1f.mp3", "duration_ms": 12720}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f75b3e23-fb31-40cf-9b58-e918769e51b9', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "yes-no-cases", "title": "Sí o no: ¿ayuda al puesto?", "locale": "es-MX", "subject": "money", "objectives": ["Decidir si un gasto ayuda al puesto de limonada (sí) o es una tentación (no)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-yes-no-cases", "xp": 10, "type": "yes_no_cases", "hints": ["Piensa: ¿esto ayuda a vender más limonada o a guardar el dinero?", "Si solo es para jugar hoy, mejor esperar."], "title": "Sí o no: ¿ayuda al puesto?", "payload": {"cases": [{"id": "c1", "text_md": "Comprar 10 limones para hacer más limonada.", "image_url": "http://localhost:4006/files/lesson-images/8bcdb173d495cad9d6535835726ada14d5731cf06f3cb73e52d21fb1280244b6.png"}, {"id": "c2", "text_md": "Comprar un juguete de $5 para jugar hoy.", "image_url": "http://localhost:4006/files/lesson-images/820d9b8be66e443babcecb67ead6133ce47c039acd74df9e93ca945b6d44c312.png"}, {"id": "c3", "text_md": "Comprar 20 vasos desechables para servir la limonada.", "image_url": "http://localhost:4006/files/lesson-images/e0306da1972c36c87eba8388b9314709964b3c69a7e0ce83013c6970ab9ef5ee.png"}, {"id": "c4", "text_md": "Comprar una bolsa de dulces de $3 para ti.", "image_url": "http://localhost:4006/files/lesson-images/fbf572f92c4f8594d18da413167980165ef888cc8afbad1c1a035b68fd144f85.png"}], "rule_md": "Pregúntate: **¿esto ayuda a que el puesto funcione mejor o a ganar más dinero?** Si sí, es un gasto que vale la pena. Si no, es una tentación que puede esperar."}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Toca SÍ si ayuda al puesto, NO si es tentación.", "difficulty": 1, "explanation_md": "Comprar más limones ayuda a hacer más limonada y vender más. Un juguete nuevo no ayuda al puesto hoy.", "audio_segment_id": "s1-yes-no-cases.prompt"}], "schema_version": 1}', '{"s1-yes-no-cases": {"applies_ids": ["c1", "c3"]}}', '{"units": {"s1-yes-no-cases.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9a75efab1fbeb3ca307d11cf7ea87063ff0a0997e7cf69699bf170c59e0b4345.mp3", "hash": "044b07769748e6c780414cee4bfbb179fa9cb31b50d74f725faecb8a35623810", "bytes": 26784, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/9a75efab1fbeb3ca307d11cf7ea87063ff0a0997e7cf69699bf170c59e0b4345.mp3", "duration_ms": 4400}, "s1-yes-no-cases.hint.1": {"url": "http://localhost:4006/files/lesson-audio/90f386ed154ab015b5ee804520fea74174c35722bbb11b388d7403becebbac80.mp3", "hash": "48d06f70d0d110f822a000ec65ccaac8b018d6204e397daccd1368df2910171d", "bytes": 17136, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/90f386ed154ab015b5ee804520fea74174c35722bbb11b388d7403becebbac80.mp3", "duration_ms": 2800}, "s1-yes-no-cases.prompt": {"url": "http://localhost:4006/files/lesson-audio/e0a5d727b180bf23486923b4c7b5178439d619bb092391ab66ed2f9fc7ececeb.mp3", "hash": "ed97330e78befb9da2ac80a808ea5cf9005cf87fcec0dd93ef67670bbf774703", "bytes": 21456, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/e0a5d727b180bf23486923b4c7b5178439d619bb092391ab66ed2f9fc7ececeb.mp3", "duration_ms": 3520}, "s1-yes-no-cases.choices": {"url": "http://localhost:4006/files/lesson-audio/aa3a934ee55bd9975c38a5e14114f5ce0d1cd3b4c3ca78c6d623147d57b379fc.mp3", "hash": "d5f9081937b0a9e5595a7b4178d4029f62560bc789db39af0869813e4047605f", "bytes": 85248, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/aa3a934ee55bd9975c38a5e14114f5ce0d1cd3b4c3ca78c6d623147d57b379fc.mp3", "duration_ms": 14160}, "s1-yes-no-cases.explanation": {"url": "http://localhost:4006/files/lesson-audio/451395801e2369637a120e5a8c105af8d71422628d5220cf5e5bc6fdc07ed4dc.mp3", "hash": "bd0aaf18e2bddc9926eb870663bc1c58238f14614ace606eee807b9a6e0832e1", "bytes": 48816, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/451395801e2369637a120e5a8c105af8d71422628d5220cf5e5bc6fdc07ed4dc.mp3", "duration_ms": 8080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0c46648e-ff7a-4ad4-bf42-5829cc3fd1ac', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-dialogue", "title": "Ganar dinero con una idea", "locale": "es-MX", "subject": "money", "objectives": ["Entender que el dinero se gana ofreciendo algo que otros quieren", "Reconocer que una meta clara ayuda a empezar a ganar dinero"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogue", "xp": 0, "type": "story_dialogue", "hints": [], "title": "La guitarra de Liruf", "payload": {"lines": [{"action": "idle", "emotion": "thinking", "text_md": "Mira esa guitarra… cuesta 80 pesos. Nunca voy a juntar tanto.", "character": "liruf"}, {"action": "idle", "emotion": "happy", "text_md": "¿Y si la ganas tú mismo? Podrías vender limonada en el vecindario.", "character": "dina"}, {"action": "idle", "emotion": "surprised", "text_md": "¿Vender limonada? ¿La gente me pagaría por eso?", "character": "liruf"}, {"action": "idle", "emotion": "encouraging", "text_md": "¡Claro! Si haces una limonada rica, tus vecinos van a querer comprarla. Así ganas dinero con tu propia idea.", "character": "dina"}, {"action": "idle", "emotion": "excited", "text_md": "¡Sí! Voy a vender vasos a 5 pesos cada uno. Si vendo 4 vasos hoy, tendré 20 pesos… ¡me falta menos de la mitad! ¡Ya quiero empezar!", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/6b81461eb5e124f12ad1e319ccc3c5f37a876f21aa5ef0fe9ae429ef44b86906.png", "prompt_md": "Dina y Liruf hablan sobre la guitarra de 80 pesos.", "difficulty": 1, "explanation_md": "Vender limonada es una forma de ganar dinero ofreciendo algo que otros quieren.", "audio_segment_id": "s1-dialogue.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-dialogue.line.0": {"url": "http://localhost:4006/files/lesson-audio/d2f561183e3e25491c57055b816a9cc342a23929c20e3572c42c0504e3eb30ab.mp3", "hash": "c4435f43e35bdce359c5876ce0fdb75840e8a531df2d7ed05b070bb6b324b154", "bytes": 35424, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/d2f561183e3e25491c57055b816a9cc342a23929c20e3572c42c0504e3eb30ab.mp3", "duration_ms": 5840}, "s1-dialogue.line.1": {"url": "http://localhost:4006/files/lesson-audio/a5806d4e1f5fce213f072c1f046028e51d5cc91e52ece9e6b33d8bb5f7f304d2.mp3", "hash": "210f513010e86f3babb6218ea2952370d5cc6caa49c0b12a47951495f6951d93", "bytes": 30096, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a5806d4e1f5fce213f072c1f046028e51d5cc91e52ece9e6b33d8bb5f7f304d2.mp3", "duration_ms": 4960}, "s1-dialogue.line.2": {"url": "http://localhost:4006/files/lesson-audio/59703d784dcbf7cf905a4ef4750bb3f37e4b9f0349fa4e92283e2bb7da88a583.mp3", "hash": "aa9d61198304f94ae55680f3c597f21adde77a103eee628b83887d41d80f2b23", "bytes": 27648, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/59703d784dcbf7cf905a4ef4750bb3f37e4b9f0349fa4e92283e2bb7da88a583.mp3", "duration_ms": 4560}, "s1-dialogue.line.3": {"url": "http://localhost:4006/files/lesson-audio/7ec3c3acdbc4e8f9636926c74368dd7222875e1349cb85fcc867fe972cc3c002.mp3", "hash": "361c1f86937b070148bbe4130e101a77711c914e26eb27b15fafe438e65c48e0", "bytes": 50256, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7ec3c3acdbc4e8f9636926c74368dd7222875e1349cb85fcc867fe972cc3c002.mp3", "duration_ms": 8320}, "s1-dialogue.line.4": {"url": "http://localhost:4006/files/lesson-audio/588c4f3112483351a7b4129a41bf7ca44cb14e5062ef94af01dedb15fe4da43f.mp3", "hash": "53cd5d679b1bd53eb98b788ee39f280f94d8b0291dbdab8a6445ae891c942eec", "bytes": 67536, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/588c4f3112483351a7b4129a41bf7ca44cb14e5062ef94af01dedb15fe4da43f.mp3", "duration_ms": 11200}, "s1-dialogue.prompt": {"url": "http://localhost:4006/files/lesson-audio/ac4159907d3d24d1cd358727b83cb4cd01b95b554c1f1adf620500fafd9840ca.mp3", "hash": "b95511d9c3f058c0cc9ed4f158c0a744bb49c2a6e57b168c54bbafb94afb7164", "bytes": 24336, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/ac4159907d3d24d1cd358727b83cb4cd01b95b554c1f1adf620500fafd9840ca.mp3", "duration_ms": 4000}, "s1-dialogue.explanation": {"url": "http://localhost:4006/files/lesson-audio/9b3d72aa7f2916b078a5467d5af12936da1cf6c013653dfc710443cfe291fc14.mp3", "hash": "f58ff602f54915ef40c685a664319a13b1d0ea3b200f0b44a4f56afaa9be8bd2", "bytes": 32544, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/9b3d72aa7f2916b078a5467d5af12936da1cf6c013653dfc710443cfe291fc14.mp3", "duration_ms": 5360}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a00c4534-6e88-42ac-ab77-3465a684f47d', 'es-MX', '1', E'{"meta": {"cast": ["dina", "liruf"], "slug": "story-scene", "title": "El plan de Liruf", "locale": "es-MX", "subject": "money", "objectives": ["Entender que el dinero se gana ofreciendo algo que otros quieren, y que una meta clara ayuda a empezar."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-plan", "xp": 0, "type": "story_scene", "hints": [], "title": "El plan de Liruf", "payload": {"art": {"icon": "emoji_objects", "tint": "primary", "image_url": "http://localhost:4006/files/lesson-images/9a40fb88ec513f42927b981f2295510bd186f345857e46da126ab1f7709df9c4.png"}, "action": "idle", "body_md": "Liruf dibuja en una cartulina: un vaso de limonada cuesta **5 pesos**. La guitarra cuesta **80 pesos**. \\"Si vendo muchos vasos, ¡puedo comprar la guitarra!\\" dice Liruf.", "emotion": "happy", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Liruf dibuja su plan.", "difficulty": 1, "explanation_md": "Liruf dibujó un vaso de limonada que vale 5 pesos y una guitarra que cuesta 80. Así sabe cuántos vasos vender.", "audio_segment_id": "s1-plan.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-plan.body": {"url": "http://localhost:4006/files/lesson-audio/21faa7c5eb9046cc5529ad2e94ba812e7a693bc1ead25de2f0a2289e5a74796c.mp3", "hash": "ec7d9fe9c70b5d3d30658407c6ad0c7f90c855f38978fdf2730a5447a4f6e8b2", "bytes": 76176, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/21faa7c5eb9046cc5529ad2e94ba812e7a693bc1ead25de2f0a2289e5a74796c.mp3", "duration_ms": 12640}, "s1-plan.prompt": {"url": "http://localhost:4006/files/lesson-audio/45b63c1124f6e5528ffd2e2ebfdc6fecab7a2c0c1cbb4e5a586fde20b524c2ef.mp3", "hash": "b46be29cd236473b28bc975c163752f644fe2b46f49b5a888a99a9f32f5fcabd", "bytes": 12816, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/45b63c1124f6e5528ffd2e2ebfdc6fecab7a2c0c1cbb4e5a586fde20b524c2ef.mp3", "duration_ms": 2080}, "s1-plan.explanation": {"url": "http://localhost:4006/files/lesson-audio/302f6a9e0675743ed9db118157230d730ae75275e5f8995365fdeab853fd581d.mp3", "hash": "769154c1e6d92d624d6fb93568f7d3b9686a5a824aeeef8739692a05f34a05af", "bytes": 50688, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/302f6a9e0675743ed9db118157230d730ae75275e5f8995365fdeab853fd581d.mp3", "duration_ms": 8400}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('881ae1da-74af-4378-a3cd-da8a9bc0e6b2', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "key-ideas", "title": "As três regras de ouro do pequeno vendedor", "locale": "pt-BR", "subject": "money", "objectives": ["Definir as 3 ideias-chave do plano: ter uma meta (80 pesos), oferecer algo que as pessoas queiram (limonada gelada) e guardar o que ganhou."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-key-ideas", "xp": 0, "type": "key_ideas", "hints": [], "title": "As três regras de ouro do pequeno vendedor", "payload": {"ideas": [{"icon": "flag", "title": "Meta: 80 pesos", "body_md": "Liruf quer um violão que custa **80 pesos**. Ter uma meta clara ajuda a saber quanto é preciso ganhar.", "image_url": "http://localhost:4006/files/lesson-images/6bb3e459e5d2fd2c152c72f64f452351dc335feb03b005c98c21a65e0badae95.png"}, {"icon": "local_cafe", "title": "Oferecer limonada gelada", "body_md": "As pessoas do bairro querem algo gostoso e fresco. Liruf venderá **copos de limonada a 5 pesos**.", "image_url": "http://localhost:4006/files/lesson-images/aa900134e3b006404aaa991cb57671a4f6905b20cbd0cf9909316333a6816bcf.png"}, {"icon": "savings", "title": "Guardar o que ganhou", "body_md": "Cada vez que vender um copo, guarde o dinheiro. Pouco a pouco você chegará aos **80 pesos** do violão.", "image_url": "http://localhost:4006/files/lesson-images/d479fc84c23dc9b5918c13a6ea15389a4e46590a0cc187fa26efb927dcd34e5e.png"}]}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho escreveu no seu quadro as três regras de ouro para vender limonada. Toque em cada uma para lê-la.", "difficulty": 1, "explanation_md": "Rho anotou as três ideias-chave: uma meta clara (80 pesos), um produto que as pessoas queiram (limonada gelada) e guardar o que se ganha.", "audio_segment_id": "s1-key-ideas.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-key-ideas.idea.0": {"url": "http://localhost:4006/files/lesson-audio/1dd1e72da4333655507fe4bb75269d715cb384e00d7a11daf3d4c1781dd4a43d.mp3", "hash": "3715522a0b8e7aacd37bf96e32e8328294e7f84f09ca1d1481003b8f217c08fb", "bytes": 46944, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/1dd1e72da4333655507fe4bb75269d715cb384e00d7a11daf3d4c1781dd4a43d.mp3", "duration_ms": 7760}, "s1-key-ideas.idea.1": {"url": "http://localhost:4006/files/lesson-audio/dda0a594e591af2e99891762711a2442536f9fa9cf82584e2947be096139c182.mp3", "hash": "b11798c80d34181b7aa067012ed1398a20297657896cde6daf90a3798eb99fa9", "bytes": 44496, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/dda0a594e591af2e99891762711a2442536f9fa9cf82584e2947be096139c182.mp3", "duration_ms": 7360}, "s1-key-ideas.idea.2": {"url": "http://localhost:4006/files/lesson-audio/0e41a3c445accd6f9463b11b27015db85e826215950ee3b4e41fe364ff83c636.mp3", "hash": "d6e78cc2a28bc79280db30cdde19e1ca189b05d6b99cf6326b6cf9fe36075a6f", "bytes": 43056, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/0e41a3c445accd6f9463b11b27015db85e826215950ee3b4e41fe364ff83c636.mp3", "duration_ms": 7120}, "s1-key-ideas.prompt": {"url": "http://localhost:4006/files/lesson-audio/751cce5046091a96edffa9dd349664a62765db480e55e773c3ba38cd5e0909c1.mp3", "hash": "69e41341e8d3f862d28c3cb7da21ec17f2547d071104797954790ed4de8ab381", "bytes": 47376, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/751cce5046091a96edffa9dd349664a62765db480e55e773c3ba38cd5e0909c1.mp3", "duration_ms": 7840}, "s1-key-ideas.explanation": {"url": "http://localhost:4006/files/lesson-audio/61715e42cb7887850c2fab00e1781a62f340c213920412febf87bedd36919b4f.mp3", "hash": "0df72da05d9a4d0d853d3d1c66c4ce2d737d91bbcdbd400dd9b6199f9b29ab47", "bytes": 68976, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/61715e42cb7887850c2fab00e1781a62f340c213920412febf87bedd36919b4f.mp3", "duration_ms": 11440}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('64ccde87-2312-4acf-a950-409fd6a622c9', 'es-MX', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "read-chart", "title": "La gráfica de ventas de Zara", "locale": "es-MX", "subject": "mixed", "objectives": ["Leer la gráfica de barras de vasos vendidos por día y responder cuál fue el mejor día de la semana."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-read-chart", "xp": 10, "type": "read_chart", "hints": ["Busca la barra más alta de la gráfica.", "La barra más alta significa más vasos vendidos."], "title": "El mejor día de Zara", "payload": {"chart": {"kind": "bar", "unit": "vasos", "series": [{"label": "Vasos vendidos", "points": [{"x": "Lunes", "y": 3}, {"x": "Martes", "y": 5}, {"x": "Miércoles", "y": 2}, {"x": "Jueves", "y": 4}, {"x": "Viernes", "y": 7}]}]}, "questions": [{"id": "q1", "options": [{"id": "lunes", "text_md": "Lunes"}, {"id": "martes", "text_md": "Martes"}, {"id": "miercoles", "text_md": "Miércoles"}, {"id": "jueves", "text_md": "Jueves"}, {"id": "viernes", "text_md": "Viernes"}], "prompt_md": "¿Cuál día vendió más vasos?"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Zara dibujó una gráfica con los vasos que vendió cada día. ¿Cuál fue el día que vendió más?", "difficulty": 1, "explanation_md": "El viernes la barra llega hasta 7, que es más alto que los otros días. ¡Ese fue su mejor día!", "audio_segment_id": "s1-read-chart.prompt"}], "schema_version": 1}', '{"s1-read-chart": {"correct": {"q1": "viernes"}}}', '{"units": {"s1-read-chart.hint.0": {"url": "http://localhost:4006/files/lesson-audio/73d7cf94efde02aa67f847dc6781768fc886423bbeb030ff2cd18ff51372d446.mp3", "hash": "787a2de7d20082029a7e362cfc16e250be99d02d1d306cdc68831d4bece82864", "bytes": 14256, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/73d7cf94efde02aa67f847dc6781768fc886423bbeb030ff2cd18ff51372d446.mp3", "duration_ms": 2320}, "s1-read-chart.hint.1": {"url": "http://localhost:4006/files/lesson-audio/dec87abd6d914405eedefd6631de12a423d03631df8d8a5235339f5d8f30672b.mp3", "hash": "76e4bda7cdee1ea3eeb0d42ffe7c88901c0d2049c5cc22e8548e44c08f5ed4f6", "bytes": 19584, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/dec87abd6d914405eedefd6631de12a423d03631df8d8a5235339f5d8f30672b.mp3", "duration_ms": 3200}, "s1-read-chart.prompt": {"url": "http://localhost:4006/files/lesson-audio/16783d238d9d909b54f12211b567a07c7eb553408343166ec4b9e5f9281a4b4e.mp3", "hash": "61848c0c14c69ea1ee355d45cea5fa0efe2dedf5646255e36d3c821be988f942", "bytes": 33984, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/16783d238d9d909b54f12211b567a07c7eb553408343166ec4b9e5f9281a4b4e.mp3", "duration_ms": 5600}, "s1-read-chart.explanation": {"url": "http://localhost:4006/files/lesson-audio/1cc422e026a5d03065bf42797667257ba98b03868b05ec5567aa6f5f37189fd1.mp3", "hash": "eea45e88b842dc2791afbae3593bede0ccd53a329383a820ada565cfc3102c5d", "bytes": 39744, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1cc422e026a5d03065bf42797667257ba98b03868b05ec5567aa6f5f37189fd1.mp3", "duration_ms": 6560}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('64ccde87-2312-4acf-a950-409fd6a622c9', 'en-US', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "read-chart", "title": "Zara''s sales chart", "locale": "en-US", "subject": "mixed", "objectives": ["Read the bar chart of cups sold per day and answer which was the best day of the week."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-read-chart", "xp": 10, "type": "read_chart", "hints": ["Look for the tallest bar in the chart.", "The tallest bar means more cups sold."], "title": "Zara''s best day", "payload": {"chart": {"kind": "bar", "unit": "vasos", "series": [{"label": "Cups sold", "points": [{"x": "Monday", "y": 3}, {"x": "Tuesday", "y": 5}, {"x": "Wednesday", "y": 2}, {"x": "Thursday", "y": 4}, {"x": "Friday", "y": 7}]}]}, "questions": [{"id": "q1", "options": [{"id": "lunes", "text_md": "Monday"}, {"id": "martes", "text_md": "Tuesday"}, {"id": "miercoles", "text_md": "Wednesday"}, {"id": "jueves", "text_md": "Thursday"}, {"id": "viernes", "text_md": "Friday"}], "prompt_md": "Which day sold the most cups?"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Zara drew a chart with the cups she sold each day. Which day did she sell the most?", "difficulty": 1, "explanation_md": "On Friday the bar reaches 7, which is higher than the other days. That was her best day!", "audio_segment_id": "s1-read-chart.prompt"}], "schema_version": 1}', '{"s1-read-chart": {"correct": {"q1": "viernes"}}}', '{"units": {"s1-read-chart.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0b563acedb3b9bd9f24549d6fb7a8ffe3af3d6f290071dc76e9f50a47ddc81b3.mp3", "hash": "c242f3c7ef4155a02f8adc19e4ad347204977477c4a91718465ea4d7a8a097fc", "bytes": 11376, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/0b563acedb3b9bd9f24549d6fb7a8ffe3af3d6f290071dc76e9f50a47ddc81b3.mp3", "duration_ms": 1840}, "s1-read-chart.hint.1": {"url": "http://localhost:4006/files/lesson-audio/6aff52d416a24a5f13b3795521cd9347c937276f64b8626c23b7cf585d61c5e8.mp3", "hash": "e07d95d4422514eef2119f5fc0e5d0075e642dfa5a02b7916e5a3cdcadb1b9bc", "bytes": 12384, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6aff52d416a24a5f13b3795521cd9347c937276f64b8626c23b7cf585d61c5e8.mp3", "duration_ms": 2000}, "s1-read-chart.prompt": {"url": "http://localhost:4006/files/lesson-audio/5e815e3b9a4a3840d7854d6782e8611909d8641079b62958edddcf2cae86df41.mp3", "hash": "cb00910fc3b222d8760ae279ef4453ba1834260ce315631fa88230535c8b55c5", "bytes": 27216, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5e815e3b9a4a3840d7854d6782e8611909d8641079b62958edddcf2cae86df41.mp3", "duration_ms": 4480}, "s1-read-chart.explanation": {"url": "http://localhost:4006/files/lesson-audio/adfc206a3f4bbdcebc8ae1217298eaa4a0ff6287cfa9be7d78a8d1653674a957.mp3", "hash": "c5d403aed3fefce9f566fb00e3ea0b2e6fa2361e1a5d1390db3f9791dd0802e3", "bytes": 28224, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/adfc206a3f4bbdcebc8ae1217298eaa4a0ff6287cfa9be7d78a8d1653674a957.mp3", "duration_ms": 4640}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5cfeb5fa-1115-414d-9498-5cf6271b6245', 'en-US', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "robot-path", "title": "The delivery driver''s route", "locale": "en-US", "subject": "mixed", "objectives": ["Guide the delivery cart through the neighborhood grid to the customer''s house using the fewest steps."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-robot-path", "xp": 15, "type": "robot_path", "hints": ["The cart starts facing up. Which way should it go first?", "Count the squares from the start to the finish."], "title": "Route to the customer", "payload": {"goal": {"x": 2, "y": 2}, "grid": {"h": 3, "w": 3}, "start": {"x": 0, "y": 0, "dir": "up"}, "walls": [], "commands": ["forward", "forward", "right"], "max_commands": 3}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "The battery only lasts for 3 steps. Take the cart to the house.", "difficulty": 2, "explanation_md": "The cart moved up and then right to reach the customer''s house in 3 steps. Efficient route! This saves battery, just like saving money.", "audio_segment_id": "s1-robot-path.prompt"}], "schema_version": 1}', '{"s1-robot-path": {}}', '{"units": {"s1-robot-path.hint.0": {"url": "http://localhost:4006/files/lesson-audio/58ed6199e7fcb3c54dd1d23559fdeef88184a4cdc99a5d797c927095997cd908.mp3", "hash": "4ade28fab9bf29ac5604f4fa925150f635ea15b2d664c604da2d47184b8a36a7", "bytes": 18576, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/58ed6199e7fcb3c54dd1d23559fdeef88184a4cdc99a5d797c927095997cd908.mp3", "duration_ms": 3040}, "s1-robot-path.hint.1": {"url": "http://localhost:4006/files/lesson-audio/f60969194cf4c0a82333cfb75cbc52968313fcf95d128a786430df9188601171.mp3", "hash": "e23136b864a618c974a6d32e0b64cad8587158b6b401e1472ca94b9b3403558c", "bytes": 13248, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f60969194cf4c0a82333cfb75cbc52968313fcf95d128a786430df9188601171.mp3", "duration_ms": 2160}, "s1-robot-path.prompt": {"url": "http://localhost:4006/files/lesson-audio/8d7fa3901c624220d08e2221f3d0466a5f3b95bf6bada0c78cf68e2f12be239c.mp3", "hash": "e8120fa4b55c026e945c9479dfdb1921e4ac6801a33e2ef16589c97ba416788d", "bytes": 22896, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/8d7fa3901c624220d08e2221f3d0466a5f3b95bf6bada0c78cf68e2f12be239c.mp3", "duration_ms": 3760}, "s1-robot-path.explanation": {"url": "http://localhost:4006/files/lesson-audio/f0802dcad3ad759c3f1f75c56f46f8c8c900d3d0abf864b2a5d584591faffef1.mp3", "hash": "139b37e7f4e9e7ffa09d6a54247c95193d35dfc3b37826c08d122df96d21ed88", "bytes": 44496, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f0802dcad3ad759c3f1f75c56f46f8c8c900d3d0abf864b2a5d584591faffef1.mp3", "duration_ms": 7360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c5c3f5b2-2c4b-4aa8-bd76-cdcb594e0dda', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "concept-reveal", "title": "Costo y ganancia", "locale": "es-MX", "subject": "mixed", "objectives": ["Entender que el dinero se gana ofreciendo algo que otros quieren, y que una meta clara (la guitarra de 80 pesos) ayuda a empezar."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-concept-reveal", "xp": 0, "type": "concept_reveal", "hints": ["El costo es lo que gastas para hacer la limonada.", "La ganancia es lo que te queda después de vender."], "title": "Costo y ganancia", "payload": {"cards": [{"icon": "payments", "back_md": "Lo que gastas en limones y azúcar para hacer la limonada.", "front_md": "**Costo**", "image_url": "http://localhost:4006/files/lesson-images/e32c50a862938bbd35e5fcb103be583aa18fa7d5a3528bd19e64bc0f861973db.png"}, {"icon": "monetization_on", "back_md": "Lo que te queda después de pagar el costo de los ingredientes.", "front_md": "**Ganancia**", "image_url": "http://localhost:4006/files/lesson-images/b5bf9e5dd1322237d202ba9cc4f8ca181ad05a3bcbdea07b22de512d417db54f.png"}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Toca cada tarjeta para descubrir qué es costo y qué es ganancia.", "difficulty": 1, "explanation_md": "Costo es lo que gastas en limones y azúcar. Ganancia es lo que te queda después de pagar el costo. ¡Así Liruf sabe cuánto ahorra para su guitarra!", "audio_segment_id": "s1-concept-reveal.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-concept-reveal.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b2af4b5fec43ba46a301e3f1941e77ac5752abaa4e8a4e4f8cc693a46b6bb9e1.mp3", "hash": "0399b83dc685dfe4f4f726baea1c1211a7850e5c3cb12f4fbeb0d793c786efa9", "bytes": 17136, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/b2af4b5fec43ba46a301e3f1941e77ac5752abaa4e8a4e4f8cc693a46b6bb9e1.mp3", "duration_ms": 2800}, "s1-concept-reveal.hint.1": {"url": "http://localhost:4006/files/lesson-audio/5fa584b692cd77143c6fd2c94a4c21c64786428effe484fc8c773e3ba07e3683.mp3", "hash": "2d8c4f8b5ec4833158d9bf90ac9ec9cdd54218ea4e62cb1f9e9a2e5f579961dc", "bytes": 16704, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/5fa584b692cd77143c6fd2c94a4c21c64786428effe484fc8c773e3ba07e3683.mp3", "duration_ms": 2720}, "s1-concept-reveal.prompt": {"url": "http://localhost:4006/files/lesson-audio/ec7780828e7623180d680fe93ab30b6c99371effc4cca16659433a20d755681f.mp3", "hash": "da523ab18da57e2dd8cac2258824ea184f7fa349b6eb00815c7f087b9d424ac3", "bytes": 24768, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/ec7780828e7623180d680fe93ab30b6c99371effc4cca16659433a20d755681f.mp3", "duration_ms": 4080}, "s1-concept-reveal.card.0.back": {"url": "http://localhost:4006/files/lesson-audio/4f00749ba56dadf376cf756157c0e35197fe90a7c94a5e42c31db12ebdbf1c43.mp3", "hash": "518900fb3c23962f11b3060d5f241141583a362aa60095cc9e879e7e6f10520d", "bytes": 20448, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/4f00749ba56dadf376cf756157c0e35197fe90a7c94a5e42c31db12ebdbf1c43.mp3", "duration_ms": 3360}, "s1-concept-reveal.card.1.back": {"url": "http://localhost:4006/files/lesson-audio/87f55af3d34c1ef8aff64f1804704d91286cb30925c468b4ea362a043421971e.mp3", "hash": "db8ea9d6eaeb4a9b8e4980ed99da08f361bae09e1736859b746eea04dc03e1c4", "bytes": 21456, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/87f55af3d34c1ef8aff64f1804704d91286cb30925c468b4ea362a043421971e.mp3", "duration_ms": 3520}, "s1-concept-reveal.explanation": {"url": "http://localhost:4006/files/lesson-audio/3a2f13c1e932e876143b37cec6e8312d4776512780a33892e0e7240e014358e5.mp3", "hash": "e58095a716c497508c1c61fe0756408640767e4072011c3f736deb8ea958bd0a", "bytes": 51264, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/3a2f13c1e932e876143b37cec6e8312d4776512780a33892e0e7240e014358e5.mp3", "duration_ms": 8480}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('6e000ee0-e5b3-4521-b30f-cd54bbd72297', 'es-MX', '1', '{"meta": {"cast": ["rho"], "slug": "type-answer", "title": "Escribe la palabra: ahorro", "locale": "es-MX", "subject": "money", "objectives": ["Escribir la palabra ''ahorro'' para nombrar el dinero que se guarda para después."], "estimated_minutes": 2}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ahorro", "xp": 10, "type": "type_answer", "hints": ["Empieza con la letra A. Es lo que haces cuando no gastas todo tu dinero hoy.", "Pista: guardas dinero en tu alcancía para comprar algo después. Esa palabra es..."], "title": "Rho ahorra para su guitarra", "payload": {"max_chars": 10, "placeholder": "Escribe aquí..."}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho guarda 5 pesos cada semana. ¿Cómo se llama el dinero que guarda para después?", "difficulty": 1, "explanation_md": "El dinero que Rho guarda para su guitarra se llama ''ahorro''. ¡Así puede comprarla!", "audio_segment_id": "s1-ahorro.prompt"}], "schema_version": 1}', '{"s1-ahorro": {"accept": ["ahorro", "Ahorro"], "keywords": ["ahorro"], "case_sensitive": false}}', '{"units": {"s1-ahorro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e7f38be7173bc2767a4c9992e36e358c78f303844c95efb34119321c92559da4.mp3", "hash": "a83625762f86bfc971ff1a5973213d58f617dc68a67f7ac74b8f6b40e31b0663", "bytes": 30528, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/e7f38be7173bc2767a4c9992e36e358c78f303844c95efb34119321c92559da4.mp3", "duration_ms": 5040}, "s1-ahorro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/48c41bfdfd7439466c9234d2b954b427151f8e6dafe098512931466a2b7fe058.mp3", "hash": "0d8cc52eefde9aa8b4bd3d53b646068ab0b51bd488e99c548bb63edf764f93f3", "bytes": 36864, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/48c41bfdfd7439466c9234d2b954b427151f8e6dafe098512931466a2b7fe058.mp3", "duration_ms": 6080}, "s1-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/561022511b7ae007f7e6ca718cc3c875d2cded95547e2872da9d8f815f46acd4.mp3", "hash": "8d33286d799cc0edc4bff4a9d2456824aaacaeab312eb146cbdcb7debbf66991", "bytes": 34416, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/561022511b7ae007f7e6ca718cc3c875d2cded95547e2872da9d8f815f46acd4.mp3", "duration_ms": 5680}, "s1-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/cd1ff3638ef73a5286d6504704212952fe493c77abc0ec86869b4dfd25115cb0.mp3", "hash": "a893d330518b31a4a567f79958dbda2c934fe35cba881196340acab4ec65f763", "bytes": 36864, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/cd1ff3638ef73a5286d6504704212952fe493c77abc0ec86869b4dfd25115cb0.mp3", "duration_ms": 6080}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('3c639b5e-01f3-469e-95e3-a52a215847f4', 'en-US', '1', E'{"meta": {"cast": ["rho"], "slug": "fact-opinion", "title": "Facts and opinions at the stand", "locale": "en-US", "subject": "mixed", "objectives": ["Separate facts from opinions in lemonade stand sentences"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fact-opinion", "xp": 10, "type": "fact_opinion", "hints": ["A fact can be measured or counted. How much does the cup cost?", "An opinion tells how someone feels. It cannot be proven."], "title": "Fact or opinion", "payload": {"statements": [{"id": "s1", "text_md": "The cup of lemonade costs 5 pesos."}, {"id": "s2", "text_md": "My lemonade is the tastiest in the world."}, {"id": "s3", "text_md": "Today I sold 12 cups of lemonade."}, {"id": "s4", "text_md": "This lemonade tastes better than Dina''s."}]}, "narrator": {"emotion": "neutral", "character": "rho"}, "image_url": "http://localhost:4006/files/lesson-images/640765a62f5ef40ca3cf83bfc0c200030324e30288ddd0e8bc856883b54f78db.png", "prompt_md": "Rho heard a customer say: \\"Your lemonade is the best!\\" Is it a fact or an opinion? Tap the sentences that are FACTS.", "difficulty": 1, "explanation_md": "The price of the cup (5 pesos) is a fact because it can be verified. \\"The tastiest\\" is an opinion, because each person may think differently. Rho learned not to believe promises without proof.", "audio_segment_id": "s1-fact-opinion.prompt"}], "schema_version": 1}', '{"s1-fact-opinion": {"fact_ids": ["s1", "s3"]}}', '{"units": {"s1-fact-opinion.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0ddc8346ce51da795d8ee3ee1172aa5f178d7cdea9522a87ea13018bdf33a86a.mp3", "hash": "a26bd795fa2cc6eb59f308f392274f0808a413602bfe9c4863d6f9b2a51f0759", "bytes": 29088, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/0ddc8346ce51da795d8ee3ee1172aa5f178d7cdea9522a87ea13018bdf33a86a.mp3", "duration_ms": 4800}, "s1-fact-opinion.hint.1": {"url": "http://localhost:4006/files/lesson-audio/18172dda1d570f252086d0c78eabdea9be344c3c8f2afab9ad99b5d5a84e281d.mp3", "hash": "2b15ac3fcb3909229d13448bd4545e05ab2456ecbce483a87d3e8d377132150a", "bytes": 27648, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/18172dda1d570f252086d0c78eabdea9be344c3c8f2afab9ad99b5d5a84e281d.mp3", "duration_ms": 4560}, "s1-fact-opinion.prompt": {"url": "http://localhost:4006/files/lesson-audio/911280815e248e1ba51e73b0cb3d3c5498ab415053e751424ea435de3b1e9e55.mp3", "hash": "a2424b78e35173e9ce2954b42f1fa78db66590d87cd9b1d38ae7132eed6d5ec4", "bytes": 52128, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/911280815e248e1ba51e73b0cb3d3c5498ab415053e751424ea435de3b1e9e55.mp3", "duration_ms": 8640}, "s1-fact-opinion.explanation": {"url": "http://localhost:4006/files/lesson-audio/354db72aa412d836c0e1e9eb27e6f77e8277cd5f19b1bec95dfb3c91cd46da44.mp3", "hash": "ad4f7e06737abc95f12698f65c11d4ae76bdd0cba24a820d1a46263d3cf58e45", "bytes": 79056, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/354db72aa412d836c0e1e9eb27e6f77e8277cd5f19b1bec95dfb3c91cd46da44.mp3", "duration_ms": 13120}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4a340725-6bd9-48c4-9c1a-d8641c86b7a1', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "evidence-hunt", "title": "Evidence hunt on the receipt", "locale": "en-US", "subject": "mixed", "objectives": ["Look at the grocery receipt for the exact evidence of how much the lemons cost."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-evidence-hunt", "xp": 10, "type": "evidence_hunt", "hints": ["Find the word ''lemons'' on the receipt.", "The price is next to the word ''lemons''."], "title": "The crumpled receipt", "payload": {"claim_md": "Liruf says: ''I spent 20 pesos on lemons at the market.''", "sentences": [{"id": "s1-line1", "text_md": "Lemons — 15"}, {"id": "s1-line2", "text_md": "Sugar — 5"}, {"id": "s1-line3", "text_md": "Cups — 8"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/923e30650bd36873dcca37c2ac609bfd956f4d63338401be75d4222ec9d7f649.png", "prompt_md": "Tap the line on the receipt that shows how much the lemons cost.", "difficulty": 1, "explanation_md": "The line that says ''lemons'' and ''15'' is the exact evidence of the cost of the lemons. Just like in last class''s graph you looked for the day with the most sales, here you look for the correct line on the receipt.", "audio_segment_id": "s1-evidence-hunt.prompt"}], "schema_version": 1}', '{"s1-evidence-hunt": {"evidence_ids": ["s1-line1"]}}', '{"units": {"s1-evidence-hunt.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ffdec8eb61c1329cee49fbccba408efb748a85e69fab55cd79f7b5866521855b.mp3", "hash": "67927a397766adedf9ff99e3058f9d9b6f421e09ef8e99be419389f1f73b3721", "bytes": 12816, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ffdec8eb61c1329cee49fbccba408efb748a85e69fab55cd79f7b5866521855b.mp3", "duration_ms": 2080}, "s1-evidence-hunt.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a617fa333a183c09c57d20be3d0ca8f02cc1a0a070600b17e21f1fc36947b52e.mp3", "hash": "b4018cbb2b4d8fbf3fed8f48fab9764fca088b309536cea9f9e8a65af2847a28", "bytes": 12384, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/a617fa333a183c09c57d20be3d0ca8f02cc1a0a070600b17e21f1fc36947b52e.mp3", "duration_ms": 2000}, "s1-evidence-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/466cea2fb58e9757a36324657740fb05c15e6bf996f3a6447a2a23ab4ab16903.mp3", "hash": "2050218b4574914a8dbe691680d593545c9ee13a043f871645a40e8953527d11", "bytes": 20448, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/466cea2fb58e9757a36324657740fb05c15e6bf996f3a6447a2a23ab4ab16903.mp3", "duration_ms": 3360}, "s1-evidence-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/c1efd033d6f1ee53f1fcedf0e847eab42560b2423c8bbddb2223715e2d0a5845.mp3", "hash": "357e098ad11900bc7b2dca6328bb9b0e0366731fe2aa43780c7a877b795b01e5", "bytes": 64656, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c1efd033d6f1ee53f1fcedf0e847eab42560b2423c8bbddb2223715e2d0a5845.mp3", "duration_ms": 10720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('35abfab2-f1da-4643-915a-3fdba69f3a63', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fill-blank", "title": "Preencha os espaços do caderno da Dina", "locale": "pt-BR", "subject": "mixed", "objectives": ["Completar frases numéricas sobre economia da barraca", "Escrever respostas numéricas exatas (somas até 10, contagens até 20)"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ahorro", "xp": 10, "type": "fill_blank", "hints": ["Conte as moedas que ele economizou: 3 e depois 2.", "3 mais 2 são..."], "title": "Economia do dia", "payload": {"bank": [{"id": "b1", "text_md": "5"}, {"id": "b2", "text_md": "1"}], "mode": "typed", "text_md": "Liruf economizou 3 reais e depois mais 2. No total, ele economizou {{1}} reais."}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf economizou 5 reais. Quanto ele economizou no total?", "difficulty": 1, "explanation_md": "Liruf economizou 3 reais e depois mais 2, então ele tem 5 reais economizados. Muito bem!", "audio_segment_id": "s1-ahorro.prompt"}], "schema_version": 1}', '{"s1-ahorro": {"gaps": [{"gap": 1, "accept": ["5", "cinco"], "bank_id": "b1"}]}}', '{"units": {"s1-ahorro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0d71d08a3ea143b418e348307690d102e985162a6484f7b917c9f30f81f1a8cd.mp3", "hash": "2bae5e4de8dfd66fc7cc8f45bd72cf751ed64aaf331bf89663a7a61f51954aff", "bytes": 23904, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0d71d08a3ea143b418e348307690d102e985162a6484f7b917c9f30f81f1a8cd.mp3", "duration_ms": 3920}, "s1-ahorro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/0aafaa983bd048564b801dc3c7a04059535ea4c0024928c881f9010a799153ab.mp3", "hash": "147dbf4bfb0627992ea81d1fc403d4ee93d3850b3f63addf046e7d6510e3cab8", "bytes": 13248, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0aafaa983bd048564b801dc3c7a04059535ea4c0024928c881f9010a799153ab.mp3", "duration_ms": 2160}, "s1-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/f647bfc49eaa714dc5563a7c4c5a5f8b6a540bf7df9b59df52bea4f770bb2965.mp3", "hash": "d1f8eba4c2949ecc4eda2829367142829cb6e63066213afad4b0f7cf3d4aec13", "bytes": 27648, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f647bfc49eaa714dc5563a7c4c5a5f8b6a540bf7df9b59df52bea4f770bb2965.mp3", "duration_ms": 4560}, "s1-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/ebdcb7c740ab60d6004386c23e3064fdec6e9e7302fe8021e88aef0de0716905.mp3", "hash": "ea04d361575314455325752521cc414502d7d0fca438bce8f80f2a77f0e74e2c", "bytes": 51696, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/ebdcb7c740ab60d6004386c23e3064fdec6e9e7302fe8021e88aef0de0716905.mp3", "duration_ms": 8560}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8d0292b9-0597-4d9c-8b65-84f2fd19b142', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "red-flags", "title": "Red flags in a deal", "locale": "en-US", "subject": "mixed", "objectives": ["Spotting red flags in a stranger''s offer: promises too good to be true are not trustworthy."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-red-flags", "xp": 10, "type": "red_flags", "hints": ["Think: how much are they promising and how much do you have to give?", "Do you know that person? Do they seem in a hurry?"], "title": "The magic business", "payload": {"flags": [{"id": "promesa-dinero", "text_md": "Promises a lot of money fast"}, {"id": "desconocido", "text_md": "It''s a stranger"}, {"id": "apurado", "text_md": "Says ''today only'' and is in a hurry"}, {"id": "poco-tiempo", "text_md": "Asks you to decide right away"}], "artifact_md": "A handwritten sign that says: ''MAGIC BUSINESS! Give me 20 pesos today and tomorrow I''ll give you 100. Today only!'' The sign is taped to a pole.", "artifact_kind": "ad"}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/75dec13abb194524ad478339013d5f39f42a6a8daeebafd18fc077acc73b6cf2.png", "prompt_md": "Liruf is at his lemonade stand. A hurried man tells him: ''Give me your 20 pesos today and tomorrow I''ll give you 100.'' What red flags do you see?", "difficulty": 1, "explanation_md": "Promises of making a lot of money very fast, from a stranger, and in a hurry, are red flags. Liruf was right to be suspicious.", "audio_segment_id": "s1-red-flags.prompt"}], "schema_version": 1}', '{"s1-red-flags": {"redflag_ids": ["promesa-dinero", "desconocido", "apurado", "poco-tiempo"]}}', '{"units": {"s1-red-flags.hint.0": {"url": "http://localhost:4006/files/lesson-audio/535f2c01daa4f1bec60e2a9343aea4c78f98b1a6e87b390140c1987b1c2f739e.mp3", "hash": "ead037cd0afebb047e4d89eb8cb38d2e30583ac0ba2b9a9e088c9ded6e034607", "bytes": 21024, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/535f2c01daa4f1bec60e2a9343aea4c78f98b1a6e87b390140c1987b1c2f739e.mp3", "duration_ms": 3440}, "s1-red-flags.hint.1": {"url": "http://localhost:4006/files/lesson-audio/e281e98e7019d1430a86d3e7a875bcf2bd885ee4324124479c8d8da5d81b8ca5.mp3", "hash": "0bd636aa0839c369d7bfd34d07bd83ab16cd262d70afe3d28e71123f29833d18", "bytes": 16704, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e281e98e7019d1430a86d3e7a875bcf2bd885ee4324124479c8d8da5d81b8ca5.mp3", "duration_ms": 2720}, "s1-red-flags.prompt": {"url": "http://localhost:4006/files/lesson-audio/98c4125853c565b8e473c749cca782d8b83854e5ac1bd11acc793798bcec6339.mp3", "hash": "5d8f385964668af22466f0cb87ddd202c17883e45fcfcbf5043413f303228753", "bytes": 50688, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/98c4125853c565b8e473c749cca782d8b83854e5ac1bd11acc793798bcec6339.mp3", "duration_ms": 8400}, "s1-red-flags.explanation": {"url": "http://localhost:4006/files/lesson-audio/38e2c5cef3626fed5d87ad5574a635be98060a98d901e9c614ef5aefbfd9f0ce.mp3", "hash": "5eb2699cfeecb9d81e9dc7203be2009a1fa3fd6c45f2d6034bb94dee1e69eee9", "bytes": 39744, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/38e2c5cef3626fed5d87ad5574a635be98060a98d901e9c614ef5aefbfd9f0ce.mp3", "duration_ms": 6560}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('105d5cdf-c98a-4076-a3ed-440deb643d64', 'en-US', '1', '{"meta": {"cast": ["dina"], "slug": "would-you-rather", "title": "What would you do?", "locale": "en-US", "subject": "mixed", "objectives": ["Choose between two paths for the vendor and defend it: earn 10 pesos today or 20 next week?"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-would-you-rather", "xp": 10, "type": "would_you_rather", "hints": ["Think about what you need most right now: a treat today or something bigger later?", "No answer is bad, but each has a different consequence."], "title": "Earn today or tomorrow", "payload": {"a": {"icon": "local_atm", "text_md": "Earn 10 pesos today by selling 2 glasses of lemonade right now.", "image_url": "http://localhost:4006/files/lesson-images/ed68d45bedb9a96853c714535d36735fb8458892f4fb763c301b312d9bf3c1c8.png"}, "b": {"icon": "schedule", "text_md": "Wait until next week to earn 20 pesos by selling 4 glasses.", "image_url": "http://localhost:4006/files/lesson-images/5493a111cc1054c00a921915d656690562c4f0974bf260c9fad430e868c5f775.png"}, "followup_md": "Why did you choose that option? Tell Dina your reason."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Dina asks you: what would you do?", "difficulty": 1, "explanation_md": "Dina smiles: ''There is no single answer, the important thing is that you think about what you gain and what you lose with each decision.''", "audio_segment_id": "s1-would-you-rather.prompt"}], "schema_version": 1}', '{"s1-would-you-rather": {"qualities": {"a": 50, "b": 50}, "reveal_md": "Dina asiente: ''Si eliges 10 hoy, tienes dinero rápido para un antojo. Si eliges 20 la próxima semana, ahorras más pero esperas. Ambas son decisiones válidas.''"}}', '{"units": {"s1-would-you-rather.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9e5129fc0fa8afa3e0bcc303060a8e30459a3db66ec5abbc2a0bcb70d7a1c3bf.mp3", "hash": "b8564e7f56da5baac44ad5e69b0febc4d1c83e13cb75284a89b63751c6e340fb", "bytes": 28656, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9e5129fc0fa8afa3e0bcc303060a8e30459a3db66ec5abbc2a0bcb70d7a1c3bf.mp3", "duration_ms": 4720}, "s1-would-you-rather.hint.1": {"url": "http://localhost:4006/files/lesson-audio/365e9566f55b2cfc9419fc3961d1f9d8f6335ce7214c235ce95e25ecff47afbe.mp3", "hash": "6b737d6fe41977544524c7689b4f118c5d710552ad34ab4d34328aceffc5708b", "bytes": 19008, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/365e9566f55b2cfc9419fc3961d1f9d8f6335ce7214c235ce95e25ecff47afbe.mp3", "duration_ms": 3120}, "s1-would-you-rather.prompt": {"url": "http://localhost:4006/files/lesson-audio/0a72a3877885e37e01aff3c52f75605a196aee968c2cee3f40690b020938d0cf.mp3", "hash": "e55c4b994798869712f818a9391672ba565c6105e389311aef7d82234987c20b", "bytes": 13248, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/0a72a3877885e37e01aff3c52f75605a196aee968c2cee3f40690b020938d0cf.mp3", "duration_ms": 2160}, "s1-would-you-rather.choices": {"url": "http://localhost:4006/files/lesson-audio/c9d5a2d8bd6e5d8791d5a3bbca153aa8f3ee4d8cd57e0c47b571bca485b3e0e0.mp3", "hash": "f3ad674daf57d7c75a4e3e917ff9e5320ca04c8ff36f26262cfcfbfce4205fe6", "bytes": 44496, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c9d5a2d8bd6e5d8791d5a3bbca153aa8f3ee4d8cd57e0c47b571bca485b3e0e0.mp3", "duration_ms": 7360}, "s1-would-you-rather.explanation": {"url": "http://localhost:4006/files/lesson-audio/a3439e505b4cf5422a11b901b16426e60d1bc6e760d02f1af9ce3c23a7cdc45f.mp3", "hash": "e1aa5a4eecfc28210d71d11d9cb5d0942207d1fcd5dea72f2ce55dcb1e0a4e0a", "bytes": 37728, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/a3439e505b4cf5422a11b901b16426e60d1bc6e760d02f1af9ce3c23a7cdc45f.mp3", "duration_ms": 6240}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('105d5cdf-c98a-4076-a3ed-440deb643d64', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "would-you-rather", "title": "O que você faria?", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher entre dois caminhos do vendedor e defendê-lo: ganhar 10 reais hoje ou 20 na próxima semana?"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-would-you-rather", "xp": 10, "type": "would_you_rather", "hints": ["Pense no que você mais precisa agora: um prazer hoje ou algo maior depois?", "Nenhuma resposta é ruim, mas cada uma tem uma consequência diferente."], "title": "Ganhar hoje ou amanhã", "payload": {"a": {"icon": "local_atm", "text_md": "Ganhar 10 reais hoje vendendo 2 copos de limonada agora mesmo.", "image_url": "http://localhost:4006/files/lesson-images/7ab08faa3fe37221bfb2f482c5db73add0afd94f92f4ee008cae51051be64962.png"}, "b": {"icon": "schedule", "text_md": "Esperar até a próxima semana para ganhar 20 reais vendendo 4 copos.", "image_url": "http://localhost:4006/files/lesson-images/8175b12300d4b686b41f8d62cf78c94c6ed137bfcbc7c50ec480dfe617a56572.png"}, "followup_md": "Por que você escolheu essa opção? Conte para Dina o seu motivo."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Dina pergunta: o que você faria?", "difficulty": 1, "explanation_md": "Dina sorri: ''Não há resposta única, o importante é que você pense no que ganha e no que perde com cada decisão.''", "audio_segment_id": "s1-would-you-rather.prompt"}], "schema_version": 1}', '{"s1-would-you-rather": {"qualities": {"a": 50, "b": 50}, "reveal_md": "Dina asiente: ''Si eliges 10 hoy, tienes dinero rápido para un antojo. Si eliges 20 la próxima semana, ahorras más pero esperas. Ambas son decisiones válidas.''"}}', '{"units": {"s1-would-you-rather.hint.0": {"url": "http://localhost:4006/files/lesson-audio/cfc737e96906e65b0ce13821e2011850c5b164b591a7e250b9db13c9fdc1879d.mp3", "hash": "902c29d95cf127a4192f3489c4a315caaeae4e4d55127f0ef55f94910305e1f1", "bytes": 31536, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/cfc737e96906e65b0ce13821e2011850c5b164b591a7e250b9db13c9fdc1879d.mp3", "duration_ms": 5200}, "s1-would-you-rather.hint.1": {"url": "http://localhost:4006/files/lesson-audio/da4fcf1c76af73826b0930f3f3d3bffdeff6527568119732010d3cea304c6bb7.mp3", "hash": "cd432403aed073e0ee04d5e8486b6159432f448b822dbf1f08e8fef7a016b11c", "bytes": 29088, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/da4fcf1c76af73826b0930f3f3d3bffdeff6527568119732010d3cea304c6bb7.mp3", "duration_ms": 4800}, "s1-would-you-rather.prompt": {"url": "http://localhost:4006/files/lesson-audio/f7b5e8cbc4abdafcb63b993192f5613172f1dc3a2af5db075d30c5f9ba4800fb.mp3", "hash": "c50cef1b5983f6a221a395252b50f9e9aee735049b84799c219d9c33d87e45d9", "bytes": 17136, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f7b5e8cbc4abdafcb63b993192f5613172f1dc3a2af5db075d30c5f9ba4800fb.mp3", "duration_ms": 2800}, "s1-would-you-rather.choices": {"url": "http://localhost:4006/files/lesson-audio/f9d853942cad3261ed622efe780092337728d07d5e4f30d6c3a9333155919da9.mp3", "hash": "dc22cb9aaec6cb7992f34ab258e88ac2b4283f45dcfad6d020c712de098d43bb", "bytes": 67536, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f9d853942cad3261ed622efe780092337728d07d5e4f30d6c3a9333155919da9.mp3", "duration_ms": 11200}, "s1-would-you-rather.explanation": {"url": "http://localhost:4006/files/lesson-audio/0819cffc26bb4f6a9a1aeb1e648206bde7f8709e8bf9f4ece01a3c7a6edb2912.mp3", "hash": "89dc26984cff1027a34b563e2a374888620d7baafc29915b80a768641ac72365", "bytes": 51696, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0819cffc26bb4f6a9a1aeb1e648206bde7f8709e8bf9f4ece01a3c7a6edb2912.mp3", "duration_ms": 8560}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4dcc7a9f-f2f6-4b40-abd4-a522d168e446', 'pt-BR', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "flash-match", "title": "Flash Match: Conceitos do cargo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Relacionar palavras-chave do cargo (poupança, custo, lucro) com seus exemplos concretos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-flash-match", "xp": 10, "type": "flash_match", "hints": ["Pense no que cada palavra significa no cargo de limonada."], "title": "Conexão rápida!", "payload": {"left": [{"id": "ahorro", "text_md": "Poupança", "image_url": "http://localhost:4006/files/lesson-images/0a7966af2091fd067939ef0ce6f06ced0c165cae51bf3b79287c630f514368f6.png"}, {"id": "costo", "text_md": "Custo", "image_url": "http://localhost:4006/files/lesson-images/9f77533ab67a0b6b07faa6415b9f629b3a8f39a49ffcc805adbb0dd364197953.png"}, {"id": "ganancia", "text_md": "Lucro", "image_url": "http://localhost:4006/files/lesson-images/11f98d7f760a42a616fe014bda595a42f9840e9f9f497404506b758c8e86496d.png"}], "right": [{"id": "alcancia", "text_md": "Cofrinho da Dina"}, {"id": "limones", "text_md": "5 limões para limonada"}, {"id": "lo-que-sobra", "text_md": "Moedas que sobram"}], "seconds": 30}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Una cada palavra com seu exemplo.", "difficulty": 1, "explanation_md": "Poupança é o que Dina guarda no cofrinho para o skate. Custo são os 5 limões que ela comprou para fazer limonada. Lucro é o que sobra depois de vender.", "audio_segment_id": "s1-flash-match.prompt"}], "schema_version": 1}', '{"s1-flash-match": {"pairs": [["ahorro", "alcancia"], ["costo", "limones"], ["ganancia", "lo-que-sobra"]]}}', '{"units": {"s1-flash-match.hint.0": {"url": "http://localhost:4006/files/lesson-audio/5d876860cdabbb048524b93249773e397c8856a32356492e36db2e4cadc91eb1.mp3", "hash": "9f915e0d599e36242f9b3a8cfaac21acd490644fca1c39bd917fdefce1e4ad1e", "bytes": 23904, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/5d876860cdabbb048524b93249773e397c8856a32356492e36db2e4cadc91eb1.mp3", "duration_ms": 3920}, "s1-flash-match.prompt": {"url": "http://localhost:4006/files/lesson-audio/0e295061eb8f0bd51064f08dd5d8146d6fd9e72007f1ac0f0f5947b29f39b8e8.mp3", "hash": "0d168c57aa97651f712f8f45704b82c8030a8f0f6d9b5840582dc097310ad0d6", "bytes": 14256, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/0e295061eb8f0bd51064f08dd5d8146d6fd9e72007f1ac0f0f5947b29f39b8e8.mp3", "duration_ms": 2320}, "s1-flash-match.explanation": {"url": "http://localhost:4006/files/lesson-audio/5f7444612ec04af7d74b709a4dc5ef94d2f7b50954a21a0d1d7e64a36b30dea4.mp3", "hash": "36994f4fd261b73cc18dcf493685e026448cd852a1f7b6143ccbb24f218e600a", "bytes": 67104, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/5f7444612ec04af7d74b709a4dc5ef94d2f7b50954a21a0d1d7e64a36b30dea4.mp3", "duration_ms": 11120}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58172086-898d-4095-acf1-3502b8607e76', 'en-US', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "story-branch", "title": "The price of the day", "locale": "en-US", "subject": "mixed", "objectives": ["Choosing the price of lemonade considering the production cost and profit per cup.", "Observing how price affects sales and progress toward a savings goal."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio", "xp": 20, "type": "story_branch", "hints": ["If he charges too much, maybe no one will buy. If he charges too little, he''ll earn little per cup."], "title": "Choose the price", "payload": {"nodes": [{"id": "inicio", "choices": [{"id": "precio5", "next": "final5", "text_md": "5 pesos (the usual)"}, {"id": "precio3", "next": "final3", "text_md": "3 pesos (cheaper)"}, {"id": "precio10", "next": "final10", "text_md": "10 pesos (double)"}], "emotion": "thinking", "text_md": "It''s very hot and six neighbors are lining up at Liruf''s stand. Each cup of lemonade costs 2 pesos to make. What price does Liruf set today?", "character": "liruf"}, {"id": "final5", "choices": [{"id": "fin5", "next": null, "text_md": "End"}], "emotion": "happy", "text_md": "All 6 neighbors buy! Each cup gives 3 pesos profit (5 - 2 = 3). Liruf earns 18 pesos today. Good progress toward the 80-peso guitar!", "character": "liruf"}, {"id": "final3", "choices": [{"id": "fin3", "next": null, "text_md": "End"}], "emotion": "surprised", "text_md": "All 6 buy, but you only earn 1 peso per cup (3 - 2 = 1). Liruf earns only 6 pesos. Hardly any progress toward the guitar.", "character": "liruf"}, {"id": "final10", "choices": [{"id": "fin10", "next": null, "text_md": "End"}], "emotion": "surprised", "text_md": "The neighbors make a face and go for ice cream. Liruf is left with the full pitcher. He sells nothing and earns nothing for the guitar.", "character": "liruf"}], "start_node": "inicio"}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/a0890c0d70df3707ebd5339fd7eed5a3896a424c2bac9b64fcd40de1300e31ba.png", "prompt_md": "Liruf has to set today''s price. Each cup costs 2 pesos to make. How much will he charge?", "difficulty": 2, "explanation_md": "Liruf chose a price and saw how much he progressed toward the 80-peso guitar.", "audio_segment_id": "s1-precio.prompt"}], "schema_version": 1}', '{"s1-precio": {"qualities": [{"score": 100, "node_id": "inicio", "choice_id": "precio5"}, {"score": 30, "node_id": "inicio", "choice_id": "precio3"}, {"score": 0, "node_id": "inicio", "choice_id": "precio10"}]}}', '{"units": {"s1-precio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/eb980b71ac48e30227d10eec9b9f2488d5ddb3217c0618f54905df1ca77ae6b6.mp3", "hash": "20781c805ea4c0d0d09faba1b4cdc2c8c7abf5b69f4e49f93e5fab2c78300edc", "bytes": 31968, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/eb980b71ac48e30227d10eec9b9f2488d5ddb3217c0618f54905df1ca77ae6b6.mp3", "duration_ms": 5280}, "s1-precio.prompt": {"url": "http://localhost:4006/files/lesson-audio/449ad350c23d6dc19d6384621e334cf014c1996b0b2f60e8aa22654c795bc329.mp3", "hash": "c8fb1984ba0c891b0384d4bb2a8aa0f959934aa4e2066eae31b29abeef3cd0bc", "bytes": 33984, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/449ad350c23d6dc19d6384621e334cf014c1996b0b2f60e8aa22654c795bc329.mp3", "duration_ms": 5600}, "s1-precio.explanation": {"url": "http://localhost:4006/files/lesson-audio/359edee2c386623eddada14a7c1aac27a36a70d7585a22bba5c89e5533e6ffd1.mp3", "hash": "1017a66639b5d4f2ee359d3af9c052afcbdb7cf4f1dce6214c39420724a03181", "bytes": 25776, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/359edee2c386623eddada14a7c1aac27a36a70d7585a22bba5c89e5533e6ffd1.mp3", "duration_ms": 4240}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('99bea18a-9bc0-4fca-91fe-aa5b44c0ea6e', 'en-US', '1', '{"meta": {"cast": ["liruf"], "slug": "picture-choice", "title": "Where to keep the earnings?", "locale": "en-US", "subject": "mixed", "objectives": ["Choosing the safest place to keep money by comparing options"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-guardar-ganancias", "xp": 10, "type": "picture_choice", "hints": ["Think: where can the money not fall or get lost?", "Look for a place that has a lock or key."], "title": "Safe place", "payload": {"options": [{"id": "alcancia", "icon": "savings", "label": "Piggy bank with a key", "image_url": "http://localhost:4006/files/lesson-images/fc53490dcfdebcbd1c908e67f9cfd5dfbace2ec64bb17a3760c5b410e23a5ca1.png"}, {"id": "bolsillo", "icon": "checkroom", "label": "Torn pocket", "image_url": "http://localhost:4006/files/lesson-images/3ed6394fc1abacd88a06145cd482977b16e457ec3e203c3995af07f6b4210993.png", "rationale_md": "The torn pocket lets coins fall out, so it is not safe."}, {"id": "mesa", "icon": "table_restaurant", "label": "Stall table", "image_url": "http://localhost:4006/files/lesson-images/d667355eaf618db630a17da6e8598bb71fe4c801dfa628caeee5bb03ac2b5b43.png", "rationale_md": "The stall table is in plain sight of everyone, and anyone can take the money."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Yesterday Liruf saved 5 pesos from each sale. Today he already has 20 pesos. Where does he keep them best?", "difficulty": 1, "explanation_md": "The piggy bank with a key is the safest because no one else can open it. The torn pocket lets coins fall out, and the stall table is in plain sight of everyone.", "audio_segment_id": "s1-guardar-ganancias.prompt"}], "schema_version": 1}', '{"s1-guardar-ganancias": {"correct_option_id": "alcancia"}}', '{"units": {"s1-guardar-ganancias.hint.0": {"url": "http://localhost:4006/files/lesson-audio/cb11bb4963b4c800a28bab62255d74a0f0528c31291bbe81ca300906217f41bf.mp3", "hash": "5819fae477b4d89b5a8c1666e1251e51d8cc42d7a6e9950fd1dd8db06ae546f2", "bytes": 18144, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/cb11bb4963b4c800a28bab62255d74a0f0528c31291bbe81ca300906217f41bf.mp3", "duration_ms": 2960}, "s1-guardar-ganancias.hint.1": {"url": "http://localhost:4006/files/lesson-audio/abc3dc57d49b8a25960510c624948e5ba9cd6dfbd070604a43308cbe8a5b861c.mp3", "hash": "84ea14498fe3f0e70c936285e8418bd4e1ef02fe1b07dd400c66490eca16f256", "bytes": 17568, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/abc3dc57d49b8a25960510c624948e5ba9cd6dfbd070604a43308cbe8a5b861c.mp3", "duration_ms": 2880}, "s1-guardar-ganancias.prompt": {"url": "http://localhost:4006/files/lesson-audio/d6c7835b0f48420c7987904160a4f8003dc05387d1aac4663882722fb19db51a.mp3", "hash": "b8e9c15161914537fda0d2a1672d2983b96349a2b4fbca4afd3eaee80bdef87b", "bytes": 49824, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/d6c7835b0f48420c7987904160a4f8003dc05387d1aac4663882722fb19db51a.mp3", "duration_ms": 8240}, "s1-guardar-ganancias.choices": {"url": "http://localhost:4006/files/lesson-audio/d24a57b3cee7f9eb502f8b052d6e0035d1e0d7ba33b77482ae44e2c69dd9941b.mp3", "hash": "5122df93ce352b9bfcd80cf7c7e2d58c915c3c541faa2529542991ebf4e27f2c", "bytes": 21888, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/d24a57b3cee7f9eb502f8b052d6e0035d1e0d7ba33b77482ae44e2c69dd9941b.mp3", "duration_ms": 3600}, "s1-guardar-ganancias.explanation": {"url": "http://localhost:4006/files/lesson-audio/39dd7ce55b2240a743ba193cdebeeeb6dca5c0a8d1d5e473f82c757d03e00614.mp3", "hash": "17376d9a42f0df0f342106e18835b10e2a0fbd66e0c5ef2d4b31ddeee6f71367", "bytes": 54144, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/39dd7ce55b2240a743ba193cdebeeeb6dca5c0a8d1d5e473f82c757d03e00614.mp3", "duration_ms": 8960}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('cf7bec3a-945e-4d4a-828c-5535f3a7e69c', 'es-MX', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "equation-builder", "title": "Arma la suma de la tarde", "locale": "es-MX", "subject": "money", "objectives": ["Armar con fichas la suma de la tarde: 5 + 5 + 5 = 15 pesos (tres vasos vendidos)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-arma-suma", "xp": 15, "type": "equation_builder", "hints": ["Liruf vendió tres vasos de limonada. Cada vaso vale 5 pesos."], "title": "Arma la suma", "payload": {"slots": 5, "tokens": [{"id": "t1", "text": "5"}, {"id": "t2", "text": "+"}, {"id": "t3", "text": "5"}, {"id": "t4", "text": "+"}, {"id": "t5", "text": "5"}, {"id": "t6", "text": "3"}, {"id": "t7", "text": "15"}], "target_result": 15}, "narrator": {"emotion": "encouraging", "character": "rho"}, "prompt_md": "Toca las fichas para mostrar cuánto ganó Liruf hoy.", "difficulty": 2, "explanation_md": "Liruf vendió tres vasos de 5 pesos cada uno, así que la suma es 5 + 5 + 5 = 15 pesos. ¡Ya tiene 15 pesos para su guitarra de 80!", "audio_segment_id": "s1-arma-suma.prompt"}], "schema_version": 1}', '{"s1-arma-suma": {"accepted": ["t1 t2 t3 t4 t5"]}}', '{"units": {"s1-arma-suma.hint.0": {"url": "http://localhost:4006/files/lesson-audio/3cbed41cf4c511d35e86d9321bba4a912dfccac40405390eda44d40a25bc6f94.mp3", "hash": "c07139bde3ab5f5bc6edaf0ff17e9f3fdc7cce5d9a1c30db99104e2a253cbbee", "bytes": 32976, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/3cbed41cf4c511d35e86d9321bba4a912dfccac40405390eda44d40a25bc6f94.mp3", "duration_ms": 5440}, "s1-arma-suma.prompt": {"url": "http://localhost:4006/files/lesson-audio/83e0cafd6333c102bed92b80ae1caf93b73fd73c30a110e6031c306dc0e28039.mp3", "hash": "ca5d3b93376958734196f9497925a5ccf6d0fcb49f1e8b502e65d0fb693b3d39", "bytes": 21456, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/83e0cafd6333c102bed92b80ae1caf93b73fd73c30a110e6031c306dc0e28039.mp3", "duration_ms": 3520}, "s1-arma-suma.explanation": {"url": "http://localhost:4006/files/lesson-audio/62721093d0091155df8e495e236d54565b42733675c42d0580e4ff23492eb392.mp3", "hash": "8cc082c94954e6d7977293c09f29fcb7ef1dd46f58c45d72e26d661d69edde68", "bytes": 74736, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/62721093d0091155df8e495e236d54565b42733675c42d0580e4ff23492eb392.mp3", "duration_ms": 12400}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c3cd699b-431a-4c74-8563-19360a968d77', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "debug-hunt", "title": "Bug Hunt: The Promotion Poster", "locale": "en-US", "subject": "mixed", "objectives": ["Finding the error in a promotion poster that advertises 2 cups for 8 pesos when each cup costs 5 pesos individually.", "Correct the price or quantity so that the promotion is cheaper than buying individually."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-debug-hunt", "xp": 15, "type": "debug_hunt", "hints": ["Each cup costs 5 pesos individually. How much do two individual cups cost?", "The promotion must be cheaper than buying individually, not more expensive."], "title": "The Wrong Poster", "payload": {"blocks": [{"id": "b1", "text_md": "2 cups for 8 pesos"}, {"id": "b2", "text_md": "It''s more expensive than buying individually!"}, {"id": "b3", "text_md": "Each individual cup: 5 pesos"}], "intro_md": "Liruf put up a promotion poster: ''2 glasses of lemonade for 8 pesos''. But customers are laughing. It says it''s more expensive than buying individually. Is it right?"}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Tap the error on the promotion poster.", "difficulty": 2, "explanation_md": "Two individual cups cost 10 pesos (5+5). The promotion sells them for 8 pesos, which is cheaper. But the poster says ''2 cups for 8 pesos… it''s more expensive!'' — the error is that it says ''more expensive'' when it''s actually cheaper.", "audio_segment_id": "s1-debug-hunt.prompt"}], "schema_version": 1}', '{"s1-debug-hunt": {"fix_md": "Cambiar ''más caro'' por ''más barato''. La promoción de 2 vasos por 8 pesos es más barata que comprar dos sueltos por 10 pesos.", "bug_ids": ["b2"]}}', '{"units": {"s1-debug-hunt.hint.0": {"url": "http://localhost:4006/files/lesson-audio/857b8aa66408caa08e999445d9448cf7cfb6ef22fb6cfcd1371fa5fada8ed79d.mp3", "hash": "ab4bb3ca61f857d9f65d5ccb761124b8b9cc421b6cb8be4037a0d38345f152b8", "bytes": 28656, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/857b8aa66408caa08e999445d9448cf7cfb6ef22fb6cfcd1371fa5fada8ed79d.mp3", "duration_ms": 4720}, "s1-debug-hunt.hint.1": {"url": "http://localhost:4006/files/lesson-audio/4069dd900b747867ffd6f9be9ad509ecd6094bec18da1c5feeadc63237e43a55.mp3", "hash": "b141596a65777a572eca475807de1dbb3a70571ea68a9abe16576b654b451690", "bytes": 24336, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4069dd900b747867ffd6f9be9ad509ecd6094bec18da1c5feeadc63237e43a55.mp3", "duration_ms": 4000}, "s1-debug-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/ed647c29b13da2980c8df1385f02d0660be228663b3de45b394047a18175cc67.mp3", "hash": "be3f580ecda021ad64a35d192e86b8397de9d84bbdb8f7f04f45e5e93ae10b4c", "bytes": 11808, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/ed647c29b13da2980c8df1385f02d0660be228663b3de45b394047a18175cc67.mp3", "duration_ms": 1920}, "s1-debug-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/0682269002c5a36a3148c3f49a41113bb2bfbf75567f2aae869f9e92740526ef.mp3", "hash": "0b3068b321fec3aad1e9cbdd1427d19cdcbf32a549e6b3d80cf62800845fe813", "bytes": 81936, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/0682269002c5a36a3148c3f49a41113bb2bfbf75567f2aae869f9e92740526ef.mp3", "duration_ms": 13600}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9ceeee19-c270-4624-a828-92e6f501754e', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "confidence-quiz", "title": "Confianza en tus cuentas", "locale": "es-MX", "subject": "money", "objectives": ["Sumar dos cantidades pequeñas (5+5) y evaluar el nivel de confianza en el resultado."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-confidence-quiz", "xp": 10, "type": "confidence_quiz", "hints": ["Cada vaso cuesta 5 pesos. ¿Cuánto es 5 más 5?", "Puedes contar con los dedos: 5 dedos de una mano y 5 de la otra."], "title": "¿Cuánto vendió Liruf?", "payload": {"options": [{"id": "opt-10-seguro", "text_md": "10 pesos — muy seguro", "rationale_md": "¡Correcto! 5+5=10 y te sientes seguro. ¡Bien!"}, {"id": "opt-10-inseguro", "text_md": "10 pesos — no tan seguro", "rationale_md": "El resultado es correcto (10 pesos), pero puedes confiar más en tu cuenta. ¡Sigue practicando!"}, {"id": "opt-8-seguro", "text_md": "8 pesos — muy seguro", "rationale_md": "Parece que restaste en vez de sumar. Cada vaso cuesta 5, y dos vasos son 5+5=10, no 8."}, {"id": "opt-12-seguro", "text_md": "12 pesos — muy seguro", "rationale_md": "Sumaste de más. Cada vaso cuesta 5, y dos vasos son 5+5=10, no 12."}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf vendió dos vasos de limonada. ¿Cuánto dinero juntó? Luego elige qué tan seguro estás.", "difficulty": 1, "explanation_md": "Cada vaso cuesta 5 pesos, y dos vasos son 5 + 5 = 10 pesos. ¡Liruf juntó 10 pesos!", "audio_segment_id": "s1-confidence-quiz.prompt"}], "schema_version": 1}', '{"s1-confidence-quiz": {"correct_option_id": "opt-10-seguro"}}', '{"units": {"s1-confidence-quiz.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9a109af3c5214541fb282662d7b1e5dd9f505447bf014d9d91e85a003004af4d.mp3", "hash": "3785e7a32aaa642db90dbe09cc1c8a1a40c9096cafbd7d3f6d1f275ddcd68875", "bytes": 30096, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/9a109af3c5214541fb282662d7b1e5dd9f505447bf014d9d91e85a003004af4d.mp3", "duration_ms": 4960}, "s1-confidence-quiz.hint.1": {"url": "http://localhost:4006/files/lesson-audio/17d2ac8a344363506a23f9e3e5340f5c6452b466c4b8df50b5435d10d0848678.mp3", "hash": "568daf84c481997ec2d163cf9b1ab7eb278eae85f40e92743bf64c1f7a9beb4b", "bytes": 28224, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/17d2ac8a344363506a23f9e3e5340f5c6452b466c4b8df50b5435d10d0848678.mp3", "duration_ms": 4640}, "s1-confidence-quiz.prompt": {"url": "http://localhost:4006/files/lesson-audio/9b6243da1d988b3ca7e6e49b5ab7226576ff50099e4cb655cbfa6587e9539c41.mp3", "hash": "32f30e62559abdf462cb501ad2d4f4942bc4fd0e7efde254ba88cd35be0f59b1", "bytes": 41184, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/9b6243da1d988b3ca7e6e49b5ab7226576ff50099e4cb655cbfa6587e9539c41.mp3", "duration_ms": 6800}, "s1-confidence-quiz.choices": {"url": "http://localhost:4006/files/lesson-audio/59f4895b9ee26c11d89643704dabbd2ee7e70eb84da711b89eb4fb0fb309c67a.mp3", "hash": "676ac1d9498b861de83ed4a325f5c68a1914d62e51c9d66209b3313da680e0f4", "bytes": 50256, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/59f4895b9ee26c11d89643704dabbd2ee7e70eb84da711b89eb4fb0fb309c67a.mp3", "duration_ms": 8320}, "s1-confidence-quiz.explanation": {"url": "http://localhost:4006/files/lesson-audio/a55cddc2cbfdb9d46f53088f320f53ee1a4e14e76869b88089099e81b74a9512.mp3", "hash": "a4e8fa75ab8903829001bd40c1c9b0ab7b95923ee6abfad68495c27a9ea6dc04", "bytes": 49824, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/a55cddc2cbfdb9d46f53088f320f53ee1a4e14e76869b88089099e81b74a9512.mp3", "duration_ms": 8240}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9ceeee19-c270-4624-a828-92e6f501754e', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "confidence-quiz", "title": "Confiança nas suas contas", "locale": "pt-BR", "subject": "money", "objectives": ["Somar duas quantidades pequenas (5+5) e avaliar o nível de confiança no resultado."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-confidence-quiz", "xp": 10, "type": "confidence_quiz", "hints": ["Cada copo custa 5 reais. Quanto é 5 mais 5?", "Você pode contar nos dedos: 5 dedos de uma mão e 5 da outra."], "title": "Quanto Liruf vendeu?", "payload": {"options": [{"id": "opt-10-seguro", "text_md": "10 reais — muito seguro", "rationale_md": "Correto! 5+5=10 e você se sente seguro. Muito bem!"}, {"id": "opt-10-inseguro", "text_md": "10 reais — não tão seguro", "rationale_md": "O resultado está correto (10 reais), mas você pode confiar mais na sua conta. Continue praticando!"}, {"id": "opt-8-seguro", "text_md": "8 reais — muito seguro", "rationale_md": "Parece que você subtraiu em vez de somar. Cada copo custa 5, e dois copos são 5+5=10, não 8."}, {"id": "opt-12-seguro", "text_md": "12 reais — muito seguro", "rationale_md": "Você somou a mais. Cada copo custa 5, e dois copos são 5+5=10, não 12."}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf vendeu dois copos de limonada. Quanto dinheiro ele juntou? Depois escolha o quão seguro você está.", "difficulty": 1, "explanation_md": "Cada copo custa 5 reais, e dois copos são 5 + 5 = 10 reais. Liruf juntou 10 reais!", "audio_segment_id": "s1-confidence-quiz.prompt"}], "schema_version": 1}', '{"s1-confidence-quiz": {"correct_option_id": "opt-10-seguro"}}', '{"units": {"s1-confidence-quiz.hint.0": {"url": "http://localhost:4006/files/lesson-audio/80bd5bf6741120e2455ea8dc6f34af512e000fc1df99726a8cacdaf711dc7869.mp3", "hash": "bb5cdf94f8ace8eb93b2f7ba0b23af256d37b148a6526d0401d19ccc4c87cd2a", "bytes": 28656, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/80bd5bf6741120e2455ea8dc6f34af512e000fc1df99726a8cacdaf711dc7869.mp3", "duration_ms": 4720}, "s1-confidence-quiz.hint.1": {"url": "http://localhost:4006/files/lesson-audio/16691aacf49d75a3e8606a63ab04798f471195884675ce70880768e2c158959b.mp3", "hash": "9319d1d0bf4ee6eb6456eb05f4440a15814e06a7d7e1a3c4d033d852368c4a7b", "bytes": 31968, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/16691aacf49d75a3e8606a63ab04798f471195884675ce70880768e2c158959b.mp3", "duration_ms": 5280}, "s1-confidence-quiz.prompt": {"url": "http://localhost:4006/files/lesson-audio/0752705b680ac73dde8859e858860c028aad050114742b8449a8cd48c49f02d5.mp3", "hash": "3debda6349654db10de5dd62e5a31ec4fecdabbeb156498b9cccce74d874b19e", "bytes": 52128, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0752705b680ac73dde8859e858860c028aad050114742b8449a8cd48c49f02d5.mp3", "duration_ms": 8640}, "s1-confidence-quiz.choices": {"url": "http://localhost:4006/files/lesson-audio/24b4ed8c78390b4dbd8396eebfbe3adebe5ade372c1b3d58f4d7cc0221f308d6.mp3", "hash": "3fe4d1cae4684a262b9c6ae74968bc74275be699993305af58ca7df301d1d121", "bytes": 61344, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/24b4ed8c78390b4dbd8396eebfbe3adebe5ade372c1b3d58f4d7cc0221f308d6.mp3", "duration_ms": 10160}, "s1-confidence-quiz.explanation": {"url": "http://localhost:4006/files/lesson-audio/9d5ca11735427f13e210d6ef26e6c6d9f7ea5f280eab3dcd72adda97d5a68026.mp3", "hash": "334c328717defa1a32b4d3ed40f8dc8310ea970a6b36448588a55525888e288c", "bytes": 50688, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/9d5ca11735427f13e210d6ef26e6c6d9f7ea5f280eab3dcd72adda97d5a68026.mp3", "duration_ms": 8400}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4b45b37b-19f0-4fd5-99c2-0bcf9fabfbcd', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "machine-io", "title": "A máquina de gorjetas", "locale": "pt-BR", "subject": "mixed", "objectives": ["Descobrir a regra da máquina de gorjetas: dobra a entrada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-machine-io", "xp": 15, "type": "machine_io", "hints": ["Observe: 1 → 2, 3 → 6. Qual operação se repete?", "Teste: 1 × 2 = 2, 3 × 2 = 6. Então 5 × ?"], "title": "A máquina de gorjetas", "payload": {"options": [{"id": "opt-7", "text_md": "7"}, {"id": "opt-8", "text_md": "8"}, {"id": "opt-10", "text_md": "10"}, {"id": "opt-15", "text_md": "15"}], "examples": [{"in": 1, "out": 2}, {"in": 3, "out": 6}], "probe_in": 5}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Liruf coloca 1 moeda e saem 2. Depois coloca 3 e saem 6. Quantas sairão se colocar 5?", "difficulty": 2, "explanation_md": "A máquina dobra o que entra. 1 vira 2, 3 vira 6, então 5 vira 10.", "audio_segment_id": "s1-machine-io.prompt"}], "schema_version": 1}', '{"s1-machine-io": {"value": 10, "correct_option_id": "opt-10"}}', '{"units": {"s1-machine-io.hint.0": {"url": "http://localhost:4006/files/lesson-audio/82aa215cc8011ea422bc1c30b2189d5dac3426cf66526979b2c823b89631cef5.mp3", "hash": "6f1679275f6fe026d2a6dabbeb2cd0f2f7dd713ae00a93eda48e7c7351b785e6", "bytes": 35424, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/82aa215cc8011ea422bc1c30b2189d5dac3426cf66526979b2c823b89631cef5.mp3", "duration_ms": 5840}, "s1-machine-io.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a4eaac996eca21fa176d99817704b1a5fab4bbc84f664afb1267fa6614d04e2f.mp3", "hash": "bcde418d832dd12f78db1e473ab6f97ee1d46d1cd4663e8665374618b174f6af", "bytes": 46944, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a4eaac996eca21fa176d99817704b1a5fab4bbc84f664afb1267fa6614d04e2f.mp3", "duration_ms": 7760}, "s1-machine-io.prompt": {"url": "http://localhost:4006/files/lesson-audio/960f86f61d35b3070be17046987c4ed83ac01fa5d1c00ee3d8fab0436112579d.mp3", "hash": "974737ef4f80758db27dc1a39dc313cfc55ab901074d05114a27ccdcb6698708", "bytes": 48384, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/960f86f61d35b3070be17046987c4ed83ac01fa5d1c00ee3d8fab0436112579d.mp3", "duration_ms": 8000}, "s1-machine-io.explanation": {"url": "http://localhost:4006/files/lesson-audio/735d6383cdd8330917746c00e2af75b6067b37056e8e7b32252d96aa53bfc5cb.mp3", "hash": "3d3ad5cdd03648eb37f55413d3e67abbdbf32cf58ccc1a52e7e5c6172fadd8e4", "bytes": 39168, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/735d6383cdd8330917746c00e2af75b6067b37056e8e7b32252d96aa53bfc5cb.mp3", "duration_ms": 6480}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('376d331c-9296-4bfd-9d4f-d2f052be4db4', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "piggy-split", "title": "Dividir o lucro", "locale": "pt-BR", "subject": "money", "objectives": ["Dividir 10 pesos de lucro entre dois cofrinhos: um para a meta do violão e outro para repor ingredientes."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "repartir-ganancia", "xp": 15, "type": "piggy_split", "hints": ["O violão custa 80 pesos, então é melhor economizar mais para ele.", "Mas se você não colocar nada na barraca, amanhã não poderá comprar limões."], "title": "Dividir o lucro", "payload": {"jars": [{"id": "guitarra", "icon": "savings", "label": "Cofrinho do violão", "hint_md": "Para o violão de 80 pesos", "image_url": "http://localhost:4006/files/lesson-images/a06d3807e12c0df75ad40f34ef57b4a544141a71c9168707ff5d5cdc30fd0c83.png"}, {"id": "puesto", "icon": "store", "label": "Cofrinho da barraca", "hint_md": "Para repor limões e copos", "image_url": "http://localhost:4006/files/lesson-images/b1c798faedeb112cc2f8c17e9648eef915f81bac9f48cdc48fb196b813349c54.png"}], "step": 1, "unit": "MXN", "income": 10}, "narrator": {"emotion": "happy", "character": "dina"}, "prompt_md": "Liruf ganhou 10 pesos. Coloque mais no cofrinho do violão do que no da barraca.", "difficulty": 2, "explanation_md": "Liruf colocou 6 no violão e 4 na barraca. Assim, ele economiza mais para sua meta e ainda tem para ingredientes.", "audio_segment_id": "repartir-ganancia.prompt"}], "schema_version": 1}', '{"repartir-ganancia": {"targets": {"puesto": {"max": 4, "min": 1}, "guitarra": {"max": 9, "min": 6}}, "rationale_md": "Debes poner más en la guitarra que en el puesto, pero al menos 1 en el puesto para poder seguir vendiendo."}}', '{"units": {"repartir-ganancia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/c74dfb2240c69ceb88d6a8b7e382a4df3231c204871c2f5aa35f760589dab60b.mp3", "hash": "1c5c9c9299dfa994af103fc7c832f84c76d8ab865a5f3a65ecd885288fabbf7c", "bytes": 33984, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/c74dfb2240c69ceb88d6a8b7e382a4df3231c204871c2f5aa35f760589dab60b.mp3", "duration_ms": 5600}, "repartir-ganancia.hint.1": {"url": "http://localhost:4006/files/lesson-audio/711de5ce2275f8d6a8d362d54c3ac63a03f5bd1ed810eadf6969f9d9a93d723d.mp3", "hash": "2ff26b7cf851765ddd1838b58a5406d700a3a8e476d7f21362c4c0f9d05906da", "bytes": 32976, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/711de5ce2275f8d6a8d362d54c3ac63a03f5bd1ed810eadf6969f9d9a93d723d.mp3", "duration_ms": 5440}, "repartir-ganancia.prompt": {"url": "http://localhost:4006/files/lesson-audio/b627f27ea15a828047b4182a3eaa80432b4dee34991e6562c56986ee0ba43a10.mp3", "hash": "f57fd552af0c179b15fc73022e85131e26b7bc1300138112f625bf63a74387cc", "bytes": 34416, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b627f27ea15a828047b4182a3eaa80432b4dee34991e6562c56986ee0ba43a10.mp3", "duration_ms": 5680}, "repartir-ganancia.explanation": {"url": "http://localhost:4006/files/lesson-audio/17637ef811518f086baf8e395efe0472e6e345e15a191d14e0031ed199b27bc1.mp3", "hash": "c70f83dd46bbebfd34b6c0519a2641a65986d8b4a6a4143bc1b29daa45dc1ab5", "bytes": 52704, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/17637ef811518f086baf8e395efe0472e6e345e15a191d14e0031ed199b27bc1.mp3", "duration_ms": 8720}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('58ff84ee-6d0e-4e43-a182-5b9ffd992543', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "memory-flip", "title": "Match products with their exact payment", "locale": "en-US", "subject": "mixed", "objectives": ["Memory-match each product with the coins that pay for it, using the stand prices: cookie = 3 (1+2), small cup = 5, large pitcher = 20 (10+10)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-memory-flip", "xp": 10, "type": "memory_flip", "hints": ["The cookie costs 3, the small cup 5, and the large pitcher 20."], "title": "Stand prices", "payload": {"pairs": [{"a_md": "Cookie", "b_md": "1 + 2", "a_icon": "cookie", "b_icon": "payments", "a_image_url": "http://localhost:4006/files/lesson-images/f6a651de0e0476e1e039511e898773c0ee5678eeccd886462288d46bceb62bee.png", "b_image_url": "http://localhost:4006/files/lesson-images/c4fcfe2407afd7420e3a9412b4c5c52aa70ea539362fd43756792143001a6c31.png"}, {"a_md": "Small cup", "b_md": "5", "a_icon": "water_drop", "b_icon": "payments", "a_image_url": "http://localhost:4006/files/lesson-images/ed2b34291d93c8e55fa9e893d00549d7426d8370e2707952ec300615298c3985.png", "b_image_url": "http://localhost:4006/files/lesson-images/82048d6ce67c385dbdc9d4bddd50737d50bd412ebeedf9dc853a8d5971d1eb53.png"}, {"a_md": "Large pitcher", "b_md": "10 + 10", "a_icon": "local_bar", "b_icon": "payments", "a_image_url": "http://localhost:4006/files/lesson-images/94a48eabffbf92903e39f230fab01edc2ce1eadb0ee32cb3f6ca6c9aae0fbccc.png", "b_image_url": "http://localhost:4006/files/lesson-images/56490c7515ec208f4812c0edb0412c35617fb239a1f511ca6892e1062acdb80b.png"}]}, "narrator": {"emotion": "encouraging", "character": "zara"}, "prompt_md": "Tap the cards to match each product with its exact payment. Prices: cookie 3, small cup 5, large pitcher 20.", "difficulty": 1, "explanation_md": "Each product has a fixed price: cookie 3, small cup 5, large pitcher 20. When you match correctly, you remember how much to charge.", "audio_segment_id": "s1-memory-flip.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-memory-flip.hint.0": {"url": "http://localhost:4006/files/lesson-audio/0ef69edd403cc12f24d67068fdafa18999de6116d02bccf528dca03f43b3863b.mp3", "hash": "c446cf0bfad056ba1020e309566bd7a6092ffcc504c09deb2d81195151d7dc0c", "bytes": 32544, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/0ef69edd403cc12f24d67068fdafa18999de6116d02bccf528dca03f43b3863b.mp3", "duration_ms": 5360}, "s1-memory-flip.prompt": {"url": "http://localhost:4006/files/lesson-audio/8779ca0b00b0c7b50c5ac4d03514d2869d39ef1a50b1407f7b65157378185dc0.mp3", "hash": "d16e27cf873cece08ab50a397f3d9f9a63571342725c4765a8237181341340ea", "bytes": 54576, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/8779ca0b00b0c7b50c5ac4d03514d2869d39ef1a50b1407f7b65157378185dc0.mp3", "duration_ms": 9040}, "s1-memory-flip.explanation": {"url": "http://localhost:4006/files/lesson-audio/197340fd7b4a16644812b38532d819056c6fc370dfb6767d5a37e727a5fd5c44.mp3", "hash": "d96dc5ff64efeb4a26a67a7d42c0208507770cc95360f306d6d896c7af6fe3f1", "bytes": 58896, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/197340fd7b4a16644812b38532d819056c6fc370dfb6767d5a37e727a5fd5c44.mp3", "duration_ms": 9760}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7f76a2de-27d1-4660-8203-c9ddad8fb861', 'es-MX', '1', '{"meta": {"cast": ["zara"], "slug": "estimate-slider", "title": "Estimar vasos de limonada", "locale": "es-MX", "subject": "mixed", "objectives": ["Estimar cantidades usando una barra deslizante", "Desarrollar sentido numérico al estimar antes de contar"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-estimate-jar", "xp": 15, "type": "estimate_slider", "hints": ["Liruf vendió 4 vasos con una jarra más pequeña. Esta jarra es más grande.", "Piensa: si la jarra pequeña daba 4 vasos, esta más grande da más."], "title": "¿Cuántos vasos salen?", "payload": {"max": 20, "min": 1, "step": 1, "unit": "vasos", "scale": "linear"}, "narrator": {"emotion": "thinking", "character": "zara"}, "image_url": "http://localhost:4006/files/lesson-images/85973cc6d60787bd207ee592d087a036dd6a7a45aad5f744ab3b4e6b446c9f23.png", "prompt_md": "Zara ve la jarra llena. ¿Cuántos vasos crees que puede vender?", "difficulty": 2, "explanation_md": "¡Así es! Esta jarra grande alcanza para 8 vasos. Zara puede venderlos y ganar dinero, como Liruf hizo con sus 4 vasos.", "audio_segment_id": "s1-estimate-jar.prompt"}], "schema_version": 1}', '{"s1-estimate-jar": {"value": 8, "full_credit_delta": 2, "zero_credit_delta": 7}}', '{"units": {"s1-estimate-jar.hint.0": {"url": "http://localhost:4006/files/lesson-audio/5094fa5b7a840025d96797fd6f1dce075455c72b4f36afed9984cf58ffbe6b89.mp3", "hash": "06bae1a8ad751c54bd6cd671b44fba17eae46444998c9713ee16d1ea6bba2be3", "bytes": 34416, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/5094fa5b7a840025d96797fd6f1dce075455c72b4f36afed9984cf58ffbe6b89.mp3", "duration_ms": 5680}, "s1-estimate-jar.hint.1": {"url": "http://localhost:4006/files/lesson-audio/6e74008df16a7b1c3df21c9f64d49d7da474b61311073093c4b8aed883088cc3.mp3", "hash": "130d7dde1dfb8266421b7338196c34a855339032e1d6073018ae5a5670504f8e", "bytes": 29088, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/6e74008df16a7b1c3df21c9f64d49d7da474b61311073093c4b8aed883088cc3.mp3", "duration_ms": 4800}, "s1-estimate-jar.prompt": {"url": "http://localhost:4006/files/lesson-audio/3ce70b8679e36aa47b84d4e613c7e93e8bc9fa07c2b5f6643f966bb8e95fab84.mp3", "hash": "99321ca60edb154551506b2438a7e5a736f21cd04d9d0ea64124ab281e4d1c8f", "bytes": 23328, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/3ce70b8679e36aa47b84d4e613c7e93e8bc9fa07c2b5f6643f966bb8e95fab84.mp3", "duration_ms": 3840}, "s1-estimate-jar.explanation": {"url": "http://localhost:4006/files/lesson-audio/0d074b48b44cc48f2aba4110c1355971c1af9072374df94c06735c17e118491a.mp3", "hash": "2238b9ba7ca10212fc1ff2f2adb753155986fb24949c2b9e2cf788694ab58f37", "bytes": 52704, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/0d074b48b44cc48f2aba4110c1355971c1af9072374df94c06735c17e118491a.mp3", "duration_ms": 8720}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('df879f53-8479-4b98-9651-889fcae66fdc', 'es-MX', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "repaso-true-false", "title": "Repaso: ¿Verdadero o Falso?", "locale": "es-MX", "subject": "mixed", "objectives": ["Distinguir entre ingresos y ganancias en un puesto de limonada", "Recordar que cada vaso cuesta 2 pesos de insumos"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 10, "type": "true_false", "hints": ["Recuerda que Liruf tuvo que comprar limones y azúcar para hacer la limonada."], "title": "¿Verdadero o Falso?", "payload": {"statement_md": "Liruf vendió 10 vasos a 5 pesos, entonces ganó 50 pesos.", "justifications": [{"id": "verdadero", "text_md": "Verdadero, porque 10 × 5 = 50 y eso es lo que recibió"}, {"id": "falso", "text_md": "Falso, porque gastó 20 pesos en ingredientes"}]}, "narrator": {"emotion": "happy", "character": "rho"}, "prompt_md": "Liruf vendió 10 vasos a 5 pesos cada uno. Gastó 20 pesos en limones y azúcar. ¿Ganó 50 pesos?", "difficulty": 1, "explanation_md": "Es falso. Liruf recibió 50 pesos por las ventas, pero gastó 20 pesos en los ingredientes. Así que lo que realmente ganó fue 50 - 20 = 30 pesos. ¡No todo lo que entra es ganancia!", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": false, "correct_justification_id": "falso"}}', '{"units": {"s1-true-false.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9f976bb2e3b4f90be17677db296a0d0a0961bbacaa8bc32246e4293590e4d4c1.mp3", "hash": "56c583c86891cfbd588619f4af7380a83f0c7bc083463d5aed07a0c82fb156c6", "bytes": 35424, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/9f976bb2e3b4f90be17677db296a0d0a0961bbacaa8bc32246e4293590e4d4c1.mp3", "duration_ms": 5840}, "s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/1de8f895d847589d489416e2d52cd7ffe0538ee42524eb48ddd02a3c01de2302.mp3", "hash": "9bf20035af46b8e1552d74dd25a1ecaa063671e3b7aafa21bbe600062f33978f", "bytes": 56448, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/1de8f895d847589d489416e2d52cd7ffe0538ee42524eb48ddd02a3c01de2302.mp3", "duration_ms": 9360}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/2ecdd9ed37c2d4321319c1f3bace7c82dc4b6e0f92d21398554ed0bc7882d685.mp3", "hash": "8767be005dc96832cc6681796a17fb32cb9eba70573bd3d1f429fa43e708656b", "bytes": 87696, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/2ecdd9ed37c2d4321319c1f3bace7c82dc4b6e0f92d21398554ed0bc7882d685.mp3", "duration_ms": 14560}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('000a07f3-d716-40f9-bb5f-2d175c582162', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "spot-error", "title": "Encuentra el error en la cuenta", "locale": "es-MX", "subject": "mixed", "objectives": ["Detectar un error en una suma de ventas", "Leer una gráfica simple de vasos vendidos por día", "Reconocer señales de un mal trato"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-spot-error", "xp": 15, "type": "spot_error", "hints": ["Cuenta cuántos vasos vendió Liruf: 5, luego 5, luego 5. ¿Cuánto suman?", "Si cada vaso cuesta 5 pesos, tres vasos son 5+5+5. ¿Eso da 20?"], "title": "La cuenta que no cuadra", "payload": {"steps": [{"id": "paso1", "text_md": "5 (primer vaso)"}, {"id": "paso2", "text_md": "+ 5 (segundo vaso)"}, {"id": "paso3", "text_md": "+ 5 (tercer vaso)"}, {"id": "paso4", "text_md": "= 20 (total)"}], "context_md": "Liruf vendió 3 vasos de limonada a 5 pesos cada uno. En su cuaderno escribió: 5 + 5 + 5 = 20."}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/9df238abb3fdd77db3ee5bfbe2700f1203a42d480dace5c55e3f650628d6847b.png", "prompt_md": "Liruf anotó: 5 + 5 + 5 = 20. ¿Qué paso está mal?", "difficulty": 2, "explanation_md": "5 + 5 + 5 es 15, no 20. Liruf sumó mal el último paso: puso 20 en vez de 15.", "audio_segment_id": "s1-spot-error.prompt"}], "schema_version": 1}', '{"s1-spot-error": {"error_ids": ["paso4"], "correction_md": "El error está en el total: 5 + 5 + 5 = 15, no 20."}}', '{"units": {"s1-spot-error.hint.0": {"url": "http://localhost:4006/files/lesson-audio/de364dfcc49d7ae6b7c93cbd0d075e5a9a838943d160c2e137a02de6128b788f.mp3", "hash": "2d868295ea330996b85a7b5f11a16aa62a7cb45f2d8d28d67b78d3d8a5acaf08", "bytes": 44928, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/de364dfcc49d7ae6b7c93cbd0d075e5a9a838943d160c2e137a02de6128b788f.mp3", "duration_ms": 7440}, "s1-spot-error.hint.1": {"url": "http://localhost:4006/files/lesson-audio/00ee56384c4ea359b752fea5f49006cb9404808aec8412b5ee519abcc8b5e23b.mp3", "hash": "f0b18c9df73e25943067238dd2578fd9d741ac924efe287368923b6d65e83039", "bytes": 38304, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/00ee56384c4ea359b752fea5f49006cb9404808aec8412b5ee519abcc8b5e23b.mp3", "duration_ms": 6320}, "s1-spot-error.prompt": {"url": "http://localhost:4006/files/lesson-audio/8d8d0fdd2f34384078ef697aa07b225b531681080621dab8745abb2c4f2c7bc9.mp3", "hash": "cec84bc708457b5e8018dbef7e88941df287c9b66686bf122cf1efee74a7f910", "bytes": 33984, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/8d8d0fdd2f34384078ef697aa07b225b531681080621dab8745abb2c4f2c7bc9.mp3", "duration_ms": 5600}, "s1-spot-error.explanation": {"url": "http://localhost:4006/files/lesson-audio/8db4c8877ca66346bf5bc64fc557574f9ff7dbe035731e801d5b725f202690c8.mp3", "hash": "9b2a31aa990761bf63ad0cd265549ea1b68fdcfa88c7ae57d9214bad450bc41d", "bytes": 51264, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/8db4c8877ca66346bf5bc64fc557574f9ff7dbe035731e801d5b725f202690c8.mp3", "duration_ms": 8480}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('35abfab2-f1da-4643-915a-3fdba69f3a63', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fill-blank", "title": "Fill in the blanks in Dina''s notebook", "locale": "en-US", "subject": "mixed", "objectives": ["Complete number sentences about stall savings", "Write exact number answers (sums up to 10, counts up to 20)"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ahorro", "xp": 10, "type": "fill_blank", "hints": ["Count the coins he saved: 3 and then 2.", "3 plus 2 is..."], "title": "Savings of the day", "payload": {"bank": [{"id": "b1", "text_md": "5"}, {"id": "b2", "text_md": "1"}], "mode": "typed", "text_md": "Liruf saved 3 pesos and then 2 more. In total he saved {{1}} pesos."}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf saved 5 pesos. How much did he save in total?", "difficulty": 1, "explanation_md": "Liruf saved 3 pesos and then 2 more, so he has 5 pesos saved. Great!", "audio_segment_id": "s1-ahorro.prompt"}], "schema_version": 1}', '{"s1-ahorro": {"gaps": [{"gap": 1, "accept": ["5", "cinco"], "bank_id": "b1"}]}}', '{"units": {"s1-ahorro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a71bec64b71d822416f4f0c328a25c909e0c6a87ff00b7b303b3a1bc57e372ae.mp3", "hash": "7d91ddcbbb87be8b22d51c16602fe2edd390ce3b0cc8e264ea8b2e35c60f5923", "bytes": 19584, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/a71bec64b71d822416f4f0c328a25c909e0c6a87ff00b7b303b3a1bc57e372ae.mp3", "duration_ms": 3200}, "s1-ahorro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/aeb10154cd137e8e0fc6adbb0c8059cc44f49027bb46a7cae377ce172be49626.mp3", "hash": "966045466a37ce756cb371589278a9c42168a0f2ce587a7849ae614e5e151d09", "bytes": 10368, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/aeb10154cd137e8e0fc6adbb0c8059cc44f49027bb46a7cae377ce172be49626.mp3", "duration_ms": 1680}, "s1-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/f74969a57895153d8f8830cfbe252d18c2cab2763000e937df6786adb01aea32.mp3", "hash": "b373a268d7e6fec793267e76cf18785cdb3ddb3ead9bb1b0ba8ebe660716cf4a", "bytes": 22896, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f74969a57895153d8f8830cfbe252d18c2cab2763000e937df6786adb01aea32.mp3", "duration_ms": 3760}, "s1-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/bc4a1a7c3e2b76b8768a4e383302bec9463d9b24df4eaf77f5a167db251bda78.mp3", "hash": "fb70c405f1088e481c6c2500fd0cb3b7909fd2bde5488f216472d0a41ba9b469", "bytes": 32544, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/bc4a1a7c3e2b76b8768a4e383302bec9463d9b24df4eaf77f5a167db251bda78.mp3", "duration_ms": 5360}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ea98847f-02a1-4527-97a4-36921728b56d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "rho"], "slug": "cause-effect", "title": "Cause and effect at the stand", "locale": "en-US", "subject": "mixed", "objectives": ["Connect causes and effects at the stand: sunny day → more thirst → more cups sold; doubling the price → fewer customers."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-causa-efecto", "xp": 10, "type": "cause_effect", "hints": ["Think: what happened first in the day?"], "title": "What happened at the stand?", "payload": {"slots": 5, "events": [{"id": "e1", "text_md": "It''s very sunny"}, {"id": "e2", "text_md": "People are thirstier"}, {"id": "e3", "text_md": "Liruf sells 10 cups at $2"}, {"id": "e4", "text_md": "Liruf raises the price to $4"}, {"id": "e5", "text_md": "Only sells 3 cups"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "prompt_md": "Liruf sold 10 cups at $2 each. Then he raised the price to $4 and sold 3. Order the events.", "difficulty": 1, "explanation_md": "With sun, people are thirstier and buy more. But if the price goes up too much, they buy less. Liruf learned that he shouldn''t raise the price so much.", "audio_segment_id": "s1-causa-efecto.prompt"}], "schema_version": 1}', '{"s1-causa-efecto": {"chain": ["e1", "e2", "e3", "e4", "e5"]}}', '{"units": {"s1-causa-efecto.hint.0": {"url": "http://localhost:4006/files/lesson-audio/85413edfe9c852225ab9e6104f62c7e7e6d4a6e2e8762018c7318f80b5f847b0.mp3", "hash": "da22f6dc81698c79147dd5b4bc7afdcca6f3de5525bd5e0cda11b9983480a40c", "bytes": 11808, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/85413edfe9c852225ab9e6104f62c7e7e6d4a6e2e8762018c7318f80b5f847b0.mp3", "duration_ms": 1920}, "s1-causa-efecto.prompt": {"url": "http://localhost:4006/files/lesson-audio/5bc9e6b49e1e5bf336312a705976a70fe0af3dd06dd314213ab3f53078b040d3.mp3", "hash": "07a97b50f15d7a6dd56b44e4ad8014de62de1dc8d173cd0c7b8291767786f58b", "bytes": 40176, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/5bc9e6b49e1e5bf336312a705976a70fe0af3dd06dd314213ab3f53078b040d3.mp3", "duration_ms": 6640}, "s1-causa-efecto.explanation": {"url": "http://localhost:4006/files/lesson-audio/9ad52136995e2f74b63b71ddead7df8a35cace594117f32f3e72bb150214f925.mp3", "hash": "b1bac3aae7c978d72727a0999aca38fae726f7d0f9c8891cb2fb928548201138", "bytes": 46944, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9ad52136995e2f74b63b71ddead7df8a35cace594117f32f3e72bb150214f925.mp3", "duration_ms": 7760}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c5c3f5b2-2c4b-4aa8-bd76-cdcb594e0dda', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "concept-reveal", "title": "Cost and profit", "locale": "en-US", "subject": "mixed", "objectives": ["Understand that money is earned by offering something others want, and that a clear goal (the 80-peso guitar) helps you get started."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-concept-reveal", "xp": 0, "type": "concept_reveal", "hints": ["Cost is what you spend to make the lemonade.", "Profit is what you have left after selling."], "title": "Cost and profit", "payload": {"cards": [{"icon": "payments", "back_md": "What you spend on lemons and sugar to make the lemonade.", "front_md": "**Cost**", "image_url": "http://localhost:4006/files/lesson-images/4952f7929865542128aeead93e3f2f71ed49fc0a201b110e69472e3dbf5eff42.png"}, {"icon": "monetization_on", "back_md": "What you have left after paying the cost of the ingredients.", "front_md": "**Profit**", "image_url": "http://localhost:4006/files/lesson-images/cd5f535083bf8fd6d39cd293ecfd50865545542ab9f05cde2d1c79ff8f81911b.png"}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Tap each card to discover what is cost and what is profit.", "difficulty": 1, "explanation_md": "Cost is what you spend on lemons and sugar. Profit is what you have left after paying the cost. That''s how Liruf knows how much to save for his guitar!", "audio_segment_id": "s1-concept-reveal.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-concept-reveal.hint.0": {"url": "http://localhost:4006/files/lesson-audio/5ffb18375a4b025c9e0ba8598bb7c9d75ad473d4d30dd4ccd38f1dd50fd9b87c.mp3", "hash": "b10023be8bfeaafe0308e243a2bb12e25318acde5767dc4e720823135d00e545", "bytes": 17136, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/5ffb18375a4b025c9e0ba8598bb7c9d75ad473d4d30dd4ccd38f1dd50fd9b87c.mp3", "duration_ms": 2800}, "s1-concept-reveal.hint.1": {"url": "http://localhost:4006/files/lesson-audio/bff955c7c31dfede6f19b59691e2f2a194d2d785e04256538c0a3c78eef596b8.mp3", "hash": "613a89f8b19331ae6c4d1e3397cfb140c761b4d974690437980670cd2b610905", "bytes": 15696, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/bff955c7c31dfede6f19b59691e2f2a194d2d785e04256538c0a3c78eef596b8.mp3", "duration_ms": 2560}, "s1-concept-reveal.prompt": {"url": "http://localhost:4006/files/lesson-audio/3ff917b997aa0eec1a6fb2248944ad61068f477fa83474b6364ef6bd472f930d.mp3", "hash": "649b55a3cf3efe068e92b99234b852bb72b1c1a972b8a97def67e67b5de84e1f", "bytes": 25344, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/3ff917b997aa0eec1a6fb2248944ad61068f477fa83474b6364ef6bd472f930d.mp3", "duration_ms": 4160}, "s1-concept-reveal.card.0.back": {"url": "http://localhost:4006/files/lesson-audio/7c3b0ceb7642372111fa95e62dd731d98b134e9f27e086d5603f2e2bb940b8bd.mp3", "hash": "05008f82e034ac357cd5aa2da0fad1e8b94c2e687c04f4d6702ff2aef59966b0", "bytes": 21024, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/7c3b0ceb7642372111fa95e62dd731d98b134e9f27e086d5603f2e2bb940b8bd.mp3", "duration_ms": 3440}, "s1-concept-reveal.card.1.back": {"url": "http://localhost:4006/files/lesson-audio/3efbb3754d5d9eda86ba17053283399daef81cc050baa23467353f3ffb560ab2.mp3", "hash": "82d91d8dec3db86d970aed940d2b0c0950104b3d613e168420747450d94be6a8", "bytes": 22464, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/3efbb3754d5d9eda86ba17053283399daef81cc050baa23467353f3ffb560ab2.mp3", "duration_ms": 3680}, "s1-concept-reveal.explanation": {"url": "http://localhost:4006/files/lesson-audio/c7299c9d264883413e188ddb8a8bff67ef4090c6093696c18646ab0f8b3a6f6a.mp3", "hash": "820d8a96d9e27fce21fbc793b8c2d3e0a45bf113eccfe77432fdf70d8bbfbb1a", "bytes": 55584, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/c7299c9d264883413e188ddb8a8bff67ef4090c6093696c18646ab0f8b3a6f6a.mp3", "duration_ms": 9200}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('97238255-709d-4d86-8930-3ea433f54f7d', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "checkpoint", "title": "A noite antes de abrir", "locale": "pt-BR", "subject": "mixed", "objectives": ["Revisar a meta do violão de 80 pesos, o preço da limonada a 5 pesos o copo, e que o lucro é o que sobra depois de pagar o custo e vai para o pote do violão."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "checkpoint-noche", "xp": 0, "type": "checkpoint", "hints": [], "title": "A noite antes de abrir", "payload": {"recap_md": "Liruf já tem sua meta colada na parede: o violão de **80 pesos**. O cartaz diz: limonada a **5 pesos o copo**. E o mais importante: de cada copo, o que sobra depois do custo é o **lucro** que vai direto para o pote do violão. Amanhã é o teste de verdade!", "mood_prompt_md": "Quão perto você já sente esse violão, Liruf?"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Dina e Liruf revisam o que têm pronto.", "difficulty": 1, "explanation_md": "Ter uma meta clara, um preço e saber que o lucro enche o pote faz com que amanhã seja real.", "audio_segment_id": "checkpoint-noche.prompt"}], "schema_version": 1}', '{}', '{"units": {"checkpoint-noche.recap": {"url": "http://localhost:4006/files/lesson-audio/d72ed497fb8aa43c2ce17ebd5acfe0286aa880339d8d251573917912f6cedab4.mp3", "hash": "ba3f5dec9eff7165fddb223c21e7c4b913fda10a10839f2c618507d0a989eeb1", "bytes": 114048, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d72ed497fb8aa43c2ce17ebd5acfe0286aa880339d8d251573917912f6cedab4.mp3", "duration_ms": 18960}, "checkpoint-noche.prompt": {"url": "http://localhost:4006/files/lesson-audio/7b0536fc89528ebd99336edbfb93d6bfcae9e93ff6ee90980808b8c5b1630714.mp3", "hash": "02719984d83fa7c2709ddb769550f7bb1bc68a2f0c645fdb06b050388247b492", "bytes": 17568, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7b0536fc89528ebd99336edbfb93d6bfcae9e93ff6ee90980808b8c5b1630714.mp3", "duration_ms": 2880}, "checkpoint-noche.explanation": {"url": "http://localhost:4006/files/lesson-audio/bc245b249801fcef8948b4337152fec974bdeed6b8f0bc9fa6d8b4bc47763ccc.mp3", "hash": "7cd53d834d748417dc0e499cfd4ab8d14645d084d35ff5d6cfb379e6476c66da", "bytes": 41616, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/bc245b249801fcef8948b4337152fec974bdeed6b8f0bc9fa6d8b4bc47763ccc.mp3", "duration_ms": 6880}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('3c639b5e-01f3-469e-95e3-a52a215847f4', 'pt-BR', '1', E'{"meta": {"cast": ["rho"], "slug": "fact-opinion", "title": "Fatos e opiniões na barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Separar fatos de opiniões em frases da barraca de limonada"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-fact-opinion", "xp": 10, "type": "fact_opinion", "hints": ["Um fato pode ser medido ou contado. Quanto custa o copo?", "Uma opinião diz como alguém se sente. Não pode ser comprovada."], "title": "Fato ou opinião", "payload": {"statements": [{"id": "s1", "text_md": "O copo de limonada custa 5 pesos."}, {"id": "s2", "text_md": "Minha limonada é a mais gostosa do mundo."}, {"id": "s3", "text_md": "Hoje vendi 12 copos de limonada."}, {"id": "s4", "text_md": "Esta limonada tem um gosto melhor que a da Dina."}]}, "narrator": {"emotion": "neutral", "character": "rho"}, "image_url": "http://localhost:4006/files/lesson-images/d95172984c3619a14cf765c5dce3f56b91b432ca7785ee9447245d01390800ca.png", "prompt_md": "Rho ouviu um cliente dizer: \\"Sua limonada é a melhor!\\" Isso é um fato ou uma opinião? Toque nas frases que são FATOS.", "difficulty": 1, "explanation_md": "O preço do copo (5 pesos) é um fato porque pode ser verificado. \\"A mais gostosa\\" é uma opinião, porque cada pessoa pode pensar diferente. Rho aprendeu a não acreditar em promessas sem provas.", "audio_segment_id": "s1-fact-opinion.prompt"}], "schema_version": 1}', '{"s1-fact-opinion": {"fact_ids": ["s1", "s3"]}}', '{"units": {"s1-fact-opinion.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ac3adc539b4e8d8ff1848aae389392563f1e421e6c982df2c38c3aeefecf5147.mp3", "hash": "f73b760f99a718f4b2afbc03b1f69262c3b230e51f0de0a3a4c32028c66b0ee5", "bytes": 27648, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/ac3adc539b4e8d8ff1848aae389392563f1e421e6c982df2c38c3aeefecf5147.mp3", "duration_ms": 4560}, "s1-fact-opinion.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a7980ee50b15c6b55312cbbebb556eae824853b178ff22705ccbafd0f4f7c9f3.mp3", "hash": "ccc977358b87190c30a760c883fb45629fc0f8fd22e8695e031ab2a9e6f051e4", "bytes": 28656, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/a7980ee50b15c6b55312cbbebb556eae824853b178ff22705ccbafd0f4f7c9f3.mp3", "duration_ms": 4720}, "s1-fact-opinion.prompt": {"url": "http://localhost:4006/files/lesson-audio/909e4330d8f273b7e9aa75044f559429a80b3a09eab56bbc523b5bde107f6424.mp3", "hash": "59d201637329b77fcbaa9d81eab550167203ffbf3166f889a307871f1ae59d95", "bytes": 57024, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/909e4330d8f273b7e9aa75044f559429a80b3a09eab56bbc523b5bde107f6424.mp3", "duration_ms": 9440}, "s1-fact-opinion.explanation": {"url": "http://localhost:4006/files/lesson-audio/2cdccfbec2e66a1405ec0b8d6407d176ad62daa334001f8d06d53e606e9b7c3e.mp3", "hash": "71efc95284067804529bcf1d643268cbbe3eb19538342a445700a7c6874d5cf2", "bytes": 91008, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/2cdccfbec2e66a1405ec0b8d6407d176ad62daa334001f8d06d53e606e9b7c3e.mp3", "duration_ms": 15120}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4dcc7a9f-f2f6-4b40-abd4-a522d168e446', 'en-US', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "flash-match", "title": "Flash Match: Stand Concepts", "locale": "en-US", "subject": "mixed", "objectives": ["Match key stand words (savings, cost, profit) with their concrete examples."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-flash-match", "xp": 10, "type": "flash_match", "hints": ["Think about what each word means at the lemonade stand."], "title": "Quick match!", "payload": {"left": [{"id": "ahorro", "text_md": "Savings", "image_url": "http://localhost:4006/files/lesson-images/fc01f0ebffe45301891a2d5d9ff120a402ca189f1f471d246f609fecf21c3d35.png"}, {"id": "costo", "text_md": "Cost", "image_url": "http://localhost:4006/files/lesson-images/2d81098ceaf7d0c2f3b19823938b8b75c9c404c0a4a8ecc0dc336317f12a9ea7.png"}, {"id": "ganancia", "text_md": "Profit", "image_url": "http://localhost:4006/files/lesson-images/1f17ab1e27dd990361ef23f07b45d6a24b083b1a9e846d0fd6e69fd70280d4a3.png"}], "right": [{"id": "alcancia", "text_md": "Dina''s piggy bank"}, {"id": "limones", "text_md": "5 lemons for lemonade"}, {"id": "lo-que-sobra", "text_md": "Leftover coins"}], "seconds": 30}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Match each word with its example.", "difficulty": 1, "explanation_md": "Savings is what Dina keeps in her piggy bank for the skateboard. Cost is the 5 lemons she bought to make lemonade. Profit is what''s left after selling.", "audio_segment_id": "s1-flash-match.prompt"}], "schema_version": 1}', '{"s1-flash-match": {"pairs": [["ahorro", "alcancia"], ["costo", "limones"], ["ganancia", "lo-que-sobra"]]}}', '{"units": {"s1-flash-match.hint.0": {"url": "http://localhost:4006/files/lesson-audio/5fdca91d80254d36c3d2772baf458caf0a3a9e28040511b35e82914144326058.mp3", "hash": "04fbef61fd0bd8e244351e766fe2974498058e48b85e7d8aeec5389e7a0e9023", "bytes": 21888, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/5fdca91d80254d36c3d2772baf458caf0a3a9e28040511b35e82914144326058.mp3", "duration_ms": 3600}, "s1-flash-match.prompt": {"url": "http://localhost:4006/files/lesson-audio/6c2e5b97147bfb519bc91972d2cb9f7fb7cd1b03713f58bdf8ef292082025833.mp3", "hash": "c12134e00eb5f572703efad55080542ddc95ed83e6b00dc9adcd1b7c3576671f", "bytes": 13248, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/6c2e5b97147bfb519bc91972d2cb9f7fb7cd1b03713f58bdf8ef292082025833.mp3", "duration_ms": 2160}, "s1-flash-match.explanation": {"url": "http://localhost:4006/files/lesson-audio/ec336702586d449300d4038de8629947f1515e864b7045034d0302b0079d8ed6.mp3", "hash": "109b01f2df36a44865a53dbd6bde274493f168fb693a5911c21254e15abc06f8", "bytes": 57888, "voice": "qwen-tts-vc-zara_en_us-voice-20260714105641492-c927", "file_id": "lesson-audio/ec336702586d449300d4038de8629947f1515e864b7045034d0302b0079d8ed6.mp3", "duration_ms": 9600}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('08604886-c155-4f4b-85dd-0b5b853997e1', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "quiz-mcq", "title": "Fair price for lemonade", "locale": "en-US", "subject": "money", "objectives": ["Choosing the fair price for a glass of lemonade by comparing options."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-precio-justo", "xp": 10, "type": "quiz_mcq", "hints": ["Think: if it costs too much, no one buys; if it costs too little, Liruf loses money.", "One glass costs 5 pesos to make. What price gives profit without scaring away customers?"], "title": "How much per glass?", "payload": {"options": [{"id": "op1", "text_md": "50 pesos", "rationale_md": "50 pesos is very expensive for a glass of lemonade. Customers would go to another stand."}, {"id": "op2", "text_md": "5 pesos"}, {"id": "op3", "text_md": "1 peso", "rationale_md": "1 peso isn''t enough to even buy the lemons. Liruf would lose money on each glass."}], "shuffle": true}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf sets the price for a glass of lemonade. Which one is fair?", "difficulty": 1, "explanation_md": "5 pesos is fair: it covers the cost of 5 pesos and people buy. 50 pesos is too expensive; 1 peso doesn''t even cover the lemons.", "audio_segment_id": "s1-precio-justo.prompt"}], "schema_version": 1}', '{"s1-precio-justo": {"correct_option_id": "op2"}}', '{"units": {"s1-precio-justo.hint.0": {"url": "http://localhost:4006/files/lesson-audio/1df3ea28da8d4830f759ae0c951ae8235a7896afd2f53473285cb9186bf10438.mp3", "hash": "63a22c11f96a65829eb757f47c91bd37a3479c21dc38a0f019210ab208e09068", "bytes": 32976, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/1df3ea28da8d4830f759ae0c951ae8235a7896afd2f53473285cb9186bf10438.mp3", "duration_ms": 5440}, "s1-precio-justo.hint.1": {"url": "http://localhost:4006/files/lesson-audio/4695a9b63e9accfc382618c1e9871cf5b62e209dffe4b00c499a89f1f9f0a4e4.mp3", "hash": "fd8c8c67be1d88bf34ab46ffd3f29607cb5b3e75f53e6a4cdb5435ba5a788efe", "bytes": 33984, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4695a9b63e9accfc382618c1e9871cf5b62e209dffe4b00c499a89f1f9f0a4e4.mp3", "duration_ms": 5600}, "s1-precio-justo.prompt": {"url": "http://localhost:4006/files/lesson-audio/a738f951cb1b8b180f245a89e6b0dc5c464d7a322d83bec3c2d735b1c65978e5.mp3", "hash": "853463f2016eb7bdc95cae2bf00d14a08f3d19d0933e0b6e5ebed1b393315c95", "bytes": 24768, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/a738f951cb1b8b180f245a89e6b0dc5c464d7a322d83bec3c2d735b1c65978e5.mp3", "duration_ms": 4080}, "s1-precio-justo.choices": {"url": "http://localhost:4006/files/lesson-audio/22b30ed86a36ca499c6a56170bf320c7ace263bd994e5d77a316b6eea570c36a.mp3", "hash": "69cfb391fcb9e04c02ab23f2a3148e5ba0e66689b50be61f39fc6cfc59f89b30", "bytes": 19584, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/22b30ed86a36ca499c6a56170bf320c7ace263bd994e5d77a316b6eea570c36a.mp3", "duration_ms": 3200}, "s1-precio-justo.explanation": {"url": "http://localhost:4006/files/lesson-audio/e606604dddf661dafa848144ae2da54b9ef70681e361ae543027fcf47d3b708c.mp3", "hash": "dd1953cb3a10d930ae44ac93c4242dbd44aed5f41e07cf833f064bc82aa6cf49", "bytes": 51264, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e606604dddf661dafa848144ae2da54b9ef70681e361ae543027fcf47d3b708c.mp3", "duration_ms": 8480}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('99bea18a-9bc0-4fca-91fe-aa5b44c0ea6e', 'pt-BR', '1', '{"meta": {"cast": ["liruf"], "slug": "picture-choice", "title": "Onde guardar os lucros?", "locale": "pt-BR", "subject": "mixed", "objectives": ["Escolher o lugar mais seguro para guardar dinheiro comparando opções"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-guardar-ganancias", "xp": 10, "type": "picture_choice", "hints": ["Pense: onde o dinheiro não pode cair nem se perder?", "Procure um lugar que tenha cadeado ou chave."], "title": "Lugar seguro", "payload": {"options": [{"id": "alcancia", "icon": "savings", "label": "Cofrinho com chave", "image_url": "http://localhost:4006/files/lesson-images/fc53490dcfdebcbd1c908e67f9cfd5dfbace2ec64bb17a3760c5b410e23a5ca1.png"}, {"id": "bolsillo", "icon": "checkroom", "label": "Bolso furado", "image_url": "http://localhost:4006/files/lesson-images/3ed6394fc1abacd88a06145cd482977b16e457ec3e203c3995af07f6b4210993.png", "rationale_md": "O bolso furado deixa as moedas caírem, então não é seguro."}, {"id": "mesa", "icon": "table_restaurant", "label": "Mesa da barraca", "image_url": "http://localhost:4006/files/lesson-images/d667355eaf618db630a17da6e8598bb71fe4c801dfa628caeee5bb03ac2b5b43.png", "rationale_md": "A mesa da barraca está à vista de todos e qualquer um pode pegar o dinheiro."}]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Ontem Liruf economizou 5 reais de cada venda. Hoje já tem 20 reais. Onde ele guarda melhor?", "difficulty": 1, "explanation_md": "O cofrinho com chave é o mais seguro porque ninguém mais pode abri-lo. O bolso furado deixa as moedas caírem e a mesa da barraca está à vista de todos.", "audio_segment_id": "s1-guardar-ganancias.prompt"}], "schema_version": 1}', '{"s1-guardar-ganancias": {"correct_option_id": "alcancia"}}', '{"units": {"s1-guardar-ganancias.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e55590a86e6ab73d670821a342a50e2988ca4b67a041d2690a6998b4c227a079.mp3", "hash": "bdf2f961f0c0a4610347ca821cc55493fffe98f7604c457b430c94e9bea30c2e", "bytes": 21456, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/e55590a86e6ab73d670821a342a50e2988ca4b67a041d2690a6998b4c227a079.mp3", "duration_ms": 3520}, "s1-guardar-ganancias.hint.1": {"url": "http://localhost:4006/files/lesson-audio/9e166bed11c15ac162cd8a71ce9689fc1b70630bb0a33a0d6255132f4dca8f5c.mp3", "hash": "183b796ea3f891f89444a1db14f9d2092c5574f93bca65f50f39b103f0d904ba", "bytes": 17136, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/9e166bed11c15ac162cd8a71ce9689fc1b70630bb0a33a0d6255132f4dca8f5c.mp3", "duration_ms": 2800}, "s1-guardar-ganancias.prompt": {"url": "http://localhost:4006/files/lesson-audio/8c38d0413c40e9cfb4aa13dec037744baafceed61a4dff98bf06d0421fe8062a.mp3", "hash": "58ed175923b0f0cdd6734b0981277a8bd440ed0d5caf33f7eeff27651c4d2f34", "bytes": 47808, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/8c38d0413c40e9cfb4aa13dec037744baafceed61a4dff98bf06d0421fe8062a.mp3", "duration_ms": 7920}, "s1-guardar-ganancias.choices": {"url": "http://localhost:4006/files/lesson-audio/2d394d90d87b8ca6f5d5487e18948e6ecaa7f3e6b60e4d107f1d12fc7613d76e.mp3", "hash": "7d104123a6d68ded4a1247d48431c8474b2180e6c95cef249ac77132f7b70187", "bytes": 28656, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/2d394d90d87b8ca6f5d5487e18948e6ecaa7f3e6b60e4d107f1d12fc7613d76e.mp3", "duration_ms": 4720}, "s1-guardar-ganancias.explanation": {"url": "http://localhost:4006/files/lesson-audio/ab719b701694ea1a5cd3167159ba5aff7ef597794ea5dc9292ef7150c4de0c2f.mp3", "hash": "f335691b8346298c2529648534b9f2877d891d6a23cedcc402a9890af71550c4", "bytes": 58896, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/ab719b701694ea1a5cd3167159ba5aff7ef597794ea5dc9292ef7150c4de0c2f.mp3", "duration_ms": 9760}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c9d7856b-a75e-414e-ae61-e324a19a350d', 'pt-BR', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "measure-read", "title": "Medir a limonada justa", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ler a linha do líquido em um copo medidor para servir copos iguais de 5 reais."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-leer-jarra", "xp": 10, "type": "measure_read", "hints": ["Observe a linha azul do líquido. Está na marca de 200, 250 ou 300 ml?"], "title": "Até onde chegou?", "payload": {"max": 300, "min": 0, "unit": "ml", "ticks": 3, "instrument": "beaker", "pointer_value": 250}, "narrator": {"emotion": "neutral", "character": "rho"}, "image_url": "http://localhost:4006/files/lesson-images/d98c0b5d008fab963f16bc862566d3f707470eff34bb20f9ef8e8f0055a6b605.png", "prompt_md": "Rho serviu limonada. Até que linha o líquido chegou?", "difficulty": 1, "explanation_md": "O líquido chegou até a linha de 250 ml. Assim todos os copos de 5 reais ficam iguais, como na balança do escambo.", "audio_segment_id": "s1-leer-jarra.prompt"}], "schema_version": 1}', '{"s1-leer-jarra": {"value": 250, "tolerance": 0}}', '{"units": {"s1-leer-jarra.hint.0": {"url": "http://localhost:4006/files/lesson-audio/ca53b3f916c8e9edf09f6fc6b1f42a11e5039fe9e300768741ecbf06858d851a.mp3", "hash": "f884b36a2a6bda62f7a5b1311fa33cf7169a52e6ab0d749b9d91273cd4e3263d", "bytes": 45936, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/ca53b3f916c8e9edf09f6fc6b1f42a11e5039fe9e300768741ecbf06858d851a.mp3", "duration_ms": 7600}, "s1-leer-jarra.prompt": {"url": "http://localhost:4006/files/lesson-audio/a425c4da3f8eba2cef64c3af2085e5b6cb38361fd6da67bec5f2eee0bdf6d9ba.mp3", "hash": "01b05398274dd5df74d8a28ba8112c6ee18cab029eaedef40985f2bfcc5512d1", "bytes": 25344, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/a425c4da3f8eba2cef64c3af2085e5b6cb38361fd6da67bec5f2eee0bdf6d9ba.mp3", "duration_ms": 4160}, "s1-leer-jarra.explanation": {"url": "http://localhost:4006/files/lesson-audio/688de735e1c7ac80524dac2a8af388c98428388dc3e593bfc05c05097c7b2771.mp3", "hash": "76e95f6ce7d6adf36f9234eecb514d505dab9eda653a1bcb436a99a4608be3a0", "bytes": 64224, "voice": "qwen-tts-vc-rho_pt_br-voice-20260714105905005-6480", "file_id": "lesson-audio/688de735e1c7ac80524dac2a8af388c98428388dc3e593bfc05c05097c7b2771.mp3", "duration_ms": 10640}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ec92e8b8-2834-4bff-88e8-59733b2e617a', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "repaso-quiz-mcq", "title": "Repaso rápido del puesto", "locale": "es-MX", "subject": "money", "objectives": ["Responder de memoria la ganancia por vaso de limonada", "Recordar el precio justo y el ahorro"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia-vaso", "xp": 10, "type": "quiz_mcq", "hints": ["¿Cuánto te queda después de pagar los ingredientes?"], "title": "Ganancia por vaso", "payload": {"options": [{"id": "a", "text_md": "3 pesos", "rationale_md": "Correcto. 5 - 2 = 3 pesos de ganancia por vaso."}, {"id": "b", "text_md": "2 pesos", "rationale_md": "Ese es el costo de los ingredientes, no la ganancia. La ganancia es lo que sobra después de pagar los ingredientes."}, {"id": "c", "text_md": "5 pesos", "rationale_md": "Ese es el precio del vaso, pero no has restado lo que cuestan los ingredientes. La ganancia es menos."}, {"id": "d", "text_md": "7 pesos", "rationale_md": "Sumaste el precio y el costo, pero la ganancia se calcula restando, no sumando."}], "shuffle": true}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Cada vaso cuesta 5 pesos. Los ingredientes cuestan 2 pesos. ¿Cuánto ganas por vaso?", "difficulty": 1, "explanation_md": "Ganas 3 pesos por vaso: 5 pesos que cobras menos 2 pesos de ingredientes. Así calculaste la ganancia ayer.", "audio_segment_id": "s1-ganancia-vaso.prompt"}], "schema_version": 1}', '{"s1-ganancia-vaso": {"correct_option_id": "a"}}', '{"units": {"s1-ganancia-vaso.hint.0": {"url": "http://localhost:4006/files/lesson-audio/f1a597a11387242caf3fd0fc2138841b2de63b6bca0d8fea94570f2ed851b1a5.mp3", "hash": "050f5b193ed3b29629fa242c2e872d0620719fd8d2ead8796ad80eacc1a24a58", "bytes": 17136, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f1a597a11387242caf3fd0fc2138841b2de63b6bca0d8fea94570f2ed851b1a5.mp3", "duration_ms": 2800}, "s1-ganancia-vaso.prompt": {"url": "http://localhost:4006/files/lesson-audio/7b39d0a84302d8a06a74893bc766899618def8a727d3c211c6b550503f447029.mp3", "hash": "c20cc0f37c9933bfc86e45a53e1473313ec03450e8a1a8ae04e9338e40f8d76d", "bytes": 38736, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7b39d0a84302d8a06a74893bc766899618def8a727d3c211c6b550503f447029.mp3", "duration_ms": 6400}, "s1-ganancia-vaso.choices": {"url": "http://localhost:4006/files/lesson-audio/65c9680846b817295d5919d1a233f0e5c4f12b33acfe04b16f672c0a291cfa5e.mp3", "hash": "ae1c1f2c766a66b6a59ecee167792930ab0bda9f76a39e0183c3c834521e2225", "bytes": 25344, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/65c9680846b817295d5919d1a233f0e5c4f12b33acfe04b16f672c0a291cfa5e.mp3", "duration_ms": 4160}, "s1-ganancia-vaso.explanation": {"url": "http://localhost:4006/files/lesson-audio/d6b74a4387d3a0f16ba1db83518f0ad7b39e59063e6711a2da77440db4e23774.mp3", "hash": "59c98593324e02e278852c76bc436d5de00ad70c178d4281747062781c28255c", "bytes": 49248, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d6b74a4387d3a0f16ba1db83518f0ad7b39e59063e6711a2da77440db4e23774.mp3", "duration_ms": 8160}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0a2bda3a-e275-46b8-b659-a7ad68a0afb3', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "lightning-round", "title": "Ronda relámpago", "locale": "es-MX", "subject": "money", "objectives": ["Calcular cambio rápido para pedidos de 1-3 vasos a 5 pesos cada uno, pagando con 10 o 20 pesos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "lightning-round-1", "xp": 15, "type": "lightning_round", "hints": ["Primero suma el costo de los vasos: 2 vasos × 5 pesos = 10 pesos.", "Luego resta ese total del pago: 20 − 10 = ?"], "title": "Ronda relámpago", "payload": {"questions": [{"id": "q1", "options": [{"id": "a", "text_md": "10 pesos"}, {"id": "b", "text_md": "5 pesos"}, {"id": "c", "text_md": "15 pesos"}, {"id": "d", "text_md": "20 pesos"}], "prompt_md": "Doña Rosa pide 2 vasos. Paga con 20. ¿Cuánto cambio le das?"}, {"id": "q2", "options": [{"id": "a", "text_md": "5 pesos"}, {"id": "b", "text_md": "10 pesos"}, {"id": "c", "text_md": "0 pesos"}, {"id": "d", "text_md": "2 pesos"}], "prompt_md": "Don Toño pide 1 vaso. Paga con 10. ¿Cuánto cambio le das?"}, {"id": "q3", "options": [{"id": "a", "text_md": "5 pesos"}, {"id": "b", "text_md": "10 pesos"}, {"id": "c", "text_md": "15 pesos"}, {"id": "d", "text_md": "20 pesos"}], "prompt_md": "La señora Lupita pide 3 vasos. Paga con 20. ¿Cuánto cambio le das?"}, {"id": "q4", "options": [{"id": "a", "text_md": "0 pesos"}, {"id": "b", "text_md": "5 pesos"}, {"id": "c", "text_md": "10 pesos"}, {"id": "d", "text_md": "2 pesos"}], "prompt_md": "El niño Juan pide 2 vasos. Paga con 10. ¿Cuánto cambio le das?"}, {"id": "q5", "options": [{"id": "a", "text_md": "15 pesos"}, {"id": "b", "text_md": "10 pesos"}, {"id": "c", "text_md": "5 pesos"}, {"id": "d", "text_md": "20 pesos"}], "prompt_md": "Doña Chuy pide 1 vaso. Paga con 20. ¿Cuánto cambio le das?"}, {"id": "q6", "options": [{"id": "a", "text_md": "0 pesos"}, {"id": "b", "text_md": "5 pesos"}, {"id": "c", "text_md": "10 pesos"}, {"id": "d", "text_md": "15 pesos"}], "prompt_md": "Don Beto pide 3 vasos. Paga con 10. ¿Cuánto cambio le das?"}], "seconds_per_q": 15}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Doña Rosa pide 2 vasos. Paga con 20. ¿Cuánto cambio le das?", "difficulty": 2, "explanation_md": "El costo de 2 vasos es 10 pesos. Resta 10 de 20 y obtienes 10 pesos de cambio.", "audio_segment_id": "lightning-round-1.prompt"}], "schema_version": 1}', '{"lightning-round-1": {"correct": {"q1": "a", "q2": "a", "q3": "a", "q4": "a", "q5": "a", "q6": "a"}}}', '{"units": {"lightning-round-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9f8a4174edab7634944d1a3633c56144c3eb7debe53c845039ec52246bd0d740.mp3", "hash": "6bb1d8741c122d94c8dee1647fd28ea1b1d7cfce8305d801d2fb664056af7358", "bytes": 35424, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/9f8a4174edab7634944d1a3633c56144c3eb7debe53c845039ec52246bd0d740.mp3", "duration_ms": 5840}, "lightning-round-1.hint.1": {"url": "http://localhost:4006/files/lesson-audio/ef67416c6d47113ab9c6c0934f43ab866e95b83341a01511cb3bcad27c3bf1be.mp3", "hash": "1663d0a1b0bc296f809f4df94d10d864da74248047b2fb9e46c13a954753d41b", "bytes": 29088, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/ef67416c6d47113ab9c6c0934f43ab866e95b83341a01511cb3bcad27c3bf1be.mp3", "duration_ms": 4800}, "lightning-round-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/1b47122ddcf2586f1eeb19170bf34e13d5aa47728e169fc2b87a04c6aeef994b.mp3", "hash": "f9afa3f64b3fc094a3dea4336e5d59b22f067f66c1369f4503f9bb1f2d2d33f9", "bytes": 35856, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/1b47122ddcf2586f1eeb19170bf34e13d5aa47728e169fc2b87a04c6aeef994b.mp3", "duration_ms": 5920}, "lightning-round-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/7eb58cf3c37a14548f030418bacafabf602b257b8f360c92c35d5644f4726fd2.mp3", "hash": "f7887487d1de9f3971a08cf805a8767210a4242439c4ed74740e477b035893bf", "bytes": 39744, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/7eb58cf3c37a14548f030418bacafabf602b257b8f360c92c35d5644f4726fd2.mp3", "duration_ms": 6560}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a00c4534-6e88-42ac-ab77-3465a684f47d', 'en-US', '1', E'{"meta": {"cast": ["dina", "liruf"], "slug": "story-scene", "title": "Liruf''s Plan", "locale": "en-US", "subject": "money", "objectives": ["Understand that money is earned by offering something others want, and that a clear goal helps to start."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-plan", "xp": 0, "type": "story_scene", "hints": [], "title": "Liruf''s Plan", "payload": {"art": {"icon": "emoji_objects", "tint": "primary", "image_url": "http://localhost:4006/files/lesson-images/5668e610e447687db10bbdd1e4698c64f521c1df90c8f53ee80e119876dfd41f.png"}, "action": "idle", "body_md": "Liruf draws on a poster: a glass of lemonade costs **5 pesos**. The guitar costs **80 pesos**. \\"If I sell many glasses, I can buy the guitar!\\" says Liruf.", "emotion": "happy", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Liruf draws his plan.", "difficulty": 1, "explanation_md": "Liruf drew a glass of lemonade worth 5 pesos and a guitar that costs 80. That way he knows how many glasses to sell.", "audio_segment_id": "s1-plan.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-plan.body": {"url": "http://localhost:4006/files/lesson-audio/465d07c6f26a3834f74845a3b2263aef27a955c9dbbdaf2e272384e48a244512.mp3", "hash": "3b92717a64232ac2df6b8c8eda4dc5512a0f9cc240c8c0bda191d0cf6b481ab7", "bytes": 61344, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/465d07c6f26a3834f74845a3b2263aef27a955c9dbbdaf2e272384e48a244512.mp3", "duration_ms": 10160}, "s1-plan.prompt": {"url": "http://localhost:4006/files/lesson-audio/a33ef0faa38738cc849743bd25323c98bfc32eea3677194b6833dd66609f7580.mp3", "hash": "df60d58ea5baf92dbdc139a80ba130b5a81b3cbcb41e1cda79005319492b3885", "bytes": 8928, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/a33ef0faa38738cc849743bd25323c98bfc32eea3677194b6833dd66609f7580.mp3", "duration_ms": 1440}, "s1-plan.explanation": {"url": "http://localhost:4006/files/lesson-audio/196f27bce8dfcbeebd27ad36cf4bcaa87b9730ac4e2ff8ef0c3417bb420980b9.mp3", "hash": "e7a1fb0bcb895c5d6d4ec0393f5e4fdda1c623440e672b4f630fe8923743e518", "bytes": 39168, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/196f27bce8dfcbeebd27ad36cf4bcaa87b9730ac4e2ff8ef0c3417bb420980b9.mp3", "duration_ms": 6480}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('881ae1da-74af-4378-a3cd-da8a9bc0e6b2', 'en-US', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "key-ideas", "title": "The three golden rules of the little seller", "locale": "en-US", "subject": "money", "objectives": ["Set the 3 key ideas of the plan: have a goal (80 pesos), offer something people want (cold lemonade), and save what you earn."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-key-ideas", "xp": 0, "type": "key_ideas", "hints": [], "title": "The three golden rules of the little seller", "payload": {"ideas": [{"icon": "flag", "title": "Goal: 80 pesos", "body_md": "Liruf wants a guitar that costs **80 pesos**. Having a clear goal helps you know how much you need to earn.", "image_url": "http://localhost:4006/files/lesson-images/83f47cb63c206310bd19c8d265dfd7a3a6ba2418fa82340c41b98477fad6a27d.png"}, {"icon": "local_cafe", "title": "Offer cold lemonade", "body_md": "The neighbors want something tasty and refreshing. Liruf will sell **cups of lemonade for 5 pesos**.", "image_url": "http://localhost:4006/files/lesson-images/4269ac83f7149ddfbb8441360f56f16fb2cbd7e887f7043dd3e980a783232ac0.png"}, {"icon": "savings", "title": "Save what you earn", "body_md": "Every time you sell a cup, save the money. Little by little you''ll reach the **80 pesos** for the guitar.", "image_url": "http://localhost:4006/files/lesson-images/503e65d50e02921ec8e36f2e8cc7ee87b9afbe94ba05ffda43d30114281772a7.png"}]}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Rho wrote on his board the three golden rules for selling lemonade. Tap each one to read it.", "difficulty": 1, "explanation_md": "Rho noted the three key ideas: a clear goal (80 pesos), a product people want (cold lemonade), and saving what you earn.", "audio_segment_id": "s1-key-ideas.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-key-ideas.idea.0": {"url": "http://localhost:4006/files/lesson-audio/065746612940abb483de2b696c3d8e4eb18d476d65cba6264e6f7b6573162102.mp3", "hash": "4294daca1b6e8713512277e46a6b688445fcb0f13403f498832f38b27381993b", "bytes": 50256, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/065746612940abb483de2b696c3d8e4eb18d476d65cba6264e6f7b6573162102.mp3", "duration_ms": 8320}, "s1-key-ideas.idea.1": {"url": "http://localhost:4006/files/lesson-audio/362b26dafe650c384c6ee53fd4bee17a6e9ef165e4c7aae000194edaf9173888.mp3", "hash": "d68395f41f7d57d29df28e203f3bf5a18b6daa4aabbd9b445b7e099b47342764", "bytes": 45504, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/362b26dafe650c384c6ee53fd4bee17a6e9ef165e4c7aae000194edaf9173888.mp3", "duration_ms": 7520}, "s1-key-ideas.idea.2": {"url": "http://localhost:4006/files/lesson-audio/4830f3d9afa3348d823a981cf7a9d516ad54570ce1713857a3a9be5a74ce2d66.mp3", "hash": "977840a65ac7462cc2a88c2074ccd12ccfb634d9d11841d8f1128d86980ecc51", "bytes": 42048, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/4830f3d9afa3348d823a981cf7a9d516ad54570ce1713857a3a9be5a74ce2d66.mp3", "duration_ms": 6960}, "s1-key-ideas.prompt": {"url": "http://localhost:4006/files/lesson-audio/5a8756d10b5643ccde4e5463253898d2c94b31fc4a3d66eab82f420c6684e524.mp3", "hash": "9413fae7bb30243fdcd5d448c4420f288a1f024672fd05e7ea62ade95fa5a87a", "bytes": 38736, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/5a8756d10b5643ccde4e5463253898d2c94b31fc4a3d66eab82f420c6684e524.mp3", "duration_ms": 6400}, "s1-key-ideas.explanation": {"url": "http://localhost:4006/files/lesson-audio/24e9e43b4a3bb35c1d1b1ef45345bfa08561b410957c70cf4e77d8afc8ce3866.mp3", "hash": "b7d990e7799689e86e48c969fcd452d8bdbfcaca75b9b0e881fefc1cae6ce296", "bytes": 60336, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/24e9e43b4a3bb35c1d1b1ef45345bfa08561b410957c70cf4e77d8afc8ce3866.mp3", "duration_ms": 10000}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a8fced2e-cab0-454c-866f-d7f94e9da924', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-dinero", "title": "Close the Sunday cash box", "locale": "en-US", "subject": "mixed", "objectives": ["Count coins of 1, 5, and 10 pesos to know the total sales of the day.", "Calculate the correct change when paying with a 20-peso bill for a 5-peso glass.", "Determine how many more Sundays you need to save 20 pesos to reach 80 pesos."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cuenta", "xp": 10, "type": "coin_count", "hints": ["Group coins of the same value and then add them up."], "title": "Count the coins", "payload": {"target": 20, "currency": "MXN", "denominations": [1, 5, 10]}, "narrator": {"emotion": "excited", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/d0190b8a16d1557d892585161229d7d884e1f3f78c9b5e00992f02935674c8e9.png", "prompt_md": "Count the coins customers left today. How much money is there in total?", "difficulty": 1, "explanation_md": "There are 20 pesos in total: 3 coins of 1 peso (3), 2 of 5 pesos (10), and 1 of 10 pesos (10). 3+10+10=20.", "audio_segment_id": "s1-cuenta.prompt"}, {"id": "s2-cambio", "xp": 10, "type": "make_change", "hints": ["Subtract the price of the glass from the bill she gave you."], "title": "Give change", "payload": {"price": 5, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10, 20]}, "narrator": {"emotion": "happy", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/f321bbdc7515f0c0ef204c7a9ea0ef7cdf6faceda2b1bc83c5d053b5a4d8514b.png", "prompt_md": "The last customer pays for her 5-peso glass with a 20-peso bill. How much change do you give her?", "difficulty": 1, "explanation_md": "The change is 15 pesos, because 20 minus 5 is 15. That way the customer leaves happy.", "audio_segment_id": "s2-cambio.prompt"}, {"id": "s3-ahorro", "xp": 10, "type": "savings_goal", "hints": ["First, calculate how much money you still need for the guitar.", "Then divide the amount needed by what you save each Sunday."], "title": "How many Sundays are left?", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [20]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "The guitar costs 80 pesos. You already have 40 in your piggy bank. If you save 20 pesos each Sunday, how many more Sundays do you need?", "difficulty": 1, "explanation_md": "You need 40 pesos more, and if you save 20 each Sunday, you need 2 more Sundays: 40 ÷ 20 = 2.", "audio_segment_id": "s3-ahorro.prompt"}], "schema_version": 1}', '{"s1-cuenta": {}, "s2-cambio": {}, "s3-ahorro": {}}', '{"units": {"s1-cuenta.hint.0": {"url": "http://localhost:4006/files/lesson-audio/39f86449b19fa0134cc832eff1825fda0422672d6014a453a2587bc2904fa7d9.mp3", "hash": "39deba8d709744ed1e842840fb8ac11021a7db4606124ed047f51c5d2f7b7e94", "bytes": 17568, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/39f86449b19fa0134cc832eff1825fda0422672d6014a453a2587bc2904fa7d9.mp3", "duration_ms": 2880}, "s1-cuenta.prompt": {"url": "http://localhost:4006/files/lesson-audio/e4048523ab2bdd1c9724ec12b2ce78784787490c0dea169957a73e52a6c59a77.mp3", "hash": "263011013c452e1159d77ceccab28568a05e2a9239d8b1700d53184b3d2797fe", "bytes": 24768, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e4048523ab2bdd1c9724ec12b2ce78784787490c0dea169957a73e52a6c59a77.mp3", "duration_ms": 4080}, "s2-cambio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/d23b2781afa0517a81262cade3f30a787dc31caac4fd230825e74ab5bc82dad8.mp3", "hash": "d7bff99cc5085c1ab7ab2b153275732bcc0fa115b98f9cf3f608c0370cc358ea", "bytes": 20016, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/d23b2781afa0517a81262cade3f30a787dc31caac4fd230825e74ab5bc82dad8.mp3", "duration_ms": 3280}, "s2-cambio.prompt": {"url": "http://localhost:4006/files/lesson-audio/dbce320d8f046e57ec55ceef3238c393cd652b3a535505a9bfe0485b0b626c82.mp3", "hash": "64ccab41d0b2cc21b6e8e25ad3caf3f11a94379f4338054e8d61b988d7e9a07f", "bytes": 38304, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/dbce320d8f046e57ec55ceef3238c393cd652b3a535505a9bfe0485b0b626c82.mp3", "duration_ms": 6320}, "s3-ahorro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e2f070594eca6ca9f2c296141b1314b2115b190d6475aa4035e7cae93b9b17a1.mp3", "hash": "13a00d01241685d88bcaf5ccd14396218bb232e345271dabcde4e801c5f97e85", "bytes": 18576, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e2f070594eca6ca9f2c296141b1314b2115b190d6475aa4035e7cae93b9b17a1.mp3", "duration_ms": 3040}, "s3-ahorro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/a8fea066691520eea065345b3cc5ea04d522efb0ed1cea7ee7e71915ed457055.mp3", "hash": "281fb1934914fae9d36a87c3cba62b686d23b38d695b2226c59a1e8a5ac08daa", "bytes": 18576, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/a8fea066691520eea065345b3cc5ea04d522efb0ed1cea7ee7e71915ed457055.mp3", "duration_ms": 3040}, "s3-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/d68f90a29435e68a300baa7e1ef35c6a4e0019c6d6b9ead306099c649943b072.mp3", "hash": "0f5c2f52099ba7c014cc4a063ba304f4ade6b5f07fc650699fc24105ef7898f2", "bytes": 48816, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/d68f90a29435e68a300baa7e1ef35c6a4e0019c6d6b9ead306099c649943b072.mp3", "duration_ms": 8080}, "s1-cuenta.explanation": {"url": "http://localhost:4006/files/lesson-audio/fa305c4f81a638dc4e33bb12a34a661b54f206518e29c1ba909a188b3149e7d3.mp3", "hash": "125943626788f148658aeb10c93dc08e28088cbcd11b3ecc4ec157e10401ff3a", "bytes": 61776, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/fa305c4f81a638dc4e33bb12a34a661b54f206518e29c1ba909a188b3149e7d3.mp3", "duration_ms": 10240}, "s2-cambio.explanation": {"url": "http://localhost:4006/files/lesson-audio/ef6e0ff39888f97594b6ea522bb51235c7be68ccac1f07f3ddeb8dac5744d77f.mp3", "hash": "822db792ac201e8b93dd72d74004f63f5e1acb581baa406709467bcb3675c603", "bytes": 39744, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/ef6e0ff39888f97594b6ea522bb51235c7be68ccac1f07f3ddeb8dac5744d77f.mp3", "duration_ms": 6560}, "s3-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/af426b25c60d1de1da745add0c1058e7dd5ee245da987f1b571616a214a0c551.mp3", "hash": "63fef614d6629ff72376730fe334d15aa408f62b353db3cf38944e81cfef7158", "bytes": 44928, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/af426b25c60d1de1da745add0c1058e7dd5ee245da987f1b571616a214a0c551.mp3", "duration_ms": 7440}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('35abfab2-f1da-4643-915a-3fdba69f3a63', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "fill-blank", "title": "Llena los huecos del cuaderno de Dina", "locale": "es-MX", "subject": "mixed", "objectives": ["Completar frases numéricas sobre ahorro del puesto", "Escribir respuestas numéricas exactas (sumas hasta 10, conteos hasta 20)"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ahorro", "xp": 10, "type": "fill_blank", "hints": ["Cuenta las monedas que ahorró: 3 y luego 2.", "3 más 2 son..."], "title": "Ahorro del día", "payload": {"bank": [{"id": "b1", "text_md": "5"}, {"id": "b2", "text_md": "1"}], "mode": "typed", "text_md": "Liruf ahorró 3 pesos y luego 2 más. En total ahorró {{1}} pesos."}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf ahorró 5 pesos. ¿Cuánto ahorró en total?", "difficulty": 1, "explanation_md": "Liruf ahorró 3 pesos y luego 2 más, así que tiene 5 pesos ahorrados. ¡Bien!", "audio_segment_id": "s1-ahorro.prompt"}], "schema_version": 1}', '{"s1-ahorro": {"gaps": [{"gap": 1, "accept": ["5", "cinco"], "bank_id": "b1"}]}}', '{"units": {"s1-ahorro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/76249bb6e6ec3857994e19bd7b8e5bf701ea89056e4fc708d754c47264f032fd.mp3", "hash": "c57a36066ea25ef9d4e8d913df638c37b09529c273786caf3c7e94837b203272", "bytes": 22464, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/76249bb6e6ec3857994e19bd7b8e5bf701ea89056e4fc708d754c47264f032fd.mp3", "duration_ms": 3680}, "s1-ahorro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/aebd5dcae7287a96a78126225b288b0485895715696e9123e2f770696d15fc17.mp3", "hash": "8eaaf51625aa6dc069bee77d48ba1fac048caceccb6795695ce08dcf729bc705", "bytes": 9504, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/aebd5dcae7287a96a78126225b288b0485895715696e9123e2f770696d15fc17.mp3", "duration_ms": 1520}, "s1-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/618ea10c70254c5d34c4ee1caa1086b333ce4908bcd0de3a9fa2c72503ce9382.mp3", "hash": "03ff122a4e6a6d170a5b60b7f1f24a1cb04afb40c56d5c80fb0c57f8ea3ac75d", "bytes": 24336, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/618ea10c70254c5d34c4ee1caa1086b333ce4908bcd0de3a9fa2c72503ce9382.mp3", "duration_ms": 4000}, "s1-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/bfd21ad18909cf8468114fc0b844862fa277e8bffc0d8cbc2a1e4d7389a40a30.mp3", "hash": "d6b3e5cc3e9ecad2f2d45972bcee8114832719c081fd71d427911a5f990b05db", "bytes": 39744, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/bfd21ad18909cf8468114fc0b844862fa277e8bffc0d8cbc2a1e4d7389a40a30.mp3", "duration_ms": 6560}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8ee4aa69-44e4-4d40-9cde-af0d59cc6b99', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "true-false", "title": "Decisiones de dinero: ¿Cierto o falso?", "locale": "es-MX", "subject": "mixed", "objectives": ["Tomar decisiones simples de dinero comparando opciones: precio justo, lugar seguro para guardar, y distinguir un buen trato de uno malo.", "Decidir si es cierto o falso: ''Si guardo 5 pesos de cada venta, mi ahorro CRECE cada día''."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-true-false", "xp": 10, "type": "true_false", "hints": ["Piensa: si ayer tenía 5 pesos y hoy guarda otros 5, ¿ahora tiene más o menos?", "Cada día que guarda, suma más dinero al ahorro."], "title": "¿Cierto o falso?", "payload": {"statement_md": "Si guardo 5 pesos de cada venta, mi ahorro CRECE cada día.", "justifications": [{"id": "crece", "text_md": "Cada día que guardo 5 pesos, el total de mi ahorro es mayor que el día anterior."}, {"id": "no-crece", "text_md": "Si guardo 5 pesos cada día, el ahorro se queda igual porque no sumo nada nuevo."}]}, "narrator": {"emotion": "excited", "character": "zara"}, "prompt_md": "Zara vende limonada a 5 pesos. Cada día guarda 5 pesos en su alcancía. ¿Su ahorro crece o se queda igual?", "difficulty": 1, "explanation_md": "Es cierto. Si guardas 5 pesos cada día, tu ahorro suma más cada vez. Por ejemplo, el lunes 5, el martes 10, el miércoles 15. ¡Crece!", "audio_segment_id": "s1-true-false.prompt"}], "schema_version": 1}', '{"s1-true-false": {"is_true": true, "correct_justification_id": "crece"}}', '{"units": {"s1-true-false.hint.0": {"url": "http://localhost:4006/files/lesson-audio/8d8616cd5b1cb9da1db9cc462635b3945c65b39bf1e7068213f0f5554c50617b.mp3", "hash": "6a0e021caee80d50c590f4fb2ceaece2eb98b67465a12bf45143f054f6d91c26", "bytes": 36288, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/8d8616cd5b1cb9da1db9cc462635b3945c65b39bf1e7068213f0f5554c50617b.mp3", "duration_ms": 6000}, "s1-true-false.hint.1": {"url": "http://localhost:4006/files/lesson-audio/26598ad6d0f7c637a46b0d2586cec947d4ee62390f7d0e7563f879d4863b7b5a.mp3", "hash": "a48ddc214882d1d5c9538d97df11ebefc52ac5320732f96c4b39d2feb21b9cad", "bytes": 19584, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/26598ad6d0f7c637a46b0d2586cec947d4ee62390f7d0e7563f879d4863b7b5a.mp3", "duration_ms": 3200}, "s1-true-false.prompt": {"url": "http://localhost:4006/files/lesson-audio/1bf437850b14c7a41b928627f69494c1ae70d67a534a4d2242adc7f4331b186e.mp3", "hash": "98eeeda00e699a2fe1408d989ed3663be11ef9e95284f2de70e96b6cf739ef4e", "bytes": 49248, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/1bf437850b14c7a41b928627f69494c1ae70d67a534a4d2242adc7f4331b186e.mp3", "duration_ms": 8160}, "s1-true-false.explanation": {"url": "http://localhost:4006/files/lesson-audio/b24bb087aefae67f0e20cea17093cd12bbed7a67865f4701f9b111176ff1ae7b.mp3", "hash": "70d728b9d81a02beb977e04d40624e6f1bab4f79b836d34fc16b500faf74f7e1", "bytes": 58464, "voice": "qwen-tts-vc-zara_es_mx-voice-20260714105757807-9e29", "file_id": "lesson-audio/b24bb087aefae67f0e20cea17093cd12bbed7a67865f4701f9b111176ff1ae7b.mp3", "duration_ms": 9680}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0a2bda3a-e275-46b8-b659-a7ad68a0afb3', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "lightning-round", "title": "Lightning round", "locale": "en-US", "subject": "money", "objectives": ["Quickly calculate change for orders of 1-3 cups at 5 pesos each, paying with 10 or 20 pesos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "lightning-round-1", "xp": 15, "type": "lightning_round", "hints": ["First add the cost of the cups: 2 cups × 5 pesos = 10 pesos.", "Then subtract that total from the payment: 20 − 10 = ?"], "title": "Lightning round", "payload": {"questions": [{"id": "q1", "options": [{"id": "a", "text_md": "10 pesos"}, {"id": "b", "text_md": "5 pesos"}, {"id": "c", "text_md": "15 pesos"}, {"id": "d", "text_md": "20 pesos"}], "prompt_md": "Doña Rosa asks for 2 cups. She pays with 20. How much change do you give her?"}, {"id": "q2", "options": [{"id": "a", "text_md": "5 pesos"}, {"id": "b", "text_md": "10 pesos"}, {"id": "c", "text_md": "0 pesos"}, {"id": "d", "text_md": "2 pesos"}], "prompt_md": "Don Toño asks for 1 cup. He pays with 10. How much change do you give him?"}, {"id": "q3", "options": [{"id": "a", "text_md": "5 pesos"}, {"id": "b", "text_md": "10 pesos"}, {"id": "c", "text_md": "15 pesos"}, {"id": "d", "text_md": "20 pesos"}], "prompt_md": "Señora Lupita asks for 3 cups. She pays with 20. How much change do you give her?"}, {"id": "q4", "options": [{"id": "a", "text_md": "0 pesos"}, {"id": "b", "text_md": "5 pesos"}, {"id": "c", "text_md": "10 pesos"}, {"id": "d", "text_md": "2 pesos"}], "prompt_md": "Little Juan asks for 2 cups. He pays with 10. How much change do you give him?"}, {"id": "q5", "options": [{"id": "a", "text_md": "15 pesos"}, {"id": "b", "text_md": "10 pesos"}, {"id": "c", "text_md": "5 pesos"}, {"id": "d", "text_md": "20 pesos"}], "prompt_md": "Doña Chuy asks for 1 cup. She pays with 20. How much change do you give her?"}, {"id": "q6", "options": [{"id": "a", "text_md": "0 pesos"}, {"id": "b", "text_md": "5 pesos"}, {"id": "c", "text_md": "10 pesos"}, {"id": "d", "text_md": "15 pesos"}], "prompt_md": "Don Beto asks for 3 cups. He pays with 10. How much change do you give him?"}], "seconds_per_q": 15}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Doña Rosa asks for 2 cups. She pays with 20. How much change do you give her?", "difficulty": 2, "explanation_md": "The cost of 2 cups is 10 pesos. Subtract 10 from 20 and you get 10 pesos in change.", "audio_segment_id": "lightning-round-1.prompt"}], "schema_version": 1}', '{"lightning-round-1": {"correct": {"q1": "a", "q2": "a", "q3": "a", "q4": "a", "q5": "a", "q6": "a"}}}', '{"units": {"lightning-round-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/8b79db63aa6bd84ea2f33f0b0d18e26ae5aa251188c0691c84e70e489b93eb01.mp3", "hash": "478521580340bbc447e2416ed1de3bdc27ecc49ff4c08661ec04da4af12690a4", "bytes": 33984, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/8b79db63aa6bd84ea2f33f0b0d18e26ae5aa251188c0691c84e70e489b93eb01.mp3", "duration_ms": 5600}, "lightning-round-1.hint.1": {"url": "http://localhost:4006/files/lesson-audio/9148cbce0730228efc3068e8cbcaab39f93e7982e31db4e0b36cce982dd3e530.mp3", "hash": "de7b870b013721bc02d841c44afee46cde7f77bf7094136d7287f5d770facb9a", "bytes": 26208, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/9148cbce0730228efc3068e8cbcaab39f93e7982e31db4e0b36cce982dd3e530.mp3", "duration_ms": 4320}, "lightning-round-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/703afa0edf34a0ea737f3d27358199ad65e3954d2fa1e011efdbe7e66c54166a.mp3", "hash": "f4c4934f174444e21bc11912b96f564b3433a6c1851dad1b2482f1658b6e2771", "bytes": 31536, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/703afa0edf34a0ea737f3d27358199ad65e3954d2fa1e011efdbe7e66c54166a.mp3", "duration_ms": 5200}, "lightning-round-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/386cb9a5134379cbbce43be216029ace3cdf26fc2bd924b563f823463f5abd59.mp3", "hash": "ec67561a9babca44f9afdf56cb6fc93e0e23c1569c53dd2a7ac8f41b2839c0c4", "bytes": 39168, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/386cb9a5134379cbbce43be216029ace3cdf26fc2bd924b563f823463f5abd59.mp3", "duration_ms": 6480}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('5cfeb5fa-1115-414d-9498-5cf6271b6245', 'es-MX', '1', '{"meta": {"cast": ["dina", "zara"], "slug": "robot-path", "title": "La ruta del repartidor", "locale": "es-MX", "subject": "mixed", "objectives": ["Guiar al carrito repartidor por la cuadrícula del barrio hasta la casa del cliente gastando la menor cantidad de pasos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-robot-path", "xp": 15, "type": "robot_path", "hints": ["El carrito empieza mirando hacia arriba. ¿Hacia dónde debe ir primero?", "Cuenta las casillas desde la salida hasta la meta."], "title": "Ruta al cliente", "payload": {"goal": {"x": 2, "y": 2}, "grid": {"h": 3, "w": 3}, "start": {"x": 0, "y": 0, "dir": "up"}, "walls": [], "commands": ["forward", "forward", "right"], "max_commands": 3}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "La batería solo da para 3 pasos. Lleva el carrito a la casa.", "difficulty": 2, "explanation_md": "El carrito avanzó hacia arriba y luego a la derecha para llegar a la casa del cliente en 3 pasos. ¡Ruta eficiente! Así ahorras batería, como ahorrar dinero.", "audio_segment_id": "s1-robot-path.prompt"}], "schema_version": 1}', '{"s1-robot-path": {}}', '{"units": {"s1-robot-path.hint.0": {"url": "http://localhost:4006/files/lesson-audio/702f10f9f4d1b27ef382cad3808dad0f2fcee2c97dc8221585788613ef58fb97.mp3", "hash": "43d32104cdf464270b7850de3f2977f7286bf9e7e9ed57e2816ee64ef3e545ba", "bytes": 28224, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/702f10f9f4d1b27ef382cad3808dad0f2fcee2c97dc8221585788613ef58fb97.mp3", "duration_ms": 4640}, "s1-robot-path.hint.1": {"url": "http://localhost:4006/files/lesson-audio/373711cca13d5fef43a97e4f021581867f0aa1628a4a85e9353117b3f984fd42.mp3", "hash": "1cc7ffdbaf5005b8d46c77cebb0d71352dfa670b6791ad4548a2d21e95680ed1", "bytes": 19584, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/373711cca13d5fef43a97e4f021581867f0aa1628a4a85e9353117b3f984fd42.mp3", "duration_ms": 3200}, "s1-robot-path.prompt": {"url": "http://localhost:4006/files/lesson-audio/5835b58d0e84a3a25bda2a76e9ee41d2cbca5cc5722bf23dfcc4753dfa1df979.mp3", "hash": "e9e4349aade17a87c0d6ea72b951f8a1d5921c2625c1156f67d427a26b62d5d1", "bytes": 26784, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/5835b58d0e84a3a25bda2a76e9ee41d2cbca5cc5722bf23dfcc4753dfa1df979.mp3", "duration_ms": 4400}, "s1-robot-path.explanation": {"url": "http://localhost:4006/files/lesson-audio/f9a36479ca2753953bcdaa98d83ea77111a6148b88438d7427525c7d595aeb64.mp3", "hash": "8d4a21cf1a6bb4f07b1c9de4453cc8a3b10d3eb02f7f83a1424c591ec515fb93", "bytes": 60336, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/f9a36479ca2753953bcdaa98d83ea77111a6148b88438d7427525c7d595aeb64.mp3", "duration_ms": 10000}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a8fced2e-cab0-454c-866f-d7f94e9da924', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-dinero", "title": "Fechar a caixa do domingo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Contar moedas de 1, 5 e 10 pesos para saber o total de vendas do dia.", "Calcular o troco correto ao pagar com nota de 20 pesos um copo de 5 pesos.", "Determinar quantos domingos mais é preciso economizar 20 pesos para chegar a 80 pesos."], "estimated_minutes": 10}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cuenta", "xp": 10, "type": "coin_count", "hints": ["Agrupe as moedas do mesmo valor e depois some-as."], "title": "Contar as moedas", "payload": {"target": 20, "currency": "MXN", "denominations": [1, 5, 10]}, "narrator": {"emotion": "excited", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/8ca86443a6efb4520f468cff713ed93ed595a41631ec6d3df9351c4aaf9b516b.png", "prompt_md": "Conte as moedas que os clientes deixaram hoje. Quanto dinheiro há no total?", "difficulty": 1, "explanation_md": "Há 20 pesos no total: 3 moedas de 1 peso (3), 2 de 5 pesos (10) e 1 de 10 pesos (10). 3+10+10=20.", "audio_segment_id": "s1-cuenta.prompt"}, {"id": "s2-cambio", "xp": 10, "type": "make_change", "hints": ["Subtraia o preço do copo da nota que ela te deu."], "title": "Dar o troco", "payload": {"price": 5, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10, 20]}, "narrator": {"emotion": "happy", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/ba53e16d74fd51c2fbf9bfc585207eefdd9744f5d75fd6dcbaea1095aff891c1.png", "prompt_md": "A última cliente paga seu copo de 5 pesos com uma nota de 20. Quanto troco você dá a ela?", "difficulty": 1, "explanation_md": "O troco é 15 pesos, porque 20 menos 5 é 15. Assim a cliente vai embora feliz.", "audio_segment_id": "s2-cambio.prompt"}, {"id": "s3-ahorro", "xp": 10, "type": "savings_goal", "hints": ["Primeiro calcule quanto dinheiro falta para o violão.", "Depois divida o que falta pelo que você economiza a cada domingo."], "title": "Quantos domingos faltam?", "payload": {"goal": 80, "currency": "MXN", "weekly_options": [20]}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "O violão custa 80 pesos. Você já tem 40 no cofrinho. Se cada domingo você guarda 20, quantos domingos mais precisa?", "difficulty": 1, "explanation_md": "Faltam 40 pesos, e se cada domingo você guarda 20, precisa de mais 2 domingos: 40 ÷ 20 = 2.", "audio_segment_id": "s3-ahorro.prompt"}], "schema_version": 1}', '{"s1-cuenta": {}, "s2-cambio": {}, "s3-ahorro": {}}', '{"units": {"s1-cuenta.hint.0": {"url": "http://localhost:4006/files/lesson-audio/7e329fc871a6b64bc42798489388f6b390a33968ce22b3479219a8ddc7bd1b54.mp3", "hash": "8ef2d235c715f015e3e75b48e4fb1c0fe9727a8fa0db766b18e7fb1d7486b735", "bytes": 23328, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7e329fc871a6b64bc42798489388f6b390a33968ce22b3479219a8ddc7bd1b54.mp3", "duration_ms": 3840}, "s1-cuenta.prompt": {"url": "http://localhost:4006/files/lesson-audio/3240d1491f4bccb31ad69661c2cd3cfce05a0f95cf09b389d4f77d53bd0eee64.mp3", "hash": "54f6b37164279cb53e7897a78e0407b5cf7a240a485fe4d7d455d0314af40371", "bytes": 31104, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/3240d1491f4bccb31ad69661c2cd3cfce05a0f95cf09b389d4f77d53bd0eee64.mp3", "duration_ms": 5120}, "s2-cambio.hint.0": {"url": "http://localhost:4006/files/lesson-audio/5449d5b3cdb8d5b81fdc743534d07f7168ebfa3521f5e4254c33c4e758c455ae.mp3", "hash": "3fda2833ff729470cdbc3d4a0f6366514dbde0688918ab6cd0ebffb61207ee23", "bytes": 18576, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/5449d5b3cdb8d5b81fdc743534d07f7168ebfa3521f5e4254c33c4e758c455ae.mp3", "duration_ms": 3040}, "s2-cambio.prompt": {"url": "http://localhost:4006/files/lesson-audio/325fc3ab5293c935ccce1d6a6c6e6bd9ffee9125a0ab2cc9adb94ce2f7b0086a.mp3", "hash": "e63d44776252b4d87bf0d3644bc9fa06f1d54b8b41c425c29dd39fda96095a34", "bytes": 37728, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/325fc3ab5293c935ccce1d6a6c6e6bd9ffee9125a0ab2cc9adb94ce2f7b0086a.mp3", "duration_ms": 6240}, "s3-ahorro.hint.0": {"url": "http://localhost:4006/files/lesson-audio/692f490c9b63aee70541e80c3e8f56e2773f65bf13fe7df0a8aac92a6d5dc513.mp3", "hash": "b4559f42a7a90359ea55f3c2f15f8f39368be81277b8a100214c75a442185ac2", "bytes": 21456, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/692f490c9b63aee70541e80c3e8f56e2773f65bf13fe7df0a8aac92a6d5dc513.mp3", "duration_ms": 3520}, "s3-ahorro.hint.1": {"url": "http://localhost:4006/files/lesson-audio/7ab9d43527fdaa57730f85e7c9481091398052af5e15a8c2f1c96ba59837c820.mp3", "hash": "65b62bcda85b9ccc4c5562e702e18841e2afc0aed8dd09fa02c4121fbeffe9ae", "bytes": 28656, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7ab9d43527fdaa57730f85e7c9481091398052af5e15a8c2f1c96ba59837c820.mp3", "duration_ms": 4720}, "s3-ahorro.prompt": {"url": "http://localhost:4006/files/lesson-audio/43aec637174e8408359bc06271dd12de12d3c8daf22cb3a306ea798cc7d30859.mp3", "hash": "588c8d5ed118b5016d5f8c7bd71faa4bda7c27e21817c2e0c6cb6e5899c41228", "bytes": 51696, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/43aec637174e8408359bc06271dd12de12d3c8daf22cb3a306ea798cc7d30859.mp3", "duration_ms": 8560}, "s1-cuenta.explanation": {"url": "http://localhost:4006/files/lesson-audio/22528b840ce1f34ab51f011631ec65d0eb37663024d38b12dfcd8c56051e8ea6.mp3", "hash": "0015316df5f62b7c740801a9fe3b24c24beb3b3d724140bab07e18a501ba7cf6", "bytes": 81504, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/22528b840ce1f34ab51f011631ec65d0eb37663024d38b12dfcd8c56051e8ea6.mp3", "duration_ms": 13520}, "s2-cambio.explanation": {"url": "http://localhost:4006/files/lesson-audio/05bf2f2cbc0bd9ff2bb3a0474ad4b6ad4abad455374cc2b1fc2ebdabeced5034.mp3", "hash": "d8d05d3b626ca14c8ef55cb7a7071f982c4b76d3d23903bff110bf7746c8f199", "bytes": 44064, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/05bf2f2cbc0bd9ff2bb3a0474ad4b6ad4abad455374cc2b1fc2ebdabeced5034.mp3", "duration_ms": 7280}, "s3-ahorro.explanation": {"url": "http://localhost:4006/files/lesson-audio/2d18d15233c0cd2164acd0fa5e6c77f2aa3742f988a5d313d5a58436fceb2e27.mp3", "hash": "564f371e4b7a35d2dd8c1b221a9a2eaea0f306806686f0498f9a364fb1353ea6", "bytes": 59904, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/2d18d15233c0cd2164acd0fa5e6c77f2aa3742f988a5d313d5a58436fceb2e27.mp3", "duration_ms": 9920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('574fb312-93f9-4f2f-adea-606bbb0ca99d', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "best-decision", "title": "Liruf''s Best Decision", "locale": "en-US", "subject": "mixed", "objectives": ["Choosing the best decision when a customer pays with a 20-peso bill for a 5-peso glass: counting the change calmly."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-best-decision", "xp": 15, "type": "best_decision", "hints": ["Think: if the glass costs 5 and they pay you with 20, how much should you give back?", "Imagine you are Liruf: do you prefer to count slowly or guess?"], "title": "Liruf''s Change", "payload": {"options": [{"id": "contar", "text_md": "Count the change calmly: 15 pesos", "rationale_md": "Counting calmly is the best decision because it ensures the change is correct."}, {"id": "adivinar", "text_md": "Guess the change quickly and give her 10 pesos", "rationale_md": "Guessing can make you give incorrect change and the customer loses money."}, {"id": "quedarse", "text_md": "Keep the whole bill and give no change", "rationale_md": "Keeping the whole bill is incorrect because the customer overpaid and deserves her change."}], "scenario_md": "Liruf has already learned that lemonade needs lemons and sugar, and that those cost money. Now he serves his first customer. She gives him a 20-peso bill for a 5-peso glass of lemonade. Liruf is nervous and doesn''t know what to do."}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/96cb76d57d4626dbb854c04bbf57441984e6b7ed3a38e9ad605d5059b47d46fe.png", "prompt_md": "The customer pays with 20 pesos. The glass costs 5. What do you do?", "difficulty": 2, "explanation_md": "Counting the change calmly ensures you don''t make a mistake. 20 minus 5 is 15 pesos in change.", "audio_segment_id": "s1-best-decision.prompt"}], "schema_version": 1}', '{"s1-best-decision": {"qualities": {"contar": 100, "adivinar": 20, "quedarse": 0}}}', '{"units": {"s1-best-decision.hint.0": {"url": "http://localhost:4006/files/lesson-audio/9a7adf90379969426f6dbc94f464554f1091b87cb17e4efc43a722160cc77df8.mp3", "hash": "9b43186ce96df5139172618aa86b6cc12bc23738f7fea4a384f6af863428028c", "bytes": 28656, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9a7adf90379969426f6dbc94f464554f1091b87cb17e4efc43a722160cc77df8.mp3", "duration_ms": 4720}, "s1-best-decision.hint.1": {"url": "http://localhost:4006/files/lesson-audio/fa73f30bd5ee64ad224940f08a9a859815d439182a26eb543458544273661b0e.mp3", "hash": "c090b95f24e1aefc360acfbe77a699f618777342c4caca7a47dbd83d46b8b3ea", "bytes": 21888, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/fa73f30bd5ee64ad224940f08a9a859815d439182a26eb543458544273661b0e.mp3", "duration_ms": 3600}, "s1-best-decision.prompt": {"url": "http://localhost:4006/files/lesson-audio/f8da17ce0c3ead6b54eb40ede9fa44007cc3e3e1421b20c2fda21591d3182808.mp3", "hash": "906baede18ce2f2056370450dc79392e0710ac58fac063c1008763b1080004cd", "bytes": 27648, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f8da17ce0c3ead6b54eb40ede9fa44007cc3e3e1421b20c2fda21591d3182808.mp3", "duration_ms": 4560}, "s1-best-decision.choices": {"url": "http://localhost:4006/files/lesson-audio/c06ecb8a4b0736ed6fdc24dc2a5a47456eccb524625a23dab88d8610249cdd1c.mp3", "hash": "deccf63508987d32d211467d22df4248427fa33b7e7a6ac0f10da9fd00c6a0b9", "bytes": 44064, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/c06ecb8a4b0736ed6fdc24dc2a5a47456eccb524625a23dab88d8610249cdd1c.mp3", "duration_ms": 7280}, "s1-best-decision.explanation": {"url": "http://localhost:4006/files/lesson-audio/4827093d0889fac770d45401d2f40de052d340718075caf950521055db6f81e3.mp3", "hash": "65b0fa678e7292740b6229565e8f8a2d46344b0f2212f3d04d9a6ef509cff526", "bytes": 35424, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4827093d0889fac770d45401d2f40de052d340718075caf950521055db6f81e3.mp3", "duration_ms": 5840}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a0b48602-bbeb-4aac-8309-90ec3cdeba90', 'es-MX', '1', '{"meta": {"cast": ["liruf", "rho"], "slug": "number-line", "title": "La recta del ahorro", "locale": "es-MX", "subject": "mixed", "objectives": ["Ubicar cantidades en una recta numérica del 0 al 100", "Identificar cuánto falta para alcanzar una meta de ahorro"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-number-line", "xp": 15, "type": "number_line", "hints": ["Cuenta de 10 en 10 desde 20 hasta 80.", "20 + 10 = 30, 30 + 10 = 40... ¿cuántos 10s hasta 80?"], "title": "La recta del ahorro", "payload": {"max": 100, "min": 0, "ticks": 10, "labels": false}, "narrator": {"emotion": "excited", "character": "rho"}, "prompt_md": "Liruf tiene 20 pesos. El patinete cuesta 80. ¿Cuánto falta?", "difficulty": 2, "explanation_md": "Faltan 60 pesos. 20 + 60 = 80. Si pusiste 80, sumaste lo que ya tiene; si pusiste 20, restaste lo que ya tiene. ¡Bien por intentarlo!", "audio_segment_id": "s1-number-line.prompt"}], "schema_version": 1}', '{"s1-number-line": {"value": 60, "full_credit_delta": 5, "zero_credit_delta": 15}}', '{"units": {"s1-number-line.hint.0": {"url": "http://localhost:4006/files/lesson-audio/68b480948633404f0611e2c5f33d6c77e4e6157ba10c82ac4179102fb976d6b1.mp3", "hash": "11001f59d804ade932dee300556ecf120ab902253852f98c72f7f120b82d47b0", "bytes": 23328, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/68b480948633404f0611e2c5f33d6c77e4e6157ba10c82ac4179102fb976d6b1.mp3", "duration_ms": 3840}, "s1-number-line.hint.1": {"url": "http://localhost:4006/files/lesson-audio/acddce4fe293391513bbd8af2da214fe34cfe87b36fdc1cc03c6fad929c6c27c.mp3", "hash": "f70873a547bc58e2c42351f9ae72d5faeb0ba0345b8f5ea3c11b61fcd4ba48f0", "bytes": 45504, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/acddce4fe293391513bbd8af2da214fe34cfe87b36fdc1cc03c6fad929c6c27c.mp3", "duration_ms": 7520}, "s1-number-line.prompt": {"url": "http://localhost:4006/files/lesson-audio/de6b8e0486a7b916ad0844f4e39ecb62192e7cd89ee1c9a5170cb05fc8b0509f.mp3", "hash": "9914b2d497b23de88d2b07a8ade7ff4ca00ec2af1abab648df3099aadb553d37", "bytes": 33984, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/de6b8e0486a7b916ad0844f4e39ecb62192e7cd89ee1c9a5170cb05fc8b0509f.mp3", "duration_ms": 5600}, "s1-number-line.explanation": {"url": "http://localhost:4006/files/lesson-audio/a97588ecd91a66a4e35e1a5c4659d214fb935d85c4fd33f5d40e85ffc7de4254.mp3", "hash": "a75f0f1db5edb13272bc19a4c19068ea8bf2fc32d66d4c4db88ac53d2a59ed65", "bytes": 73728, "voice": "qwen-tts-vc-rho_es_mx-voice-20260714105730265-3c5d", "file_id": "lesson-audio/a97588ecd91a66a4e35e1a5c4659d214fb935d85c4fd33f5d40e85ffc7de4254.mp3", "duration_ms": 12240}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('bd130a62-6800-475b-8af6-59f14ffebc50', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "number-input", "title": "Writing numbers: stand profit", "locale": "en-US", "subject": "mixed", "objectives": ["Calculate and write how much Liruf earned in total if he sold 4 cups for 5 pesos each (20 pesos)."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia-total", "xp": 10, "type": "number_input", "hints": ["Each cup gives 5 pesos. How much do 4 cups give?", "You can add 5 + 5 + 5 + 5."], "title": "Day''s profit", "payload": {"unit": "pesos", "decimals_hint": 0}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/a55e22cb7a25b46c2c69f33f2b59dc74ded57ff59defcf424e0fbc6fc949bb12.png", "prompt_md": "Liruf sold 4 cups of lemonade for 5 pesos each. How much money is in the cash box?", "difficulty": 1, "explanation_md": "Liruf earned 20 pesos because 4 cups × 5 pesos each = 20 pesos.", "audio_segment_id": "s1-ganancia-total.prompt"}], "schema_version": 1}', '{"s1-ganancia-total": {"value": 20, "tolerance": 0}}', '{"units": {"s1-ganancia-total.hint.0": {"url": "http://localhost:4006/files/lesson-audio/cea5a90d325b378cb272684da89a7bba3fbefd0489f7dbc518e4873f3861e0a8.mp3", "hash": "ddf35c2c50c056f5f513ae1bc40835fe74903f350bc1a3bdd6e86c72f64397f5", "bytes": 23328, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/cea5a90d325b378cb272684da89a7bba3fbefd0489f7dbc518e4873f3861e0a8.mp3", "duration_ms": 3840}, "s1-ganancia-total.hint.1": {"url": "http://localhost:4006/files/lesson-audio/e37ca1374893b0146c9f61e45fd7b2497a6041accac91a7bb13efe738c4fb9ec.mp3", "hash": "7d83e7955ff958e99860cc89c0bdf2fc127cf6629c401b924bc1d1bd4b4fef85", "bytes": 18576, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/e37ca1374893b0146c9f61e45fd7b2497a6041accac91a7bb13efe738c4fb9ec.mp3", "duration_ms": 3040}, "s1-ganancia-total.prompt": {"url": "http://localhost:4006/files/lesson-audio/28b87dd393aa03ec4516a7c705c2ba10c236499f834d0b4fce3ce148e590fd4b.mp3", "hash": "0bf00d194b7fce40be0352745ade52ebe039242d4cd082533b28956b6f3d13cf", "bytes": 31968, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/28b87dd393aa03ec4516a7c705c2ba10c236499f834d0b4fce3ce148e590fd4b.mp3", "duration_ms": 5280}, "s1-ganancia-total.explanation": {"url": "http://localhost:4006/files/lesson-audio/26e33fa94c9234afe4a61d17f6f57818eb050de58e20998add3942c7a45bcf33.mp3", "hash": "8ab490dfa2f38aedf0bae0923d999ace507d11b2f0d0b43538a973e7737b9fc6", "bytes": 31968, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/26e33fa94c9234afe4a61d17f6f57818eb050de58e20998add3942c7a45bcf33.mp3", "duration_ms": 5280}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('7f76a2de-27d1-4660-8203-c9ddad8fb861', 'pt-BR', '1', '{"meta": {"cast": ["zara"], "slug": "estimate-slider", "title": "Estimar copos de limonada", "locale": "pt-BR", "subject": "mixed", "objectives": ["Estimar quantidades usando uma barra deslizante", "Desenvolver senso numérico ao estimar antes de contar"], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-estimate-jar", "xp": 15, "type": "estimate_slider", "hints": ["Liruf vendeu 4 copos com uma jarra menor. Esta jarra é maior.", "Pense: se a jarra pequena dava 4 copos, esta maior dá mais."], "title": "Quantos copos saem?", "payload": {"max": 20, "min": 1, "step": 1, "unit": "vasos", "scale": "linear"}, "narrator": {"emotion": "thinking", "character": "zara"}, "image_url": "http://localhost:4006/files/lesson-images/dfd841dd0cfb5a5f63b1b878009b10d03f63cae61e9b1d0c5c7be4073b0bad79.png", "prompt_md": "Zara vê a jarra cheia. Quantos copos você acha que ela pode vender?", "difficulty": 2, "explanation_md": "Isso mesmo! Esta jarra grande dá para 8 copos. Zara pode vendê-los e ganhar dinheiro, como Liruf fez com seus 4 copos.", "audio_segment_id": "s1-estimate-jar.prompt"}], "schema_version": 1}', '{"s1-estimate-jar": {"value": 8, "full_credit_delta": 2, "zero_credit_delta": 7}}', '{"units": {"s1-estimate-jar.hint.0": {"url": "http://localhost:4006/files/lesson-audio/8aca9e84e1e7a05f61913eb5e2bc697a8dac5a2ed09f9be25df54dfa894f68ad.mp3", "hash": "cf0970e39dea6c62da20dd0586ef803188bfd83e9c2bde0690acea073afefa7b", "bytes": 33408, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/8aca9e84e1e7a05f61913eb5e2bc697a8dac5a2ed09f9be25df54dfa894f68ad.mp3", "duration_ms": 5520}, "s1-estimate-jar.hint.1": {"url": "http://localhost:4006/files/lesson-audio/45d3ac8564b53f5a34f1f1440e58da89bb47988c6ffadbcf82af863acdee0e29.mp3", "hash": "7331a857fc2809776da267f7d6ae1f6ebb064245225e5fec90fce485769b08e1", "bytes": 30528, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/45d3ac8564b53f5a34f1f1440e58da89bb47988c6ffadbcf82af863acdee0e29.mp3", "duration_ms": 5040}, "s1-estimate-jar.prompt": {"url": "http://localhost:4006/files/lesson-audio/7fff60cf626f515de9271d5218e3a2f4729188264b2b2555b55d10992c69f90e.mp3", "hash": "4d9d9513a1479907525e193b674f1b52983f5320ea5dc4286ba3d8b2e55d839c", "bytes": 31968, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/7fff60cf626f515de9271d5218e3a2f4729188264b2b2555b55d10992c69f90e.mp3", "duration_ms": 5280}, "s1-estimate-jar.explanation": {"url": "http://localhost:4006/files/lesson-audio/bcfa679f5b48d8204cf112f35d17b655c03dda01d1361e19a9c35ee61d7d5cfe.mp3", "hash": "f7043300a39acb5daec1f8f240aaed839599e2d870a4c63d88d4453fb4530ae6", "bytes": 58896, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/bcfa679f5b48d8204cf112f35d17b655c03dda01d1361e19a9c35ee61d7d5cfe.mp3", "duration_ms": 9760}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f62a6048-4f69-4ab4-9256-d87525c8e112', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "make-change", "title": "Giving exact change", "locale": "en-US", "subject": "mixed", "objectives": ["Calculating change from a 20-peso bill when buying two products costing 5 and 3 pesos", "Making change with coins of 1, 2, 5, and 10"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-cambio-don-beto", "xp": 15, "type": "make_change", "hints": ["Add the cost of the glass and the cookie.", "The change is what is left from the 20-peso bill after paying."], "title": "Don Beto''s change", "payload": {"price": 8, "currency": "MXN", "paid_with": 20, "denominations": [1, 2, 5, 10]}, "narrator": {"emotion": "thinking", "character": "liruf"}, "image_url": "http://localhost:4006/files/lesson-images/3a0e0689143b2ebfbe064984277005b3cbde37285774da01d6dc8bff40c2b290.png", "prompt_md": "Don Beto buys 1 glass (5 pesos) and 1 cookie (3 pesos). He pays with 20 pesos. He makes his change with coins.", "difficulty": 2, "explanation_md": "Glass 5 + cookie 3 = 8 pesos. From 20, 12 remain. The coins that add up to 12 are 10 + 2.", "audio_segment_id": "s1-cambio-don-beto.prompt"}], "schema_version": 1}', '{"s1-cambio-don-beto": {}}', '{"units": {"s1-cambio-don-beto.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4192e2130f26c9fcfee0a0c34f6cf6cd038992e67a2b702acfdff19bc32f2b0e.mp3", "hash": "ca84f7a60c6965ff566dd96f3b303f5e5dea836ba9c6dedecdc9de7cee213be0", "bytes": 15264, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/4192e2130f26c9fcfee0a0c34f6cf6cd038992e67a2b702acfdff19bc32f2b0e.mp3", "duration_ms": 2480}, "s1-cambio-don-beto.hint.1": {"url": "http://localhost:4006/files/lesson-audio/168779995df6e42ef2a8752e82ede06444a8720d01d0f149c7e63ee161327d9d.mp3", "hash": "a1558b63346abbed05ae27b6ac7b8d9dec29c94f9ab5f776f319efbc3fa252fa", "bytes": 23904, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/168779995df6e42ef2a8752e82ede06444a8720d01d0f149c7e63ee161327d9d.mp3", "duration_ms": 3920}, "s1-cambio-don-beto.prompt": {"url": "http://localhost:4006/files/lesson-audio/fbad3189bae1527700cfbfed8160d0b0af2745b11c1b4997a2735f2f70e23dcc.mp3", "hash": "74479d7a7721e37db857c68b94ea2b1006b5b379dca59a2bd7c1cf0c639e1ad3", "bytes": 49824, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/fbad3189bae1527700cfbfed8160d0b0af2745b11c1b4997a2735f2f70e23dcc.mp3", "duration_ms": 8240}, "s1-cambio-don-beto.explanation": {"url": "http://localhost:4006/files/lesson-audio/0c028a3f22d61dc5ad44091b45a865b244a138d2ac7fc4629294864b4275c078.mp3", "hash": "41b413ae5a109678c60c0af68af639d7792ffc41c33a240b6600821d368f2372", "bytes": 48816, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/0c028a3f22d61dc5ad44091b45a865b244a138d2ac7fc4629294864b4275c078.mp3", "duration_ms": 8080}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0a2bda3a-e275-46b8-b659-a7ad68a0afb3', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "lightning-round", "title": "Rodada relâmpago", "locale": "pt-BR", "subject": "money", "objectives": ["Calcular troco rápido para pedidos de 1-3 copos a 5 pesos cada, pagando com 10 ou 20 pesos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "lightning-round-1", "xp": 15, "type": "lightning_round", "hints": ["Primeiro some o custo dos copos: 2 copos × 5 pesos = 10 pesos.", "Depois subtraia esse total do pagamento: 20 − 10 = ?"], "title": "Rodada relâmpago", "payload": {"questions": [{"id": "q1", "options": [{"id": "a", "text_md": "10 pesos"}, {"id": "b", "text_md": "5 pesos"}, {"id": "c", "text_md": "15 pesos"}, {"id": "d", "text_md": "20 pesos"}], "prompt_md": "Dona Rosa pede 2 copos. Paga com 20. Quanto de troco você dá?"}, {"id": "q2", "options": [{"id": "a", "text_md": "5 pesos"}, {"id": "b", "text_md": "10 pesos"}, {"id": "c", "text_md": "0 pesos"}, {"id": "d", "text_md": "2 pesos"}], "prompt_md": "Seu Toño pede 1 copo. Paga com 10. Quanto de troco você dá?"}, {"id": "q3", "options": [{"id": "a", "text_md": "5 pesos"}, {"id": "b", "text_md": "10 pesos"}, {"id": "c", "text_md": "15 pesos"}, {"id": "d", "text_md": "20 pesos"}], "prompt_md": "Dona Lupita pede 3 copos. Paga com 20. Quanto de troco você dá?"}, {"id": "q4", "options": [{"id": "a", "text_md": "0 pesos"}, {"id": "b", "text_md": "5 pesos"}, {"id": "c", "text_md": "10 pesos"}, {"id": "d", "text_md": "2 pesos"}], "prompt_md": "O menino João pede 2 copos. Paga com 10. Quanto de troco você dá?"}, {"id": "q5", "options": [{"id": "a", "text_md": "15 pesos"}, {"id": "b", "text_md": "10 pesos"}, {"id": "c", "text_md": "5 pesos"}, {"id": "d", "text_md": "20 pesos"}], "prompt_md": "Dona Chuy pede 1 copo. Paga com 20. Quanto de troco você dá?"}, {"id": "q6", "options": [{"id": "a", "text_md": "0 pesos"}, {"id": "b", "text_md": "5 pesos"}, {"id": "c", "text_md": "10 pesos"}, {"id": "d", "text_md": "15 pesos"}], "prompt_md": "Seu Beto pede 3 copos. Paga com 10. Quanto de troco você dá?"}], "seconds_per_q": 15}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Dona Rosa pede 2 copos. Paga com 20. Quanto de troco você dá?", "difficulty": 2, "explanation_md": "O custo de 2 copos é 10 pesos. Subtraia 10 de 20 e você obtém 10 pesos de troco.", "audio_segment_id": "lightning-round-1.prompt"}], "schema_version": 1}', '{"lightning-round-1": {"correct": {"q1": "a", "q2": "a", "q3": "a", "q4": "a", "q5": "a", "q6": "a"}}}', '{"units": {"lightning-round-1.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b3ea72a27280ee01b2c660bd6d420c77941a2c32c2ac999f9d2905439c7eebca.mp3", "hash": "47d8451c171f96a2ce83ddaca0ceb355f505454f0b3e36639cb08af410f545b8", "bytes": 35856, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/b3ea72a27280ee01b2c660bd6d420c77941a2c32c2ac999f9d2905439c7eebca.mp3", "duration_ms": 5920}, "lightning-round-1.hint.1": {"url": "http://localhost:4006/files/lesson-audio/7e52cb36405fce7475d7ec693a947a604a2fa7a74564101a0f95032f07f3a3e0.mp3", "hash": "9bcf7a704daeedc47a603588753cf2b815cc4205e2339e281e713fc7aaeb4346", "bytes": 25776, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/7e52cb36405fce7475d7ec693a947a604a2fa7a74564101a0f95032f07f3a3e0.mp3", "duration_ms": 4240}, "lightning-round-1.prompt": {"url": "http://localhost:4006/files/lesson-audio/99d3a1a722342d9e19fb811f8461d4e89b0f91c644effcb4dd54ec959d641a16.mp3", "hash": "d3cf8dcc388b85dc0e435b16d1baaa7c27bc4cc356b31bc4afd576d8ac947293", "bytes": 31968, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/99d3a1a722342d9e19fb811f8461d4e89b0f91c644effcb4dd54ec959d641a16.mp3", "duration_ms": 5280}, "lightning-round-1.explanation": {"url": "http://localhost:4006/files/lesson-audio/66e31224b7ed7c24987492f33ba41f9084a088cb3594a6520077ba8b475cb9fc.mp3", "hash": "7e8cd004c30f8e7971d47ee8f1a36635f91e5c4f8f3469465eb19fb4c3d60aca", "bytes": 42624, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/66e31224b7ed7c24987492f33ba41f9084a088cb3594a6520077ba8b475cb9fc.mp3", "duration_ms": 7040}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('21c29ede-4ec5-4118-8e88-04f1068e985b', 'es-MX', '1', '{"meta": {"cast": ["liruf", "dina"], "slug": "count-objects", "title": "Contar monedas del frasco volcado", "locale": "es-MX", "subject": "mixed", "objectives": ["Contar monedas de un vistazo (hasta 12) y asociar cada moneda a un vaso de limonada vendido."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-count-coins", "xp": 10, "type": "count_objects", "hints": ["Mira solo las monedas, no las galletas ni el vaso.", "Puedes tocarlas una por una para contarlas."], "title": "Monedas en el frasco", "payload": {"scene": [{"icon": "monetization_on", "tint": "primary", "count": 8}, {"icon": "cookie", "tint": "accent", "count": 3}, {"icon": "local_drink", "tint": "accent", "count": 1}], "ask_icon": "monetization_on"}, "narrator": {"emotion": "surprised", "character": "liruf"}, "prompt_md": "Cuenta las monedas que se cayeron del frasco. ¿Cuántas hay?", "difficulty": 1, "explanation_md": "Hay 8 monedas. Cada moneda es un vaso de 5 pesos que Liruf vendió hoy. Ese número es lo que suma para la guitarra de 80 pesos.", "audio_segment_id": "s1-count-coins.prompt"}], "schema_version": 1}', '{"s1-count-coins": {"value": 8}}', '{"units": {"s1-count-coins.hint.0": {"url": "http://localhost:4006/files/lesson-audio/fbe292e0cbaf3bac6e98bf37e34715b5302a0a9486bf36d494cad03288b39117.mp3", "hash": "ff5470c54f7e95f1ec9a144064aa5102d3845d46e75a73ae39097a535e21449b", "bytes": 24768, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/fbe292e0cbaf3bac6e98bf37e34715b5302a0a9486bf36d494cad03288b39117.mp3", "duration_ms": 4080}, "s1-count-coins.hint.1": {"url": "http://localhost:4006/files/lesson-audio/7268f69542760804466e3f0270deb3481bd9fe77fa630f831e1e06edcbed787b.mp3", "hash": "fe58bbf8e1c136069338ad93968822402c00820d6d6f495e682da1bc91eb5f19", "bytes": 17568, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/7268f69542760804466e3f0270deb3481bd9fe77fa630f831e1e06edcbed787b.mp3", "duration_ms": 2880}, "s1-count-coins.prompt": {"url": "http://localhost:4006/files/lesson-audio/1051f6d42947590c012f9f79d032536025dd64e7fa2ec46531f4f37eae5298d8.mp3", "hash": "57f4d41721c8c654f3d1a2d66eb83c4850778b9064ba5172ef898340212a8448", "bytes": 25776, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/1051f6d42947590c012f9f79d032536025dd64e7fa2ec46531f4f37eae5298d8.mp3", "duration_ms": 4240}, "s1-count-coins.explanation": {"url": "http://localhost:4006/files/lesson-audio/09508f3797088f684818aa5787162524692eb716026f5b1cc00385ad39c7fed1.mp3", "hash": "17ff4779b1279a2725f7b42ed5ff1b7dfc8e2e79080f4a6c6a1ad629c0358361", "bytes": 54144, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/09508f3797088f684818aa5787162524692eb716026f5b1cc00385ad39c7fed1.mp3", "duration_ms": 8960}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0c46648e-ff7a-4ad4-bf42-5829cc3fd1ac', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-dialogue", "title": "Ganhar dinheiro com uma ideia", "locale": "pt-BR", "subject": "money", "objectives": ["Entender que o dinheiro é ganho oferecendo algo que outros querem", "Reconhecer que uma meta clara ajuda a começar a ganhar dinheiro"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogue", "xp": 0, "type": "story_dialogue", "hints": [], "title": "O violão de Liruf", "payload": {"lines": [{"action": "idle", "emotion": "thinking", "text_md": "Olha aquele violão… custa 80 reais. Nunca vou juntar tudo isso.", "character": "liruf"}, {"action": "idle", "emotion": "happy", "text_md": "E se você mesmo ganhar? Poderia vender limonada na vizinhança.", "character": "dina"}, {"action": "idle", "emotion": "surprised", "text_md": "Vender limonada? As pessoas me pagariam por isso?", "character": "liruf"}, {"action": "idle", "emotion": "encouraging", "text_md": "Claro! Se você fizer uma limonada gostosa, seus vizinhos vão querer comprar. Assim você ganha dinheiro com sua própria ideia.", "character": "dina"}, {"action": "idle", "emotion": "excited", "text_md": "Sim! Vou vender copos a 5 reais cada. Se eu vender 4 copos hoje, terei 20 reais… falta menos da metade! Já quero começar!", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/f42d5ef79aca46f4205d81c57afffd618b7f061913635526a13bc2de42a9a9c6.png", "prompt_md": "Dina e Liruf falam sobre o violão de 80 reais.", "difficulty": 1, "explanation_md": "Vender limonada é uma forma de ganhar dinheiro oferecendo algo que outros querem.", "audio_segment_id": "s1-dialogue.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-dialogue.line.0": {"url": "http://localhost:4006/files/lesson-audio/88776c4a144bdeeb5126cc9edc11e84eae13d483098f317bf4ce92adaa24c8eb.mp3", "hash": "2be5b1d68ebbdeafa723dffc305c01b94b0789705fd45a7b8a24b7b81fff12b3", "bytes": 36864, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/88776c4a144bdeeb5126cc9edc11e84eae13d483098f317bf4ce92adaa24c8eb.mp3", "duration_ms": 6080}, "s1-dialogue.line.1": {"url": "http://localhost:4006/files/lesson-audio/f04339a125b42ffa84a2983cc293abcf8ca40dd7ad2541d5dcd387d4623b1f1b.mp3", "hash": "e4734b7e58b137130ab952eab4c9f7d3c34243951548b1f2182624b1e850075b", "bytes": 29088, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/f04339a125b42ffa84a2983cc293abcf8ca40dd7ad2541d5dcd387d4623b1f1b.mp3", "duration_ms": 4800}, "s1-dialogue.line.2": {"url": "http://localhost:4006/files/lesson-audio/d699fc7e0bb5e295dd3b53e0db454e41f9b05d1332f23b08e7851252caa57ab3.mp3", "hash": "31eba0e860d786708e56bfe54105f0221cdce1268c1220750b028b6547a8969c", "bytes": 22464, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/d699fc7e0bb5e295dd3b53e0db454e41f9b05d1332f23b08e7851252caa57ab3.mp3", "duration_ms": 3680}, "s1-dialogue.line.3": {"url": "http://localhost:4006/files/lesson-audio/ba75741fef109dfffe9f788ac357945ec48e5da6e7d10957011d9c4a59e65feb.mp3", "hash": "1e57f03fd4f28315bee73bedba8f841a9928a38011e88e57f771244f163882d7", "bytes": 50256, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/ba75741fef109dfffe9f788ac357945ec48e5da6e7d10957011d9c4a59e65feb.mp3", "duration_ms": 8320}, "s1-dialogue.line.4": {"url": "http://localhost:4006/files/lesson-audio/34a0f465b4a7b1bad0379f73d28b66bd97ccbff0f6b7e360520adabee18ba729.mp3", "hash": "4d820599ee53fdeae31dec36703349a0b8eea859673305c55f43ecfcfbebe351", "bytes": 60768, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/34a0f465b4a7b1bad0379f73d28b66bd97ccbff0f6b7e360520adabee18ba729.mp3", "duration_ms": 10080}, "s1-dialogue.prompt": {"url": "http://localhost:4006/files/lesson-audio/0b86249f571f1a3ab02626e4ba00f4836fac3643e52f903607b2059425da0eb1.mp3", "hash": "a85de249f4fe009c5e86dcca3dc15c8b7d49c4cecbfa6a7925f51cd2ffb9b125", "bytes": 24336, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0b86249f571f1a3ab02626e4ba00f4836fac3643e52f903607b2059425da0eb1.mp3", "duration_ms": 4000}, "s1-dialogue.explanation": {"url": "http://localhost:4006/files/lesson-audio/84a97e9a763f088426fdf6aaaec046be323579edc93748f836d03cf95dfe8872.mp3", "hash": "99b66cb54960b18ad443aeaa513a8f1bc988b6490d7f5cce2642ab60dac2698f", "bytes": 35856, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/84a97e9a763f088426fdf6aaaec046be323579edc93748f836d03cf95dfe8872.mp3", "duration_ms": 5920}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0c46648e-ff7a-4ad4-bf42-5829cc3fd1ac', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "story-dialogue", "title": "Earning Money with an Idea", "locale": "en-US", "subject": "money", "objectives": ["Understanding that money is earned by offering something others want", "Recognizing that a clear goal helps you start earning money"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-dialogue", "xp": 0, "type": "story_dialogue", "hints": [], "title": "Liruf''s Guitar", "payload": {"lines": [{"action": "idle", "emotion": "thinking", "text_md": "Look at that guitar… it costs 80 pesos. I''ll never save up that much.", "character": "liruf"}, {"action": "idle", "emotion": "happy", "text_md": "What if you earn it yourself? You could sell lemonade in the neighborhood.", "character": "dina"}, {"action": "idle", "emotion": "surprised", "text_md": "Sell lemonade? People would pay me for that?", "character": "liruf"}, {"action": "idle", "emotion": "encouraging", "text_md": "Of course! If you make tasty lemonade, your neighbors will want to buy it. That''s how you earn money with your own idea.", "character": "dina"}, {"action": "idle", "emotion": "excited", "text_md": "Yes! I''m going to sell cups for 5 pesos each. If I sell 4 cups today, I''ll have 20 pesos… I''m less than halfway there! I can''t wait to start!", "character": "liruf"}]}, "narrator": {"emotion": "neutral", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/073ceb218593cb5127064f072d73a9b46e3bab4be2b94186b8e5fdc4fa3f3bcf.png", "prompt_md": "Dina and Liruf talk about the 80-peso guitar.", "difficulty": 1, "explanation_md": "Selling lemonade is a way to earn money by offering something others want.", "audio_segment_id": "s1-dialogue.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-dialogue.line.0": {"url": "http://localhost:4006/files/lesson-audio/196c9cf902401cfad9bc462eec1a19bacf5fa2b4df4a8b38198c6365aef1c998.mp3", "hash": "3dd8f1ffae883d69a5da0a6ed2acdf61bdf62e962fb74a88ed2c626f434318b1", "bytes": 28656, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/196c9cf902401cfad9bc462eec1a19bacf5fa2b4df4a8b38198c6365aef1c998.mp3", "duration_ms": 4720}, "s1-dialogue.line.1": {"url": "http://localhost:4006/files/lesson-audio/cfa71033167c9ca3ecac32892e8d53abcdcd898e380251ffc8015db8a182caa7.mp3", "hash": "c689bc0a291081fde52aefc33ff9df8ab35a1f9791168667276dbfa60fd11795", "bytes": 21888, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/cfa71033167c9ca3ecac32892e8d53abcdcd898e380251ffc8015db8a182caa7.mp3", "duration_ms": 3600}, "s1-dialogue.line.2": {"url": "http://localhost:4006/files/lesson-audio/aeb16ace2f438fe690307eb2e3aa83ae1030f5dd845482eed2429771bdf24fea.mp3", "hash": "31c357ac646f5aa9f25505f727607b606e2b396684609a77afa4415d6f9214ba", "bytes": 17136, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/aeb16ace2f438fe690307eb2e3aa83ae1030f5dd845482eed2429771bdf24fea.mp3", "duration_ms": 2800}, "s1-dialogue.line.3": {"url": "http://localhost:4006/files/lesson-audio/6d0dab3cf6f1681601aea4633ed1355f243d0c7ee3c971df6504c7950a2642f5.mp3", "hash": "a015d7bf015335ff935c0474cface4458c0be359f4663f18176038363f9212b0", "bytes": 39168, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/6d0dab3cf6f1681601aea4633ed1355f243d0c7ee3c971df6504c7950a2642f5.mp3", "duration_ms": 6480}, "s1-dialogue.line.4": {"url": "http://localhost:4006/files/lesson-audio/433fc3fddaa62fd2874061acf0166aa2caae5fc6d0444abcc62b679f0b218f5a.mp3", "hash": "6c7593c10c7e2c60b3b4aa87b897b09ef88ef163efafaf12c5f9f4d7fb5e9f70", "bytes": 54576, "voice": "qwen-tts-vc-liruf_en_us-voice-20260714105613837-fba6", "file_id": "lesson-audio/433fc3fddaa62fd2874061acf0166aa2caae5fc6d0444abcc62b679f0b218f5a.mp3", "duration_ms": 9040}, "s1-dialogue.prompt": {"url": "http://localhost:4006/files/lesson-audio/568d0d22758f98411f7ac4342367c11debd8976d71caaa448e3a0d515a879e6d.mp3", "hash": "5ef43c8c5ab2ece865662aa11e498c0db2410b238f31dde40aceb9a0db58e1f1", "bytes": 19008, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/568d0d22758f98411f7ac4342367c11debd8976d71caaa448e3a0d515a879e6d.mp3", "duration_ms": 3120}, "s1-dialogue.explanation": {"url": "http://localhost:4006/files/lesson-audio/1523b4415de57e1cf3e6acfe0135e3660a87c35787bdf7045fa8be122ff9c3bf.mp3", "hash": "845064314ac5421b5a980003e651a54b925bbf65d5c71ff0bdc4add5e9e917ab", "bytes": 22464, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/1523b4415de57e1cf3e6acfe0135e3660a87c35787bdf7045fa8be122ff9c3bf.mp3", "duration_ms": 3680}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('8f1a89c3-ae63-41f5-a2fa-70d1b7c6aac9', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "coin-count", "title": "Contar moedas: a primeira venda", "locale": "pt-BR", "subject": "money", "objectives": ["Contar moedas de 1, 2 e 5 pesos para somar uma quantia exata."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-contar-monedas", "xp": 10, "type": "coin_count", "hints": ["Primeiro conte as moedas de 2, depois as de 1.", "Junte todas as moedas e veja se somam 5."], "title": "A primeira venda", "payload": {"target": 5, "currency": "MXN", "denominations": [1, 2]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/aa6d3e5fbecef7d364aa326249cf5bfe077685371af57d34f75094a9044354fb.png", "prompt_md": "Conte as moedas que o cliente te deu. São 5 pesos exatos?", "difficulty": 1, "explanation_md": "Você tem uma moeda de 2 e três de 1: 2 + 1 + 1 + 1 = 5. Sim, são 5 pesos exatos!", "audio_segment_id": "s1-contar-monedas.prompt"}], "schema_version": 1}', '{"s1-contar-monedas": {}}', '{"units": {"s1-contar-monedas.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4eca274175cad926680cb7a53319c7a232cf42d7d0819f54555f5689c4e737ba.mp3", "hash": "1a383c76cfe233eba288489a3ff440f5cb40fde3582e3406c922dd1fbe312257", "bytes": 21024, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4eca274175cad926680cb7a53319c7a232cf42d7d0819f54555f5689c4e737ba.mp3", "duration_ms": 3440}, "s1-contar-monedas.hint.1": {"url": "http://localhost:4006/files/lesson-audio/36d998d56e57afbd8b61ccfff8d056c391ecc6fbb1cf4bef0f7fd6e1a874b81f.mp3", "hash": "fe5231008b7e7a409598dfc94e2bdba3aa6485d5f75c73101408a6979e7ec1e7", "bytes": 24768, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/36d998d56e57afbd8b61ccfff8d056c391ecc6fbb1cf4bef0f7fd6e1a874b81f.mp3", "duration_ms": 4080}, "s1-contar-monedas.prompt": {"url": "http://localhost:4006/files/lesson-audio/1ed57b04f58d2c78f50dc7b4dfeef73a679fc9281a7b15facbc88f5a18608dae.mp3", "hash": "c701dc83450716308c33c0a82bf90dc16bad3c9556ac8a4c03f9eb53d3f39b5f", "bytes": 26208, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1ed57b04f58d2c78f50dc7b4dfeef73a679fc9281a7b15facbc88f5a18608dae.mp3", "duration_ms": 4320}, "s1-contar-monedas.explanation": {"url": "http://localhost:4006/files/lesson-audio/e50662201024dddca33e54b4a565bc8cdb5e1cb28872026a3d1063ca2771c8b3.mp3", "hash": "9c0d93b4caba8d9491818dc1316552b3edcba3ca4f94007132d31fe4b61b7a12", "bytes": 58896, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/e50662201024dddca33e54b4a565bc8cdb5e1cb28872026a3d1063ca2771c8b3.mp3", "duration_ms": 9760}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('36624bae-eea6-49e3-8767-c43ffbdf09e7', 'pt-BR', '1', '{"meta": {"cast": ["dina"], "slug": "compare-table", "title": "Compare fornecedores de limões", "locale": "pt-BR", "subject": "mixed", "objectives": ["Leia uma tabela de dois fornecedores de limões (preço e quantidade) e escolha o que dá mais por menos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-compare-table", "xp": 15, "type": "compare_table", "hints": ["Veja quantos limões cada um dá por 5 reais."], "title": "Escolha o melhor fornecedor", "payload": {"cols": [{"id": "precio", "label": "Preço"}, {"id": "cantidad", "label": "Quantidade de limões"}], "rows": [{"id": "proveedor-a", "label": "Fornecedor A"}, {"id": "proveedor-b", "label": "Fornecedor B"}], "tokens": [{"id": "t1", "text_md": "5 reais"}, {"id": "t2", "text_md": "10 limões"}, {"id": "t3", "text_md": "5 reais"}, {"id": "t4", "text_md": "8 limões"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/0ec3149e44b0dd33b5cff3bf4f74c86d99165b0e5b906c34d4585f62f20e7c76.png", "prompt_md": "Dina tem 5 reais. Com qual fornecedor ela consegue mais limões?", "difficulty": 1, "explanation_md": "Com o fornecedor A, Dina obtém 10 limões por seus 5 reais. Com o B, apenas 8. O A dá mais limões pelo mesmo dinheiro!", "audio_segment_id": "s1-compare-table.prompt"}], "schema_version": 1}', '{"s1-compare-table": {"cells": {"proveedor-a:precio": "t1", "proveedor-b:precio": "t3", "proveedor-a:cantidad": "t2", "proveedor-b:cantidad": "t4"}}}', '{"units": {"s1-compare-table.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4ecc6f70d000c9fcd95eadd6971116a54ac0088ecd359480bc8aeab4c02bc828.mp3", "hash": "5fe7411db6c951dc5fcde7a93d5a7d18f42229df396493e11e9d849f9ff2a3fe", "bytes": 26208, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4ecc6f70d000c9fcd95eadd6971116a54ac0088ecd359480bc8aeab4c02bc828.mp3", "duration_ms": 4320}, "s1-compare-table.prompt": {"url": "http://localhost:4006/files/lesson-audio/d32ffff6265a06aa572d5d269656df7ebe2cc665b24a3d756fe4fe733813e43a.mp3", "hash": "7ae9e23ffa8bcbbf99f8df06e8b9c9888af372d18275850a6ab9a01508706b8e", "bytes": 31968, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d32ffff6265a06aa572d5d269656df7ebe2cc665b24a3d756fe4fe733813e43a.mp3", "duration_ms": 5280}, "s1-compare-table.explanation": {"url": "http://localhost:4006/files/lesson-audio/ba18dd28356a78d6bd086a1a17a4e7cfc60cd01db8068422d097911090770225.mp3", "hash": "70f0ad64bedb2a823fc504333862a4c980e2b7e378876985083b37a77a25d4af", "bytes": 64224, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/ba18dd28356a78d6bd086a1a17a4e7cfc60cd01db8068422d097911090770225.mp3", "duration_ms": 10640}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('105d5cdf-c98a-4076-a3ed-440deb643d64', 'es-MX', '1', '{"meta": {"cast": ["dina"], "slug": "would-you-rather", "title": "¿Qué harías tú?", "locale": "es-MX", "subject": "mixed", "objectives": ["Elegir entre dos caminos del vendedor y defenderlo: ¿ganar 10 pesos hoy o 20 la próxima semana?"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-would-you-rather", "xp": 10, "type": "would_you_rather", "hints": ["Piensa en lo que más necesitas ahora: ¿un gusto hoy o algo más grande después?", "Ninguna respuesta es mala, pero cada una tiene una consecuencia diferente."], "title": "Ganar hoy o mañana", "payload": {"a": {"icon": "local_atm", "text_md": "Ganar 10 pesos hoy vendiendo 2 vasos de limonada ahora mismo.", "image_url": "http://localhost:4006/files/lesson-images/e329f79c8688db11db861c7fdce569e94cf0a24f8beba801c903899cbad7e4e2.png"}, "b": {"icon": "schedule", "text_md": "Esperar a la próxima semana para ganar 20 pesos vendiendo 4 vasos.", "image_url": "http://localhost:4006/files/lesson-images/9c66ad02a222309f84564e572f3f1f8e273f4b1542a9cb876b001c41ca7e5d88.png"}, "followup_md": "¿Por qué elegiste esa opción? Cuéntale a Dina tu razón."}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Dina te pregunta: ¿qué harías tú?", "difficulty": 1, "explanation_md": "Dina sonríe: ''No hay respuesta única, lo importante es que pienses en lo que ganas y lo que pierdes con cada decisión.''", "audio_segment_id": "s1-would-you-rather.prompt"}], "schema_version": 1}', '{"s1-would-you-rather": {"qualities": {"a": 50, "b": 50}, "reveal_md": "Dina asiente: ''Si eliges 10 hoy, tienes dinero rápido para un antojo. Si eliges 20 la próxima semana, ahorras más pero esperas. Ambas son decisiones válidas.''"}}', '{"units": {"s1-would-you-rather.hint.0": {"url": "http://localhost:4006/files/lesson-audio/74c512b21721ae8a31fed1809d4b8e5d0cc008dc8a818019cfd33139585c7be6.mp3", "hash": "1900c151cfdedadc13c5cbe601268ca604e0d95db32e6b98ec8cf229cc740b5c", "bytes": 32544, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/74c512b21721ae8a31fed1809d4b8e5d0cc008dc8a818019cfd33139585c7be6.mp3", "duration_ms": 5360}, "s1-would-you-rather.hint.1": {"url": "http://localhost:4006/files/lesson-audio/e475e53851c14f7d311cfd1b1e0e9c976fe5168b135465c00292ec442bcc6329.mp3", "hash": "0a922049f455845c5d510888aea1f0e100d8a7e1c38f3eb5a3d1a7631d65d0db", "bytes": 31104, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/e475e53851c14f7d311cfd1b1e0e9c976fe5168b135465c00292ec442bcc6329.mp3", "duration_ms": 5120}, "s1-would-you-rather.prompt": {"url": "http://localhost:4006/files/lesson-audio/c88ca30bbd61b612d930680a7d1c0c0885a07db00f27bc4e60d17b18d352d70a.mp3", "hash": "fc3522a451d8757d79bff7a568c5291ad876cd0813ff117e5c5b6e9e1118aad8", "bytes": 16128, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c88ca30bbd61b612d930680a7d1c0c0885a07db00f27bc4e60d17b18d352d70a.mp3", "duration_ms": 2640}, "s1-would-you-rather.choices": {"url": "http://localhost:4006/files/lesson-audio/64ae996d12cf01ce1c5504c2976fbcea0356527f7da97c7e880ef9002c9ed40b.mp3", "hash": "3dd551a98812e49bf97094d6b5fa9b904423afe1f6351cb3e25d8076f45b5c1b", "bytes": 58896, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/64ae996d12cf01ce1c5504c2976fbcea0356527f7da97c7e880ef9002c9ed40b.mp3", "duration_ms": 9760}, "s1-would-you-rather.explanation": {"url": "http://localhost:4006/files/lesson-audio/e163569f2409016713ab0c84603cff6a0a260e1c019c936506dafb63b64929c3.mp3", "hash": "9370af0342b0a981dc32ac97a8b93318a65e7b053853c037e6422a364ccff431", "bytes": 44496, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/e163569f2409016713ab0c84603cff6a0a260e1c019c936506dafb63b64929c3.mp3", "duration_ms": 7360}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f9ad47f4-7031-4552-97cd-a0b426882208', 'es-MX', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "code-order", "title": "La registradora de cartón de Rho", "locale": "es-MX", "subject": "mixed", "objectives": ["Ordenar las instrucciones de la registradora casera: recibir pago, verificar monto, dar cambio, anotar la venta."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-code-order", "xp": 15, "type": "code_order", "hints": ["Piensa: primero el cliente paga, luego revisas si es suficiente, después devuelves el cambio, y al final apuntas la venta.", "El paso que usa la calculadora va antes de dar el cambio."], "title": "Ordena los pasos de la registradora", "payload": {"blocks": [{"id": "b1", "text_md": "Recibir pago"}, {"id": "b2", "text_md": "Verificar monto"}, {"id": "b3", "text_md": "Dar cambio"}, {"id": "b4", "text_md": "Anotar la venta"}], "language_hint": "es-MX"}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Rho vende un mango por 15 pesos. El cliente paga con 20. Ordena los pasos: ¿qué hace primero, segundo, tercero y cuarto?", "difficulty": 2, "explanation_md": "Primero recibes los 20 pesos, luego verificas que 20 alcanza para el mango de 15, después das 5 de cambio y al final anotas la venta. Así Rho no se equivoca.", "audio_segment_id": "s1-code-order.prompt"}], "schema_version": 1}', '{"s1-code-order": {"order": ["b1", "b2", "b3", "b4"]}}', '{"units": {"s1-code-order.hint.0": {"url": "http://localhost:4006/files/lesson-audio/1d46f06b9a0ec81d25588d44ff3efedf303b83f66fb50b92b5f264b569fbdbd8.mp3", "hash": "ba901365b78a499e641979137667153343a5b453aebb51c0b22221b3f8d06384", "bytes": 50688, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/1d46f06b9a0ec81d25588d44ff3efedf303b83f66fb50b92b5f264b569fbdbd8.mp3", "duration_ms": 8400}, "s1-code-order.hint.1": {"url": "http://localhost:4006/files/lesson-audio/d83fa48aa1e2bfb1866e853d6f1f27c4dcbc5a74956417020748fcfde51f0872.mp3", "hash": "37cc7db8d941fce97c40146838907884afab848a2fc6bd078d19657ec1cc4868", "bytes": 25344, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d83fa48aa1e2bfb1866e853d6f1f27c4dcbc5a74956417020748fcfde51f0872.mp3", "duration_ms": 4160}, "s1-code-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/c0c36311348889c80bde33a61eead1711e44d31618db007356c073027e9aa036.mp3", "hash": "44599f5c8c451e0dde134feace52bcd85a9bcb802217cef142ef58c8a55621b0", "bytes": 59904, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/c0c36311348889c80bde33a61eead1711e44d31618db007356c073027e9aa036.mp3", "duration_ms": 9920}, "s1-code-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/d9bda10c09c9893dbc9406434bed2f157e2e1a7f219d567b8791dd05c42f9797.mp3", "hash": "77c883b3e371608f832f701e8655c8e739d2faf711a0b771eb87b55862c20092", "bytes": 67968, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d9bda10c09c9893dbc9406434bed2f157e2e1a7f219d567b8791dd05c42f9797.mp3", "duration_ms": 11280}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('a00c4534-6e88-42ac-ab77-3465a684f47d', 'pt-BR', '1', E'{"meta": {"cast": ["dina", "liruf"], "slug": "story-scene", "title": "O plano de Liruf", "locale": "pt-BR", "subject": "money", "objectives": ["Entender que o dinheiro é ganho oferecendo algo que os outros querem, e que uma meta clara ajuda a começar."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-plan", "xp": 0, "type": "story_scene", "hints": [], "title": "O plano de Liruf", "payload": {"art": {"icon": "emoji_objects", "tint": "primary", "image_url": "http://localhost:4006/files/lesson-images/3a496d28daa212320a30dbef743979ba46bd06dc73cb227ad4a43d0508067bed.png"}, "action": "idle", "body_md": "Liruf desenha em um cartaz: um copo de limonada custa **5 reais**. O violão custa **80 reais**. \\"Se eu vender muitos copos, posso comprar o violão!\\" diz Liruf.", "emotion": "happy", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Liruf desenha seu plano.", "difficulty": 1, "explanation_md": "Liruf desenhou um copo de limonada que vale 5 reais e um violão que custa 80. Assim ele sabe quantos copos vender.", "audio_segment_id": "s1-plan.prompt"}], "schema_version": 1}', '{}', '{"units": {"s1-plan.body": {"url": "http://localhost:4006/files/lesson-audio/f7bdb26cfef48b079eda8c069114bf2633b82336ec97d8dbe6d5a25bb1008157.mp3", "hash": "350da380c4a6462ad6567ccb1bd6e582051db2eec6d3f502ced80f812a41adf7", "bytes": 74304, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/f7bdb26cfef48b079eda8c069114bf2633b82336ec97d8dbe6d5a25bb1008157.mp3", "duration_ms": 12320}, "s1-plan.prompt": {"url": "http://localhost:4006/files/lesson-audio/08082eb61881b89a22d76c0ba068d2f5c1e8c666bc487b733ae2fe2e35089459.mp3", "hash": "91e1635e4b1b5234f52a574eb2282772dde6c4a73e13a1826f07ccfaca9af40d", "bytes": 12384, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/08082eb61881b89a22d76c0ba068d2f5c1e8c666bc487b733ae2fe2e35089459.mp3", "duration_ms": 2000}, "s1-plan.explanation": {"url": "http://localhost:4006/files/lesson-audio/ab10ca1f5e3e8b98e54aae557563d446eccf2879da04f5b4dd9b403d8c136aa8.mp3", "hash": "88dff9de291d2fd305721fd8cab6a2a34d0aaf71343d6c962746f2b2d93c63e5", "bytes": 57456, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/ab10ca1f5e3e8b98e54aae557563d446eccf2879da04f5b4dd9b403d8c136aa8.mp3", "duration_ms": 9520}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f9ad47f4-7031-4552-97cd-a0b426882208', 'en-US', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "code-order", "title": "Rho''s cardboard cash register", "locale": "en-US", "subject": "mixed", "objectives": ["Order the instructions for the homemade cash register: receive payment, verify amount, give change, record the sale."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-code-order", "xp": 15, "type": "code_order", "hints": ["Think: first the customer pays, then you check if it''s enough, then you give back the change, and finally you record the sale.", "The step that uses the calculator comes before giving change."], "title": "Order the cash register steps", "payload": {"blocks": [{"id": "b1", "text_md": "Receive payment"}, {"id": "b2", "text_md": "Verify amount"}, {"id": "b3", "text_md": "Give change"}, {"id": "b4", "text_md": "Record the sale"}], "language_hint": "en-US"}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Rho sells a mango for 15 pesos. The customer pays with 20. Order the steps: what does he do first, second, third, and fourth?", "difficulty": 2, "explanation_md": "First you receive the 20 pesos, then you verify that 20 is enough for the 15-peso mango, then you give 5 in change, and finally you record the sale. That way Rho doesn''t make a mistake.", "audio_segment_id": "s1-code-order.prompt"}], "schema_version": 1}', '{"s1-code-order": {"order": ["b1", "b2", "b3", "b4"]}}', '{"units": {"s1-code-order.hint.0": {"url": "http://localhost:4006/files/lesson-audio/71d5dc00a9eb8bbbf3c3941e4a82e6dc579ba96c3f8cbb32198b74fa62572598.mp3", "hash": "7c4141b5233d9c323c9ae71c64fb3e2f67889e1f767a3b99478216e35d1c9367", "bytes": 43056, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/71d5dc00a9eb8bbbf3c3941e4a82e6dc579ba96c3f8cbb32198b74fa62572598.mp3", "duration_ms": 7120}, "s1-code-order.hint.1": {"url": "http://localhost:4006/files/lesson-audio/fb7044f67527c0fe5d61e51f0d7a03632066c2f165d4b2fcc1fd2d198c24e1f3.mp3", "hash": "06d9709ffd02bb8d590e8676fd5da1842432925cf37f741a0526e68de54e20c8", "bytes": 18576, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/fb7044f67527c0fe5d61e51f0d7a03632066c2f165d4b2fcc1fd2d198c24e1f3.mp3", "duration_ms": 3040}, "s1-code-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/d85113d0e9382dadf3c9f37e040ded01658f9e3dc7844c74502a7413923d08dd.mp3", "hash": "838d2107d11f0084345a1ae0c6552545f3506f87a3392b25b324fb48f5a2d46a", "bytes": 47376, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/d85113d0e9382dadf3c9f37e040ded01658f9e3dc7844c74502a7413923d08dd.mp3", "duration_ms": 7840}, "s1-code-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/66f666bf16655b2e3b189d30bb8968fd72d1090acfa5ceb7e7e38aae473e9dfd.mp3", "hash": "c5a1e8e7521facc3d6e2aba810ddaecbf7f13ff8430ca8df57111337ba912c93", "bytes": 61776, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/66f666bf16655b2e3b189d30bb8968fd72d1090acfa5ceb7e7e38aae473e9dfd.mp3", "duration_ms": 10240}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4a340725-6bd9-48c4-9c1a-d8641c86b7a1', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "evidence-hunt", "title": "Caça à evidência no recibo", "locale": "pt-BR", "subject": "mixed", "objectives": ["Procurar no recibo do mercado a evidência exata de quanto custaram os limões."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-evidence-hunt", "xp": 10, "type": "evidence_hunt", "hints": ["Procure a palavra ''limões'' no recibo.", "O preço está ao lado da palavra ''limões''."], "title": "O recibo amassado", "payload": {"claim_md": "Liruf diz: ''Gastei 20 reais em limões no mercado.''", "sentences": [{"id": "s1-line1", "text_md": "Limões — 15"}, {"id": "s1-line2", "text_md": "Açúcar — 5"}, {"id": "s1-line3", "text_md": "Copos — 8"}]}, "narrator": {"emotion": "thinking", "character": "dina"}, "image_url": "http://localhost:4006/files/lesson-images/dd487b53e3cb706e2810fa6595d736dd75838967392b39372122299a9a8914d6.png", "prompt_md": "Toque na linha do recibo que mostra quanto custaram os limões.", "difficulty": 1, "explanation_md": "A linha que diz ''limões'' e ''15'' é a evidência exata do custo dos limões. Assim como no gráfico da aula passada você procurou o dia com mais vendas, aqui você procura a linha correta no recibo.", "audio_segment_id": "s1-evidence-hunt.prompt"}], "schema_version": 1}', '{"s1-evidence-hunt": {"evidence_ids": ["s1-line1"]}}', '{"units": {"s1-evidence-hunt.hint.0": {"url": "http://localhost:4006/files/lesson-audio/b61f6eafbf0e6b1fa18d98e662a3ba44bc6ec683477dcd9898d18f067bd22089.mp3", "hash": "1156f773679aabf911604bf2365c7d4fea1970c9cdda416cc6d77708336e8267", "bytes": 18576, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/b61f6eafbf0e6b1fa18d98e662a3ba44bc6ec683477dcd9898d18f067bd22089.mp3", "duration_ms": 3040}, "s1-evidence-hunt.hint.1": {"url": "http://localhost:4006/files/lesson-audio/1c626687a6cb9528dd905ca8f114fc32aa073def069c617ac02efbc1ee731d50.mp3", "hash": "1f713c46903167ce96eb7ec04484a981b92e4f889c00b7066f05c271a126ba9f", "bytes": 19584, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/1c626687a6cb9528dd905ca8f114fc32aa073def069c617ac02efbc1ee731d50.mp3", "duration_ms": 3200}, "s1-evidence-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/998d5ccc179c7e883c341e32137d11a84e8f70aa356fed520e9e7b0845095ad8.mp3", "hash": "e3a8ce55d914667e7cd3c98c756743deb2d431d69f70ac8f514af7615a3e23e4", "bytes": 25776, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/998d5ccc179c7e883c341e32137d11a84e8f70aa356fed520e9e7b0845095ad8.mp3", "duration_ms": 4240}, "s1-evidence-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/27efbcd7952b180ce217d6eee43c5f90268dcda81288224900330abb4cd58266.mp3", "hash": "0ada7fd0c64fc91cd596a70c4c3522ba8bf8c61302bdd993fd96baa1b1af856c", "bytes": 82944, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/27efbcd7952b180ce217d6eee43c5f90268dcda81288224900330abb4cd58266.mp3", "duration_ms": 13760}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('85c2a66b-c70b-43e4-8fd5-4862d4acb66b', 'en-US', '1', '{"meta": {"cast": ["dina", "rho", "liruf"], "slug": "rank-choices", "title": "Order the stand''s purchases", "locale": "en-US", "subject": "money", "objectives": ["Rank from most to least urgent what to spend today''s profit on: restock lemons first, then cups, and finally decorations."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-rank", "xp": 15, "type": "rank_choices", "hints": ["No lemons, no lemonade; no cups, no serving.", "Decorations are nice, but not urgent for selling today."], "title": "What to buy first?", "payload": {"items": [{"id": "limones", "text_md": "Lemons for lemonade", "image_url": "http://localhost:4006/files/lesson-images/15e3579916c1ea9b65742f2d00408d845d4041f514743bca8d75ea0e119e9ec3.png"}, {"id": "vasos", "text_md": "Cups for serving", "image_url": "http://localhost:4006/files/lesson-images/39bc65d1cc38e1ddcb1bd0b49d93a0188924d549300149df758b0cc3626ab6d5.png"}, {"id": "adornos", "text_md": "Decorations for the stand", "image_url": "http://localhost:4006/files/lesson-images/ddc5f381842bf8f1e6e7a33df5fb20b5b3b16dfedebbab891f1b23efc83d05b5.png"}], "criterion_md": "Rank from most to least urgent for Liruf''s stand"}, "narrator": {"emotion": "thinking", "character": "rho"}, "prompt_md": "Liruf has $20. Tap the expenses in order: the most urgent first.", "difficulty": 2, "explanation_md": "Lemons are the most urgent because without them there is no lemonade. Cups come next, and decorations last, because they are a treat that can wait.", "audio_segment_id": "s1-rank.prompt"}], "schema_version": 1}', '{"s1-rank": {"order": ["limones", "vasos", "adornos"]}}', '{"units": {"s1-rank.hint.0": {"url": "http://localhost:4006/files/lesson-audio/e759f01304c694625fb4069c3147b78236b41545f5da8ba122ba359a40b0c8d2.mp3", "hash": "9560e0b2d963fc0182a99614a6d80a29098b3e4e33373afa2dd4e9c5bea1b8e1", "bytes": 25776, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/e759f01304c694625fb4069c3147b78236b41545f5da8ba122ba359a40b0c8d2.mp3", "duration_ms": 4240}, "s1-rank.hint.1": {"url": "http://localhost:4006/files/lesson-audio/1983be8f746d3c499eb3c0aa379667e9e125fc718fdd66e50febe92a12a41006.mp3", "hash": "b2d78cc7d56648b827b416f1df87d90e5ce940660b86b6f6e0ed4c3d8ce1ba5a", "bytes": 23904, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/1983be8f746d3c499eb3c0aa379667e9e125fc718fdd66e50febe92a12a41006.mp3", "duration_ms": 3920}, "s1-rank.prompt": {"url": "http://localhost:4006/files/lesson-audio/5526dae849886ea70b528f0a4c50e6c1897eed61d7b1d244d1bfa00116281a93.mp3", "hash": "4e1a43727636b386a7a5e218dbd352d4061b869d966c11ee3a96d1ed303eb0cc", "bytes": 36864, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/5526dae849886ea70b528f0a4c50e6c1897eed61d7b1d244d1bfa00116281a93.mp3", "duration_ms": 6080}, "s1-rank.explanation": {"url": "http://localhost:4006/files/lesson-audio/75b3e7c9a020dd7597aeb6e6e58f9210db2346bcc904e06fc8cc568978b922ac.mp3", "hash": "2c7d46b35a3b87bfba477c8742ffc19774b4c70bd336cb3af281a58edeb834c8", "bytes": 64656, "voice": "qwen-tts-vc-rho_en_us-voice-20260714105627877-07ef", "file_id": "lesson-audio/75b3e7c9a020dd7597aeb6e6e58f9210db2346bcc904e06fc8cc568978b922ac.mp3", "duration_ms": 10720}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('f9ad47f4-7031-4552-97cd-a0b426882208', 'pt-BR', '1', '{"meta": {"cast": ["dina", "rho"], "slug": "code-order", "title": "A registradora de papelão da Rho", "locale": "pt-BR", "subject": "mixed", "objectives": ["Ordenar as instruções da registradora caseira: receber pagamento, verificar valor, dar troco, anotar a venda."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-code-order", "xp": 15, "type": "code_order", "hints": ["Pense: primeiro o cliente paga, depois você confere se é suficiente, em seguida devolve o troco, e por fim anota a venda.", "O passo que usa a calculadora vem antes de dar o troco."], "title": "Ordenar os passos da registradora", "payload": {"blocks": [{"id": "b1", "text_md": "Receber pagamento"}, {"id": "b2", "text_md": "Verificar valor"}, {"id": "b3", "text_md": "Dar troco"}, {"id": "b4", "text_md": "Anotar a venda"}], "language_hint": "pt-BR"}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Rho vende uma manga por 15 pesos. O cliente paga com 20. Ordene os passos: o que ela faz primeiro, segundo, terceiro e quarto?", "difficulty": 2, "explanation_md": "Primeiro você recebe os 20 pesos, depois verifica que 20 é suficiente para a manga de 15, em seguida dá 5 de troco e por fim anota a venda. Assim a Rho não erra.", "audio_segment_id": "s1-code-order.prompt"}], "schema_version": 1}', '{"s1-code-order": {"order": ["b1", "b2", "b3", "b4"]}}', '{"units": {"s1-code-order.hint.0": {"url": "http://localhost:4006/files/lesson-audio/6048735bb52c67a4e643b44ebb82da4bfd93217354800cf6248e724a641478a0.mp3", "hash": "ca79e0718a7b572ec25f8497c5d9834841cfd078b12faf8e7741ad9251d70dd8", "bytes": 52704, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/6048735bb52c67a4e643b44ebb82da4bfd93217354800cf6248e724a641478a0.mp3", "duration_ms": 8720}, "s1-code-order.hint.1": {"url": "http://localhost:4006/files/lesson-audio/5edd63fabf5247458fed90493b850bf406cce31b1a5874d18b6ab9bd84bedb84.mp3", "hash": "3391a96e9d49875f05d546605daaf16764eaee5363367b6f800630030e84ea24", "bytes": 23328, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/5edd63fabf5247458fed90493b850bf406cce31b1a5874d18b6ab9bd84bedb84.mp3", "duration_ms": 3840}, "s1-code-order.prompt": {"url": "http://localhost:4006/files/lesson-audio/3d0a064df538dbb79207075d629a6274ab767bbd0720218d8451d03089e020f6.mp3", "hash": "e1f43d20f5462c1a5225ef57f6a308c0210c22212cf6aaf661ff4f8229bce590", "bytes": 62784, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/3d0a064df538dbb79207075d629a6274ab767bbd0720218d8451d03089e020f6.mp3", "duration_ms": 10400}, "s1-code-order.explanation": {"url": "http://localhost:4006/files/lesson-audio/4f874ab7f5f0072003b880285b96fa57c03bdc619373a8fb30d993752c32a744.mp3", "hash": "3cd2c2a28e5699fd10854a801aa400dacb9234becfc7f81ce6bd2ba6168b9a4d", "bytes": 74304, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/4f874ab7f5f0072003b880285b96fa57c03bdc619373a8fb30d993752c32a744.mp3", "duration_ms": 12320}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('9ceeee19-c270-4624-a828-92e6f501754e', 'en-US', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "confidence-quiz", "title": "Confidence in your accounts", "locale": "en-US", "subject": "money", "objectives": ["Add two small amounts (5+5) and evaluate your confidence in the result."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-confidence-quiz", "xp": 10, "type": "confidence_quiz", "hints": ["Each glass costs 5 pesos. What is 5 plus 5?", "You can count on your fingers: 5 fingers from one hand and 5 from the other."], "title": "How much did Liruf sell?", "payload": {"options": [{"id": "opt-10-seguro", "text_md": "10 pesos — very sure", "rationale_md": "Correct! 5+5=10 and you feel confident. Great!"}, {"id": "opt-10-inseguro", "text_md": "10 pesos — not so sure", "rationale_md": "The result is correct (10 pesos), but you can trust your calculation more. Keep practicing!"}, {"id": "opt-8-seguro", "text_md": "8 pesos — very sure", "rationale_md": "It seems you subtracted instead of adding. Each glass costs 5, and two glasses are 5+5=10, not 8."}, {"id": "opt-12-seguro", "text_md": "12 pesos — very sure", "rationale_md": "You added too much. Each glass costs 5, and two glasses are 5+5=10, not 12."}]}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Liruf sold two glasses of lemonade. How much money did he collect? Then choose how sure you are.", "difficulty": 1, "explanation_md": "Each glass costs 5 pesos, and two glasses are 5 + 5 = 10 pesos. Liruf collected 10 pesos!", "audio_segment_id": "s1-confidence-quiz.prompt"}], "schema_version": 1}', '{"s1-confidence-quiz": {"correct_option_id": "opt-10-seguro"}}', '{"units": {"s1-confidence-quiz.hint.0": {"url": "http://localhost:4006/files/lesson-audio/4c24cd3ef86458b33e97d52f48c974d63a3a22b715dbc3094dba75268e4a281c.mp3", "hash": "1e3420da6641f2ad4a169943e14c93bfa458c7c6ffe4e995d380aed124bc9848", "bytes": 21456, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/4c24cd3ef86458b33e97d52f48c974d63a3a22b715dbc3094dba75268e4a281c.mp3", "duration_ms": 3520}, "s1-confidence-quiz.hint.1": {"url": "http://localhost:4006/files/lesson-audio/f2370117c2923efda50768c99a86f33911846ea1021c8b3189f851a61f1685bf.mp3", "hash": "0c0c5b960abe31ca4c6fa8595e7f1b4f3af74faf62d8f90dd4933c4c8c8b95a5", "bytes": 27216, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/f2370117c2923efda50768c99a86f33911846ea1021c8b3189f851a61f1685bf.mp3", "duration_ms": 4480}, "s1-confidence-quiz.prompt": {"url": "http://localhost:4006/files/lesson-audio/629a5762b1ac7aa6755bd4cafb0a6878aab1684e69e8c8bea292ef5a5d77c75f.mp3", "hash": "6589e054fb87f3078c6e547f8cfe2bad65038ff7474e70cc438d501155676492", "bytes": 32544, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/629a5762b1ac7aa6755bd4cafb0a6878aab1684e69e8c8bea292ef5a5d77c75f.mp3", "duration_ms": 5360}, "s1-confidence-quiz.choices": {"url": "http://localhost:4006/files/lesson-audio/7ea651d5837ccc0ae90a310f53621bf087d7be02e258bb9df6633e65287051ae.mp3", "hash": "7c040792f382d90bdb910adb050841e7228117d8c0e43aa4349eb0b0dab99f6f", "bytes": 45936, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/7ea651d5837ccc0ae90a310f53621bf087d7be02e258bb9df6633e65287051ae.mp3", "duration_ms": 7600}, "s1-confidence-quiz.explanation": {"url": "http://localhost:4006/files/lesson-audio/9de4c570e1c9118bde3cd5c3db94d640b644fe0d3c073f01158358efc5b82c71.mp3", "hash": "874254d4e7c8eb07a765af6eb5c5d48ec93028f4dcdeb9b71c8c44e788e0e77e", "bytes": 44064, "voice": "qwen-tts-vc-dina_en_us-voice-20260714105602187-c3d4", "file_id": "lesson-audio/9de4c570e1c9118bde3cd5c3db94d640b644fe0d3c073f01158358efc5b82c71.mp3", "duration_ms": 7280}}, "version": 1, "voice_profile": "Jennifer"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c3cd699b-431a-4c74-8563-19360a968d77', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "debug-hunt", "title": "Cacería de errores: el cartel de la promoción", "locale": "es-MX", "subject": "mixed", "objectives": ["Encontrar el error en un cartel de promoción que anuncia 2 vasos por 8 pesos cuando cada vaso cuesta 5 pesos suelto.", "Corregir el precio o la cantidad para que la promoción sea más barata que comprar sueltos."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-debug-hunt", "xp": 15, "type": "debug_hunt", "hints": ["Cada vaso cuesta 5 pesos suelto. ¿Cuánto cuestan dos vasos sueltos?", "La promoción debe ser más barata que comprar sueltos, no más cara."], "title": "El cartel equivocado", "payload": {"blocks": [{"id": "b1", "text_md": "2 vasos por 8 pesos"}, {"id": "b2", "text_md": "¡Sale más caro que comprar sueltos!"}, {"id": "b3", "text_md": "Cada vaso suelto: 5 pesos"}], "intro_md": "Liruf puso un cartel de promoción: ''2 vasos de limonada por 8 pesos''. Pero los clientes se ríen. Dice que sale más caro que comprar sueltos. ¿Tiene razón?"}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Toca el error en el cartel de promoción.", "difficulty": 2, "explanation_md": "Dos vasos sueltos cuestan 10 pesos (5+5). La promoción los vende a 8 pesos, que es más barato. Pero el cartel dice ''2 vasos por 8 pesos… ¡sale más caro!'' — el error es que dice ''más caro'' cuando en realidad es más barato.", "audio_segment_id": "s1-debug-hunt.prompt"}], "schema_version": 1}', '{"s1-debug-hunt": {"fix_md": "Cambiar ''más caro'' por ''más barato''. La promoción de 2 vasos por 8 pesos es más barata que comprar dos sueltos por 10 pesos.", "bug_ids": ["b2"]}}', '{"units": {"s1-debug-hunt.hint.0": {"url": "http://localhost:4006/files/lesson-audio/7e3cca58bc5730caa5d170f1d04c84e2a78699f22daeeff61276c9f5afff211a.mp3", "hash": "790216eabd6b6af61a8549583df788cce644dc9b1b980890e5422dccfc131741", "bytes": 30528, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7e3cca58bc5730caa5d170f1d04c84e2a78699f22daeeff61276c9f5afff211a.mp3", "duration_ms": 5040}, "s1-debug-hunt.hint.1": {"url": "http://localhost:4006/files/lesson-audio/8c46bfd916d1be2aece1cbef9eb94f6deaa71fdc426966afce592519c1287c19.mp3", "hash": "8f1b7afbb4244054a3c4cc7a7e1e4644310f09e239d0cf0bd0e3bc3b0762a540", "bytes": 26784, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/8c46bfd916d1be2aece1cbef9eb94f6deaa71fdc426966afce592519c1287c19.mp3", "duration_ms": 4400}, "s1-debug-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/e82cc4b2435fe8b7c1bdf7faccfbedcbdfecd3edcdcd8742cb405e68aef01076.mp3", "hash": "d7ea1fcf50c021887fd2af02658c4b0706efbcf4016e96144be63bbaddc46069", "bytes": 14688, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/e82cc4b2435fe8b7c1bdf7faccfbedcbdfecd3edcdcd8742cb405e68aef01076.mp3", "duration_ms": 2400}, "s1-debug-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/4ea3c2778e46c460f7375c0f5e94e8191cb93393a6c749d12924d2daeabc0643.mp3", "hash": "b9653dc19ad0e107bd268a5e33812d8ef9d2eea0588ccacc351c788a3730d50f", "bytes": 93456, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/4ea3c2778e46c460f7375c0f5e94e8191cb93393a6c749d12924d2daeabc0643.mp3", "duration_ms": 15520}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('c3cd699b-431a-4c74-8563-19360a968d77', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "debug-hunt", "title": "Caça aos erros: o cartaz da promoção", "locale": "pt-BR", "subject": "mixed", "objectives": ["Encontrar o erro em um cartaz de promoção que anuncia 2 copos por 8 pesos quando cada copo custa 5 pesos avulso.", "Corrigir o preço ou a quantidade para que a promoção seja mais barata do que comprar avulso."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-debug-hunt", "xp": 15, "type": "debug_hunt", "hints": ["Cada copo custa 5 pesos avulso. Quanto custam dois copos avulsos?", "A promoção deve ser mais barata do que comprar avulso, não mais cara."], "title": "O cartaz errado", "payload": {"blocks": [{"id": "b1", "text_md": "2 copos por 8 pesos"}, {"id": "b2", "text_md": "Sai mais caro do que comprar avulso!"}, {"id": "b3", "text_md": "Cada copo avulso: 5 pesos"}], "intro_md": "Liruf colocou um cartaz de promoção: ''2 copos de limonada por 8 pesos''. Mas os clientes riem. Diz que sai mais caro do que comprar avulso. Será que ele tem razão?"}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Toque no erro no cartaz de promoção.", "difficulty": 2, "explanation_md": "Dois copos avulsos custam 10 pesos (5+5). A promoção os vende por 8 pesos, que é mais barato. Mas o cartaz diz ''2 copos por 8 pesos… sai mais caro!'' — o erro é que diz ''mais caro'' quando na verdade é mais barato.", "audio_segment_id": "s1-debug-hunt.prompt"}], "schema_version": 1}', '{"s1-debug-hunt": {"fix_md": "Cambiar ''más caro'' por ''más barato''. La promoción de 2 vasos por 8 pesos es más barata que comprar dos sueltos por 10 pesos.", "bug_ids": ["b2"]}}', '{"units": {"s1-debug-hunt.hint.0": {"url": "http://localhost:4006/files/lesson-audio/a764e5838b4e8c44549e2474bb32adaa18929b6f86effb0b06a964c58ad15ccd.mp3", "hash": "1253d6b9b9f3c330da769db30100d805ec9ec5ce27a183e3e9286e42c3d7e755", "bytes": 33408, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a764e5838b4e8c44549e2474bb32adaa18929b6f86effb0b06a964c58ad15ccd.mp3", "duration_ms": 5520}, "s1-debug-hunt.hint.1": {"url": "http://localhost:4006/files/lesson-audio/37251c479cc8dc7f32a6b1c83ef0c335b869e65fd266a47bff527fc6f2d71334.mp3", "hash": "348a782aa41810e016134f7d821f396818d92a653e454a21f8fa720923758ea4", "bytes": 29088, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/37251c479cc8dc7f32a6b1c83ef0c335b869e65fd266a47bff527fc6f2d71334.mp3", "duration_ms": 4800}, "s1-debug-hunt.prompt": {"url": "http://localhost:4006/files/lesson-audio/a438068add861671f3c5a1d6275ff4606f538bcbea80fb74a6cc8140c5fd5a33.mp3", "hash": "ef2972b5d5254e9e360cb5ddab222d56197e67592fd7902833655dc920839e81", "bytes": 15264, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/a438068add861671f3c5a1d6275ff4606f538bcbea80fb74a6cc8140c5fd5a33.mp3", "duration_ms": 2480}, "s1-debug-hunt.explanation": {"url": "http://localhost:4006/files/lesson-audio/0a884486674517f0c8d03e4e6ea50158351148d515d5c597e29f34d963605ace.mp3", "hash": "273b51dbc435dee6a5af2fa1ded2f942c7e87c5f020074ec44d73892c97dd99a", "bytes": 100224, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/0a884486674517f0c8d03e4e6ea50158351148d515d5c597e29f34d963605ace.mp3", "duration_ms": 16640}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('97238255-709d-4d86-8930-3ea433f54f7d', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "checkpoint", "title": "La noche antes de abrir", "locale": "es-MX", "subject": "mixed", "objectives": ["Repasar la meta de la guitarra de 80 pesos, el precio de la limonada a 5 pesos el vaso, y que la ganancia es lo que sobra tras pagar el costo y va al frasco de la guitarra."], "estimated_minutes": 3}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "checkpoint-noche", "xp": 0, "type": "checkpoint", "hints": [], "title": "La noche antes de abrir", "payload": {"recap_md": "Liruf ya tiene su meta pegada en la pared: la guitarra de **80 pesos**. El cartel dice: limonada a **5 pesos el vaso**. Y lo más importante: de cada vaso, lo que sobra después del costo es la **ganancia** que va directo al frasco de la guitarra. ¡Mañana se prueba de verdad!", "mood_prompt_md": "¿Qué tan cerca sientes ya esa guitarra, Liruf?"}, "narrator": {"emotion": "encouraging", "character": "dina"}, "prompt_md": "Dina y Liruf repasan lo que tienen listo.", "difficulty": 1, "explanation_md": "Tener una meta clara, un precio y saber que la ganancia empuja el frasco hace que mañana sea real.", "audio_segment_id": "checkpoint-noche.prompt"}], "schema_version": 1}', '{}', '{"units": {"checkpoint-noche.recap": {"url": "http://localhost:4006/files/lesson-audio/55d82a60ed328804b72009762f506fc8796328778389c46d16e3b551656605fb.mp3", "hash": "1b23ad56edae5eb9acaba1bb9086b8203d1e40b4f7eeeef1c1260e4e6a5ac301", "bytes": 105408, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/55d82a60ed328804b72009762f506fc8796328778389c46d16e3b551656605fb.mp3", "duration_ms": 17520}, "checkpoint-noche.prompt": {"url": "http://localhost:4006/files/lesson-audio/20856a1f826cbd5c1e4d6843abcfe93906b25983ac64410487c435717b6c9b18.mp3", "hash": "beca56de91982f8016a4b13a205929159a181a01454b06ca832093c07214742b", "bytes": 17136, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/20856a1f826cbd5c1e4d6843abcfe93906b25983ac64410487c435717b6c9b18.mp3", "duration_ms": 2800}, "checkpoint-noche.explanation": {"url": "http://localhost:4006/files/lesson-audio/e5a3d855c898e10ce9e23a0b05c3fc571c7acef631ae8cd22cc5d2d7f912c45d.mp3", "hash": "f99d7f9d29aaee037c2b3aa982d418a1d55c5c31e46d4b3048efb7c9469290ce", "bytes": 42048, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/e5a3d855c898e10ce9e23a0b05c3fc571c7acef631ae8cd22cc5d2d7f912c45d.mp3", "duration_ms": 6960}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4b45b37b-19f0-4fd5-99c2-0bcf9fabfbcd', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "machine-io", "title": "La máquina de propinas", "locale": "es-MX", "subject": "mixed", "objectives": ["Descubrir la regla de la máquina de propinas: duplica la entrada."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-machine-io", "xp": 15, "type": "machine_io", "hints": ["Observa: 1 → 2, 3 → 6. ¿Qué operación se repite?", "Prueba: 1 × 2 = 2, 3 × 2 = 6. Entonces 5 × ?"], "title": "La máquina de propinas", "payload": {"options": [{"id": "opt-7", "text_md": "7"}, {"id": "opt-8", "text_md": "8"}, {"id": "opt-10", "text_md": "10"}, {"id": "opt-15", "text_md": "15"}], "examples": [{"in": 1, "out": 2}, {"in": 3, "out": 6}], "probe_in": 5}, "narrator": {"emotion": "excited", "character": "dina"}, "prompt_md": "Liruf mete 1 moneda y salen 2. Luego mete 3 y salen 6. ¿Cuántas saldrán si mete 5?", "difficulty": 2, "explanation_md": "La máquina duplica lo que entra. 1 se vuelve 2, 3 se vuelve 6, así que 5 se vuelve 10.", "audio_segment_id": "s1-machine-io.prompt"}], "schema_version": 1}', '{"s1-machine-io": {"value": 10, "correct_option_id": "opt-10"}}', '{"units": {"s1-machine-io.hint.0": {"url": "http://localhost:4006/files/lesson-audio/7574e17d5c5aec113fbc292b7d814a16c16fe491284810871764aae80d717e6b.mp3", "hash": "27620bcf609e437d5885a865edf8a5e5d9e3a9320383247f5c80bd2d821db52a", "bytes": 32976, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/7574e17d5c5aec113fbc292b7d814a16c16fe491284810871764aae80d717e6b.mp3", "duration_ms": 5440}, "s1-machine-io.hint.1": {"url": "http://localhost:4006/files/lesson-audio/d4fd5b5a8e256988805afb5aa19d4f7b665b6664243818976df10a3038192639.mp3", "hash": "7a38d8d4b1c3a244f3ae28afb302bfad6d8cc322f7e6e7b83172c30d3b9bdd74", "bytes": 33984, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/d4fd5b5a8e256988805afb5aa19d4f7b665b6664243818976df10a3038192639.mp3", "duration_ms": 5600}, "s1-machine-io.prompt": {"url": "http://localhost:4006/files/lesson-audio/63eb6b301b8de720e9d1bc6866a99dc5e3d3928c6c74afff39719d2eb2569d50.mp3", "hash": "74d34ab939a316cdc78fe6f8ee91ff02fb961174eff4a96823707e6f1b79151f", "bytes": 49248, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/63eb6b301b8de720e9d1bc6866a99dc5e3d3928c6c74afff39719d2eb2569d50.mp3", "duration_ms": 8160}, "s1-machine-io.explanation": {"url": "http://localhost:4006/files/lesson-audio/246ba12cb4dc05452da8e024c61ae603c46c65d12259d919f93ddd9866346fee.mp3", "hash": "356a2c797d7ecdaf3ecd37fe98170dea8d3e0bbb222ce32e9c46d2060d8ec851", "bytes": 44928, "voice": "qwen-tts-vc-dina_es_mx-voice-20260714105657179-761a", "file_id": "lesson-audio/246ba12cb4dc05452da8e024c61ae603c46c65d12259d919f93ddd9866346fee.mp3", "duration_ms": 7440}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0754f3ae-1483-4dd4-bc05-e1f681fd5bcf', 'es-MX', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-narrativa-choice", "title": "Un sábado en el puesto", "locale": "es-MX", "subject": "mixed", "objectives": ["Encadenar varias habilidades en una misma lección: escuchar la situación, decidir, calcular y cobrar."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-apertura-sabado", "xp": 0, "type": "story_scene", "title": "Apertura del sábado", "payload": {"art": {"icon": "storefront", "tint": "primary", "image_url": "http://localhost:4006/files/lesson-images/e30162e65ee97713b52bcd168d0d48eb040447d740cc3e5ea717f73bc8ce7fd1.png"}, "action": "idle", "body_md": "Ayer aprendiste que la máquina de propinas duplica lo que metes. Hoy Liruf abre su puesto de limonada. Ya hay fila de clientes. ¿A qué precio venderá cada vaso? Si vende 3 vasos a 5 pesos, gana 15 pesos. ¿Y si los vende a 6?", "emotion": "excited", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "excited", "character": "liruf"}, "prompt_md": "¡Llegó el sábado!", "difficulty": 1, "audio_segment_id": "s1-apertura-sabado.prompt"}, {"id": "s2-precio-del-dia", "xp": 15, "type": "quiz_mcq", "hints": ["Piensa: 3 vasos, cada uno a 5 pesos. ¿Cuánto es 3 veces 5?", "Usa lo de la máquina: duplicar ayuda, pero aquí es sumar 5+5+5."], "title": "Precio del día", "payload": {"options": [{"id": "a", "text_md": "15 pesos", "rationale_md": "Correcto: 3 vasos × 5 pesos = 15 pesos. ¡Buen trabajo!"}, {"id": "b", "text_md": "10 pesos", "rationale_md": "Casi: 3 vasos a 5 pesos no son 10. Recuerda sumar 5 tres veces."}, {"id": "c", "text_md": "18 pesos", "rationale_md": "Eso sería si cada vaso costara 6 pesos. Pero aquí son 5 pesos cada uno."}], "shuffle": true}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf tiene 3 vasos. ¿Cuánto gana si vende cada vaso a 5 pesos?", "difficulty": 2, "explanation_md": "3 vasos a 5 pesos cada uno son 15 pesos en total. Si los vendía a 6, serían 18, pero quizá venda menos vasos. Mejor mantener el precio justo.", "audio_segment_id": "s2-precio-del-dia.prompt"}], "schema_version": 1}', '{"s2-precio-del-dia": {"correct_option_id": "a"}}', '{"units": {"s1-apertura-sabado.body": {"url": "http://localhost:4006/files/lesson-audio/08589676d65bf5b0482cba9ebf59c91c4ff1ff0165656fe9c44ac5aa13e67087.mp3", "hash": "9c36cda28938cc26d7ee0d40bd8f53b35c6c696511fabd5998d7c20dad9e8146", "bytes": 100224, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/08589676d65bf5b0482cba9ebf59c91c4ff1ff0165656fe9c44ac5aa13e67087.mp3", "duration_ms": 16640}, "s2-precio-del-dia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/363c61ae150360d6c5fb51010c9fda6063bfdf1ec3aaf74aaabbf53bd3d0a495.mp3", "hash": "e13ddb646f278b5d9c8ccbad1076979438bc4832216af7cc22740ae55c385c38", "bytes": 38304, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/363c61ae150360d6c5fb51010c9fda6063bfdf1ec3aaf74aaabbf53bd3d0a495.mp3", "duration_ms": 6320}, "s2-precio-del-dia.hint.1": {"url": "http://localhost:4006/files/lesson-audio/49a334da5c7469727de7b97696b75bab55b7c4f0ca4b2e9da08251dd0794d5d9.mp3", "hash": "9a8f48ee46698649918fb325ae1c85326c81c545efdd4e30ee809a83209c0b69", "bytes": 34848, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/49a334da5c7469727de7b97696b75bab55b7c4f0ca4b2e9da08251dd0794d5d9.mp3", "duration_ms": 5760}, "s2-precio-del-dia.prompt": {"url": "http://localhost:4006/files/lesson-audio/05596aa30f1ac90f2e74c467f035cfde44112bd61ed81acb6a189bfa65fae07c.mp3", "hash": "29fd51d3662dbcd7a72163ef003387c564ad21c38a50b68390445c12fa580133", "bytes": 34416, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/05596aa30f1ac90f2e74c467f035cfde44112bd61ed81acb6a189bfa65fae07c.mp3", "duration_ms": 5680}, "s1-apertura-sabado.prompt": {"url": "http://localhost:4006/files/lesson-audio/22b80caac21a2aca0c1e6ecc670c11e488e8f41ec4c3f30a13f0d2d7436f4467.mp3", "hash": "e0bc6367e0809d144212203e9c8534875ed1767f39b3801e8ff510d26b3a2669", "bytes": 7488, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/22b80caac21a2aca0c1e6ecc670c11e488e8f41ec4c3f30a13f0d2d7436f4467.mp3", "duration_ms": 1200}, "s2-precio-del-dia.choices": {"url": "http://localhost:4006/files/lesson-audio/c44ef7e6402d4f53c5c9ca88099b669da8921171482a4c82d8c2d2979d8ab33b.mp3", "hash": "8cda377700f7e79a86a730a9dba8f511d683009cc1a38331c33a3c571e01a92b", "bytes": 30096, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/c44ef7e6402d4f53c5c9ca88099b669da8921171482a4c82d8c2d2979d8ab33b.mp3", "duration_ms": 4960}, "s2-precio-del-dia.explanation": {"url": "http://localhost:4006/files/lesson-audio/8d4e7f6b6e5262ee0c1336653cda50d36171ab8d10f60e40f2d7cb9f6696bd4c.mp3", "hash": "fbf107a77fb5175eb25a6df4757e8db0026eaded409a53fb7c7067e24c0e7aba", "bytes": 67536, "voice": "qwen-tts-vc-liruf_es_mx-voice-20260714105712357-ebfd", "file_id": "lesson-audio/8d4e7f6b6e5262ee0c1336653cda50d36171ab8d10f60e40f2d7cb9f6696bd4c.mp3", "duration_ms": 11200}}, "version": 1, "voice_profile": "Li"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('0754f3ae-1483-4dd4-bc05-e1f681fd5bcf', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "combo-narrativa-choice", "title": "Um sábado na barraca", "locale": "pt-BR", "subject": "mixed", "objectives": ["Combinar várias habilidades em uma mesma lição: ouvir a situação, decidir, calcular e cobrar."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-apertura-sabado", "xp": 0, "type": "story_scene", "title": "Abertura do sábado", "payload": {"art": {"icon": "storefront", "tint": "primary", "image_url": "http://localhost:4006/files/lesson-images/167f29137e0f299bd61bc6636260116ed47cee17a87fae11eec25d59c574c529.png"}, "action": "idle", "body_md": "Ontem você aprendeu que a máquina de gorjetas dobra o que você coloca. Hoje Liruf abre sua barraca de limonada. Já tem fila de clientes. A que preço ele venderá cada copo? Se vender 3 copos a 5 reais, ganha 15 reais. E se vender a 6?", "emotion": "excited", "backdrop": "band", "character": "liruf"}, "narrator": {"emotion": "excited", "character": "liruf"}, "prompt_md": "Chegou o sábado!", "difficulty": 1, "audio_segment_id": "s1-apertura-sabado.prompt"}, {"id": "s2-precio-del-dia", "xp": 15, "type": "quiz_mcq", "hints": ["Pense: 3 copos, cada um a 5 reais. Quanto é 3 vezes 5?", "Use o da máquina: dobrar ajuda, mas aqui é somar 5+5+5."], "title": "Preço do dia", "payload": {"options": [{"id": "a", "text_md": "15 reais", "rationale_md": "Correto: 3 copos × 5 reais = 15 reais. Bom trabalho!"}, {"id": "b", "text_md": "10 reais", "rationale_md": "Quase: 3 copos a 5 reais não são 10. Lembre-se de somar 5 três vezes."}, {"id": "c", "text_md": "18 reais", "rationale_md": "Isso seria se cada copo custasse 6 reais. Mas aqui são 5 reais cada."}], "shuffle": true}, "narrator": {"emotion": "thinking", "character": "liruf"}, "prompt_md": "Liruf tem 3 copos. Quanto ele ganha se vender cada copo a 5 reais?", "difficulty": 2, "explanation_md": "3 copos a 5 reais cada são 15 reais no total. Se vendesse a 6, seriam 18, mas talvez vendesse menos copos. Melhor manter o preço justo.", "audio_segment_id": "s2-precio-del-dia.prompt"}], "schema_version": 1}', '{"s2-precio-del-dia": {"correct_option_id": "a"}}', '{"units": {"s1-apertura-sabado.body": {"url": "http://localhost:4006/files/lesson-audio/3974be4e78cd7fd1482da1bf352693f60ba4004347b3c790508cb797ff84241b.mp3", "hash": "c87d4c2ff99226bb243417e1ead525117d5e5f128c9d8be9d4dbaee21bf6f470", "bytes": 102528, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/3974be4e78cd7fd1482da1bf352693f60ba4004347b3c790508cb797ff84241b.mp3", "duration_ms": 17040}, "s2-precio-del-dia.hint.0": {"url": "http://localhost:4006/files/lesson-audio/7477da15e3394dcedd7ceb1aab4d5113cc11eec5bb171932a8f563b048199b9e.mp3", "hash": "3358addd80e59155527dca16a54cf5a9d2a9467a967561c8f1497ccd0c01741e", "bytes": 37728, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/7477da15e3394dcedd7ceb1aab4d5113cc11eec5bb171932a8f563b048199b9e.mp3", "duration_ms": 6240}, "s2-precio-del-dia.hint.1": {"url": "http://localhost:4006/files/lesson-audio/288c39fb128297320a7e214ece1d44874738d666d959c6109f6ffae08d0007d9.mp3", "hash": "bd5eeae1eac406d03cccb6fef1cc22dce890d3464eafc94d35745c59e6837c6e", "bytes": 40608, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/288c39fb128297320a7e214ece1d44874738d666d959c6109f6ffae08d0007d9.mp3", "duration_ms": 6720}, "s2-precio-del-dia.prompt": {"url": "http://localhost:4006/files/lesson-audio/2392cec40d3bb542414b093b6170eab219e42a5f8cbb9000a1cfe90efd42a156.mp3", "hash": "05e0ee273a283016b3619b946cc92194c3fb9ced621afd7aa9db82ad65f04ed3", "bytes": 35856, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/2392cec40d3bb542414b093b6170eab219e42a5f8cbb9000a1cfe90efd42a156.mp3", "duration_ms": 5920}, "s1-apertura-sabado.prompt": {"url": "http://localhost:4006/files/lesson-audio/1686e8b0dca852e0e673b7b9da20bc78e966573e215548165e5752db75038e86.mp3", "hash": "20138e949638f265ff038bd018032c1d582235eb03f54f5e4c674663001383e4", "bytes": 8064, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/1686e8b0dca852e0e673b7b9da20bc78e966573e215548165e5752db75038e86.mp3", "duration_ms": 1280}, "s2-precio-del-dia.choices": {"url": "http://localhost:4006/files/lesson-audio/a3abc1e521c3f601404fffb40d802d57549ed2f3070759fdbf82a81b7c9e49a6.mp3", "hash": "6548b3bfec11ca16b67f4bcae2d8a10d9e003d08f6864404bb7f2c092db426a1", "bytes": 26208, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/a3abc1e521c3f601404fffb40d802d57549ed2f3070759fdbf82a81b7c9e49a6.mp3", "duration_ms": 4320}, "s2-precio-del-dia.explanation": {"url": "http://localhost:4006/files/lesson-audio/5041eff363bd6dfc5bf9c274c77714700e327cc6762a20459b823e71ec3e9d51.mp3", "hash": "b04cc311f50e97996dee2f9d0f8d0b6ed0e3f1e61203a4a93606dfb674404f1a", "bytes": 72864, "voice": "qwen-tts-vc-liruf_pt_br-voice-20260714105833227-c3f9", "file_id": "lesson-audio/5041eff363bd6dfc5bf9c274c77714700e327cc6762a20459b823e71ec3e9d51.mp3", "duration_ms": 12080}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('ec92e8b8-2834-4bff-88e8-59733b2e617a', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf"], "slug": "repaso-quiz-mcq", "title": "Revisão rápida do cargo", "locale": "pt-BR", "subject": "money", "objectives": ["Responder de memória o lucro por copo de limonada", "Lembrar o preço justo e a economia"], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-ganancia-vaso", "xp": 10, "type": "quiz_mcq", "hints": ["Quanto sobra depois de pagar os ingredientes?"], "title": "Lucro por copo", "payload": {"options": [{"id": "a", "text_md": "3 reais", "rationale_md": "Correto. 5 - 2 = 3 reais de lucro por copo."}, {"id": "b", "text_md": "2 reais", "rationale_md": "Esse é o custo dos ingredientes, não o lucro. O lucro é o que sobra depois de pagar os ingredientes."}, {"id": "c", "text_md": "5 reais", "rationale_md": "Esse é o preço do copo, mas você não subtraiu o custo dos ingredientes. O lucro é menor."}, {"id": "d", "text_md": "7 reais", "rationale_md": "Você somou o preço e o custo, mas o lucro é calculado subtraindo, não somando."}], "shuffle": true}, "narrator": {"emotion": "thinking", "character": "dina"}, "prompt_md": "Cada copo custa 5 reais. Os ingredientes custam 2 reais. Quanto você ganha por copo?", "difficulty": 1, "explanation_md": "Você ganha 3 reais por copo: 5 reais que você cobra menos 2 reais de ingredientes. Assim você calculou o lucro ontem.", "audio_segment_id": "s1-ganancia-vaso.prompt"}], "schema_version": 1}', '{"s1-ganancia-vaso": {"correct_option_id": "a"}}', '{"units": {"s1-ganancia-vaso.hint.0": {"url": "http://localhost:4006/files/lesson-audio/02b87797b35fdc4e6ea05abe26994af772d8d3ced005a8cab85dc11d3e38b93f.mp3", "hash": "e7dc3a24ebef9308d28ea11ce17cd2735ff0a407e66139462b56a3af5b060fea", "bytes": 18144, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/02b87797b35fdc4e6ea05abe26994af772d8d3ced005a8cab85dc11d3e38b93f.mp3", "duration_ms": 2960}, "s1-ganancia-vaso.prompt": {"url": "http://localhost:4006/files/lesson-audio/fa854d73201831fff913402a2aad07a4a3cd00378b58187ac5f5fcf29bfbc10d.mp3", "hash": "f956b8268818533f30603c542761536b9f1d5543fd79a346d58751e15e762ae3", "bytes": 42048, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/fa854d73201831fff913402a2aad07a4a3cd00378b58187ac5f5fcf29bfbc10d.mp3", "duration_ms": 6960}, "s1-ganancia-vaso.choices": {"url": "http://localhost:4006/files/lesson-audio/d6603ffee565419e14038a6b69ac89d2a01ecd35859889a038a90c7bb49e7c19.mp3", "hash": "94e149f1714648b2547f1ae0b34f8b57fb357fcc593f41d26a85120191fd6d30", "bytes": 34416, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/d6603ffee565419e14038a6b69ac89d2a01ecd35859889a038a90c7bb49e7c19.mp3", "duration_ms": 5680}, "s1-ganancia-vaso.explanation": {"url": "http://localhost:4006/files/lesson-audio/7c6301ac2a22126230baf672850041f073fa6b64e8ba35ea7e1b63954fb6ab8a.mp3", "hash": "af6f6b0995d14340339775d9271fd0ae7b0eb30978987009ec0b8579c5c209a5", "bytes": 57456, "voice": "qwen-tts-vc-dina_pt_br-voice-20260714105817107-dbdc", "file_id": "lesson-audio/7c6301ac2a22126230baf672850041f073fa6b64e8ba35ea7e1b63954fb6ab8a.mp3", "duration_ms": 9520}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
INSERT INTO lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio) VALUES ('4785eb58-e0ca-4b5c-a796-a6f01b2ab3ae', 'pt-BR', '1', '{"meta": {"cast": ["dina", "liruf", "zara"], "slug": "pattern-complete", "title": "Escada de preços", "locale": "pt-BR", "subject": "money", "objectives": ["Organizar etapas, combinar produtos com preços e classificar compras entre necessidades da barraca e gostos que podem esperar."], "estimated_minutes": 5}, "scoring": {"hearts": null, "max_attempts": 2, "pass_threshold": 70, "hint_penalty_pct": 10}, "segments": [{"id": "s1-escalera", "xp": 15, "type": "pattern_complete", "hints": ["Observe como o preço sobe: pequeno R$5, médio R$10, grande R$15, depois recomeça. Qual tamanho vem depois do médio?", "A escada sempre sobe de preço: pequeno → médio → grande → pequeno → médio → ¿? O próximo deve ser o mais caro."], "title": "Escada de preços", "payload": {"options": [{"id": "grande", "icon": "local_cafe", "tint": "success"}, {"id": "chico", "icon": "local_cafe", "tint": "primary"}, {"id": "limon", "icon": "nutrition", "tint": "delight"}], "sequence": [{"icon": "local_cafe", "tint": "primary"}, {"icon": "local_cafe", "tint": "accent"}, {"icon": "local_cafe", "tint": "success"}, {"icon": "local_cafe", "tint": "primary"}, {"icon": "local_cafe", "tint": "accent"}, {"icon": "local_cafe", "tint": "warning"}], "missing_slots": 1}, "narrator": {"emotion": "thinking", "character": "zara"}, "prompt_md": "Toque no copo que completa a escada: pequeno R$5, médio R$10, grande R$15, pequeno R$5, médio R$10, ¿?", "difficulty": 2, "explanation_md": "Depois do médio de R$10 vem o grande de R$15, porque a escada sobe de preço: pequeno (R$5), médio (R$10), grande (R$15) e recomeça.", "audio_segment_id": "s1-escalera.prompt"}], "schema_version": 1}', '{"s1-escalera": {"correct": {"5": "grande"}}}', '{"units": {"s1-escalera.hint.0": {"url": "http://localhost:4006/files/lesson-audio/acb1b38e59f3db66dce5da1e8b8175b486d5f60ee2bcd649999a64f00dd2ae0b.mp3", "hash": "c3aae27c11012d26d897d9cd34a879576ab8ba076b60b7498cb8cc01ad999fa7", "bytes": 59904, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/acb1b38e59f3db66dce5da1e8b8175b486d5f60ee2bcd649999a64f00dd2ae0b.mp3", "duration_ms": 9920}, "s1-escalera.hint.1": {"url": "http://localhost:4006/files/lesson-audio/397bfbaff2373888eab7d3f0cd0e701b6f8d19cf52fc6027429be47b8280311d.mp3", "hash": "ba9ca3e4d1b81d9df762b7b6948027b363c268d11464d754d553e3ab917e9ec5", "bytes": 46368, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/397bfbaff2373888eab7d3f0cd0e701b6f8d19cf52fc6027429be47b8280311d.mp3", "duration_ms": 7680}, "s1-escalera.prompt": {"url": "http://localhost:4006/files/lesson-audio/470660e95c59ad62bc16d6f89f1eb8f0a8c7a5f00f975c19602e276e1e8534b3.mp3", "hash": "ffbe27985cc9dcf40bdd94a1674cf7a0420d10353978fd2c16d11090a3d49ca7", "bytes": 60336, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/470660e95c59ad62bc16d6f89f1eb8f0a8c7a5f00f975c19602e276e1e8534b3.mp3", "duration_ms": 10000}, "s1-escalera.explanation": {"url": "http://localhost:4006/files/lesson-audio/179fe937b912c993cf6e7b6a2405e17fd491fd18d93baa38b47d511d783ad54a.mp3", "hash": "4a170bd180d904797670a5914743d90903f5264491ea78f4bef110feffac352a", "bytes": 72288, "voice": "qwen-tts-vc-zara_pt_br-voice-20260714105932039-386f", "file_id": "lesson-audio/179fe937b912c993cf6e7b6a2405e17fd491fd18d93baa38b47d511d783ad54a.mp3", "duration_ms": 12000}}, "version": 1, "voice_profile": "Ryan"}') ON CONFLICT (lesson_id, locale) DO NOTHING;
